import csv
import json
import sys
import os

def main():
    args = sys.argv[1:]
    if not args:
        sys.stderr.write("usage: csv2json.py PATH [--indent N]\n")
        sys.exit(2)

    path = None
    indent = None
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--indent':
            if i + 1 >= len(args):
                sys.stderr.write("usage: csv2json.py PATH [--indent N]\n")
                sys.exit(2)
            try:
                val = args[i + 1]
                if '.' in val:
                    raise ValueError
                n = int(val)
                if n < 0:
                    raise ValueError
                indent = n
            except ValueError:
                sys.stderr.write("usage: csv2json.py PATH [--indent N]\n")
                sys.exit(2)
            i += 2
        else:
            if path is not None:
                sys.stderr.write("usage: csv2json.py PATH [--indent N]\n")
                sys.exit(2)
            path = arg
            i += 1

    if path is None:
        sys.stderr.write("usage: csv2json.py PATH [--indent N]\n")
        sys.exit(2)

    if not os.path.exists(path) or not os.path.isfile(path):
        sys.stderr.write(f"csv2json.py: no such file: {path}\n")
        sys.exit(2)

    try:
        with open(path, 'r', encoding='utf-8-sig', newline='') as f:
            reader = csv.reader(f)
            records = []
            header = None
            record_index = 0

            for row in reader:
                if not row:
                    continue

                record_index += 1

                if header is None:
                    header = row
                else:
                    if len(row) > len(header):
                        sys.stderr.write(f"csv2json.py: record {record_index} has {len(row)} fields, expected {len(header)}\n")
                        sys.exit(1)

                    if len(row) < len(header):
                        row = row + [None] * (len(header) - len(row))

                    obj = {}
                    for j, key in enumerate(header):
                        obj[key] = row[j]
                    records.append(obj)

            if header is None:
                sys.stderr.write(f"csv2json.py: empty file: {path}\n")
                sys.exit(2)

    except Exception as e:
        sys.stderr.write(f"csv2json.py: error: {e}\n")
        sys.exit(2)

    if indent is not None:
        output = json.dumps(records, indent=indent, ensure_ascii=False)
    else:
        output = json.dumps(records, ensure_ascii=False)

    sys.stdout.write(output + '\n')

if __name__ == '__main__':
    main()
