import re
from typing import Union, Tuple, List


def _compare_prerelease(pre_a: Tuple[str, ...], pre_b: Tuple[str, ...]) -> int:
    """Compare pre-release identifiers according to SemVer rules."""
    # Compare identifier by identifier
    for i in range(min(len(pre_a), len(pre_b))):
        a, b = pre_a[i], pre_b[i]
        # Determine if each identifier is numeric
        a_is_num = a.isdigit()
        b_is_num = b.isdigit()

        if a_is_num and b_is_num:
            # Compare numerically
            na, nb = int(a), int(b)
            if na < nb:
                return -1
            elif na > nb:
                return 1
        elif a_is_num:
            # Numeric is always lower than alphanumeric
            return -1
        elif b_is_num:
            # Numeric is always lower than alphanumeric
            return 1
        else:
            # Both alphanumeric, compare in ASCII order
            if a < b:
                return -1
            elif a > b:
                return 1

    # If all compared identifiers are equal, the shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1
    return 0


class Version:
    """Represents a Semantic Version 2.0.0 version number."""

    # Regex pattern for parsing semver strings
    _SEMVER_RE = re.compile(
        r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
        r'(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)'
        r'(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
        r'(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
    )

    def __init__(self, major: int, minor: int, patch: int,
                 prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        self._major = major
        self._minor = minor
        self._patch = patch
        self._prerelease = prerelease
        self._build = build

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """Parse a semantic version string."""
        if not isinstance(text, str):
            raise ValueError("Version text must be a string")

        match = cls._SEMVER_RE.match(text)
        if not match:
            raise ValueError(f"Invalid semantic version: {text!r}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))

        prerelease_str = match.group(4)
        build_str = match.group(5)

        prerelease = tuple(prerelease_str.split('.')) if prerelease_str else ()
        build = tuple(build_str.split('.')) if build_str else ()

        return cls(major, minor, patch, prerelease, build)

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    @property
    def prerelease(self) -> Tuple[str, ...]:
        return self._prerelease

    @property
    def build(self) -> Tuple[str, ...]:
        return self._build

    def __str__(self) -> str:
        """Return the canonical string representation."""
        base = f"{self._major}.{self._minor}.{self._patch}"
        if self._prerelease:
            base += '-' + '.'.join(self._prerelease)
        if self._build:
            base += '+' + '.'.join(self._build)
        return base

    def __repr__(self) -> str:
        return f"Version('{str(self)}')"

    def _compare_core(self, other: 'Version') -> int:
        """Compare major, minor, patch numerically."""
        if self._major != other._major:
            return -1 if self._major < other._major else 1
        if self._minor != other._minor:
            return -1 if self._minor < other._minor else 1
        if self._patch != other._patch:
            return -1 if self._patch < other._patch else 1
        return 0

    def _compare_pre(self, other: 'Version') -> int:
        """Compare pre-release fields. Returns -1, 0, or 1."""
        # If both have no pre-release, they're equal in this aspect
        if not self._prerelease and not other._prerelease:
            return 0
        # A version with pre-release is lower than without
        if self._prerelease and not other._prerelease:
            return -1
        if not self._prerelease and other._prerelease:
            return 1
        # Both have pre-release, compare them
        return _compare_prerelease(self._prerelease, other._prerelease)

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        if self._compare_core(other) != 0:
            return False
        if self._compare_pre(other) != 0:
            return False
        return True

    def __ne__(self, other) -> bool:
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        core = self._compare_core(other)
        if core != 0:
            return core < 0
        pre = self._compare_pre(other)
        return pre < 0

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        core = self._compare_core(other)
        if core != 0:
            return core < 0
        pre = self._compare_pre(other)
        return pre <= 0

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not self.__le__(other)

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return not self.__lt__(other)

    def __hash__(self) -> int:
        # Build metadata is ignored for equality, so hash must ignore it too
        return hash((self._major, self._minor, self._patch, self._prerelease))

    def bump(self, kind: str) -> 'Version':
        """Return a new version with the specified component bumped."""
        if kind == 'major':
            return Version(self._major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self._major, self._minor + 1, 0)
        elif kind == 'patch':
            return Version(self._major, self._minor, self._patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: {kind!r}")


def _parse_partial_version(text: str) -> Version:
    """
    Parse a partial version like '1', '1.2', or '1.2.3'.
    Returns a Version with 0s for missing parts.
    Raises ValueError if the format is invalid or has prerelease/build.
    """
    if not isinstance(text, str):
        raise ValueError("Version text must be a string")

    # Check for prerelease or build parts - not allowed in partial versions
    if '-' in text or '+' in text:
        raise ValueError(f"Partial version cannot have prerelease or build: {text!r}")

    parts = text.split('.')

    if len(parts) == 1:
        # Must be a single number
        part = parts[0]
        if not re.match(r'^(0|[1-9]\d*)$', part):
            raise ValueError(f"Invalid version component: {part!r}")
        return Version(int(part), 0, 0)
    elif len(parts) == 2:
        # Must be two numbers
        for part in parts:
            if not re.match(r'^(0|[1-9]\d*)$', part):
                raise ValueError(f"Invalid version component: {part!r}")
        return Version(int(parts[0]), int(parts[1]), 0)
    elif len(parts) == 3:
        # Parse as full version
        return Version.parse(text)
    else:
        raise ValueError(f"Invalid version format: {text!r}")


def _parse_comparator(spec: str) -> List[tuple]:
    """
    Parse a single comparator like '>=1.2.3', '^1.2', '~1', '=1.2.3', '1.2.3'.
    Returns a list of (operator, version) tuples.
    """
    if not isinstance(spec, str):
        raise ValueError("Comparator must be a string")

    spec = spec.strip()
    if not spec:
        raise ValueError("Empty comparator")

    # Check for operator prefixes
    if spec.startswith('>='):
        op = '>='
        ver_text = spec[2:].strip()
    elif spec.startswith('<='):
        op = '<='
        ver_text = spec[2:].strip()
    elif spec.startswith('>'):
        op = '>'
        ver_text = spec[1:].strip()
    elif spec.startswith('<'):
        op = '<'
        ver_text = spec[1:].strip()
    elif spec.startswith('='):
        op = '='
        ver_text = spec[1:].strip()
    elif spec.startswith('^'):
        op = '^'
        ver_text = spec[1:].strip()
    elif spec.startswith('~'):
        op = '~'
        ver_text = spec[1:].strip()
    else:
        op = '='
        ver_text = spec

    ver_text = ver_text.strip()
    if not ver_text:
        raise ValueError(f"Missing version in comparator: {spec!r}")

    version = _parse_partial_version(ver_text)

    return [(op, version)]


def satisfies(version, spec: str) -> bool:
    """
    Check if a version satisfies a semver range specification.

    version can be a Version object or a version string.
    spec is a semver range like '>=1.2.3 <2.0.0' or '^1.2'.
    """
    if isinstance(version, str):
        version = Version.parse(version)
    elif not isinstance(version, Version):
        raise ValueError("version must be a Version object or a string")

    if not isinstance(spec, str):
        raise ValueError("spec must be a string")

    spec = spec.strip()
    if not spec:
        raise ValueError("Empty spec")

    # Split spec by whitespace to get individual comparators
    # But we need to be careful: '>=1.2.3' should be one comparator
    # Split on whitespace, but each part is a comparator
    parts = spec.split()
    if not parts:
        raise ValueError("Empty spec")

    comparators = []
    for part in parts:
        comparators.extend(_parse_comparator(part))

    # Check each comparator
    for op, ver in comparators:
        if op == '>=':
            if not (version >= ver):
                return False
        elif op == '<=':
            if not (version <= ver):
                return False
        elif op == '>':
            if not (version > ver):
                return False
        elif op == '<':
            if not (version < ver):
                return False
        elif op == '=':
            if not (version == ver):
                return False
        elif op == '^':
            # ^V allows changes that do not modify the left-most non-zero part
            # ^1.2.3 -> >=1.2.3 <2.0.0
            # ^0.2.3 -> >=0.2.3 <0.3.0
            # ^0.0.3 -> >=0.0.3 <0.0.4
            # ^0.0.0 -> >=0.0.0 <0.0.1 (if patch is 0, still bump patch? Let's think)
            # ^0.0.0 means only patch can change, but since patch is 0... 
            # Actually ^0.0.0 is >=0.0.0 <0.0.1
            # ^1.2 (partial) is ^1.2.0

            major = ver.major
            minor = ver.minor
            patch = ver.patch

            if major != 0:
                lower = ver
                upper = Version(major + 1, 0, 0)
            elif minor != 0:
                lower = ver
                upper = Version(major, minor + 1, 0)
            else:
                # major and minor are 0
                lower = ver
                upper = Version(major, minor, patch + 1)

            if not (version >= lower):
                return False
            if not (version < upper):
                return False
        elif op == '~':
            # ~V allows patch-level changes
            # ~1.2.3 -> >=1.2.3 <1.3.0
            # ~1.2 -> >=1.2.0 <1.3.0
            # ~1 -> >=1.0.0 <2.0.0

            major = ver.major
            minor = ver.minor
            patch = ver.patch

            lower = ver
            upper = Version(major, minor + 1, 0)

            if not (version >= lower):
                return False
            if not (version < upper):
                return False
        else:
            raise ValueError(f"Unknown operator: {op}")

    return True
