    """
    Evaluate the arithmetic expression exactly and return a Fraction.
    Raises CalcError with position information on syntax or division by zero errors.
    """
    # Tokenize first
    tokens = tokenize(expr)

    # Parser state
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        t = peek()
        if t is None:
            raise CalcError("Unexpected end of expression", len(expr))
        pos += 1
        return t

    def parse_expression():
        return parse_add_sub()

    def parse_add_sub():
        left = parse_mul_div()
        while True:
            t = peek()
            if t is None:
                break
            if t.type in ('PLUS', 'MINUS'):
                op_tok = consume()
                right = parse_mul_div()
                left = ('binop', op_tok.type, left, right, op_tok.position)
            else:
                break
        return left

    def parse_mul_div():
        left = parse_unary()
        while True:
            t = peek()
            if t is None:
                break
            if t.type in ('STAR', 'SLASH'):
                op_tok = consume()
                right = parse_unary()
                left = ('binop', op_tok.type, left, right, op_tok.position)
            else:
                break
        return left

    def parse_unary():
        t = peek()
        if t is not None and t.type == 'MINUS':
            op_tok = consume()
            operand = parse_unary()
            return ('unary_minus', operand, op_tok.position)
        else:
            return parse_primary()

    def parse_primary():
        t = peek()
        if t is None:
            raise CalcError("Unexpected end of expression", len(expr))

        if t.type == 'NUMBER':
            consume()
            return ('number', Fraction(t.value), t.position)

        elif t.type == 'LPAREN':
            consume()
            expr_node = parse_expression()
