    Tokenize the expression string into a list of Tokens.
    Raises CalcError if an invalid character or malformed number is found.
    """
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        # Skip whitespace
        if c in (' ', '\t'):
            i += 1
            continue

        # Check for operators and parentheses
        if c in '+-*/()':
            if c == '*':
                # Check for **
                if i + 1 < n and expr[i+1] == '*':
                    tokens.append(Token('POW', '**', i))
                    i += 2
                    continue
                else:
                    tokens.append(Token('STAR', '*', i))
                    i += 1
                    continue
            else:
                token_map = {
                    '+': 'PLUS',
                    '-': 'MINUS',
                    '/': 'SLASH',
                    '(': 'LPAREN',
                    ')': 'RPAREN'
                }
                tokens.append(Token(token_map[c], c, i))
                i += 1
            continue

        # Check for comma
        if c == ',':
            tokens.append(Token('COMMA', ',', i))
            i += 1
            continue

        # Check for identifiers (letters and _)
        if c.isalpha() or c == '_':
            start = i
            i += 1
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            val = expr[start:i]
            tokens.append(Token('IDENT', val, start))
            continue

        # Check for numbers
        if c.isdigit():
            start = i
            i += 1
            # Consume remaining digits
            while i < n and expr[i].isdigit():
                i += 1

            # Check for decimal part
            if i < n and expr[i] == '.':
                dot_pos = i
                i += 1
                # After dot, must have at least one digit
                if i >= n or not expr[i].isdigit():
                    # Invalid number format like "5." or "5.x"
                    # The dot is the problematic character because:
                    # 1. It cannot be part of the current number (spec: "5." is not a number)
                    # 2. It cannot start a new number (spec: ".5" is not a number)
                    # Thus, the error is at the position of the dot.
                    raise CalcError("Invalid number", dot_pos)
                # Consume digits after dot
                while i < n and expr[i].isdigit():
                    i += 1

            # Valid number formed
            num_str = expr[start:i]
            tokens.append(Token('NUMBER', num_str, start))
            continue

        # Invalid character
        # If it's not whitespace, operator, paren, digit, ident start, or comma, it's unexpected.
        raise CalcError(f"Unexpected character '{c}'", i)

    return tokens


def evaluate(expr: str, variables=None) -> Fraction:
    """
    Evaluate the arithmetic expression exactly and return a Fraction.
    variables is a dict mapping names to int or Fraction.
    """
    tokens = tokenize(expr)

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        t = peek()
        if t is None:
            # Should be handled by callers, but safe guard
            raise CalcError("Unexpected end of expression", len(expr))
        pos += 1
        return t

    def parse_expression():
        return parse_add_sub()

    def parse_add_sub():
        left = parse_mul_div()
        while True:
            t = peek()
            if t is None:
                break
            if t.type in ('PLUS', 'MINUS'):
                op_tok = consume()
                right = parse_mul_div()
                left = ('binop', op_tok.type, left, right, op_tok.position)
            else:
                break
        return left

    def parse_mul_div():
        left = parse_unary()
        while True:
            t = peek()
            if t is None:
                break
            if t.type in ('STAR', 'SLASH'):
                op_tok = consume()
                right = parse_unary()
                left = ('binop', op_tok.type, left, right, op_tok.position)
            else:
                break
        return left

    def parse_unary():
        t = peek()
        if t is not None and t.type == 'MINUS':
            op_tok = consume()
            operand = parse_unary()
            return ('unary_minus', operand, op_tok.position)
        else:
            return parse_power()

    def parse_power():
        # Right-associative: base ** exponent
        # Exponent can start with unary minus
        base = parse_primary()
        t = peek()
        if t is not None and t.type == 'POW':
            op_tok = consume()
            # The exponent can be unary minus followed by power, or just power
            exponent = parse_exponent()
            return ('binop', 'POW', base, exponent, op_tok.position)
        return base

    def parse_exponent():
        # Parses the right-hand side of **.
        # It can be a unary minus followed by a power term, or just a power term.
        # Since ** binds tighter than unary minus on the left, but the right operand
        # "may start with unary minus", we allow unary minus here.
        t = peek()
        if t is not None and t.type == 'MINUS':
            op_tok = consume()
            inner = parse_exponent()
            return ('unary_minus', inner, op_tok.position)
        return parse_power()

    def parse_primary():
        """Parse primary expressions: numbers and parenthesized expressions."""
        t = peek()
        if t is None:
            # Unexpected end of expression (e.g., "1 +", "(")
            raise CalcError("Unexpected end of expression", len(expr))

        if t.type == 'NUMBER':
            consume()
            return ('number', Fraction(t.value), t.position)

        elif t.type == 'LPAREN':
            consume()
            expr_node = parse_expression()
            # Expect RPAREN
            t = peek()
            if t is None or t.type != 'RPAREN':
                if t is None:
                    # Missing closing paren, error at end of input
                    raise CalcError("Expected ')'", len(expr))
                else:
                    # Mismatched paren, error at the unexpected token
                    raise CalcError("Expected ')'", t.position)
            consume()
            return expr_node

        elif t.type == 'IDENT':
            name_tok = consume()
            name = name_tok.value
            next_t = peek()

            # Check if it's a function call
            if next_t is not None and next_t.type == 'LPAREN':
                consume() # Consume '('
                args = []

                # Check for empty arguments list
                if peek() is not None and peek().type == 'RPAREN':
                    consume()
                    return ('func', name, [], name_tok.position)

                while True:
                    arg = parse_expression()
                    args.append(arg)

                    t = peek()
                    if t is None:
                        raise CalcError("Expected ',' or ')'", len(expr))
                    if t.type == 'COMMA':
                        consume()
                        continue
                    elif t.type == 'RPAREN':
                        consume()
                        break
                    else:
                        raise CalcError("Expected ',' or ')'", t.position)

                return ('func', name, args, name_tok.position)
            else:
                # Variable
                return ('variable', name, name_tok.position)

        else:
            # Unexpected token (e.g., unary plus, RPAREN at start, etc.)
            # This handles cases like "()" where RPAREN is encountered in primary position
            raise CalcError("Unexpected token", t.position)

    # Handle empty expression
    if not tokens:
        raise CalcError("Empty expression", 0)

    # Parse
    ast = parse_expression()

    # Check for trailing tokens
    # If tokens remain, it means the expression ended prematurely or there's garbage left
    # e.g., "1 2" -> parse 1, then see 2 which is not an operator, so loop breaks.
    # pos points to token "2".
    if pos < len(tokens):
        t = tokens[pos]
        raise CalcError("Unexpected token after expression", t.position)

    # Evaluate AST
    def eval_node(node):
        if not node:
            raise CalcError("Invalid AST", 0)

        kind = node[0]

        if kind == 'number':
            return node[1]

        elif kind == 'variable':
            name, pos_var = node[1], node[2]
            if variables is None:
                raise CalcError("Unknown variable", pos_var)
            if name not in variables:
                raise CalcError("Unknown variable", pos_var)
            val = variables[name]
            # Spec: variables mapping to int or Fraction
            if isinstance(val, int):
                return Fraction(val)
            elif isinstance(val, Fraction):
                return val
            else:
                # Try to convert if possible, though spec implies strict types
                return Fraction(val)

        elif kind == 'unary_minus':
            val = eval_node(node[1])
            return -val

        elif kind == 'binop':
            _, op, left_node, right_node, op_pos = node

            # Left-to-right evaluation order: evaluate left first, then right.
            # This ensures that if there are multiple division by zero errors,
            # the leftmost one is raised first.
            left_val = eval_node(left_node)
            right_val = eval_node(right_node)

            if op == 'PLUS':
                return left_val + right_val
            elif op == 'MINUS':
                return left_val - right_val
            elif op == 'STAR':
                return left_val * right_val
            elif op == 'SLASH':
                if right_val == 0:
                    raise CalcError("Division by zero", op_pos)
                return left_val / right_val
            elif op == 'POW':
                # Exponent must be a whole number
                # Fraction is whole if denominator is 1
                if right_val.denominator != 1:
                    raise CalcError("Exponent is not a whole number", op_pos)

                exp_int = int(right_val)

                # Check 0 ** negative
                if left_val == 0 and exp_int < 0:
                    raise CalcError("Division by zero", op_pos)

                return left_val ** exp_int
            else:
                raise CalcError("Unknown operator", op_pos)

        elif kind == 'func':
            name, args, func_pos = node[1], node[2], node[3]

            # Spec: "A function's name and argument count are checked before its arguments are evaluated."

            if name == 'abs':
                if len(args) != 1:
                    raise CalcError("Wrong number of arguments", func_pos)
            elif name == 'min':
                if len(args) < 1:
                    raise CalcError("Wrong number of arguments", func_pos)
            elif name == 'max':
                if len(args) < 1:
                    raise CalcError("Wrong number of arguments", func_pos)
            else:
                raise CalcError("Unknown function", func_pos)

            # Now evaluate arguments left to right
            eval_args = []
            for arg_node in args:
                eval_args.append(eval_node(arg_node))

            if name == 'abs':
                return abs(eval_args[0])
            elif name == 'min':
                return min(eval_args)
            elif name == 'max':
                return max(eval_args)

        else:
            raise CalcError("Invalid AST node", 0)

    return eval_node(ast)
