def encode(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        return ""

    result = []
    i = 0
    n = len(text)

    while i < n:
        char = text[i]
        # Count the run length
        j = i + 1
        while j < n and text[j] == char:
            j += 1
        run_length = j - i

        # Write the character
        if char == '\\':
            written = '\\\\'
