                count_val = int(count_str)
            except ValueError:
                raise ValueError(f"Invalid count at position {i}")

            if count_val < 2:
                raise ValueError(f"Count must be 2 or more, got {count_val} at position {i}")

            count = count_val
            i = j

            # After a count, we need a written character
            if i >= n:
