                    i += 2
                elif next_char.isdigit():
                    written_char = next_char
                    i += 2
                else:
                    raise ValueError(f"Invalid escape: backslash followed by '{next_char}' at position {i}")
            elif data[i].isdigit():
                # After a count, a digit without backslash is invalid because
                # it would be ambiguous - the count would absorb it
                # Actually, let's think: after a count like '12', if next is '5',
                # is it count 125? No, the count is already parsed.
                # So '5' after '12' means count=12, written_char='5'?
                # But '5' is a digit, which should be escaped as '\5'
                # So this is invalid.
                raise ValueError(f"Digit '{data[i]}' after count at position {i} must be escaped with backslash")
            else:
                # Any non-digit, non-backslash character is valid as-is
                written_char = data[i]
