"""Business-day arithmetic on datetime.date values."""

import datetime
from datetime import date, timedelta
from typing import Iterable


def _validate_weekend(weekend: Iterable[int]) -> frozenset[int]:
    """Validate and normalize the weekend parameter.

    Ensures that weekend entries are integers from 0 to 6, and that at least
    one weekday remains a working day.
    """
    ws = frozenset(weekend)
    for w in ws:
        # bool is a subclass of int, so explicitly reject it
        if not isinstance(w, int) or isinstance(w, bool):
            raise ValueError(f"weekend entries must be integers from 0 to 6, got {w!r}")
        if w < 0 or w > 6:
            raise ValueError(f"weekend entries must be integers from 0 to 6, got {w}")
    if len(ws) == 7:
        raise ValueError("weekend must leave at least one working day")
    return ws


def _normalize_holidays(holidays: Iterable[date]) -> frozenset[date]:
    """Normalize holidays to a frozenset of date objects.

    Filters out non-date objects and datetime objects (since datetime is a 
    subclass of date, we want strict date objects).
    """
    return frozenset(
        h for h in holidays 
        if isinstance(h, date) and not isinstance(h, datetime.datetime)
    )


def is_business_day(d: date, *, holidays: Iterable[date] = (), weekend: Iterable[int] = (5, 6)) -> bool:
    """Check if a date is a business day.

    A business day is a date whose weekday is not in weekend and that is not in holidays.
    """
    ws = _validate_weekend(weekend)
    hs = _normalize_holidays(holidays)
    wd = d.weekday()
    if wd in ws:
        return False
    if d in hs:
        return False
    return True


def business_days_between(
    start: date,
    end: date,
    *,
    include_start: bool = True,
    include_end: bool = False,
    holidays: Iterable[date] = (),
    weekend: Iterable[int] = (5, 6),
) -> int:
    """Count the number of business days from start to end.

    With defaults (include_start=True, include_end=False), the range is half-open.
    If start > end, raise ValueError.
    """
    if not isinstance(start, date) or isinstance(start, datetime.datetime):
        raise TypeError("start must be a datetime.date")
    if not isinstance(end, date) or isinstance(end, datetime.datetime):
        raise TypeError("end must be a datetime.date")

    ws = _validate_weekend(weekend)
    hs = _normalize_holidays(holidays)

    if start > end:
        raise ValueError("start must not be after end")

    def is_bd(d: date) -> bool:
        wd = d.weekday()
        if wd in ws:
            return False
        if d in hs:
            return False
        return True

    # Handle start == end case explicitly as per requirements
    if start == end:
        if include_start and include_end and is_bd(start):
            return 1
        return 0

    # Count business days in the range [start, end] respecting include flags
    count = 0
    current = start

    # Iterate from start up to but not including end
    while current < end:
        if is_bd(current):
            # Include start only if include_start is True
            if current == start:
                if include_start:
                    count += 1
            else:
                # Interior points are always included if they are business days
                count += 1
        current += timedelta(days=1)

    # Check end date separately
    if current == end and is_bd(end):
        if include_end:
            count += 1

    return count


def add_business_days(
    d: date,
    n: int,
    *,
    holidays: Iterable[date] = (),
    weekend: Iterable[int] = (5, 6),
) -> date:
    """Add n business days to d.

    For n > 0: the n-th business day after d (d itself is never counted).
    For n < 0: the |n|-th business day before d.
    For n == 0: d itself if it is a business day, otherwise the first business day after d.
    """
    if not isinstance(d, date) or isinstance(d, datetime.datetime):
        raise TypeError("d must be a datetime.date")
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")

    ws = _validate_weekend(weekend)
    hs = _normalize_holidays(holidays)

    def is_bd(dt: date) -> bool:
        wd = dt.weekday()
        if wd in ws:
            return False
        if dt in hs:
            return False
        return True

    if n == 0:
        if is_bd(d):
            return d
        # Find the first business day after d
        result = d + timedelta(days=1)
        while not is_bd(result):
            result += timedelta(days=1)
        return result

    step = timedelta(days=1) if n > 0 else timedelta(days=-1)
    remaining = abs(n)

    # Start looking one day away from d
    if n > 0:
        current = d + step
    else:
        current = d + step  # step is -1 day

    while remaining > 0:
        if is_bd(current):
            remaining -= 1
        if remaining > 0:
            current += step

    return current
