import time

class TokenBucket:
    """Token bucket rate limiter."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        # Validate that rate and capacity are numbers (int or float) and greater than 0
        # Use not (val > 0) to catch NaN and non-positive numbers correctly
        if not isinstance(rate, (int, float)):
            raise ValueError("rate must be a number greater than 0")
        if not isinstance(capacity, (int, float)):
            raise ValueError("capacity must be a number greater than 0")

        if not (rate > 0):
            raise ValueError("rate must be greater than 0")
        if not (capacity > 0):
            raise ValueError("capacity must be greater than 0")

        self._rate = rate
        self._capacity = capacity
        self._clock = clock
        self._last_time = clock()
        # Initialize as float to ensure consistent return types from available()
        self._tokens = float(capacity)

    def _refill(self):
        now = self._clock()
        if now <= self._last_time:
            return
