        if day_matches(parsed, year, month, day):
            # If this is the starting day, we respect the start hour/minute
            # Otherwise, we start at 0:00
            if year == candidate.year and month == candidate.month and day == candidate.day:
                start_h, start_m = hour, minute
            else:
