import collections.abc


class PathError(LookupError):
    """Error raised for path syntax errors or missing values."""

    def __init__(self, path: str, message: str = None):
        self.path = path
        if message is None:
            message = f"Path error for: {path!r}"
        super().__init__(message)


def parse(path: str) -> list:
    """
    Parse a path string into a list of segments.

    Segments are either str (names/keys) or int (indices).

    Raises PathError on syntax errors.
    """
    if path == "":
        return []

    segments = []
    i = 0
    n = len(path)

    # We need to handle the first segment specially: it can be a bare name
    # After that, names must be preceded by '.' and brackets follow directly

    first = True
    while i < n:
