                result, i = _parse_bracket(path, i, n, first_segment=True)
                segments.extend(result)
                first = False
            elif path[i] == '.':
                raise PathError(path, "Path cannot start with '.'")
            else:
                # Bare name
                name, i = _parse_bare_name(path, i, n)
                if name is None:
                    raise PathError(path, f"Invalid character at position {i}")
                segments.append(name)
                first = False
        else:
            # Not first segment
            if path[i] == '.':
                i += 1  # consume the dot
                # After a dot, we expect a name (not empty)
                if i >= n:
                    raise PathError(path, "Path ends with '.'")
                if path[i] == '.':
                    raise PathError(path, "Empty name between dots")
                if path[i] == '[':
                    raise PathError(path, "Dot before bracket is not allowed")
                name, i = _parse_bare_name(path, i, n)
                if name is None:
                    raise PathError(path, f"Invalid character at position {i}")
                segments.append(name)
            elif path[i] == '[':
                result, i = _parse_bracket(path, i, n, first_segment=False)
                segments.extend(result)
            else:
                raise PathError(path, f"Unexpected character at position {i}")

    return segments


def _parse_bare_name(path: str, i: int, n: int):
    """Parse a bare name starting at position i. Returns (name_str or None, new_i)."""
    start = i
    while i < n and path[i] not in ('.', '[', ']', '"'):
        i += 1
    if i == start:
        return None, i
    return path[start:i], i


def _parse_bracket(path: str, i: int, n: int, first_segment: bool):
    """Parse a bracket expression starting at position i (which is '['). Returns (list_of_segments, new_i)."""
