"""
jpath.py - Utility for reading, writing, and deleting values in nested JSON-like data.
"""

import collections.abc


class PathError(LookupError):
    """Exception raised for errors in path parsing or navigation."""

    def __init__(self, path: str, message: str = None):
        self.path = path
        if message is None:
            message = f"Path error for: {path}"
        super().__init__(message)


# Sentinel for wildcard segments
WILDCARD = object()

# Sentinel for distinguishing 'default not provided' from 'default=None'
_MISSING = object()


def parse(path: str) -> list:
    """
    Parses a path string into a list of segments.
    Segments can be:
    - str: names or quoted keys
    - int: indices
    - WILDCARD: for [*]

    Raises PathError on syntax errors.
    """
    if not isinstance(path, str):
        raise PathError(path, "Path must be a string")

    if path == "":
        return []

    segments = []
    i = 0
    n = len(path)

    def parse_bare_name(start_idx):
        j = start_idx
        while j < n and path[j] not in ('.', '[', ']', '"'):
            j += 1
        if j == start_idx:
            return None, j
        return path[start_idx:j], j

    while i < n:
        # Determine if we expect a dot separator (after the first segment if the previous was a name/key)
        # The first segment can be a name or a bracket.
        # Subsequent names must be preceded by a dot.
        # Subsequent brackets can follow directly.

        if i > 0:
            prev_seg = segments[-1]
            # If previous segment was a name (str that isn't from quoted key? No, parse distinguishes them)
            # Actually, the spec says: "A name is... the first segment may be a bare name; every later name is written after a ."
            # "Brackets follow the previous segment directly"
            # So if current char is '.', it must be followed by a name.
            # If current char is '[', it can follow anything.

            if path[i] == '.':
                # Expect a name
                # Check if next char is invalid
                if i + 1 >= n:
                    raise PathError(path, "Empty name at end of path")
                # Quoted keys cannot start with dot? `a."b"` is syntax error.
                # `a.["b"]` is syntax error.
                # So after dot, we must see a valid bare name char.
                # Valid chars for bare name start: anything not '.', '[', ']', '"'
                start_idx = i + 1
                name, new_i = parse_bare_name(start_idx)
                if name is None:
                    raise PathError(path, f"Empty name after '.' at index {i}")
                segments.append(name)
                i = new_i
                continue
            elif path[i] == '[':
                # Bracket follows directly, no dot. Proceed to parse bracket.
                pass
            else:
                raise PathError(path, f"Expected '.' or '[' after previous segment at index {i}")

        # Parse a segment
        if path[i] == '[':
            # Parse bracket segment
            i += 1
            if i >= n:
                raise PathError(path, "Unclosed bracket")

            if path[i] == '"':
                # Quoted key
                i += 1
                start_idx = i
                parts = []
                while i < n:
                    c = path[i]
                    if c == '\\':
                        i += 1
                        if i >= n:
                            raise PathError(path, "Unclosed escape sequence in quoted key")
                        next_c = path[i]
                        if next_c == '"':
                            parts.append('"')
                        elif next_c == '\\':
                            parts.append('\\')
                        else:
                            raise PathError(path, f"Invalid escape sequence \\{next_c}")
                        i += 1
                    elif c == '"':
                        # End of quoted string
                        i += 1
                        break
                    else:
                        parts.append(c)
                        i += 1
                else:
                    raise PathError(path, "Unclosed quoted key")

                # Now expect ']'
                if i >= n or path[i] != ']':
                    raise PathError(path, "Expected ']' after quoted key")
                i += 1
                segments.append("".join(parts))

            elif path[i] == '*':
                # Wildcard
                i += 1
                if i >= n or path[i] != ']':
                    raise PathError(path, "Expected ']' after wildcard")
                i += 1
                segments.append(WILDCARD)
            else:
                # Integer index
                start_idx = i
                # Handle optional sign
                if path[i] == '-':
                    i += 1
                    if i >= n or not path[i].isdigit():
                        raise PathError(path, "Invalid integer index")
                elif not path[i].isdigit():
                    raise PathError(path, "Invalid integer index")

                # Consume digits
                while i < n and path[i].isdigit():
                    i += 1

                # Check for closing bracket
                if i >= n or path[i] != ']':
                    raise PathError(path, "Unclosed bracket or invalid content in bracket")
                i += 1

                num_str = path[start_idx:i-1] # Exclude the closing ]
                try:
                    val = int(num_str)
                except ValueError:
                    raise PathError(path, f"Invalid integer index: {num_str}")

                segments.append(val)

        elif i == 0:
            # First segment, bare name
            name, new_i = parse_bare_name(i)
            if name is None:
                raise PathError(path, "Empty name at start of path")
            segments.append(name)
            i = new_i
        else:
            # Should have been handled by the dot check above
            raise PathError(path, f"Unexpected character at index {i}")

    return segments


