    """
    Recursive helper to resolve wildcards.
    Returns a list of values found.
    """
    # current_values is a list of (parent_container, key, value) or just values?
    # Actually, easier: pass down the list of objects we are currently considering.
    pass


def get(obj, path: str, default=_MISSING):
