    Retrieves a value from obj using the path.

    If the path contains wildcards, returns a list of all matching values.
    If the path does not contain wildcards:
      - Returns the value if found.
      - Returns default if provided and value is missing.
      - Raises PathError if no default and value is missing.

    Syntax errors always raise PathError.
    """
    segments = parse(path)

    if not segments:
        return obj

    has_wildcard = any(seg is WILDCARD for seg in segments)

    if has_wildcard:
        # Use recursive resolution for wildcards
        results = []

        def resolve(current_obj, idx, results_list):
            if idx == len(segments):
                results_list.append(current_obj)
                return

            seg = segments[idx]

            if seg is WILDCARD:
                # Iterate over all elements
                if isinstance(current_obj, (list, tuple)):
                    for item in current_obj:
                        resolve(item, idx + 1, results_list)
                elif isinstance(current_obj, collections.abc.Mapping):
                    for key in current_obj:
                        resolve(current_obj[key], idx + 1, results_list)
                # Otherwise, matches nothing, stop branch

            else:
                # Regular segment
                try:
                    if isinstance(seg, int):
                        if isinstance(current_obj, (list, tuple)):
                            next_obj = current_obj[seg]
                            resolve(next_obj, idx + 1, results_list)
                    elif isinstance(seg, str):
                        if isinstance(current_obj, collections.abc.Mapping):
                            if seg in current_obj:
                                next_obj = current_obj[seg]
                                resolve(next_obj, idx + 1, results_list)
                    # If types don't match, stop branch (missing value)
                except (IndexError, KeyError, TypeError):
                    pass

        resolve(obj, 0, results)
        return results
    else:
        # No wildcards, simple traversal
        current = obj
        for seg in segments:
            try:
                if isinstance(seg, int):
                    if not isinstance(current, (list, tuple)):
                        raise IndexError("Cannot index non-list/tuple with int")
                    current = current[seg]
                elif isinstance(seg, str):
                    if not isinstance(current, collections.abc.Mapping):
                        raise KeyError("Cannot key non-mapping with str")
                    if seg not in current:
                        raise KeyError(f"Key {seg} not found")
                    current = current[seg]
                else:
                    # Should not happen as parse ensures int or str
                    raise TypeError("Invalid segment type")
            except (IndexError, KeyError, TypeError):
                if default is not _MISSING:
                    return default
                else:
                    raise PathError(path, "Value not found")
        return current


def set(obj, path: str, value) -> None:
    """
    Sets a value in obj at the specified path.
    Creates intermediate containers (dicts or lists) as needed.
    """
    segments = parse(path)

    if not segments:
        raise PathError(path, "Path must have at least one segment")

    if any(seg is WILDCARD for seg in segments):
        raise PathError(path, "Wildcards not allowed in set path")

    # Navigate to the parent of the final segment
    # We need to ensure intermediate structures exist.

    def ensure_container(parent, seg, next_seg_is_index):
        """
        Returns the object at 'seg' in 'parent', creating it if necessary.
        If 'seg' exists, returns it.
        If 'seg' is missing, creates list (if next_seg_is_index) or dict.
        Returns (container, is_newly_created) -> actually just the container.
        """
        if isinstance(parent, collections.abc.Mapping):
            if not isinstance(seg, str):
                raise PathError(path, f"Expected string key for dict, got {type(seg).__name__}")

