            if idx == len(segments):
                results_list.append(current_obj)
                return

            seg = segments[idx]

            if seg is WILDCARD:
                # Iterate over all elements
                if isinstance(current_obj, (list, tuple)):
                    for item in current_obj:
                        resolve(item, idx + 1, results_list)
                elif isinstance(current_obj, collections.abc.Mapping):
                    for key in current_obj:
                        resolve(current_obj[key], idx + 1, results_list)
                # Otherwise, matches nothing, stop branch

            else:
                # Regular segment
                # We use a try-except block to handle missing keys/indices gracefully as "skip branch"
                try:
                    if isinstance(seg, int):
                        if isinstance(current_obj, (list, tuple)):
                            next_obj = current_obj[seg]
                            resolve(next_obj, idx + 1, results_list)
                        # If not list/tuple, do nothing (skip branch)
                    elif isinstance(seg, str):
                        if isinstance(current_obj, collections.abc.Mapping):
                            if seg in current_obj:
                                next_obj = current_obj[seg]
                                resolve(next_obj, idx + 1, results_list)
                        # If not Mapping, do nothing (skip branch)
                except (IndexError, KeyError, TypeError):
                    # If indexing fails, skip this branch
                    pass

        resolve(obj, 0, results)
        return results
    else:
        # No wildcards, simple traversal
        current = obj
        for seg in segments:
            try:
                if isinstance(seg, int):
                    if not isinstance(current, (list, tuple)):
                        raise KeyError("Cannot index non-list/tuple with int")
                    current = current[seg]
                elif isinstance(seg, str):
                    if not isinstance(current, collections.abc.Mapping):
                        raise KeyError("Cannot key non-mapping with str")
                    if seg not in current:
                        raise KeyError(f"Key {seg} not found")
                    current = current[seg]
                else:
                    # Should not happen as parse ensures int or str
                    raise KeyError("Invalid segment type")
            except (IndexError, KeyError, TypeError):
                if default is not _MISSING:
                    return default
                else:
                    raise PathError(path, "Value not found")
        return current


def set(obj, path: str, value) -> None:
    """
    Sets a value in obj at the specified path.
    Creates intermediate containers (dicts or lists) as needed.

    Atomic: If an error occurs, obj is left unchanged.
    """
    segments = parse(path)

    if not segments:
        raise PathError(path, "Path must have at least one segment")

    if any(seg is WILDCARD for seg in segments):
        raise PathError(path, "Wildcards not allowed in set path")

    # We will perform the operation step by step.
    # To ensure atomicity, we collect a list of undo operations.
    # If we fail, we replay the undo operations in reverse.

    current = obj
    changes = [] # List of (type, container, key, old_val, existed)

    try:
        # Iterate through all segments except the last
        for i in range(len(segments) - 1):
            seg = segments[i]
            next_seg = segments[i + 1]

            if isinstance(seg, int):
                if not isinstance(current, (list, tuple)):
                    raise PathError(path, f"Cannot index {type(current).__name__} with int")

                # Tuples can be indexed (read/traverse), but cannot be modified (appended to/replaced in).
                # For intermediate segments, we are just traversing.
                # If we need to CREATE a container here (because the slot is missing/append),
                # that counts as modifying the container.

                n = len(current)
                if -n <= seg <= n - 1:
                    # Element exists, just traverse
                    current = current[seg]
                elif seg == n:
                    # Need to append a new container. This modifies the current container.
                    if isinstance(current, tuple):
                        raise PathError(path, "Cannot append to tuple")

                    if isinstance(next_seg, int):
                        new_container = []
                    else:
                        new_container = {}

                    # Record undo: pop the appended item
                    changes.append(('list_append', current, n, None, False))
                    current.append(new_container)
                    current = new_container
                else:
                    raise PathError(path, f"Index {seg} out of range")

            elif isinstance(seg, str):
                if not isinstance(current, collections.abc.Mapping):
                    raise PathError(path, f"Cannot access key in {type(current).__name__}")

                if seg in current:
                    # Traverse
                    current = current[seg]
                else:
                    # Create new container. This modifies the current container.
                    if isinstance(next_seg, int):
                        new_container = []
                    else:
                        new_container = {}

                    # Record undo: del key
                    changes.append(('dict_add', current, seg, None, False))
                    current[seg] = new_container
                    current = new_container
            else:
                raise PathError(path, f"Invalid segment type: {type(seg)}")

        # Handle the last segment
        last_seg = segments[-1]

        if isinstance(last_seg, int):
            if not isinstance(current, (list, tuple)):
                raise PathError(path, f"Cannot index {type(current).__name__} with int")
            if isinstance(current, tuple):
                raise PathError(path, "Cannot modify tuple")

            n = len(current)
            if -n <= last_seg <= n - 1:
                # Replace existing
                old_val = current[last_seg]
                changes.append(('list_replace', current, last_seg, old_val, True))
                current[last_seg] = value
            elif last_seg == n:
                # Append
                changes.append(('list_append', current, n, None, False))
                current.append(value)
            else:
                raise PathError(path, f"Index {last_seg} out of range")

        elif isinstance(last_seg, str):
            if not isinstance(current, collections.abc.Mapping):
                raise PathError(path, f"Cannot access key in {type(current).__name__}")

            if last_seg in current:
                # Replace
                old_val = current[last_seg]
                changes.append(('dict_replace', current, last_seg, old_val, True))
                current[last_seg] = value
            else:
                # Add
                changes.append(('dict_add', current, last_seg, None, False))
                current[last_seg] = value
        else:
             raise PathError(path, f"Invalid segment type: {type(last_seg)}")

    except PathError:
        # Undo all changes in reverse order
        for change in reversed(changes):
            op_type, container, key, old_val, existed = change

            if op_type == 'dict_add':
                # The key was added, so remove it
                if key in container:
                    del container[key]
            elif op_type == 'dict_replace':
                # Restore old value
                container[key] = old_val
            elif op_type == 'list_append':
                # Pop the appended item
                # The length of the list should be key + 1 (since key was old length)
                if len(container) > key:
                    container.pop()
            elif op_type == 'list_replace':
                # Restore old value
                container[key] = old_val

        raise

def delete(obj, path: str):
    """
    Deletes the value at path from obj.
    Returns the deleted value.
    """
    segments = parse(path)

    if not segments:
        raise PathError(path, "Cannot delete from empty path")

    if any(seg is WILDCARD for seg in segments):
        raise PathError(path, "Wildcards not allowed in delete path")

    # Navigate to parent of the final segment
    parent = obj
    for seg in segments[:-1]:
        if isinstance(seg, int):
            if not isinstance(parent, (list, tuple)):
                raise PathError(path, "Cannot navigate into non-list/tuple with int")
            try:
                parent = parent[seg]
            except IndexError:
                raise PathError(path, "Path not found (index out of range)")
        elif isinstance(seg, str):
            if not isinstance(parent, collections.abc.Mapping):
                raise PathError(path, "Cannot navigate into non-mapping with str")
            if seg not in parent:
                raise PathError(path, "Path not found (key missing)")
            parent = parent[seg]
        else:
            raise PathError(path, "Invalid segment type")

    # Now delete from parent
    last_seg = segments[-1]

    if isinstance(parent, collections.abc.Mapping):
        if not isinstance(last_seg, str):
            raise PathError(path, "Expected string key for mapping")
        if last_seg not in parent:
            raise PathError(path, "Key not found")
        return parent.pop(last_seg)

    elif isinstance(parent, list):
        if not isinstance(last_seg, int):
            raise PathError(path, "Expected integer index for list")
        n = len(parent)
        # Check if index is valid
        if -n <= last_seg < n:
            # Python pop handles negative indices correctly
            return parent.pop(last_seg)
        else:
            raise PathError(path, f"Index {last_seg} out of range")

    elif isinstance(parent, tuple):
        raise PathError(path, "Cannot delete from tuple")

    else:
        raise PathError(path, "Parent is not a dict or list")
