            raise ValueError("Each row must be a list of 9 cells")
        for cell in row:
            if not isinstance(cell, int) or isinstance(cell, bool):
                raise ValueError("Each cell must be an integer")
            if cell < 0 or cell > 9:
                raise ValueError("Each cell must be between 0 and 9")

def parse(text: str) -> list[list[int]]:
    """Parse a sudoku string into a 9x9 grid."""
    cells = []
    for char in text:
        if char in ' \t\n\r':
            continue
        if char == '.':
            cells.append(0)
        elif '1' <= char <= '9':
            cells.append(int(char))
        elif char == '0':
            cells.append(0)
        else:
            raise ValueError(f"Invalid character: {char}")

    if len(cells) != 81:
        raise ValueError(f"Expected 81 cells, got {len(cells)}")

    grid = [cells[i*9:(i+1)*9] for i in range(9)]
    _validate_grid(grid)
    return grid

def to_string(grid: list[list[int]]) -> str:
    """Convert a grid to a string representation."""
    _validate_grid(grid)
    result = []
    for row in grid:
        for cell in row:
            if cell == 0:
                result.append('.')
            else:
                result.append(str(cell))
    return ''.join(result)

def is_valid(grid: list[list[int]]) -> bool:
    """Check if the grid is valid (no conflicts among givens)."""
    _validate_grid(grid)

    # Check rows
    for row in grid:
        seen = set()
        for cell in row:
            if cell != 0:
                if cell in seen:
                    return False
                seen.add(cell)

    # Check columns
    for col in range(9):
        seen = set()
        for row in range(9):
            cell = grid[row][col]
            if cell != 0:
                if cell in seen:
                    return False
                seen.add(cell)

    # Check 3x3 boxes
    for box_row in range(3):
        for box_col in range(3):
            seen = set()
            for r in range(3):
                for c in range(3):
                    cell = grid[box_row * 3 + r][box_col * 3 + c]
                    if cell != 0:
                        if cell in seen:
                            return False
                        seen.add(cell)

    return True

def _get_possible_values(grid: list[list[int]], row: int, col: int) -> set[int]:
    """Get possible values for a cell at (row, col)."""
    if grid[row][col] != 0:
        return set()

    used = set()

    # Check row
    for c in range(9):
        if grid[row][c] != 0:
            used.add(grid[row][c])

    # Check column
    for r in range(9):
        if grid[r][col] != 0:
            used.add(grid[r][col])

    # Check box
    box_row = (row // 3) * 3
    box_col = (col // 3) * 3
    for r in range(box_row, box_row + 3):
        for c in range(box_col, box_col + 3):
            if grid[r][c] != 0:
                used.add(grid[r][c])

    return set(range(1, 10)) - used

def _find_empty_cell(grid: list[list[int]]) -> tuple[int, int] | None:
    """Find the first empty cell, or None if none found."""
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                return (r, c)
    return None

def _solve_helper(grid: list[list[int]]) -> bool:
    """Helper function to solve the sudoku grid in-place."""
    cell = _find_empty_cell(grid)
    if cell is None:
        return True

    row, col = cell
    possible = _get_possible_values(grid, row, col)

    for val in possible:
        grid[row][col] = val
        if _solve_helper(grid):
            return True
        grid[row][col] = 0

    return False

def solve(grid: list[list[int]]) -> list[list[int]] | None:
    """Solve the sudoku puzzle, returning a new grid or None if unsolvable."""
    _validate_grid(grid)

    if not is_valid(grid):
        return None

    # Make a deep copy to avoid modifying the input
    working_grid = copy.deepcopy(grid)

    if _solve_helper(working_grid):
        return working_grid
    else:
        return None

def count_solutions(grid: list[list[int]], limit: int = 2) -> int:
    """Count the number of solutions, stopping early when limit is reached."""
    if limit < 1:
        raise ValueError("Limit must be at least 1")

    _validate_grid(grid)

    if not is_valid(grid):
        return 0

    working_grid = copy.deepcopy(grid)
    count = 0

    def _count_helper(g: list[list[int]]) -> bool:
        nonlocal count
        if count >= limit:
            return True  # Stop counting

        cell = _find_empty_cell(g)
        if cell is None:
            count += 1
            return count >= limit

        row, col = cell
        possible = _get_possible_values(g, row, col)

        for val in possible:
            g[row][col] = val
            if _count_helper(g):
                g[row][col] = 0
                return True
            g[row][col] = 0

        return False

    _count_helper(working_grid)
    return min(count, limit)
