    """
    Solves the sudoku puzzle. Returns a new grid if solved, None otherwise.
    Does not modify the input grid.
    """
    _validate_grid_structure(grid)

    if not is_valid(grid):
        return None

    # Create a deep copy to work on so we don't modify the original
    working_grid = copy.deepcopy(grid)

    # Get list of empty cells
    empties = []
    for r in range(9):
        for c in range(9):
            if working_grid[r][c] == 0:
                empties.append((r, c))

    # Helper to get valid moves for a cell
    def get_valid_moves(r: int, c: int) -> set[int]:
        used = set()
        # Row
        for i in range(9):
            if working_grid[r][i] != 0:
                used.add(working_grid[r][i])
        # Column
        for i in range(9):
            if working_grid[i][c] != 0:
                used.add(working_grid[i][c])
        # Box
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if working_grid[i][j] != 0:
                    used.add(working_grid[i][j])

        return set(range(1, 10)) - used

    # Backtracking
    def backtrack(idx: int) -> bool:
        if idx == len(empties):
            return True

        r, c = empties[idx]
        moves = get_valid_moves(r, c)

        for move in moves:
            working_grid[r][c] = move
            if backtrack(idx + 1):
                return True
            working_grid[r][c] = 0

        return False

    if backtrack(0):
        return working_grid
    else:
        return None

def count_solutions(grid: list[list[int]], limit: int = 2) -> int:
    """
    Counts the number of solutions, stopping at limit.
    Returns min(number_of_solutions, limit).
    Invalid grid returns 0.
    """
    if limit < 1:
        raise ValueError("limit must be at least 1")

    _validate_grid_structure(grid)

    if not is_valid(grid):
        return 0

    # Create a deep copy to work on
    working_grid = copy.deepcopy(grid)

    empties = []
    for r in range(9):
        for c in range(9):
            if working_grid[r][c] == 0:
                empties.append((r, c))

    def get_valid_moves(r: int, c: int) -> set[int]:
        used = set()
        for i in range(9):
            if working_grid[r][i] != 0:
                used.add(working_grid[r][i])
        for i in range(9):
            if working_grid[i][c] != 0:
                used.add(working_grid[i][c])
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if working_grid[i][j] != 0:
                    used.add(working_grid[i][j])
        return set(range(1, 10)) - used

    def backtrack(idx: int, count: int) -> int:
        if idx == len(empties):
            return count + 1

        r, c = empties[idx]
        moves = get_valid_moves(r, c)

        current_count = count
        for move in moves:
            working_grid[r][c] = move
            current_count = backtrack(idx + 1, current_count)
            working_grid[r][c] = 0

            if current_count >= limit:
                return limit

        return current_count

    total_solutions = backtrack(0, 0)
    return min(total_solutions, limit)
