def _unit_indices():
    """
    Generate all units (rows, columns, boxes) as lists of (row, col) indices.
    Returns list of 27 units, each a list of 9 (row, col) tuples.
    Order: rows 0-8, then columns 0-8, then boxes 0-8.
    """
    units = []
