    for r in range(9):
        units.append([(r, c) for c in range(9)])
    # Columns
    for c in range(9):
        units.append([(r, c) for r in range(9)])
    # Boxes
    for b in range(9):
        br = 3 * (b // 3)
        bc = 3 * (b % 3)
        cells = []
        for dr in range(3):
            for dc in range(3):
                cells.append((br + dr, bc + dc))
        units.append(cells)
    return units


def _row_units():
    """Generate row units."""
    return [( [(r, c) for c in range(9)] ) for r in range(9)]


def _col_units():
    """Generate column units."""
    return [( [(r, c) for r in range(9)] ) for c in range(9)]


def _box_units():
    """Generate box units."""
    units = []
    for b in range(9):
