    empty_cells = []
    for r in range(9):
        for c in range(9):
            if working[r][c] == 0:
                empty_cells.append((r, c))

    if not empty_cells:
        # Already complete and valid
        return 1

    count = _count_solutions_helper(working, empty_cells, 0, 0, limit)
    return count


def hint(grid: list[list[int]]) -> tuple[int, int, int, str] | None:
    """
    Find the next logical step for solving the puzzle.

    Returns (row, col, digit, reason) for the first applicable step, or None.

    Steps in order:
    1. Naked single: first empty cell (row-major) with exactly one candidate.
    2. Hidden single: first digit (rows 0-8, then cols 0-8, then boxes 0-8) that 
       appears as a candidate in exactly one empty cell of that unit.

    Raises ValueError if grid has bad shape or is not valid.
    """
