    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = _candidates_for_cell(grid, r, c)
                if len(candidates) == 1:
                    digit = next(iter(candidates))
                    return (r, c, digit, 'naked single')

