    def _find_hidden_single_in_unit(unit_cells, unit_type, unit_index):
        for digit in range(1, 10):
            # Skip if digit already present in the unit
            if _digit_in_cells(unit_cells, digit):
                continue

            # Find empty cells in this unit where digit is a candidate
            positions = []
            for r, c in unit_cells:
                if grid[r][c] == 0:
                    candidates = _candidates_for_cell(grid, r, c)
                    if digit in candidates:
                        positions.append((r, c))

            if len(positions) == 1:
                r, c = positions[0]
                if unit_type == 'row':
                    reason = 'hidden single in row'
                elif unit_type == 'column':
                    reason = 'hidden single in column'
                else: # box
                    reason = 'hidden single in box'
                return (r, c, digit, reason)

        return None

    # Check Rows 0-8
    for r in range(9):
        unit_cells = [(r, c) for c in range(9)]
        result = _find_hidden_single_in_unit(unit_cells, 'row', r)
        if result:
            return result

    # Check Columns 0-8
    for c in range(9):
        unit_cells = [(r, c) for r in range(9)]
        result = _find_hidden_single_in_unit(unit_cells, 'column', c)
        if result:
            return result

    # Check Boxes 0-8
    for b in range(9):
        br = 3 * (b // 3)
        bc = 3 * (b % 3)
        unit_cells = []
        for dr in range(3):
            for dc in range(3):
                unit_cells.append((br + dr, bc + dc))
        result = _find_hidden_single_in_unit(unit_cells, 'box', b)
        if result:
            return result

    return None


def difficulty(grid: list[list[int]]) -> dict[str, int] | None:
    """
    Determine the difficulty of a puzzle by counting steps needed to solve.

    Works on a copy of the grid, repeatedly applying hint() until complete.
    Returns {'naked': N, 'hidden': H} counting steps of each type,
    or None if the puzzle cannot be solved with just naked/hidden singles.

    Raises ValueError if grid has bad shape or is not valid.
    Never modifies the argument.
    """
    _validate_grid(grid)

    if not is_valid(grid):
        raise ValueError("Grid is not valid")

    # Make a working copy
    working = [row[:] for row in grid]

    naked_count = 0
    hidden_count = 0

    def is_complete(g):
        for r in range(9):
            for c in range(9):
                if g[r][c] == 0:
                    return False
        return True

    while not is_complete(working):
        h = hint(working)
        if h is None:
            return None

        r, c, digit, reason = h
        working[r][c] = digit

        if reason == 'naked single':
            naked_count += 1
        else:
            # All hidden singles count towards hidden_count
            hidden_count += 1

    return {'naked': naked_count, 'hidden': hidden_count}
