# events.py

from typing import Any, Callable, Hashable


class EmitError(Exception):
    """Raised when one or more listeners raise exceptions during emit."""

    def __init__(self, errors: list[tuple[Callable, Exception]]):
        self.errors = errors
        super().__init__(f"{len(errors)} listener(s) raised exceptions")


class Emitter:
    """A small synchronous event emitter."""

    def __init__(self):
        # Map from event to list of (listener, is_once) tuples
        # We use a list to preserve registration order and allow duplicates.
        self._listeners: dict[Hashable, list[tuple[Callable, bool]]] = {}

    def on(self, event: Hashable, listener: Callable) -> Callable:
        """Register a listener for an event. Returns the listener."""
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append((listener, False))
        return listener

    def once(self, event: Hashable, listener: Callable) -> Callable:
        """Register a one-time listener for an event. Returns the listener."""
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append((listener, True))
        return listener

    def off(self, event: Hashable, listener: Callable | None = None) -> int:
        """
        Remove the earliest remaining registration of listener for event (if listener is not None),
        returning 1 if removed, 0 otherwise.
        If listener is None, remove all registrations for the event, returning the count removed.
        """
        if event not in self._listeners:
            return 0

        if listener is None:
            count = len(self._listeners[event])
            del self._listeners[event]
            return count

        registrations = self._listeners[event]
        for i, (reg_listener, _) in enumerate(registrations):
            if reg_listener is listener:
                # Remove the earliest matching registration
                del registrations[i]
                # Clean up empty lists
                if not registrations:
                    del self._listeners[event]
                return 1
        return 0

    def emit(self, event: Hashable, *args: Any, **kwargs: Any) -> int:
        """
        Call all listeners registered for event in registration order.
        Returns the number of calls made.
        If any listeners raise exceptions, the remaining listeners still run,
        and an EmitError is raised after all listeners have been called.
        The set of listeners is fixed when emit starts.
        """
        if event not in self._listeners:
            return 0

        # Take a snapshot of the listeners at the start of emit
        snapshot = list(self._listeners[event])

        call_count = 0
        errors: list[tuple[Callable, Exception]] = []

        for listener, is_once in snapshot:
            call_count += 1

            # If it's a once listener, remove its registration before calling it.
            # We need to remove exactly one occurrence of this listener that was marked as once.
            if is_once:
                # Find and remove the first matching (listener, True) entry in the current list
                current_list = self._listeners.get(event, [])
                for i, (reg_listener, reg_is_once) in enumerate(current_list):
                    if reg_listener is listener and reg_is_once:
                        del current_list[i]
                        # Clean up empty lists
                        if event in self._listeners and not current_list:
                            del self._listeners[event]
                        break

            try:
                listener(*args, **kwargs)
            except Exception as e:
                errors.append((listener, e))

        if errors:
            raise EmitError(errors)

        return call_count

    def listeners(self, event: Hashable) -> list[Callable]:
        """Return a new list of registered listeners for event in order, one entry per registration."""
        if event not in self._listeners:
            return []
        return [listener for listener, _ in self._listeners[event]]
