    if isinstance(x, bool):
        raise TypeError(f"Expected int, Decimal, or str, got {type(x).__name__}")

    if isinstance(x, int):
        result = Decimal(x)
    elif isinstance(x, Decimal):
        if not x.is_finite():
            raise ValueError("Value must be a finite decimal number")
        result = x
    elif isinstance(x, str):
        try:
            result = Decimal(x.strip())
        except InvalidOperation as exc:
            raise ValueError("Not a valid decimal number") from exc
        if not result.is_finite():
            raise ValueError("Value must be a finite decimal number")
    else:
        raise TypeError(
            f"Expected int, Decimal, or str, got {type(x).__name__}"
        )

    return result.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)


def allocate(amount, ratios):
