    Uses the largest-remainder rule on whole cents. A negative amount is
    allocated as the negation of the allocation of its absolute value.

    ratios must be a non-empty list of non-negative int/Decimal values whose
    sum is positive; otherwise ValueError is raised.
    """
    if not isinstance(ratios, (list, tuple)):
        raise ValueError("ratios must be a non-empty list")
    if len(ratios) == 0:
        raise ValueError("ratios must be non-empty")

    for ratio in ratios:
        if isinstance(ratio, bool) or not isinstance(ratio, (int, Decimal)):
            raise ValueError(
                "Each ratio must be a non-negative int or Decimal"
            )
        if ratio < 0:
            raise ValueError("Each ratio must be non-negative")

    ratio_sum = sum(ratios)
    if ratio_sum <= 0:
        raise ValueError("The sum of ratios must be positive")

    amount_decimal = to_cents(amount)

    if amount_decimal < 0:
        absolute_allocation = _allocate_positive(-amount_decimal, ratios)
        return [-value for value in absolute_allocation]
    else:
        return _allocate_positive(amount_decimal, ratios)


def _allocate_positive(amount_decimal, ratios):
    """Allocate a non-negative amount using the largest-remainder rule."""
    total_cents = int((amount_decimal * 100).to_integral_value(rounding=ROUND_DOWN))
    n = len(ratios)

    if total_cents == 0:
        return [Decimal("0.00")] * n

    # Each part's exact share in whole cents: total_cents * ratio / ratio_sum.
    cents = []
    remainders = []
    for ratio in ratios:
        exact_share = Decimal(total_cents) * ratio
        floor_cents, remainder = exact_share.divmod(ratios_sum_cached(ratios))
        cents.append(int(floor_cents))
        remainders.append(remainder)

    # Distribute leftover cents to the parts with the largest remainders;
    # ties are broken by earlier position in the list.
    leftover = total_cents - sum(cents)
    order = sorted(range(n), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        cents[i] += 1

    return [Decimal(cents[i]) / 100 for i in range(n)]


def ratios_sum_cached(ratios):
    # sum() starts from int 0, so mixed int/Decimal ratios combine cleanly.
    return sum(ratios)


