        raise ValueError("n must be at least 1")
    return allocate(amount, [1] * n)


def format_money(amount):
    """Format amount with thousands commas and exactly two decimals.

    Negative amounts get a leading '-'; rounded-zero amounts have no sign.
    """
    value = to_cents(amount)

    if value < 0:
        negative = True
        value = -value
    else:
        negative = False

    text = str(value)
    if "." in text:
        integer_part, fractional_part = text.split(".")
        fractional_part = fractional_part.ljust(2, "0")
