    if ratio_sum <= 0:
        raise ValueError("The sum of ratios must be positive")

    amount_decimal = to_cents(amount)

    if amount_decimal < 0:
        absolute_allocation = _allocate_positive(-amount_decimal, ratios)
        return [-value for value in absolute_allocation]
    else:
        return _allocate_positive(amount_decimal, ratios)


def _allocate_positive(amount_decimal, ratios):
    """Allocate a non-negative amount using the largest-remainder rule."""
    total_cents = int((amount_decimal * 100).to_integral_value(rounding=ROUND_DOWN))
    n = len(ratios)

    if total_cents == 0:
        return [Decimal("0.00")] * n

    ratio_sum = sum(ratios)

    # Each part's exact share in whole cents: total_cents * ratio / ratio_sum.
    cents = []
    remainders = []
    for ratio in ratios:
        exact_share = Decimal(total_cents) * Decimal(ratio)
        floor_cents, remainder = exact_share.divmod(ratio_sum)
        cents.append(int(floor_cents))
        remainders.append(remainder)

    # Distribute leftover cents to the parts with the largest remainders;
    # ties are broken by earlier position in the list.
    leftover = total_cents - sum(cents)
    order = sorted(range(n), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        cents[i] += 1

    # Ensure exactly two decimal places for each part.
    two_places = Decimal("0.01")
    return [Decimal(cents[i]).quantize(two_places) for i in range(n)]


def split_even(amount, n):
    """Split amount evenly among n parts; first parts absorb extra cents."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer with n >= 1")
    if n < 1:
        raise ValueError("n must be at least 1")
    return allocate(amount, [1] * n)


def format_money(amount):
    """Format amount with thousands commas and exactly two decimals.

    Negative amounts get a leading '-'; rounded-zero amounts have no sign.
    """
    value = to_cents(amount)

    # Check if the value is zero (handles both positive and negative zero)
    if value == 0:
        return "0.00"

    negative = value < 0
    if negative:
        value = -value

    text = str(value)
    if "." in text:
        integer_part, fractional_part = text.split(".")
        # Ensure fractional part is exactly 2 digits, though to_cents guarantees it
        fractional_part = fractional_part[:2].ljust(2, "0")
    else:
        integer_part = text
        fractional_part = "00"

    # Insert a comma between groups of three digits.
    grouped = []
    while len(integer_part) > 3:
        grouped.insert(0, integer_part[-3:])
        integer_part = integer_part[:-3]
    grouped.insert(0, integer_part)

    formatted = ",".join(grouped) + "." + fractional_part

    if negative:
        formatted = "-" + formatted

    return formatted
