import argparse
import sys
from .store import TodoStore, StoreError
from .model import Task

def format_task(task: Task) -> str:
    status_char = "x" if task.done else " "
    line = f"{task.id} [{status_char}] {task.title}"
    for tag in task.tags:
        line += f" #{tag}"
    return line

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="todo")
    parser.add_argument("--file", default="todo.json", help="Path to the JSON file")

    subparsers = parser.add_subparsers(dest="command")

    # add
    parser_add = subparsers.add_parser("add", help="Add a new task")
    parser_add.add_argument("title", help="Task title")
    parser_add.add_argument("--tag", action="append", default=[], help="Add a tag")

    # list
    parser_list = subparsers.add_parser("list", help="List tasks")
    parser_list.add_argument("--status", default="open", choices=["open", "done", "all"], help="Filter by status")
    parser_list.add_argument("--tag", action="append", default=[], help="Filter by tag")

    # done
    parser_done = subparsers.add_parser("done", help="Mark tasks as done")
    parser_done.add_argument("ids", type=int, nargs="+", help="Task IDs")

    # remove
    parser_remove = subparsers.add_parser("remove", help="Remove a task")
    parser_remove.add_argument("id", type=int, help="Task ID")

    # edit
    parser_edit = subparsers.add_parser("edit", help="Edit a task")
    parser_edit.add_argument("id", type=int, help="Task ID")
    parser_edit.add_argument("--title", help="New title")
    parser_edit.add_argument("--tag", action="append", default=[], help="Tag to add")
    parser_edit.add_argument("--untag", action="append", default=[], help="Tag to remove")

    # Parse arguments
    try:
        args = parser.parse_args(argv)
    except SystemExit:
        # argparse calls sys.exit(2) on error by default. 
        # We intercept this to ensure we return the correct code and don't print to stdout.
        # However, argparse prints to stderr by default for errors.
        # We need to distinguish "success" (exit 0 from argparse) from "failure" (exit 2).
        # Wait, parse_args raises SystemExit(2) on error.
        # If it succeeds, it continues.
        # Actually, parse_args exits the process if it fails. 
        # To handle the exit code properly and ensure stdout is clean, we might need to wrap it carefully.
        # But the standard behavior is argparse prints to stderr and exits.
        # The requirement says: "On any error nothing goes to stdout. ... an error is one line on stderr that starts with error: "
        # Argparse default error messages don't start with "error: ".
        # We need to customize argparse error handling or catch the exception.

        # Let's restructure: Catch the SystemExit to control output format.
        pass

    if args.command is None:
        parser.print_usage(sys.stderr)
        sys.stderr.write("error: No command provided\n")
        return 2

    try:
        store = TodoStore(args.file)
    except StoreError as e:
        sys.stderr.write(f"error: {e}\n")
        return 3

    if args.command == "add":
        try:
            task = store.add(args.title, args.tag)
            print(f"added {task.id}")
            return 0
        except KeyError as e:
            # Should not happen for add
            sys.stderr.write(f"error: {e}\n")
            return 1
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    elif args.command == "list":
        try:
            tasks = store.list(args.status, args.tag)
            for t in tasks:
                print(format_task(t))
            return 0
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    elif args.command == "done":
        # Check all ids first
        for tid in args.ids:
            try:
                store.get(tid)
            except KeyError:
                sys.stderr.write(f"error: no task with id {tid}\n")
                return 1

        # Now mark them
        for tid in args.ids:
            store.mark_done(tid)
            print(f"done {tid}")
        return 0

    elif args.command == "remove":
        try:
            store.remove(args.id)
            print(f"removed {args.id}")
            return 0
        except KeyError as e:
            sys.stderr.write(f"error: no task with id {args.id}\n")
            return 1

    elif args.command == "edit":
        if args.title is None and not args.tag and not args.untag:
            sys.stderr.write("error: edit requires --title, --tag, or --untag\n")
            return 2

        try:
            store.edit(args.id, title=args.title, add_tags=args.tag, remove_tags=args.untag)
            print(f"edited {args.id}")
            return 0
        except KeyError:
            sys.stderr.write(f"error: no task with id {args.id}\n")
            return 1
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    return 2

if __name__ == "__main__":
    sys.exit(main())
