class ErrorAwareArgumentParser(argparse.ArgumentParser):
    """
    Custom ArgumentParser to ensure that on argument errors, 
    exit code is 2 and stderr starts with 'error: ' as per spec requirements
    when integrated with the return-code-based main.
    However, argparse's default behavior of printing to stderr and raising SystemExit(2)
    is largely compatible if we just catch SystemExit. 
    But the spec says: "Apart from argparse's own messages, an error is one line on stderr that starts with error: ".
