import argparse
import sys
import datetime
from .store import TodoStore, StoreError
from .model import Task, normalize_priority, parse_date

def format_task(task: Task) -> str:
    status_char = "x" if task.done else " "
    line = f"{task.id} [{status_char}] {task.title}"

    if task.priority != "normal":
        line += f" !{task.priority}"

    if task.due is not None:
        line += f" due:{task.due.strftime('%Y-%m-%d')}"

    for tag in task.tags:
        line += f" #{tag}"

    return line

class ErrorAwareArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        super().error(message)

def parse_date_arg(s: str) -> datetime.date:
    try:
        return parse_date(s)
    except ValueError as e:
        raise argparse.ArgumentTypeError(f"invalid date '{s}': {e}")

def parse_priority_arg(s: str) -> str:
    try:
        return normalize_priority(s)
    except ValueError as e:
        raise argparse.ArgumentTypeError(f"invalid priority '{s}': {e}")

def main(argv: list[str] | None = None) -> int:
    # Use the custom parser
    parser = ErrorAwareArgumentParser(prog="todo")
    parser.add_argument("--file", default="todo.json", help="Path to the JSON file")
    parser.add_argument("--today", type=parse_date_arg, help="Override today's date (YYYY-MM-DD)")

    subparsers = parser.add_subparsers(dest="command")

    # add
    parser_add = subparsers.add_parser("add", help="Add a new task")
    parser_add.add_argument("title", help="Task title")
    parser_add.add_argument("--tag", action="append", default=[], help="Add a tag")
    parser_add.add_argument("--priority", type=parse_priority_arg, default="normal", help="Priority: high, normal, low")
    parser_add.add_argument("--due", type=parse_date_arg, help="Due date YYYY-MM-DD")

    # list
    parser_list = subparsers.add_parser("list", help="List tasks")
    parser_list.add_argument("--status", default="open", choices=["open", "done", "all"], help="Filter by status")
    parser_list.add_argument("--tag", action="append", default=[], help="Filter by tag")
    parser_list.add_argument("--overdue", action="store_true", help="Show only overdue tasks")
    parser_list.add_argument("--sort", default="id", choices=["id", "priority", "due"], help="Sort order")

    # done
    parser_done = subparsers.add_parser("done", help="Mark tasks as done")
    parser_done.add_argument("ids", type=int, nargs="+", help="Task IDs")

    # remove
    parser_remove = subparsers.add_parser("remove", help="Remove a task")
    parser_remove.add_argument("id", type=int, help="Task ID")

    # edit
    parser_edit = subparsers.add_parser("edit", help="Edit a task")
    parser_edit.add_argument("id", type=int, help="Task ID")
    parser_edit.add_argument("--title", help="New title")
    parser_edit.add_argument("--tag", action="append", default=[], help="Tag to add")
    parser_edit.add_argument("--untag", action="append", default=[], help="Tag to remove")
    parser_edit.add_argument("--priority", type=parse_priority_arg, help="New priority")
    parser_edit.add_argument("--due", type=parse_date_arg, help="New due date YYYY-MM-DD")
    parser_edit.add_argument("--no-due", action="store_true", help="Clear due date")

    # Parse arguments
    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        return e.code if isinstance(e.code, int) else 2

    if args.command is None:
        parser.print_usage(sys.stderr)
        sys.stderr.write("error: No command provided\n")
        return 2

    try:
        store = TodoStore(args.file)
    except StoreError as e:
        sys.stderr.write(f"error: {e}\n")
        return 3

    today = args.today if args.today is not None else datetime.date.today()

    if args.command == "add":
        try:
            task = store.add(args.title, args.tag, priority=args.priority, due=args.due)
            print(f"added {task.id}")
            return 0
        except KeyError as e:
            sys.stderr.write(f"error: {e}\n")
            return 1
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    elif args.command == "list":
        try:
            tasks = store.list(
                status=args.status, 
                tags=args.tag, 
                overdue=args.overdue, 
                today=today, 
                sort=args.sort
            )
            for t in tasks:
                print(format_task(t))
            return 0
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    elif args.command == "done":
        for tid in args.ids:
            try:
                store.get(tid)
            except KeyError:
                sys.stderr.write(f"error: no task with id {tid}\n")
                return 1

        for tid in args.ids:
            store.mark_done(tid)
            print(f"done {tid}")
        return 0

    elif args.command == "remove":
        try:
            store.remove(args.id)
            print(f"removed {args.id}")
            return 0
        except KeyError as e:
            sys.stderr.write(f"error: no task with id {args.id}\n")
            return 1

    elif args.command == "edit":
        has_title = args.title is not None
        has_tag = bool(args.tag)
        has_untag = bool(args.untag)
        has_priority = args.priority is not None
        has_due = args.due is not None
        has_no_due = args.no_due

        if not any([has_title, has_tag, has_untag, has_priority, has_due, has_no_due]):
            sys.stderr.write("error: edit requires at least one change\n")
            return 2

        if has_due and has_no_due:
            sys.stderr.write("error: cannot specify both --due and --no-due\n")
            return 2

        try:
            store.edit(
                args.id, 
                title=args.title, 
                add_tags=args.tag, 
                remove_tags=args.untag,
                priority=args.priority,
                due=args.due,
                clear_due=args.no_due
            )
            print(f"edited {args.id}")
            return 0
        except KeyError:
            sys.stderr.write(f"error: no task with id {args.id}\n")
            return 1
        except ValueError as e:
            # This catches invalid title, tag, priority, or due date
            # Or the conflict check in edit
            sys.stderr.write(f"error: {e}\n")
            return 2

    return 2

if __name__ == "__main__":
    sys.exit(main())
