import json
import os
import pathlib
import datetime
from .model import Task, normalize_title, normalize_tag, normalize_priority, parse_date

class StoreError(Exception):
    pass

class TodoStore:
    def __init__(self, path: str | pathlib.Path):
        self.path = pathlib.Path(path)
        self.tasks: dict[int, Task] = {}
        self.next_id: int = 1

        if self.path.exists():
            try:
                with open(self.path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except (json.JSONDecodeError, UnicodeDecodeError):
                raise StoreError("file is not valid JSON")

            self._parse_data(data)

    def _parse_data(self, data: dict):
        if not isinstance(data, dict):
            raise StoreError("store root must be an object")

        version = data.get("version")
        if version not in (1, 2):
            raise StoreError("unsupported version")

        next_id = data.get("next_id")
        if not isinstance(next_id, int) or isinstance(next_id, bool) or next_id < 1:
            raise StoreError("invalid next_id")

        tasks_data = data.get("tasks")
        if not isinstance(tasks_data, list):
            raise StoreError("tasks must be a list")

        seen_ids = set()
        for t_dict in tasks_data:
            if not isinstance(t_dict, dict):
                raise StoreError("task must be an object")
            try:
                t = Task.from_dict(t_dict)
            except ValueError as e:
                raise StoreError(f"invalid task: {e}")

            if t.id in seen_ids:
                raise StoreError("duplicate task ids")
            if t.id >= next_id:
                raise StoreError("task id out of range")

            seen_ids.add(t.id)
            self.tasks[t.id] = t

        self.next_id = next_id

    def _write(self):
        tasks_list = []
        # Sort tasks by id for output
        for t in sorted(self.tasks.values(), key=lambda x: x.id):
            tasks_list.append(t.to_dict())

        data = {
            "version": 2,
            "next_id": self.next_id,
            "tasks": tasks_list
        }

        # Atomic write: write to temp file, then replace
        temp_path = self.path.with_suffix(".tmp")
        try:
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f)
            os.replace(temp_path, self.path)
        except OSError as e:
            raise StoreError(f"could not write file: {e}")

    def add(self, title: str, tags=(), priority="normal", due=None) -> Task:
        title = normalize_title(title)
        normalized_tags = sorted(set(normalize_tag(t) for t in tags))
        priority = normalize_priority(priority)

        if due is not None:
            if not isinstance(due, datetime.date):
                try:
                    due = parse_date(str(due))
                except ValueError:
                    raise ValueError("invalid due date")

        task = Task(id=self.next_id, title=title, tags=normalized_tags, done=False, priority=priority, due=due)

        self.tasks[task.id] = task
        self.next_id += 1
        self._write()

        return Task(id=task.id, title=task.title, tags=list(task.tags), done=task.done, priority=task.priority, due=task.due)

    def get(self, task_id: int) -> Task:
        if task_id not in self.tasks:
            raise KeyError(task_id)
        t = self.tasks[task_id]
        return Task(id=t.id, title=t.title, tags=list(t.tags), done=t.done, priority=t.priority, due=t.due)

    def list(self, status: str = "open", tags=(), overdue=False, today=None, sort="id") -> list[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError("status must be open, done, or all")

        if sort not in ("id", "priority", "due"):
            raise ValueError("invalid sort")

        if overdue:
            if today is None:
                raise ValueError("overdue requires today")

        normalized_tags = set(normalize_tag(t) for t in tags) if tags else set()

        result = []
        for t in self.tasks.values():
            if status == "open" and t.done:
                continue
            if status == "done" and not t.done:
                continue

            if normalized_tags and not normalized_tags.issubset(set(t.tags)):
                continue

            if overdue:
                # Only open tasks can be overdue
                if t.done:
                    continue
                if t.due is None:
                    continue
                if t.due >= today:
                    continue

            result.append(Task(id=t.id, title=t.title, tags=list(t.tags), done=t.done, priority=t.priority, due=t.due))

        # Sorting
        priority_map = {"high": 0, "normal": 1, "low": 2}

        def sort_key(task):
            if sort == "id":
                return (task.id,)
            elif sort == "priority":
                return (priority_map.get(task.priority, 1), task.id)
            elif sort == "due":
                # Tasks without due date go last. 
                if task.due is None:
                    return (datetime.date.max, task.id)
                return (task.due, task.id)
            return (task.id,)

        result.sort(key=sort_key)

        return result

    def mark_done(self, task_id: int) -> Task:
        if task_id not in self.tasks:
            raise KeyError(task_id)

        t = self.tasks[task_id]
        if not t.done:
            t.done = True
            self._write()

        return Task(id=t.id, title=t.title, tags=list(t.tags), done=t.done, priority=t.priority, due=t.due)

    def remove(self, task_id: int) -> Task:
        if task_id not in self.tasks:
            raise KeyError(task_id)

        t = self.tasks.pop(task_id)
        self._write()

        return Task(id=t.id, title=t.title, tags=list(t.tags), done=t.done, priority=t.priority, due=t.due)

    def edit(self, task_id: int, title: str | None = None, add_tags=(), remove_tags=(), priority=None, due=None, clear_due=False) -> Task:
        if task_id not in self.tasks:
            raise KeyError(task_id)

        t = self.tasks[task_id]

        # Check for conflict
        if due is not None and clear_due:
            raise ValueError("cannot specify both due and clear_due")

        # Prepare changes to validate before applying
        new_title = t.title
        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError:
                raise

        new_priority = t.priority
        if priority is not None:
            try:
                new_priority = normalize_priority(priority)
            except ValueError:
                raise

        new_due = t.due
        if clear_due:
            new_due = None
        elif due is not None:
            # Due is provided
            if not isinstance(due, datetime.date):
                 try:
                     new_due = parse_date(str(due))
                 except ValueError:
                     raise ValueError("invalid due date")
            else:
                new_due = due

        new_tags_set = set(t.tags)
        try:
            tags_to_add = [normalize_tag(tag) for tag in add_tags]
            tags_to_remove = [normalize_tag(tag) for tag in remove_tags]
        except ValueError:
            raise

        # Apply tag changes to a copy first to ensure all tags are valid
        # Order: add then remove
        new_tags_set.update(tags_to_add)
        new_tags_set.difference_update(tags_to_remove)

        # Validation passed, commit changes to the actual object
        t.title = new_title
        t.priority = new_priority
        t.due = new_due
        t.tags = sorted(new_tags_set)

        self._write()

        return Task(id=t.id, title=t.title, tags=list(t.tags), done=t.done, priority=t.priority, due=t.due)

