from dataclasses import dataclass, field
import re
import datetime

@dataclass
class Task:
    id: int
    title: str
    tags: list[str] = field(default_factory=list)
    done: bool = False
    priority: str = "normal"
    due: datetime.date | None = None

    def to_dict(self) -> dict:
        due_str = None
        if self.due is not None:
            due_str = self.due.strftime("%Y-%m-%d")

        return {
            "id": self.id,
            "title": self.title,
            "tags": self.tags,
            "done": self.done,
            "priority": self.priority,
            "due": due_str,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Task":
        if not isinstance(d, dict):
            raise ValueError("task must be a dict")

        # Check missing required keys (from v1)
        for key in ("id", "title", "tags", "done"):
            if key not in d:
                raise ValueError(f"missing key: {key}")

        val_id = d["id"]
        if not isinstance(val_id, int) or isinstance(val_id, bool):
            raise ValueError("id must be an int")

        val_title = d["title"]
        if not isinstance(val_title, str):
            raise ValueError("title must be a str")

        val_tags = d["tags"]
        if not isinstance(val_tags, list):
            raise ValueError("tags must be a list")
        for t in val_tags:
            if not isinstance(t, str):
                raise ValueError("tag must be a str")

        val_done = d["done"]
        if not isinstance(val_done, bool):
            raise ValueError("done must be a bool")

        # Handle optional fields
        priority = d.get("priority", "normal")
        if not isinstance(priority, str):
             raise ValueError("priority must be a str")
        try:
            priority = normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"invalid priority: {e}")

        due_str = d.get("due")
        due = None
        if due_str is not None:
            if not isinstance(due_str, str):
                raise ValueError("due must be a string or null")
            try:
                due = parse_date(due_str)
            except ValueError as e:
                raise ValueError(f"invalid due date: {e}")

        try:
            title = normalize_title(val_title)
            tags = sorted(set(normalize_tag(t) for t in val_tags))
        except ValueError as e:
            raise ValueError(f"invalid data: {e}")

        return cls(id=val_id, title=title, tags=tags, done=val_done, priority=priority, due=due)

def normalize_title(title: str) -> str:
    if not isinstance(title, str):
        raise ValueError("title must be a string")
    stripped = title.strip()
    if not stripped:
        raise ValueError("title cannot be empty")
    return stripped

_TAG_RE = re.compile(r'^[a-z0-9][a-z0-9_-]*$')

def normalize_tag(tag: str) -> str:
    if not isinstance(tag, str):
        raise ValueError("tag must be a string")
    stripped = tag.strip().lower()
    if not _TAG_RE.fullmatch(stripped):
        raise ValueError("invalid tag")
    return stripped

def normalize_priority(p: str) -> str:
    if not isinstance(p, str):
        raise ValueError("priority must be a string")
    stripped = p.strip().lower()
    if stripped not in ("high", "normal", "low"):
        raise ValueError("priority must be high, normal or low")
    return stripped

_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')

def parse_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError("date must be a string")
    if not _DATE_RE.match(s):
        raise ValueError("date format must be YYYY-MM-DD")
    try:
        year, month, day = map(int, s.split('-'))
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError("invalid date")
