def format_task(task: Task) -> str:
    status_char = "x" if task.done else " "
    line = f"{task.id} [{status_char}] {task.title}"

    if task.priority != "normal":
        line += f" !{task.priority}"

    if task.due is not None:
        line += f" due:{task.due.strftime('%Y-%m-%d')}"

    for tag in task.tags:
        line += f" #{tag}"

    return line

class ErrorAwareArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        super().error(message)

def parse_date_arg(s: str) -> datetime.date:
    try:
        return parse_date(s)
    except ValueError as e:
        raise argparse.ArgumentTypeError(f"invalid date '{s}': {e}")

def parse_priority_arg(s: str) -> str:
    try:
        return normalize_priority(s)
    except ValueError as e:
        raise argparse.ArgumentTypeError(f"invalid priority '{s}': {e}")

