from __future__ import annotations

import datetime
from decimal import Decimal, ROUND_HALF_UP
import dataclasses

from .models import UnknownItemError
from .movements import Ledger


@dataclasses.dataclass(frozen=True)
class Valuation:
    qty: int
    value: Decimal
    cogs: Decimal


def _round_money(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def fifo(ledger: Ledger, sku: str, as_of: datetime.date | None = None) -> Valuation:
    try:
        ledger.item(sku)
    except UnknownItemError:
        raise UnknownItemError(f"Unknown SKU: {sku}")

    movements = ledger.movements(sku=sku, as_of=as_of)

    # List of [remaining_qty, unit_cost]
    layers: list[list[Decimal, Decimal]] = [] 

    cogs_accum = Decimal(0)

    for m in movements:
        if m.kind == "receive":
            if m.qty > 0:
                layers.append([Decimal(m.qty), m.unit_cost])
        elif m.kind == "issue":
            qty_needed = Decimal(m.qty)
            for layer in layers:
                if qty_needed == 0:
                    break
                avail = layer[0]
                if avail == 0:
                    continue
                take = min(avail, qty_needed)
                layer[0] -= take
                qty_needed -= take
                cogs_accum += take * layer[1]

            layers = [l for l in layers if l[0] > 0]

            if qty_needed > 0:
                raise RuntimeError("Internal error: insufficient stock in FIFO layers")

    value_accum = Decimal(0)
    total_qty = 0
    for layer in layers:
        value_accum += layer[0] * layer[1]
        total_qty += int(layer[0])

    return Valuation(
        qty=total_qty,
        value=_round_money(value_accum),
        cogs=_round_money(cogs_accum)
    )


def average(ledger: Ledger, sku: str, as_of: datetime.date | None = None) -> Valuation:
    try:
        ledger.item(sku)
    except UnknownItemError:
        raise UnknownItemError(f"Unknown SKU: {sku}")

    movements = ledger.movements(sku=sku, as_of=as_of)

    current_qty = 0
    current_value = Decimal(0)
    cogs_accum = Decimal(0)

    for m in movements:
        if m.kind == "receive":
            current_qty += m.qty
            current_value += m.qty * m.unit_cost
        elif m.kind == "issue":
            qty_issued = m.qty
            if current_qty == 0:
                 # Should not happen if ledger integrity is maintained
                 raise RuntimeError("Cannot issue stock with zero quantity")

            if qty_issued == current_qty:
                cost = current_value
            else:
                raw_cost = (current_value * qty_issued) / current_qty
                cost = _round_money(raw_cost)

            current_value -= cost
            cogs_accum += cost
            current_qty -= qty_issued

    return Valuation(
        qty=current_qty,
        value=_round_money(current_value),
        cogs=_round_money(cogs_accum)
    )


def valuate(ledger: Ledger, sku: str, method: str = "fifo", as_of: datetime.date | None = None) -> Valuation:
    if method == "fifo":
        return fifo(ledger, sku, as_of)
    elif method == "average":
        return average(ledger, sku, as_of)
    else:
        raise ValueError(f"Invalid method: {method}")
