from __future__ import annotations

import datetime
from decimal import Decimal
import collections

from .movements import Ledger
from .valuation import valuate


def stock_report(ledger: Ledger, as_of: datetime.date | None = None, location: str | None = None) -> str:
    lines = ["location,sku,qty"]

    locations = ledger.locations()
    if location is not None:
        locations = [location]

    group_data = collections.defaultdict(list)

    for loc in locations:
        items = ledger.items()
        for item in items:
            qty = ledger.on_hand(item.sku, location=loc, as_of=as_of)
            if qty > 0:
                group_data[loc].append((item.sku, qty))

    grand_total_qty = 0

    for loc in locations:
        if loc not in group_data:
            continue

        rows = group_data[loc]
        if not rows:
            continue

        for sku, qty in rows:
            lines.append(f"{loc},{sku},{qty}")
            grand_total_qty += qty

        sub_qty = sum(qty for _, qty in rows)
        lines.append(f"{loc},TOTAL,{sub_qty}")

    lines.append(f"TOTAL,,{grand_total_qty}")

    return "\n".join(lines) + "\n"


def valuation_report(ledger: Ledger, as_of: datetime.date | None = None, method: str = "fifo", category: str | None = None) -> str:
    if method not in ("fifo", "average"):
        raise ValueError(f"Invalid method: {method}")

    lines = ["category,sku,qty,value"]

    all_items = ledger.items()
    categories = sorted(list(set(item.category for item in all_items)))

    if category is not None:
        if category not in categories:
            categories = []
        else:
            categories = [category]

    cat_data = collections.defaultdict(list)

    items_by_cat = collections.defaultdict(list)
    for item in all_items:
        items_by_cat[item.category].append(item)

    for cat in categories:
        if cat not in items_by_cat:
            continue

        for item in items_by_cat[cat]:
            val = valuate(ledger, item.sku, method=method, as_of=as_of)
            if val.qty > 0:
                cat_data[cat].append((item.sku, val.qty, val.value))

    grand_total_qty = 0
    grand_total_value = Decimal("0.00")

    for cat in categories:
        if cat not in cat_data:
            continue

        rows = cat_data[cat]
        if not rows:
            continue

        cat_total_qty = 0
        cat_total_value = Decimal("0.00")

        for sku, qty, value in rows:
            lines.append(f"{cat},{sku},{qty},{value:.2f}")
            cat_total_qty += qty
            cat_total_value += value

        grand_total_qty += cat_total_qty
        grand_total_value += cat_total_value

        lines.append(f"{cat},TOTAL,{cat_total_qty},{cat_total_value:.2f}")

    lines.append(f"TOTAL,,{grand_total_qty},{grand_total_value:.2f}")

    return "\n".join(lines) + "\n"
