from .lexer import tokenize, Token, TemplateSyntaxError
import re

# Reserved words for variable names
RESERVED = {'and', 'or', 'not', 'in'}

# Filter specifications: (name, has_arg, arg_type)
# arg_type: 'str', 'int', 'any' (str or int)
FILTERS = {
    'upper': (False, None),
    'lower': (False, None),
    'trim': (False, None),
    'length': (False, None),
    'first': (False, None),
    'last': (False, None),
    'reverse': (False, None),
    'items': (False, None),
    'join': (True, 'str'),
    'default': (True, 'any'),
    'truncate': (True, 'int'),
}

class TokenStream:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        token = self.peek()
        if token:
            self.pos += 1
        return token

class Node:
    pass

class TextNode(Node):
    def __init__(self, text: str):
        self.text = text

class VarNode(Node):
    def __init__(self, expr, lineno):
        self.expr = expr
        self.lineno = lineno

class BlockNode(Node):
    pass

class IfNode(BlockNode):
    def __init__(self):
        self.branches = [] # list of (cond, body_nodes)
        self.else_body = None # list of body_nodes

class ForNode(BlockNode):
    def __init__(self, var_name, iterable_expr, body_nodes, else_body, lineno):
        self.var_name = var_name
        self.iterable_expr = iterable_expr
        self.body_nodes = body_nodes
        self.else_body = else_body
        self.lineno = lineno

class CondNode(Node):
    pass

class OrCond(CondNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class AndCond(CondNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class NotCond(CondNode):
    def __init__(self, operand):
        self.operand = operand

class CompareCond(CondNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class BoolCond(CondNode):
    def __init__(self, expr):
        self.expr = expr

class ExprNode(Node):
    pass

class LitExpr(ExprNode):
    def __init__(self, value):
        self.value = value

class VarExpr(ExprNode):
    def __init__(self, path):
        self.path = path

class FilterExpr(ExprNode):
    def __init__(self, source, name, arg):
        self.source = source
        self.name = name
        self.arg = arg

def parse(source: str) -> list:
    tokens = tokenize(source)
    stream = TokenStream(tokens)
    nodes = parse_body(stream)

    if stream.peek():
        token = stream.peek()
        # If we are at the end, any block token other than expected closers is an error
        # But parse_body should have consumed everything or stopped at a closer.
        # If we are at EOF, peek() is None.
        # If peek() is not None, it means we stopped at a closer that didn't match, or unexpected content?
        # parse_body only stops on text/var (consumed) or block (peeked).
        # If parse_body returns, it means it hit a block token that is a closer or EOF.
        # If it hit a closer, parse_body returns.
        # Wait, parse_body breaks on block tokens that are closers.
        # So if stream.peek() is not None, it means the top level parse_body stopped at a closer?
        # No, parse_body breaks on 'endfor', 'endif', 'else', 'elif'.
        # If parse_body breaks on 'endfor' at top level, that's an error "unexpected endfor".
        # If it breaks on 'endif' at top level, that's an error "unexpected endif".
        # If it breaks on 'else' at top level, that's an error "unexpected else".

        token = stream.peek()
        if token.kind == 'block':
            key = token.value.split()[0]
            if key in ('endfor', 'endif', 'else', 'elif'):
                 raise TemplateSyntaxError(f"unexpected '{key}'", token.lineno)

        # If it's text or var, that shouldn't happen if parse_body is implemented correctly (it consumes them).
        # So if peek() is not None here, it must be a block token that wasn't handled.
        # But parse_body breaks on ANY block token? No, only the specific closers.
        # If parse_body sees 'if', it recurses.
        # If parse_body sees 'for', it recurses.
        # If parse_body sees text/var, it consumes and continues.
        # If parse_body sees block, it checks key.
        # If key is 'endfor'/'endif'/'else'/'elif', it BREAKS.
        # So if parse_body returns, and stream.peek() is not None, it MUST be one of those keys.
        # Because if it was 'if' or 'for', parse_body would have handled it and not broken.
        # If it was unknown, parse_body would have raised error.

        # So if we are here, stream.peek() is a block token that was a closer.
        # This means we encountered a closer without an opener.
        token = stream.peek()
        key = token.value.split()[0]
        raise TemplateSyntaxError(f"unexpected '{key}'", token.lineno)

    return nodes

def parse_body(stream: TokenStream):
    nodes = []
    while True:
        token = stream.peek()
        if not token:
            break

        if token.kind == 'block':
            # Peek to see if it's a closer or other control flow
            parts = token.value.split()
            if not parts:
                 stream.next()
                 continue
            key = parts[0]

            if key in ('endfor', 'endif', 'else', 'elif'):
                break

            if key == 'if':
                stream.next()
                # Pass the token to parse_if which handles its own consumption of the if token?
                # Or parse_if expects stream to be positioned at the token?
                # Let's have parse_if handle the stream.next() for the 'if' token itself?
                # No, I already did stream.next() above? No, I peeked.
                # Let's not consume here. parse_if will consume.
                nodes.append(parse_if(stream))
