def split_filters(s: str):
    parts = []
    current = []
    in_quote = None

    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            current.append(c)
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
            current.append(c)
        elif c == '|':
            parts.append(''.join(current))
            current = []
        else:
            current.append(c)
        i += 1

    parts.append(''.join(current))
    return parts

def find_colon(s: str):
    in_quote = None
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
        elif c == ':':
            return i
        i += 1
    return -1

def parse_atom(s: str, lineno: int) -> ExprNode:
    s = s.strip()
    if not s:
        raise TemplateSyntaxError("empty atom", lineno)

