from .parser import (
    TextNode, VarNode, IfNode, ForNode, 
    OrCond, AndCond, NotCond, CompareCond, BoolCond,
    LitExpr, VarExpr, FilterExpr
)
from .lexer import TemplateRenderError

import collections.abc

class Template:
    def __init__(self, source: str):
        from .parser import parse
        self.nodes = parse(source)

    def render(self, context: dict = None, **kwargs) -> str:
        if context is None:
            context = {}
        else:
            context = dict(context) # Shallow copy to avoid modifying original

        # kwargs win over context
        scope = context.copy()
        scope.update(kwargs)

        output = []
        self._render_nodes(self.nodes, scope, output)
        return "".join(output)

    def _render_nodes(self, nodes, scope, output):
        for node in nodes:
            if isinstance(node, TextNode):
                output.append(node.text)
            elif isinstance(node, VarNode):
                val = self._eval_expr(node.expr, scope, node.lineno)
                output.append(self._to_text(val))
            elif isinstance(node, IfNode):
                self._render_if(node, scope, output)
            elif isinstance(node, ForNode):
                self._render_for(node, scope, output)

    def _render_if(self, node, scope, output):
        for cond, body in node.branches:
            if self._eval_cond(cond, scope, node.lineno):
                self._render_nodes(body, scope, output)
                return
        if node.else_body:
            self._render_nodes(node.else_body, scope, output)

    def _render_for(self, node, scope, output):
        # Evaluate iterable
        val = self._eval_expr(node.iterable_expr, scope, node.lineno)

        # Get iterator
        try:
            if val is None:
                iterator = []
            elif isinstance(val, (list, tuple, str)):
                iterator = val
            elif isinstance(val, collections.abc.Mapping):
                iterator = list(val.keys()) # Keys in mapping order
            elif isinstance(val, collections.abc.Iterable):
                iterator = list(val)
            else:
                raise TemplateRenderError("value is not iterable", node.lineno)
        except Exception:
             raise TemplateRenderError("value is not iterable", node.lineno)

        length = len(iterator)

        if length == 0:
            if node.else_body:
                self._render_nodes(node.else_body, scope, output)
            return

        new_scope = scope.copy()

        for idx, item in enumerate(iterator):
            # Set loop var
            new_scope[node.var_name] = item

            # Loop info
            loop_data = {
                'index': idx + 1,
                'index0': idx,
                'first': (idx == 0),
                'last': (idx == length - 1),
                'length': length
            }
            # In nested loops, loop describes innermost.
            # We just overwrite 'loop' in new_scope.
            # Outer loops' 'loop' is hidden.
            new_scope['loop'] = loop_data

            self._render_nodes(node.body_nodes, new_scope, output)

    def _eval_expr(self, expr, scope, lineno) -> any:
        if isinstance(expr, LitExpr):
            return expr.value

        if isinstance(expr, VarExpr):
            return self._resolve_path(expr.path, scope, lineno)

        if isinstance(expr, FilterExpr):
            val = self._eval_expr(expr.source, scope, lineno)
            return self._apply_filter(val, expr.name, expr.arg, lineno)

        raise TemplateRenderError("unknown expression type", lineno)

    def _resolve_path(self, path, scope, lineno) -> any:
        # path is list of segments. First is name.
        name = path[0]
        if name in scope:
            val = scope[name]
        else:
            val = None

        for segment in path[1:]:
            val = self._resolve_segment(val, segment, lineno)

        return val

    def _resolve_segment(self, val, segment, lineno) -> any:
        if val is None:
            return None

        if isinstance(segment, int):
            # Integer index
            if isinstance(val, (list, tuple)):
                try:
                    return val[segment]
                except IndexError:
                    return None
            else:
                return None

        # String segment
        if isinstance(val, collections.abc.Mapping):
            # Lookup by string key
            return val.get(str(segment), None)

        if isinstance(val, (list, tuple)):
            # Can't access list by string name generally
            return None

        if isinstance(segment, str):
            if segment.startswith('_'):
                return None
            try:
                # Try attribute
                return getattr(val, segment, None)
            except AttributeError:
                return None

        return None

    def _apply_filter(self, val, name, arg, lineno) -> any:
        # Filters operate on values

        if name == 'upper':
            text = self._to_text(val)
            return text.upper()

        if name == 'lower':
            text = self._to_text(val)
            return text.lower()

        if name == 'trim':
            text = self._to_text(val)
            return text.strip()

        if name == 'length':
            if val is None:
                return 0
            try:
                return len(val)
            except TypeError:
                raise TemplateRenderError(f"length filter cannot handle {type(val).__name__}", lineno)

        if name == 'first':
            if val is None:
                return None
            if isinstance(val, str):
                return val[0] if len(val) > 0 else None
            if isinstance(val, (list, tuple)):
                return val[0] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                 # Try to get first item
                 try:
                     return next(iter(val))
                 except StopIteration:
                     return None
            return None

        if name == 'last':
            if val is None:
                return None
            if isinstance(val, str):
                return val[-1] if len(val) > 0 else None
            if isinstance(val, (list, tuple)):
                return val[-1] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                 # Need to iterate all the way?
                 items = list(val)
                 return items[-1] if items else None
            return None

        if name == 'reverse':
