# Reserved words for variable names
RESERVED = {'and', 'or', 'not', 'in', 'super'}

# Filter specifications: (name, has_arg, arg_type)
# arg_type: 'str', 'int', 'any' (str or int)
FILTERS = {
    'upper': (False, None),
    'lower': (False, None),
    'trim': (False, None),
    'length': (False, None),
    'first': (False, None),
    'last': (False, None),
    'reverse': (False, None),
    'items': (False, None),
