    current = []
    in_quote = None
    i = 0
    n = len(s)
    kw_len = len(kw)

    while i < n:
        c = s[i]
        if in_quote:
            current.append(c)
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
            current.append(c)
