def find_comparison(s: str, lineno: int):
    in_quote = None
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
        else:
            if s[i:i+2] in ('<=', '>=', '==', '!='):
                return s[:i].strip(), s[i:i+2], s[i+2:].strip()
            if c == '<' or c == '>':
                return s[:i].strip(), c, s[i+1:].strip()
        i += 1

    return s, None, None
