class Environment:
    def __init__(self, loader=None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> 'Template':
        if not self.loader:
            raise TemplateNotFound(name)
        try:
            source = self.loader.get_source(name)
        except TemplateNotFound:
            raise
        except Exception as e:
            raise TemplateNotFound(name)
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)

    def from_string(self, source: str) -> 'Template':
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=None)

class Template:
    def __init__(self, source: str, *, loader=None, autoescape: bool = False, name: str | None = None):
        self.source = source
        self.loader = loader
        self.autoescape = autoescape
        self.name = name
        self.nodes = parse(source)
        self._check_duplicate_blocks(self.nodes)

    def _check_duplicate_blocks(self, nodes):
        seen = set()
        def check_node(node):
            if isinstance(node, BlockDefNode):
                if node.name in seen:
                    raise TemplateSyntaxError(f"duplicate block name '{node.name}'", node.lineno)
                seen.add(node.name)
            elif isinstance(node, IfNode):
                for _, body in node.branches:
                    for n in body: check_node(n)
                if node.else_body:
                    for n in node.else_body: check_node(n)
            elif isinstance(node, ForNode):
                for n in node.body_nodes: check_node(n)
                if node.else_body:
                    for n in node.else_body: check_node(n)
            elif isinstance(node, BlockDefNode):
                for n in node.body_nodes: check_node(n)

        for node in nodes:
            check_node(node)

    def render(self, context: dict = None, **kwargs) -> str:
        if context is None:
            context = {}
        else:
            context = dict(context)

        # kwargs win over context
        scope = context.copy()
        scope.update(kwargs)

        return self._render_with_inheritance(self.nodes, scope, self.autoescape, [self.name] if self.name else [])

    def _render_with_inheritance(self, nodes, scope, autoescape, loaded_chain):
        # Find extends node
        extends_node = None
        for node in nodes:
            if isinstance(node, ExtendsNode):
                extends_node = node
                break

        if extends_node:
            parent_name = extends_node.name
            if parent_name in loaded_chain:
                raise TemplateRenderError(f"circular inheritance detected: '{parent_name}' is already in the chain", extends_node.lineno)

            if not self.loader:
                raise TemplateNotFound(parent_name)

            try:
                parent_source = self.loader.get_source(parent_name)
            except TemplateNotFound:
                raise
            except Exception as e:
                raise TemplateNotFound(parent_name)

            parent_template = Template(parent_source, loader=self.loader, autoescape=autoescape, name=parent_name)

            # Recursively render the parent with the current loaded chain extended
            # Note: The parent's render method will handle its own inheritance chain.
            # We pass the current scope.
            # The "loaded_chain" tracks which templates have been loaded to prevent cycles.
            return parent_template._render_with_inheritance(
                parent_template.nodes, 
                scope, 
                autoescape, 
                loaded_chain + [parent_name]
            )
        else:
            # No inheritance. Render nodes directly.
            # We need to resolve blocks against a "current" context.
            # If we are in a chain, the caller has already resolved the blocks.
            # Wait, the recursive approach above is slightly tricky for `super()`.
            # `super()` needs access to the "next less derived definition".
            # If we call parent.render(), the parent doesn't know about the child's overrides unless we pass them.

            # Let's restart the inheritance resolution logic properly.
            pass

        # Re-implementing inheritance resolution for clarity and correctness regarding super()
        # The recursive call above is wrong because the parent template object doesn't know about the child's block overrides.

        # Correct approach:
        # 1. Identify the full chain: Child -> Parent -> GrandParent...
        # 2. Identify the base template (the one with no extends).
        # 3. Render the base template, but whenever a block is encountered, look up the definition in the most derived template that defines it.

        # Let's rebuild _render_with_inheritance to do this properly.

        # Actually, a simpler recursive strategy:
        # _render_with_inheritance(nodes, scope, autoescape, loaded_chain, child_blocks=None)
        # If ExtendsNode found:
        #   1. Load parent source.
        #   2. Parse parent source.
        #   3. Recursively call _render_with_inheritance on the PARENT's nodes, passing the CURRENT template's blocks as 'child_blocks'.
        #   4. The recursion stops when a template has no ExtendsNode.

        # But `super()` inside the parent block (when overridden by child) needs to render the PARENT's block body.
        # `super()` inside the grandparent block (when overridden by parent AND child) needs to render the GRANDPARENT's block body.

        # Let's define a helper that takes:
        # - template_nodes: the nodes to render
        # - scope
        # - autoescape
        # - loaded_chain: for cycle detection
        # - overrides: dict[block_name, (template_nodes_for_block_body, template_name)]
        #   where 'template_name' is where the override came from (for debugging, maybe not needed)
        #   and 'template_nodes_for_block_body' is the body of the block definition in the most derived template that defines it.
        # - super_chain: list of block body nodes corresponding to the current block being rendered, from most derived to least derived.

        # This is getting complex. Let's stick to the standard Jinja-like approach.

        # Step 1: Get the full inheritance chain.
        # Step 2: Collect all block definitions.
        # Step 3: Render the base template (the root of the chain).
        # Step 4: When rendering a block in the base, find the most derived override.
        # Step 5: When rendering an override, provide a `super()` function that renders the next less derived definition.

        # Implementation:

        # Find the chain of templates
        current_template = self
        chain = [self]
        visited = {self.name or "__main__"}

        while True:
            ext_node = None
            for n in current_template.nodes:
                if isinstance(n, ExtendsNode):
                    ext_node = n
                    break

            if not ext_node:
                break

            pname = ext_node.name
            if pname in visited:
                raise TemplateRenderError(f"circular inheritance detected: '{pname}'", ext_node.lineno)
            visited.add(pname)

            if not self.loader:
                raise TemplateNotFound(pname)

            try:
                p_source = self.loader.get_source(pname)
            except TemplateNotFound:
                raise
            except Exception as e:
                raise TemplateNotFound(pname)

            p_template = Template(p_source, loader=self.loader, autoescape=autoescape, name=pname)
            chain.append(p_template)
            current_template = p_template

        # chain is now [Child, Parent, GrandParent, ..., Base]
        # The Base template is the one to render.
        base_template = chain[-1]

        # Collect block definitions from all templates in the chain.
        # Map: block_name -> list of (block_node, template_index_in_chain)
        # We want the "most derived" override. Index 0 is most derived.
        # So for each block name, we store a list of bodies in order of derivation (Child first, then Parent, etc.)

        block_definitions = {} # name -> list of BlockDefNodes (most derived first)

        for idx, tmpl in enumerate(chain):
            self._collect_blocks(tmpl.nodes, block_definitions, idx)

        # Now render the base template
        return self._render_nodes(base_template.nodes, scope, autoescape, chain, block_definitions, [])

    def _collect_blocks(self, nodes, block_map, chain_idx):
        for node in nodes:
            if isinstance(node, BlockDefNode):
                if node.name not in block_map:
                    block_map[node.name] = []
                block_map[node.name].append((chain_idx, node))
            elif isinstance(node, IfNode):
                for _, body in node.branches:
                    self._collect_blocks(body, block_map, chain_idx)
                if node.else_body:
                    self._collect_blocks(node.else_body, block_map, chain_idx)
            elif isinstance(node, ForNode):
                self._collect_blocks(node.body_nodes, block_map, chain_idx)
                if node.else_body:
                    self._collect_blocks(node.else_body, block_map, chain_idx)
            elif isinstance(node, BlockDefNode): # Nested block
                self._collect_blocks(node.body_nodes, block_map, chain_idx)

    def _render_nodes(self, nodes, scope, autoescape, chain, block_definitions, super_stack):
        """
        super_stack: list of lists of (chain_idx, BlockDefNode). 
        This is tricky. `super()` needs to know what to render next.

        Actually, `super()` inside a block rendered from `block_definitions['name'][i]` 
        should render `block_definitions['name'][i+1]`.

        If we are rendering the base block (which is in block_definitions['name'][len-1]),
        super() should fail (or render empty if that's the end?). 
        Spec: "Errors ... TemplateRenderError ... when there is no less derived definition of the block".
        Wait, "less derived" means closer to the base. 
        "super() ... outputs the next less derived definition of the enclosing block".

        If I am in the Child's block (index 0), less derived is Parent (index 1).
        If I am in Parent's block (index 1), less derived is GrandParent (index 2).
        If I am in Base's block (index N), there is no less derived. Error.

        So we need to know the index of the currently rendered block definition.
        """
        output = []
        for node in nodes:
            if isinstance(node, TextNode):
                output.append(node.text)
            elif isinstance(node, VarNode):
                val = self._eval_expr(node.expr, scope, autoescape, chain, block_definitions, super_stack, node.lineno)
