            elif isinstance(node, BlockDefNode):
                # This block is being rendered. We need to find the override.
                # The block name is node.name.
                # We look in block_definitions[node.name].
                # The list is sorted by chain index (0 is most derived).
                defs = block_definitions.get(node.name, [])
                if defs:
                    # defs[0] is the most derived definition.
                    # But wait, `defs` contains definitions from ALL templates in the chain.
                    # If we are rendering the Base template, `defs` contains [Child_Def, Parent_Def, Base_Def].
                    # We want to render Child_Def first.
                    # However, Child_Def belongs to the Child template, not the current Base template.
                    # If Child_Def exists, we render Child_Def.body_nodes.
                    # If not, we render this node's body (which is Base_Def.body_nodes).

                    # The "super_stack" logic:
                    # When we enter a block, we push the "remaining" definitions to super_stack.
                    # `super()` pops the next one.

                    # Actually, standard approach:
                    # 1. Identify the override chain for this block: [ChildBody, ParentBody, BaseBody]
                    # 2. Render the first one (ChildBody).
                    # 3. Inside ChildBody, super() renders the next (ParentBody).
                    # 4. Inside ParentBody, super() renders the next (BaseBody).

                    # So we pass a `current_block_chain` to the render of the body.

                    body_to_render = defs[0][1].body_nodes
                    next_defs = defs[1:] # The less derived definitions

                    # We need to pass `next_defs` as the "super context" for this block body.
