    def _is_last_filter_safe_or_escape(self, expr) -> bool:
        if not isinstance(expr, FilterExpr):
            return False
        if expr.name == 'safe' or expr.name == 'escape':
            return True
        return False

    def _render_if(self, node, scope, output, autoescape, chain, block_definitions, super_stack):
        for cond, body in node.branches:
            if self._eval_cond(cond, scope, autoescape, chain, block_definitions, super_stack, node.lineno):
                out = self._render_nodes(body, scope, autoescape, chain, block_definitions, super_stack)
                output.append(out)
                return
        if node.else_body:
            out = self._render_nodes(node.else_body, scope, autoescape, chain, block_definitions, super_stack)
            output.append(out)

    def _render_for(self, node, scope, output, autoescape, chain, block_definitions, super_stack):
        val = self._eval_expr(node.iterable_expr, scope, autoescape, chain, block_definitions, super_stack, node.lineno)

        try:
            if val is None:
                iterator = []
            elif isinstance(val, (list, tuple, str)):
                iterator = val
            elif isinstance(val, collections.abc.Mapping):
                iterator = list(val.keys()) 
            elif isinstance(val, collections.abc.Iterable):
                iterator = list(val)
            else:
                raise TemplateRenderError("value is not iterable", node.lineno)
        except Exception:
             raise TemplateRenderError("value is not iterable", node.lineno)

        length = len(iterator)

        if length == 0:
            if node.else_body:
                out = self._render_nodes(node.else_body, scope, autoescape, chain, block_definitions, super_stack)
                output.append(out)
            return

        new_scope = scope.copy()

        for idx, item in enumerate(iterator):
            new_scope[node.var_name] = item
            loop_data = {
                'index': idx + 1,
                'index0': idx,
                'first': (idx == 0),
                'last': (idx == length - 1),
                'length': length
            }
            new_scope['loop'] = loop_data
            out = self._render_nodes(node.body_nodes, new_scope, autoescape, chain, block_definitions, super_stack)
            output.append(out)

    def _eval_expr(self, expr, scope, autoescape, chain, block_definitions, super_stack, lineno) -> any:
        if isinstance(expr, LitExpr):
            return expr.value

        if isinstance(expr, VarExpr):
            return self._resolve_path(expr.path, scope, lineno)

        if isinstance(expr, SuperExpr):
            # Find the current block's super chain
            if '__block_super_chain' not in scope:
                raise TemplateRenderError("no less derived definition of the block", lineno)

            next_defs = scope['__block_super_chain']
            if not next_defs:
                raise TemplateRenderError("no less derived definition of the block", lineno)

            # The next definition is next_defs[0][1] (the node)
            # We need to render it.
            # But wait, if we render next_defs[0], and it has super(), it needs next_defs[1:].

            next_node = next_defs[0][1]
            remaining_defs = next_defs[1:]

            # We need to render next_node.body_nodes.
            # The scope for this render must have '__block_super_chain' = remaining_defs

            new_scope = scope.copy()
            if remaining_defs:
                new_scope['__block_super_chain'] = remaining_defs
            else:
                # If no more, remove it? Or leave empty?
                # If empty, super() in next_node will fail.
                new_scope['__block_super_chain'] = []

            out = self._render_nodes(next_node.body_nodes, new_scope, autoescape, chain, block_definitions, super_stack)
            return out

        if isinstance(expr, FilterExpr):
            val = self._eval_expr(expr.source, scope, autoescape, chain, block_definitions, super_stack, lineno)
            return self._apply_filter(val, expr.name, expr.arg, lineno)

        raise TemplateRenderError("unknown expression type", lineno)

    def _resolve_path(self, path, scope, lineno) -> any:
        name = path[0]
        if name in scope:
            val = scope[name]
        else:
            val = None

        for segment in path[1:]:
            val = self._resolve_segment(val, segment, lineno)

        return val

    def _resolve_segment(self, val, segment, lineno) -> any:
        if val is None:
            return None

        if isinstance(segment, int):
            if isinstance(val, (list, tuple)):
                try:
                    return val[segment]
                except IndexError:
                    return None
            else:
                return None

        if isinstance(val, collections.abc.Mapping):
            return val.get(str(segment), None)

        if isinstance(val, (list, tuple)):
            return None

        if isinstance(segment, str):
            if segment.startswith('_'):
                return None
            try:
                return getattr(val, segment, None)
            except AttributeError:
                return None

        return None

    def _apply_filter(self, val, name, arg, lineno) -> any:
        if name == 'upper':
            return self._to_text(val).upper()
        if name == 'lower':
            return self._to_text(val).lower()
        if name == 'trim':
            return self._to_text(val).strip()
        if name == 'length':
            if val is None: return 0
            try: return len(val)
            except TypeError: raise TemplateRenderError(f"length filter cannot handle {type(val).__name__}", lineno)
        if name == 'first':
            if val is None: return None
            if isinstance(val, str): return val[0] if len(val) > 0 else None
            if isinstance(val, (list, tuple)): return val[0] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                try: return next(iter(val))
                except StopIteration: return None
            return None
        if name == 'last':
            if val is None: return None
            if isinstance(val, str): return val[-1] if len(val) > 0 else None
            if isinstance(val, (list, tuple)): return val[-1] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                items = list(val)
                return items[-1] if items else None
            return None
        if name == 'reverse':
            if val is None: return None
            if isinstance(val, str): return val[::-1]
            if isinstance(val, collections.abc.Iterable): return list(val)[::-1]
            raise TemplateRenderError(f"reverse filter cannot handle {type(val).__name__}", lineno)
        if name == 'join':
            if arg is None: raise TemplateRenderError("join requires an argument", lineno)
            sep = str(arg)
            if val is None: return ""
            try: return sep.join(self._to_text(item) for item in val)
            except TypeError: raise TemplateRenderError(f"join filter cannot handle {type(val).__name__}", lineno)
        if name == 'default':
            if arg is None: raise TemplateRenderError("default requires an argument", lineno)
            if val is None or (isinstance(val, str) and val == ""):
                return arg
            return val
        if name == 'truncate':
            if arg is None: raise TemplateRenderError("truncate requires an argument", lineno)
            N = arg
            text = self._to_text(val)
            if len(text) > N: return text[:N] + "..."
            return text
        if name == 'items':
            if val is None: return []
            if isinstance(val, collections.abc.Mapping): return list(val.items())
            raise TemplateRenderError(f"items filter cannot handle {type(val).__name__}", lineno)
        if name == 'safe':
            # Return value unchanged. 
            # The autoescape logic in _render_nodes checks if the last filter was safe.
            return val
        if name == 'escape':
            return html.escape(self._to_text(val), quote=True)

        raise TemplateRenderError(f"unknown filter '{name}'", lineno)

    def _to_text(self, val) -> str:
        if val is None:
            return ""
        return str(val)

    def _eval_cond(self, cond, scope, autoescape, chain, block_definitions, super_stack, lineno) -> bool:
        if isinstance(cond, BoolCond):
            val = self._eval_expr(cond.expr, scope, autoescape, chain, block_definitions, super_stack, lineno)
            return bool(val)
        if isinstance(cond, NotCond):
            return not self._eval_cond(cond.operand, scope, autoescape, chain, block_definitions, super_stack, lineno)
        if isinstance(cond, AndCond):
            if not self._eval_cond(cond.left, scope, autoescape, chain, block_definitions, super_stack, lineno): return False
            return self._eval_cond(cond.right, scope, autoescape, chain, block_definitions, super_stack, lineno)
        if isinstance(cond, OrCond):
            if self._eval_cond(cond.left, scope, autoescape, chain, block_definitions, super_stack, lineno): return True
            return self._eval_cond(cond.right, scope, autoescape, chain, block_definitions, super_stack, lineno)
        if isinstance(cond, CompareCond):
            left = self._eval_expr(cond.left, scope, autoescape, chain, block_definitions, super_stack, lineno)
            right = self._eval_expr(cond.right, scope, autoescape, chain, block_definitions, super_stack, lineno)
            op = cond.op
            try:
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            except TypeError:
                raise TemplateRenderError("cannot compare values", lineno)
        raise TemplateRenderError("unknown condition type", lineno)

def render(source: str, context: dict = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)
