from .lexer import tokenize, Token, TemplateSyntaxError
import re

# Reserved words for variable names
RESERVED = {'and', 'or', 'not', 'in', 'super'}

# Filter specifications: (name, has_arg, arg_type)
# arg_type: 'str', 'int', 'any' (str or int)
FILTERS = {
    'upper': (False, None),
    'lower': (False, None),
    'trim': (False, None),
    'length': (False, None),
    'first': (False, None),
    'last': (False, None),
    'reverse': (False, None),
    'items': (False, None),
    'join': (True, 'str'),
    'default': (True, 'any'),
    'truncate': (True, 'int'),
    'safe': (False, None),
    'escape': (False, None),
}

class TokenStream:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        token = self.peek()
        if token:
            self.pos += 1
        return token

class Node:
    pass

class TextNode(Node):
    def __init__(self, text: str):
        self.text = text

class VarNode(Node):
    def __init__(self, expr, lineno):
        self.expr = expr
        self.lineno = lineno

class BlockNode(Node):
    pass

class IfNode(BlockNode):
    def __init__(self):
        self.branches = [] # list of (cond, body_nodes)
        self.else_body = None # list of body_nodes
        self.lineno = 0

class ForNode(BlockNode):
    def __init__(self, var_name, iterable_expr, body_nodes, else_body, lineno):
        self.var_name = var_name
        self.iterable_expr = iterable_expr
        self.body_nodes = body_nodes
        self.else_body = else_body
        self.lineno = lineno

class ExtendsNode(Node):
    def __init__(self, name, lineno):
        self.name = name
        self.lineno = lineno

class BlockDefNode(Node):
    def __init__(self, name, body_nodes, lineno):
        self.name = name
        self.body_nodes = body_nodes
        self.lineno = lineno

class CondNode(Node):
    pass

class OrCond(CondNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class AndCond(CondNode):
    def __init__(self, left, right):
        self.left = left
        self.right = right

class NotCond(CondNode):
    def __init__(self, operand):
        self.operand = operand

class CompareCond(CondNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class BoolCond(CondNode):
    def __init__(self, expr):
        self.expr = expr

class ExprNode(Node):
    pass

class LitExpr(ExprNode):
    def __init__(self, value):
        self.value = value

class VarExpr(ExprNode):
    def __init__(self, path):
        self.path = path

class SuperExpr(ExprNode):
    def __init__(self, lineno):
        self.lineno = lineno

class FilterExpr(ExprNode):
    def __init__(self, source, name, arg):
        self.source = source
        self.name = name
        self.arg = arg

def parse(source: str) -> list:
    tokens = tokenize(source)
    stream = TokenStream(tokens)

    # Check for extends at the very beginning
    extends_node = None
    while True:
        token = stream.peek()
        if not token:
            break
        if token.kind == 'text':
            if not token.value.isspace():
                break
            stream.next()
        elif token.kind == 'block':
            parts = token.value.split()
            if not parts:
                stream.next()
                continue
            key = parts[0]
            if key == 'extends':
                stream.next()
                extends_node = parse_extends(token)
            elif key in ('if', 'for', 'block'):
                # Other tags are allowed after whitespace/comments, but extends must be FIRST
                # So if we see something else, extends was not found or was not first
                # But we already processed extends. If we see another block, it's fine.
                # We break out of the preamble loop and let parse_body handle the rest.
                break
            else:
                break
        else:
            break

    nodes = parse_body(stream)

    if stream.peek():
        token = stream.peek()
        if token.kind == 'block':
            key = token.value.split()[0]
            if key in ('endfor', 'endif', 'else', 'elif', 'endblock'):
                 raise TemplateSyntaxError(f"unexpected '{key}'", token.lineno)
        raise TemplateSyntaxError("unexpected end of template", token.lineno)

    if extends_node:
        return [extends_node] + nodes

    return nodes

def parse_extends(token):
    parts = token.value.split(None, 1)
    if len(parts) < 2:
        raise TemplateSyntaxError("extends requires a name", token.lineno)
    rest = parts[1].strip()
    if not (rest.startswith('"') and rest.endswith('"') or rest.startswith("'") and rest.endswith("'")):
        raise TemplateSyntaxError("extends name must be a quoted string", token.lineno)
    name = rest[1:-1]
    if not name:
        raise TemplateSyntaxError("extends name cannot be empty", token.lineno)
    return ExtendsNode(name, token.lineno)

def parse_body(stream: TokenStream, in_block=False):
    nodes = []
    while True:
        token = stream.peek()
        if not token:
            break

        if token.kind == 'block':
            parts = token.value.split()
            if not parts:
                 stream.next()
                 continue
            key = parts[0]

            if key in ('endfor', 'endif', 'else', 'elif', 'endblock'):
                break

            if key == 'if':
                nodes.append(parse_if(stream, in_block))
                continue
            elif key == 'for':
                nodes.append(parse_for(stream, in_block))
                continue
            elif key == 'block':
                nodes.append(parse_block(stream, in_block))
                continue
            elif key == 'extends':
                raise TemplateSyntaxError("extends must be the first tag", token.lineno)
            else:
                raise TemplateSyntaxError(f"unknown statement '{key}'", token.lineno)

        elif token.kind == 'var':
            stream.next()
            expr = parse_value_expr(token.value, token.lineno, in_block)
            nodes.append(VarNode(expr, token.lineno))

        elif token.kind == 'text':
            stream.next()
            nodes.append(TextNode(token.value))

        else:
            raise TemplateSyntaxError(f"unexpected token kind {token.kind}", token.lineno)

    return nodes

def parse_if(stream: TokenStream, in_block):
    token = stream.next()
    # token.value is like "if COND"
    rest = token.value[3:].strip() # remove "if "
    cond = parse_condition(rest, token.lineno, in_block)

    body = parse_body(stream, in_block)
    node = IfNode()
    node.lineno = token.lineno
    node.branches.append((cond, body))

    has_else = False

    while True:
        tok = stream.peek()
        if not tok:
            raise TemplateSyntaxError("unclosed if", token.lineno)

        if tok.kind != 'block':
             # Should not happen, parse_body stops at block
             raise TemplateSyntaxError("unexpected token inside if", tok.lineno)

        parts = tok.value.split()
        key = parts[0]

        if key == 'elif':
            if has_else:
                raise TemplateSyntaxError("elif after else", tok.lineno)
            stream.next()
            # value is "elif COND"
            rest = tok.value[5:].strip()
            cond = parse_condition(rest, tok.lineno, in_block)
            body = parse_body(stream, in_block)
            node.branches.append((cond, body))

        elif key == 'else':
            if has_else:
                raise TemplateSyntaxError("duplicate else", tok.lineno)
            if len(parts) > 1:
                 raise TemplateSyntaxError("unexpected arguments for else", tok.lineno)
            stream.next()
            has_else = True
            body = parse_body(stream, in_block)
            node.else_body = body

        elif key == 'endif':
            if len(parts) > 1:
                 raise TemplateSyntaxError("unexpected arguments for endif", tok.lineno)
            stream.next()
            break

        else:
             # This should have been caught by parse_body or handled by if/for.
             # If we are here, it means parse_body returned but the token is not a closer.
             # But parse_body breaks on ANY block token? No.
             # If parse_body sees 'if', it consumes.
             # If parse_body sees unknown, it errors.
             # If parse_body sees 'endfor', it breaks.
             # So if we are here, tok is 'endfor' or something else unexpected?
             # Or 'if' / 'for' which would have been consumed by parse_body.
             # If parse_body saw 'endfor', it broke.
             # So here we see 'endfor' inside an 'if'.
            raise TemplateSyntaxError(f"unexpected '{key}' inside if", tok.lineno)

    return node

def parse_for(stream: TokenStream, in_block):
    token = stream.next()
    # token.value is like "for x in y"
    parts = token.value.split()
    if len(parts) < 3 or parts[0] != 'for' or parts[2] != 'in':
        raise TemplateSyntaxError("malformed for statement", token.lineno)

    var_name = parts[1]
    if var_name in RESERVED:
        raise TemplateSyntaxError("cannot use reserved word as variable name", token.lineno)

    expr_str = " ".join(parts[3:])
    iterable_expr = parse_value_expr(expr_str, token.lineno, in_block)

    body = parse_body(stream, in_block)

    else_body = None
    has_else = False

    # After parse_body, we should be at 'else' or 'endfor'
    tok = stream.peek()
    if not tok:
        raise TemplateSyntaxError("unclosed for", token.lineno)

    if tok.kind == 'block':
        parts = tok.value.split()
        key = parts[0]

        if key == 'else':
            if len(parts) > 1:
                raise TemplateSyntaxError("unexpected arguments for else", tok.lineno)
            stream.next()
            has_else = True
            else_body = parse_body(stream, in_block)
            tok = stream.peek()
            if not tok:
                raise TemplateSyntaxError("unclosed for", token.lineno)
            parts = tok.value.split()
            key = parts[0]

        if key == 'endfor':
            if len(parts) > 1:
                raise TemplateSyntaxError("unexpected arguments for endfor", tok.lineno)
            stream.next()
        else:
            raise TemplateSyntaxError(f"unexpected '{key}' inside for", tok.lineno)
    else:
        raise TemplateSyntaxError("unclosed for", token.lineno)

    return ForNode(var_name, iterable_expr, body, else_body, token.lineno)

def parse_block(stream: TokenStream, in_block):
    token = stream.next()
    parts = token.value.split()
    if len(parts) < 2:
        raise TemplateSyntaxError("block requires a name", token.lineno)

    name = parts[1]
    if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name) or name in RESERVED:
        raise TemplateSyntaxError(f"invalid block name '{name}'", token.lineno)

    body = parse_body(stream, True) # in_block=True

    tok = stream.peek()
    if not tok:
        raise TemplateSyntaxError(f"unclosed block '{name}'", token.lineno)

    if tok.kind == 'block':
        parts = tok.value.split()
        key = parts[0]
        if key == 'endblock':
            if len(parts) > 1:
                end_name = parts[1]
                if end_name != name:
                    raise TemplateSyntaxError(f"endblock name '{end_name}' does not match block name '{name}'", tok.lineno)
            stream.next()
        else:
            raise TemplateSyntaxError(f"unexpected '{key}' inside block '{name}'", tok.lineno)
    else:
        raise TemplateSyntaxError(f"unclosed block '{name}'", token.lineno)

    return BlockDefNode(name, body, token.lineno)

def parse_value_expr(s: str, lineno: int, in_block=False) -> ExprNode:
    s = s.strip()
    if not s:
        raise TemplateSyntaxError("empty expression", lineno)

    # Check if the entire expression is just super()
    # This must be the ONLY content of the expression to be valid in {{ }} if inside block
    # If it has filters or other ops, it's an error if it contains super()

    parts = split_filters(s)

    if not parts:
        raise TemplateSyntaxError("empty expression", lineno)

    # If the source part (before first filter) is exactly "super()"
    # and there are no filters, we return SuperExpr if in_block, else error
    source_str = parts[0].strip()
    has_filters = len(parts) > 1

    # Check if source_str is super()
    is_super_call = False
    if re.match(r'^super\(\s*\)$', source_str):
        is_super_call = True

    if is_super_call:
        if not in_block:
            raise TemplateSyntaxError("super() used outside of a block", lineno)
        if has_filters:
            raise TemplateSyntaxError("super() cannot be used with filters", lineno)
        # Valid: {{ super() }} inside block
        # Note: We don't check here if it's inside a VarNode vs Condition vs For iterable.
        # That check happens in the callers (parse_body, parse_for, parse_condition)
        return SuperExpr(lineno)

    # If we get here, it's not a standalone super().
    # If any part of the expression (atom or filter arg) involves 'super' as a name, it's an error.
    # But parse_atom/parse_var_path will catch reserved words.

    source = parse_atom(parts[0].strip(), lineno)

    for part in parts[1:]:
        part = part.strip()
        # Parse filter name and arg
        # name may have :arg
        if ':' in part:
            idx = find_colon(part)
            if idx == -1:
                raise TemplateSyntaxError("malformed filter", lineno)
            name = part[:idx]
            arg_str = part[idx+1:]
            has_arg = True
        else:
            name = part
            arg_str = None
            has_arg = False

        name = name.strip()

        if name not in FILTERS:
            raise TemplateSyntaxError(f"unknown filter '{name}'", lineno)

        exp_has_arg, exp_arg_type = FILTERS[name]

        if has_arg != exp_has_arg:
            raise TemplateSyntaxError(f"filter '{name}' argument mismatch", lineno)

        arg = None
        if has_arg:
            if exp_arg_type == 'int':
                # Must be integer literal
                # Check format: optional minus, digits
                if not re.match(r'^-?\d+$', arg_str.strip()):
                    raise TemplateSyntaxError(f"invalid integer argument for '{name}'", lineno)
                try:
                    val = int(arg_str.strip())
                except ValueError:
                    raise TemplateSyntaxError("invalid integer argument", lineno)
                arg = val
            elif exp_arg_type == 'str':
                arg = parse_string_literal(arg_str, lineno)
            elif exp_arg_type == 'any':
                s_arg = arg_str.strip()
                if s_arg.startswith(('"', "'")):
                    arg = parse_string_literal(s_arg, lineno)
                elif re.match(r'^-?\d+$', s_arg):
                    arg = int(s_arg)
                else:
                    raise TemplateSyntaxError("invalid argument", lineno)

        # Special checks
        if name == 'truncate' and (arg is None or arg < 0):
             raise TemplateSyntaxError("truncate argument must be non-negative integer", lineno)

        source = FilterExpr(source, name, arg)

    return source

def split_filters(s: str):
    parts = []
    current = []
    in_quote = None

    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            current.append(c)
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
            current.append(c)
        elif c == '|':
            parts.append(''.join(current))
            current = []
        else:
            current.append(c)
        i += 1

    parts.append(''.join(current))
    return parts

def find_colon(s: str):
    in_quote = None
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
        elif c == ':':
            return i
        i += 1
    return -1

def parse_atom(s: str, lineno: int) -> ExprNode:
    s = s.strip()
    if not s:
        raise TemplateSyntaxError("empty atom", lineno)

    # String literal
    if len(s) >= 2 and s[0] in ('"', "'") and s[-1] == s[0]:
        # Check for internal quote of same type
        inner = s[1:-1]
        if s[0] in inner:
             raise TemplateSyntaxError("string literal cannot contain its quote", lineno)
        return LitExpr(inner)

    # Integer literal
    if re.match(r'^-?\d+$', s):
        try:
            return LitExpr(int(s))
        except ValueError:
            pass

    # Check for super() with optional whitespace
    # This case is usually handled in parse_value_expr before calling parse_atom
    # But if it reaches here, it's likely part of a larger expression (error) or we are parsing atom directly?
    # parse_value_expr handles the standalone super() case.
    # If we are here, it's either a string, int, or var path.
    # If s is "super()", it was handled in parse_value_expr.
    # If s is "super.x", parse_var_path will fail reserved word check.
    # If s is "super( )", parse_var_path will fail.

    # Variable path
    return parse_var_path(s, lineno)

def parse_string_literal(s: str, lineno: int) -> str:
    s = s.strip()
    if not s.startswith(('"', "'")):
        raise TemplateSyntaxError("expected string literal", lineno)
    quote = s[0]
    if len(s) < 2 or s[-1] != quote:
        raise TemplateSyntaxError("unterminated string literal", lineno)
    content = s[1:-1]
    if quote in content:
        raise TemplateSyntaxError("string literal cannot contain its quote", lineno)
    return content

def parse_var_path(s: str, lineno: int) -> ExprNode:
    parts = s.split('.')
    if not parts:
        raise TemplateSyntaxError("invalid variable path", lineno)

    first = parts[0]
    if not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', first):
        raise TemplateSyntaxError(f"invalid variable name '{first}'", lineno)
    if first in RESERVED:
        raise TemplateSyntaxError(f"reserved word '{first}' used as variable name", lineno)

    path = [first]
    for seg in parts[1:]:
        if re.match(r'^\d+$', seg):
            path.append(int(seg))
        elif re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', seg):
            if seg in RESERVED:
                 raise TemplateSyntaxError(f"reserved word '{seg}' used in path", lineno)
            path.append(seg)
        else:
            raise TemplateSyntaxError(f"invalid path segment '{seg}'", lineno)

    return VarExpr(path)

def parse_condition(s: str, lineno: int, in_block=False) -> CondNode:
    s = s.strip()
    if not s:
        raise TemplateSyntaxError("empty condition", lineno)

    # Check for super() usage in conditions
    if 'super' in s:
        # Simple check: if super appears anywhere in a condition, it's an error
        # unless it's a variable named super (which is reserved, so error anyway)
        # We rely on parse_value_expr to catch reserved words, but specifically for super()
        # If the condition contains super(), it's likely invalid usage.
        # However, we can't easily detect it here without parsing.
        # Let's rely on the fact that parse_value_expr will fail if 'super' is used as a var.
        # But what about `{{ super() }}` inside an if condition? 
        # `{% if super() %}` -> parse_condition("super()")
        # split or/and/not -> no.
        # find_comparison -> no op.
        # calls parse_value_expr("super()", in_block)
        # If in_block=True, parse_value_expr returns SuperExpr.
        # parse_condition returns BoolCond(SuperExpr).
        # This is allowed by parser currently.
        # Spec: "any other use of super: the line of the tag."
        # So `if super()` is invalid.
        # How to detect? 
        # parse_condition calls parse_value_expr.
        # If parse_value_expr returns SuperExpr, it's an error in condition context.

        # We can check if parse_value_expr returns SuperExpr.
        # But parse_condition splits first.
        # Let's defer to the call site? Or check here.
        # If the expression is just super(), and we are in condition, it's error.
        # But we don't know if it's just super() until we parse.

        # Better approach:
        # In parse_condition, if the expression (or sub-expression) parses to SuperExpr, raise error.
        # Since we don't have the AST yet, we can't check type.
        # We can check string content? `super()` is distinct.
        # But `a == super()` is also invalid.

        # The most robust way:
        # Parse the condition into AST first, then validate no SuperExpr nodes exist.
        # Let's do that.
        node = _parse_condition_internal(s, lineno, in_block)
        if contains_super(node):
             raise TemplateSyntaxError("super() cannot be used in conditions", lineno)
        return node

    return _parse_condition_internal(s, lineno, in_block)

def _parse_condition_internal(s: str, lineno: int, in_block: bool) -> CondNode:
    # Handle OR
    parts = split_keyword(s, "or")
    if len(parts) > 1:
        node = _parse_condition_internal(parts[0], lineno, in_block)
        for p in parts[1:]:
            node = OrCond(node, _parse_condition_internal(p, lineno, in_block))
        return node

    # Handle AND
    parts = split_keyword(s, "and")
    if len(parts) > 1:
        node = _parse_condition_internal(parts[0], lineno, in_block)
        for p in parts[1:]:
            node = AndCond(node, _parse_condition_internal(p, lineno, in_block))
        return node

    # Handle NOT
    if s.startswith("not ") or s.startswith("not("): # Spec says no parentheses.
         # Spec: "not a == b" means "not (a == b)".
         # Precedence: or, and, not, comparison.
         # So if we start with "not ", the operand is the rest.
         rest = s[4:].strip()
         return NotCond(_parse_condition_internal(rest, lineno, in_block))

    # Handle Comparison
    left_expr_str, op, right_expr_str = find_comparison(s, lineno)

    if op is not None:
        # Check for chained comparisons: "a < b < c"
        # find_comparison finds the first op.
        # If right_expr_str contains another comparison op, it's an error?
        # Or is it just parsed recursively?
        # Spec: "There is at most one comparison between two value expressions".
        # So `a < b < c` should be error.
        # find_comparison("a < b < c") returns ("a", "<", "b < c")
        # We must check if "b < c" contains a comparison.

        # Simple check: if right side has comparison operators outside quotes, error.
        if has_comparison_operator(right_expr_str):
             raise TemplateSyntaxError("chained comparisons are not allowed", lineno)

        left = parse_value_expr(left_expr_str, lineno, in_block)
        right = parse_value_expr(right_expr_str, lineno, in_block)
        return CompareCond(left, op, right)

    # If no comparison, it's a bare value expression tested for truthiness
    expr = parse_value_expr(s, lineno, in_block)
    return BoolCond(expr)

def has_comparison_operator(s: str):
    in_quote = None
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
        else:
            if s[i:i+2] in ('<=', '>=', '==', '!=', '&&', '||'): # || && not used but just in case
                return True
            if c in ('<', '>', '!', '='):
                # Check if it's part of a known op or just stray?
                # In this context, if we see < > = ! outside quotes, it's likely a comparison op.
                # But = is not an operator. == is.
                # ! is not an operator. != is.
                # We already checked 2-char ops.
                # If we see < or > here, it's a single char op.
                if c in ('<', '>'):
                    return True
        i += 1
    return False

def split_keyword(s: str, kw: str):
    parts = []
    current = []
    in_quote = None
    i = 0
    n = len(s)
    kw_len = len(kw)

    while i < n:
        c = s[i]
        if in_quote:
            current.append(c)
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
            current.append(c)
        else:
            # Check for keyword
            if s[i:i+kw_len] == kw:
                # Check word boundaries
                prev_ok = (i == 0) or (not s[i-1].isalnum() and s[i-1] != '_')
                next_ok = (i + kw_len == n) or (not s[i+kw_len].isalnum() and s[i+kw_len] != '_')

                if prev_ok and next_ok:
                    parts.append(''.join(current))
                    current = []
                    i += kw_len
                    continue

        current.append(c)
        i += 1

    parts.append(''.join(current))
    return parts

def find_comparison(s: str, lineno: int):
    in_quote = None
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_quote:
            if c == in_quote:
                in_quote = None
        elif c in ('"', "'"):
            in_quote = c
        else:
            # Check for operators
            # Order matters: <= >= before < >
            if s[i:i+2] in ('<=', '>=', '==', '!='):
                return s[:i].strip(), s[i:i+2], s[i+2:].strip()
            if c == '<' or c == '>':
                # Ensure not part of <= >= which was already checked
                # Since we checked 2-char ops first, if we are here, it's single char.
                # But wait, if s[i:i+2] was <=, we returned.
                # So if c=='<', and s[i+1]=='=', we would have caught it above.
                # So if we are here, it is definitely not <= or >=.
                return s[:i].strip(), c, s[i+1:].strip()
        i += 1

    return s, None, None

def contains_super(node):
    if isinstance(node, SuperExpr):
        return True
    if isinstance(node, OrCond):
        return contains_super(node.left) or contains_super(node.right)
    if isinstance(node, AndCond):
        return contains_super(node.left) or contains_super(node.right)
    if isinstance(node, NotCond):
        return contains_super(node.operand)
    if isinstance(node, CompareCond):
        return contains_super_in_expr(node.left) or contains_super_in_expr(node.right)
    if isinstance(node, BoolCond):
        return contains_super_in_expr(node.expr)
    return False

def contains_super_in_expr(expr):
    if isinstance(expr, SuperExpr):
        return True
    if isinstance(expr, FilterExpr):
        return contains_super_in_expr(expr.source)
    return False

def parse_value_expr_in_for(s: str, lineno: int, in_block: bool):
    # Wrapper to check for super() in iterable context
    node = parse_value_expr(s, lineno, in_block)
    if contains_super_in_expr(node):
        raise TemplateSyntaxError("super() cannot be used in for-loop iterable", lineno)
    return node
