from .lexer import TemplateRenderError, TemplateNotFound, TemplateSyntaxError
import collections.abc
import html
import re

class DictLoader:
    def __init__(self, templates: dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name not in self.templates:
            raise TemplateNotFounddef render(self, context: dict = None, **kwargs) -> str:
        if context is None:
            context = {}
        else:
            context = dict(context) # Shallow copy to avoid modifying original

        # kwargs win over context
        scope = context.copy()
        scope.update(kwargs)

        # Build inheritance chain
        # chain is list of Template objects, most derived first
        chain = [self]
        visited = {self.name or "__main__"}
        current_template = self

        # We also need to keep track of the ExtendsNode from the child to report line numbers for errors
        # But standard Jinja behavior: errors in parent loading are reported at the extends line of the child.

        while True:
            ext_node = None
            for n in current_template.nodes:
                if isinstance(n, ExtendsNode):
                    ext_node = n
                    break

            if not ext_node:
                break

            pname = ext_node.name
            if pname in visited:
                raise TemplateRenderError(f"circular inheritance detected: '{pname}' is already in the chain", ext_node.lineno)
            visited.add(pname)

            if not self.loader:
                raise TemplateNotFound(pname)

            try:
                p_source = self.loader.get_source(pname)
            except TemplateNotFound:
                raise
            except Exception as e:
                raise TemplateNotFound(pname)

            try:
                p_template = Template(p_source, loader=self.loader, autoescape=self.autoescape, name=pname)
            except TemplateSyntaxError as e:
                # Propagate syntax error from parent. 
                # The spec says: "A TemplateSyntaxError in a parent's source, raised as it is."
                raise e

            chain.append(p_template)
            current_template = p_template

        # chain is now [Child, Parent, ..., Base]
        # Base is chain[-1]
        base_template = chain[-1]

        # Collect block definitions from all templates in the chain
        # block_definitions: name -> list of (template_index, BlockDefNode)
        # template_index 0 is most derived (Child)
        block_definitions = {} 

        for idx, tmpl in enumerate(chain):
            self._collect_blocks(tmpl.nodes, block_definitions, idx)

        # Render the base template's nodes
        # Pass the chain and block definitions
        # super_stack is not needed if we use the scope to pass super chain for the current block context
        return self._render_nodes(base_template.nodes, scope, self.autoescape, chain, block_definitions)

    def _collect_blocks(self, nodes, block_map, chain_idx):
        for node in nodes:
            if isinstance(node, BlockDefNode):
                if node.name not in block_map:
                    block_map[node.name] = []
                block_map[node.name].append((chain_idx, node))
                # Recurse into block body
                self._collect_blocks(node.body_nodes, block_map, chain_idx)
            elif isinstance(node, IfNode):
                for _, body in node.branches:
                    self._collect_blocks(body, block_map, chain_idx)
                if node.else_body:
                    self._collect_blocks(node.else_body, block_map, chain_idx)
            elif isinstance(node, ForNode):
                self._collect_blocks(node.body_nodes, block_map, chain_idx)
                if node.else_body:
                    self._collect_blocks(node.else_body, block_map, chain_idx)

    def _render_nodes(self, nodes, scope, autoescape, chain, block_definitions):
        output = []
        for node in nodes:
            if isinstance(node, TextNode):
                output.append(node.text)
            elif isinstance(node, VarNode):
                val = self._eval_expr(node.expr, scope, autoescape, chain, block_definitions, node.lineno)
                text = self._to_text(val)

                # Autoescape logic
                # If autoescape is on, escape UNLESS:
                # 1. The value is a SafeString (produced by safe/escape filters or super())
                # 2. The expression's last filter was safe/escape (handled by SafeString return)

                if autoescape and not isinstance(val, SafeString):
                    text = html.escape(text, quote=True)

                output.append(text)
            elif isinstance(node, IfNode):
                self._render_if(node, scope, output, autoescape, chain, block_definitions)
            elif isinstance(node, ForNode):
                self._render_for(node, scope, output, autoescape, chain, block_definitions)
            elif isinstance(node, BlockDefNode):
                # This is a block definition in the base template.
                # We need to find the most derived override.
                # block_definitions[name] contains list of (idx, node) sorted by idx (0 is most derived)

                defs = block_definitions.get(node.name, [])
                if defs:
                    # The most derived definition is defs[0]
                    # But wait, defs is built by iterating chain 0..N.
                    # If chain is [Child, Parent, Base], then for block "b":
                    # Child adds (0, child_node)
                    # Parent adds (1, parent_node)
                    # Base adds (2, base_node)
                    # defs = [(0, child_node), (1, parent_node), (2, base_node)]

                    # We want to render the most derived one (defs[0][1])
                    # And pass the "super chain" (defs[1:]) to the scope so super() works.

                    # However, this node (base_node) IS in defs.
                    # If we are here, we are rendering Base's node.
                    # But Base might not be the most derived.

                    # So we ignore the current node's body and render the most derived definition.

                    target_idx, target_node = defs[0]

                    # Construct super chain for target_node
                    # The super chain for defs[0] is defs[1:]
                    # Wait, super() in defs[0] should render defs[1] (if exists).
                    # super() in defs[1] should render defs[2].

                    # We pass a special list in scope: __block_super_chain__
                    # This list contains the REMAINING definitions to be rendered by super()

                    # If defs[0] is the most derived, its super chain is defs[1:]

                    # BUT, what if defs[0] is NOT the most derived?
                    # That cannot happen because we iterate chain 0..N and append.
                    # So defs[0] is always the most derived (lowest idx).

                    # So we render defs[0][1].body_nodes

                    # Construct new scope for this block body
                    new_scope = scope.copy()

                    # The super chain for the definition at index i in the list `defs` is defs[i+1:]
                    # We are rendering defs[0], so super chain is defs[1:]

                    # We store this in scope so SuperExpr can find it.
                    # We need to track which block we are currently in, so nested blocks work.
                    # We can use a stack in scope, or just pass it down.
                    # Since _render_nodes doesn't take block context explicitly in this simplified model,
                    # we inject it into scope.

                    # Actually, if we have nested blocks:
                    # Block A contains Block B.
                    # When rendering A, we set __current_super_chain_A__.
                    # When rendering B (inside A), we set __current_super_chain_B__.
                    # super() inside B uses __current_super_chain_B__.

                    # So we set a key in scope for the current block name.
                    # But super() is generic. It needs to know which block it's in.
                    # The SuperExpr doesn't know the block name.
                    # So we need a stack of super chains? 
                    # Or just overwrite the scope variable. 
                    # Since rendering is depth-first, and we create new_scope for each block body,
                    # the super chain for the inner block will overwrite the outer one in that scope copy.
                    # That works.

                    next_defs = defs[1:]
                    if next_defs:
                        # next_defs is list of (idx, node). 
                        # We need to store enough info to render them.
                        # We store the list of nodes?
                        # super() needs to render the NEXT definition's body.
                        # Andthat next definition may itself have a super() that needs the one after that.
                        # So we store the full remaining list.
                        # super() in the first of next_defs will use next_defs[1:] as its super chain.
                        new_scope['__current_super_chain'] = next_defs
                    else:
                        # No more definitions. super() will fail.
                        # We can remove the key or set it to None/empty list.
                        # Let's set it to None to distinguish from "not in a block".
                        new_scope['__current_super_chain'] = None

                    out = self._render_nodes(target_node.body_nodes, new_scope, autoescape, chain, block_definitions)
                    output.append(out)
                else:
                    # Should not happen if this node is from a template in the chain
                    # But if a block is defined in a template but not in the chain? No, chain includes all.
                    # If block_definitions is empty, it means no template in chain defined this block?
                    # Impossible since we are rendering a template that defines it.
                    # Unless the collection logic failed.
                    pass

        return "".join(output)

    def _render_if(self, node, scope, output, autoescape, chain, block_definitions):
        for cond, body in node.branches:
            if self._eval_cond(cond, scope, autoescape, chain, block_definitions, node.lineno):
                out = self._render_nodes(body, scope, autoescape, chain, block_definitions)
                output.append(out)
                return
        if node.else_body:
            out = self._render_nodes(node.else_body, scope, autoescape, chain, block_definitions)
            output.append(out)

    def _render_for(self, node, scope, output, autoescape, chain, block_definitions):
        val = self._eval_expr(node.iterable_expr, scope, autoescape, chain, block_definitions, node.lineno)

        try:
            if val is None:
                iterator = []
            elif isinstance(val, (list, tuple, str)):
                iterator = val
            elif isinstance(val, collections.abc.Mapping):
                iterator = list(val.keys()) 
            elif isinstance(val, collections.abc.Iterable):
                iterator = list(val)
            else:
                raise TemplateRenderError("value is not iterable", node.lineno)
        except Exception:
             raise TemplateRenderError("value is not iterable", node.lineno)

        length = len(iterator)

        if length == 0:
            if node.else_body:
                out = self._render_nodes(node.else_body, scope, autoescape, chain, block_definitions)
                output.append(out)
            return

        new_scope = scope.copy()

        for idx, item in enumerate(iterator):
            new_scope[node.var_name] = item
            loop_data = {
                'index': idx + 1,
                'index0': idx,
                'first': (idx == 0),
                'last': (idx == length - 1),
                'length': length
            }
            new_scope['loop'] = loop_data
            out = self._render_nodes(node.body_nodes, new_scope, autoescape, chain, block_definitions)
            output.append(out)

    def _eval_expr(self, expr, scope, autoescape, chain, block_definitions, lineno) -> any:
        if isinstance(expr, LitExpr):
            return expr.value

        if isinstance(expr, VarExpr):
            return self._resolve_path(expr.path, scope, lineno)

        if isinstance(expr, SuperExpr):
            # Find the current block's super chain
            if '__current_super_chain' not in scope:
                raise TemplateRenderError("super() outside of block", lineno)

            next_defs = scope['__current_super_chain']
            if not next_defs:
                raise TemplateRenderError("no less derived definition of the block", lineno)

            # The next definition is next_defs[0][1] (the node)
            # We need to render it.
            # The scope for this render must have '__current_super_chain' = next_defs[1:]

            next_node = next_defs[0][1]
            remaining_defs = next_defs[1:]

            new_scope = scope.copy()
            if remaining_defs:
                new_scope['__current_super_chain'] = remaining_defs
            else:
                new_scope['__current_super_chain'] = None

            out = self._render_nodes(next_node.body_nodes, new_scope, autoescape, chain, block_definitions)
            return SafeString(out)

        if isinstance(expr, FilterExpr):
            val = self._eval_expr(expr.source, scope, autoescape, chain, block_definitions, lineno)
            return self._apply_filter(val, expr.name, expr.arg, lineno)

        raise TemplateRenderError("unknown expression type", lineno)

    def _resolve_path(self, path, scope, lineno) -> any:
        name = path[0]
        if name in scope:
            val = scope[name]
        else:
            val = None

        for segment in path[1:]:
            val = self._resolve_segment(val, segment, lineno)

        return val

    def _resolve_segment(self, val, segment, lineno) -> any:
        if val is None:
            return None

        if isinstance(segment, int):
            if isinstance(val, (list, tuple)):
                try:
                    return val[segment]
                except IndexError:
                    return None
            else:
                return None

        if isinstance(val, collections.abc.Mapping):
            return val.get(str(segment), None)

        if isinstance(val, (list, tuple)):
            return None

        if isinstance(segment, str):
            if segment.startswith('_'):
                return None
            try:
                return getattr(val, segment, None)
            except AttributeError:
                return None

        return None

    def _apply_filter(self, val, name, arg, lineno) -> any:
        if name == 'upper':
            return self._to_text(val).upper()
        if name == 'lower':
            return self._to_text(val).lower()
        if name == 'trim':
            return self._to_text(val).strip()
        if name == 'length':
            if val is None: return 0
            try: return len(val)
            except TypeError: raise TemplateRenderError(f"length filter cannot handle {type(val).__name__}", lineno)
        if name == 'first':
            if val is None: return None
            if isinstance(val, str): return val[0] if len(val) > 0 else None
            if isinstance(val, (list, tuple)): return val[0] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                try: return next(iter(val))
                except StopIteration: return None
            return None
        if name == 'last':
            if val is None: return None
            if isinstance(val, str): return val[-1] if len(val) > 0 else None
            if isinstance(val, (list, tuple)): return val[-1] if len(val) > 0 else None
            if isinstance(val, collections.abc.Iterable):
                items = list(val)
                return items[-1] if items else None
            return None
        if name == 'reverse':
            if val is None: return None
            if isinstance(val, str): return val[::-1]
            if isinstance(val, collections.abc.Iterable): return list(val)[::-1]
            raise TemplateRenderError(f"reverse filter cannot handle {type(val).__name__}", lineno)
        if name == 'join':
            if arg is None: raise TemplateRenderError("join requires an argument", lineno)
            sep = str(arg)
            if val is None: return ""
            try: return sep.join(self._to_text(item) for item in val)
            except TypeError: raise TemplateRenderError(f"join filter cannot handle {type(val).__name__}", lineno)
        if name == 'default':
            if arg is None: raise TemplateRenderError("default requires an argument", lineno)
            if val is None or (isinstance(val, str) and val == ""):
                return arg
            return val
        if name == 'truncate':
            if arg is None: raise TemplateRenderError("truncate requires an argument", lineno)
            N = arg
            text = self._to_text(val)
            if len(text) > N: return text[:N] + "..."
            return text
        if name == 'items':
            if val is None: return []
            if isinstance(val, collections.abc.Mapping): return list(val.items())
            raise TemplateRenderError(f"items filter cannot handle {type(val).__name__}", lineno)
        if name == 'safe':
            return SafeString(self._to_text(val))
        if name == 'escape':
            return SafeString(html.escape(self._to_text(val), quote=True))

        raise TemplateRenderError(f"unknown filter '{name}'", lineno)

    def _to_text(self, val) -> str:
        if val is None:
            return ""
        if isinstance(val, SafeString):
            return str(val)
        return str(val)

    def _eval_cond(self, cond, scope, autoescape, chain, block_definitions, lineno) -> bool:
        if isinstance(cond, BoolCond):
            val = self._eval_expr(cond.expr, scope, autoescape, chain, block_definitions, lineno)
            return bool(val)
        if isinstance(cond, NotCond):
            return not self._eval_cond(cond.operand, scope, autoescape, chain, block_definitions, lineno)
        if isinstance(cond, AndCond):
            if not self._eval_cond(cond.left, scope, autoescape, chain, block_definitions, lineno): return False
            return self._eval_cond(cond.right, scope, autoescape, chain, block_definitions, lineno)
        if isinstance(cond, OrCond):
            if self._eval_cond(cond.left, scope, autoescape, chain, block_definitions, lineno): return True
            return self._eval_cond(cond.right, scope, autoescape, chain, block_definitions, lineno)
        if isinstance(cond, CompareCond):
            left = self._eval_expr(cond.left, scope, autoescape, chain, block_definitions, lineno)
            right = self._eval_expr(cond.right, scope, autoescape, chain, block_definitions, lineno)
            op = cond.op
            try:
                if op == '==': return left == right
                if op == '!=': return left != right
                if op == '<': return left < right
                if op == '<=': return left <= right
                if op == '>': return left > right
                if op == '>=': return left >= right
            except TypeError:
                raise TemplateRenderError("cannot compare values", lineno)
        raise TemplateRenderError("unknown condition type", lineno)

def render(source: str, context: dict = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)
