from dataclasses import dataclass
from typing import Any, Union
from minisql.tokens import Token, tokenize, SQLSyntaxError


# Syntax Tree Nodes
@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Select:
    columns: Union[None, list[str]]
    table: str
    where: Any
    order_by: list[tuple[str, bool]]
    limit: Union[None, int]


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_kind: str = None, expected_value: Any = None) -> Token:
        token = self.tokens[self.pos]
        if expected_kind is not None and token.kind != expected_kind:
            raise SQLSyntaxError(f"Expected {expected_kind}, got {token.kind}", token.pos)
        if expected_value is not None and token.value != expected_value:
            raise SQLSyntaxError(f"Expected {expected_value}, got {token.value}", token.pos)
        self.pos += 1
        return token

    def match(self, kind: str, value: Any = None) -> bool:
        token = self.peek()
        if token.kind == kind:
            if value is None or token.value == value:
                return True
        return False

    def parse(self) -> Select:
        # SELECT
        self.consume("KEYWORD", "SELECT")

        # Select List
        columns = self.parse_select_list()

        # FROM
        self.consume("KEYWORD", "FROM")

        # Table Name
        table_token = self.consume("IDENT")
        table_name = table_token.value

        # WHERE
        where = None
        if self.match("KEYWORD", "WHERE"):
            self.consume()
            where = self.parse_condition()

        # ORDER BY
        order_by = []
        if self.match("KEYWORD", "ORDER"):
            self.consume()
            self.consume("KEYWORD", "BY")
            order_by = self.parse_order_items()

        # LIMIT
        limit = None
        if self.match("KEYWORD", "LIMIT"):
            self.consume()
            num_token = self.consume("NUMBER")
            if not isinstance(num_token.value, int) or num_token.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", num_token.pos)
            limit = num_token.value

        # End of statement
        if not self.match("EOF"):
            raise SQLSyntaxError("Unexpected token after statement end", self.peek().pos)

        return Select(
            columns=columns,
            table=table_name,
            where=where,
            order_by=order_by,
            limit=limit
        )

    def parse_select_list(self) -> Union[None, list[str]]:
        if self.match("STAR"):
            self.consume()
            return None

        cols = []
        cols.append(self.parse_column_name())
        while self.match("COMMA"):
            self.consume()
            cols.append(self.parse_column_name())

        if len(set(cols)) != len(cols):
            raise SQLSyntaxError("Duplicate column in select list", self.tokens[self.pos-1].pos)

        return cols

    def parse_column_name(self) -> str:
        token = self.consume("IDENT")
        return token.value

    def parse_order_items(self) -> list[tuple[str, bool]]:
        items = []
        items.append(self.parse_order_item())
        while self.match("COMMA"):
            self.consume()
            items.append(self.parse_order_item())
        return items

    def parse_order_item(self) -> tuple[str, bool]:
        name = self.parse_column_name()
        desc = False
        if self.match("KEYWORD", "DESC"):
            self.consume()
            desc = True
        elif self.match("KEYWORD", "ASC"):
            self.consume()
        return (name, desc)

    def parse_condition(self) -> Any:
        return self.parse_or()

    def parse_or(self) -> Any:
        left = self.parse_and()
        while self.match("KEYWORD", "OR"):
            self.consume()
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self) -> Any:
        left = self.parse_not()
        while self.match("KEYWORD", "AND"):
            self.consume()
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self) -> Any:
        if self.match("KEYWORD", "NOT"):
            self.consume()
            operand = self.parse_not()
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self) -> Any:
        # Check for parenthesized condition
        if self.match("LPAREN"):
            self.consume()
            cond = self.parse_condition()
            self.consume("RPAREN")
            return cond

        # Parse operand
        left = self.parse_operand()

        # Check for IS [NOT] NULL
        if self.match("KEYWORD", "IS"):
            self.consume()
            negated = False
            if self.match("KEYWORD", "NOT"):
                self.consume()
                negated = True
            self.consume("KEYWORD", "NULL")
            return IsNull(left, negated)

        # Check for operator
        if self.match("OP"):
            op_token = self.consume("OP")
            right = self.parse_operand()
            return Compare(op_token.value, left, right)

        # Bare operand is not a condition in this grammar if we've reached here 
        # without an operator or IS NULL. However, the grammar says condition can be 
        # operand op operand OR ... OR IS NULL.
        # If we are at this point and haven't returned, it means we parsed an operand
        # but found no operator. This is a syntax error because a bare operand is not a condition.
        raise SQLSyntaxError("Expected operator or IS after operand", self.peek().pos)

    def parse_operand(self) -> Any:
        token = self.peek()
        if token.kind == "IDENT":
            self.consume()
            return Column(token.value)
        if token.kind == "NUMBER":
            self.consume()
            return Literal(token.value)
        if token.kind == "STRING":
            self.consume()
            return Literal(token.value)
        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.consume()
                return Literal(None)
            if token.value == "TRUE":
                self.consume()
                return Literal(True)
            if token.value == "FALSE":
                self.consume()
                return Literal(False)

        raise SQLSyntaxError(f"Expected operand, got {token.kind}", token.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()
