```python
from minisql.tokens import SQLError
from minisql.parser import (
    Select, Column, Literal, Compare, And, Or, Not, IsNull
)
from typing import Any, Union
import sys


class SQLExecutionError(SQLError):
    """Raised when execution fails due to logical or type errors."""
    pass


def get_value(row: dict, col: str) -> Any:
    return row.get(col, None)


def evaluate_operand(operand: Any, row: dict) -> Any:
    if isinstance(operand, Column):
        return get_value(row, operand.name)
    elif isinstance(operand, Literal):
        return operand.value
    else:
        raise SQLExecutionError(f"Invalid operand type: {type(operand)}")


def is_number(val: Any) -> bool:
    if isinstance(val, bool):
        return False
    return isinstance(val, (int, float))

def is_string(val: Any) -> bool:
    return isinstance(val, str)

def is_bool(val: Any) -> bool:
    return isinstance(val, bool)

def get_kind(val: Any) -> Union[str, None]:
    """Returns 'number', 'string', 'bool', or None (for NULL/Unknown/Invalid)."""
    if val is None:
        return None
    if is_number(val):
        return 'number'
    if is_string(val):
        return 'string'
    if is_bool(val):
        return 'bool'
    return None


def compare_values(op: str, left_val: Any, right_val: Any) -> Union[bool, None]:
    """
    Returns True, False, or None (Unknown).
    Raises SQLExecutionError for invalid comparisons.
    """
    # NULL logic
    if left_val is None or right_val is None:
        return None  # Unknown

    kind_left = get_kind(left_val)
    kind_right = get_kind(right_val)

    if kind_left != kind_right:
        # Different kinds
        if op == '=':
            return False
        elif op == '!=':
            return True
        else:
            raise SQLExecutionError(f"Cannot compare {kind_left} and {kind_right} with {op}")

    # Same kind
    try:
        if op == '=':
            return left_val == right_val
        elif op == '!=':
            return left_val != right_val
        elif op == '<':
            return left_val < right_val
        elif op == '<=':
            return left_val <= right_val
        elif op == '>':
            return left_val > right_val
        elif op == '>=':
            return left_val >= right_val
        else:
            raise SQLExecutionError(f"Unknown operator: {op}")
    except TypeError as e:
        raise SQLExecutionError(f"Comparison error: {e}")


def evaluate_condition(cond: Any, row: dict) -> Union[bool, None]:
    """
    Returns True, False, or None (Unknown).
    """
    if isinstance(cond, And):
        left_res = evaluate_condition(cond.left, row)
        right_res = evaluate_condition(cond.right, row)
        if left_res is False or right_res is False:
            return False
        if left_res is None or right_res is None:
            return None
        return True

    if isinstance(cond, Or):
        left_res = evaluate_condition(cond.left, row)
        right_res = evaluate_condition(cond.right, row)
        if left_res is True or right_res is True:
            return True
        if left_res is None or right_res is None:
            return None
        return False

    if isinstance(cond, Not):
        res = evaluate_condition(cond.operand, row)
        if res is None:
            return None
        return not res

    if isinstance(cond, Compare):
        left_val = evaluate_operand(cond.left, row)
        right_val = evaluate_operand(cond.right, row)
        return compare_values(cond.op, left_val, right_val)

    if isinstance(cond, IsNull):
        val = evaluate_operand(cond.operand, row)
        is_null = (val is None)
        if cond.negated:
            return not is_null
        else:
            return is_null

    raise SQLExecutionError(f"Invalid condition node: {type(cond)}")


def execute(stmt: Select, tables: dict[str, list[dict]]) -> list[dict]:
    if stmt.table not in tables:
        raise SQLExecutionError(f"Table '{stmt.table}' not found")

    source_rows = tables[stmt.table]

    # WHERE
    if stmt.where is not None:
        filtered_rows = [row for row in source_rows if evaluate_condition(stmt.where, row) is True]
    else:
        filtered_rows = list(source_rows) # Copy

    # ORDER BY
    if stmt.order_by:
        # Validate sort kinds and prepare keys
        def sort_key(row):
            keys = []
            for col_name, desc in stmt.order_by:
                val = get_value(row, col_name)
                if val is None:
                    # NULL sorts first in ASC, last in DESC.
                    # Python sorts tuples. We want a sentinel that behaves correctly.
                    # In ASC: NULL < anything.
                    # In DESC: NULL > anything.
                    # Standard trick: (is_null_flag, value)
                    # If ASC: (0, ...) for NULL? No, we want NULL first.
                    # If we use a custom comparator or key:
                    # Let's use a tuple: (kind_priority, value_for_sorting)
                    # Actually, simpler:
                    # For each column, return a tuple that allows correct sorting.
                    # We need to handle the case where different rows might have different non-null kinds.
                    # The spec says: "If the non-NULL values of an ordering column in the kept rows are of different kinds... raise SQLExecutionError"
                    pass
            return keys

        # Pre-pass to validate kinds for ordering columns
        for col_name, _ in stmt.order_by:
            kinds = set()
            for row in filtered_rows:
                val = get_value(row, col_name)
                if val is not None:
                    kind = get_kind(val)
                    if kind:
                        kinds.add(kind)
            if len(kinds) > 1:
                raise SQLExecutionError(f"Mixed types in ordering column '{col_name}'")

        # Now perform stable sort
        # Python's sort is stable. We sort by keys in reverse order of priority?
        # No, we can construct a key function.
        # Key for row: tuple of keys for each order item.
        # For each item:
        #   If value is NULL:
        #     ASC: should be smallest. Use (-inf, ...) ?
        #     DESC: should be largest. Use (inf, ...) ?
        #   If value is not NULL:
        #     Need to interleave NULLs correctly.
        #     
        # Alternative: Use a class for keys to override __lt__?
        # Or simpler: Map values to sortable tuples.
        # For a column col with desc=False (ASC):
        #   NULL -> (0, None)  -> sorts before (1, val) ? No, None isn't comparable with numbers.
        #   
        # Let's use a wrapper that handles the comparison logic for the sort key.
        # But sort(key=...) needs comparable objects.

        class SortKey:
            def __init__(self, val, desc):
                self.val = val
                self.desc = desc

            def __lt__(self, other):
                # We are sorting ascending by default in Python, so we define less-than.
                # However, we want NULLs first in ASC, last in DESC.
                # If both are NULL, they are equal.

                # Handle NULLs
                self_is_null = self.val is None
                other_is_null = other.val is None

                if self_is_null and other_is_null:
                    return False
                if self_is_null:
                    # If ASC, NULL comes first (is smaller). If DESC, NULL comes last (is larger).
                    if not self.desc: # ASC
                        return True
                    else: # DESC
                        return False
                if other_is_null:
                    # If ASC, value comes after NULL (is larger). If DESC, value comes before NULL (is smaller).
                    if not self.desc: # ASC
                        return False
                    else: # DESC
                        return True

                # Both are not null. We validated they have the same kind.
                # Comparison logic:
                # If desc=False (ASC): normal comparison
                # If desc=True (DESC): reverse comparison

                try:
                    if not self.desc:
                        return self.val < other.val
                    else:
                        return self.val > other.val
                except TypeError as e:
                    raise SQLExecutionError(f"Sort comparison error: {e}")

        # Build keys for each row
        # We need to sort by the first column, then second...
        # Python sorts tuples lexicographically.
        # So key(row) = (SortKey(col1_val, desc1), SortKey(col2_val, desc2), ...)

        def make_key(row):
            return tuple(SortKey(get_value(row, col_name), desc) for col_name, desc in stmt.order_by)

        # Sort
        filtered_rows.sort(key=make_key)

    # LIMIT
    if stmt.limit is not None:
        filtered_rows = filtered_rows[:stmt.limit]

    # Projection
    results = []
    for row in filtered_rows:
        if stmt.columns is None:
            new_row = dict(row)
        else:
            new_row = {}
            for col_name in stmt.columns:
                new_row[col_name] = get_value(row, col_name)
        results.append(new_row)

    return results


def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from minisql.parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)
