class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset: int = 0) -> Token:
        idx = self.pos + offset
        if idx >= len(self.tokens):
            return self.tokens[-1] 
        return self.tokens[idx]

    def consume(self, expected_kind: str = None, expected_value: Any = None) -> Token:
        token = self.tokens[self.pos]
        if expected_kind is not None and token.kind != expected_kind:
            raise SQLSyntaxError(f"Expected {expected_kind}, got {token.kind}", token.pos)
        if expected_value is not None and token.value != expected_value:
            raise SQLSyntaxError(f"Expected {expected_value}, got {token.value}", token.pos)
        self.pos += 1
        return token

    def match(self, kind: str, value: Any = None) -> bool:
        token = self.peek()
        if token.kind == kind:
            if value is None or token.value == value:
                return True
        return False

    def parse_ref(self) -> Column:
        start = self.pos
        token = self.peek()
        if token.kind != "IDENT":
            raise SQLSyntaxError(f"Expected identifier, got {token.kind}", token.pos)

        self.consume() 

        parts = [token.value]

        if self.match("DOT"):
            self.consume()
            second_token = self.peek()
            if second_token.kind != "IDENT":
                raise SQLSyntaxError(f"Expected identifier after '.', got {second_token.kind}", second_token.pos)
            self.consume()
            parts.append(".")
            parts.append(second_token.value)

        canonical = "".join(parts)
        return Column(canonical)

    def parse_agg(self) -> Aggregate:
        func_token = self.consume("KEYWORD")
        func_name = func_token.value 

        self.consume("LPAREN")

        arg = None
        if self.match("STAR"):
            self.consume()
            arg = None
        else:
            arg = self.parse_ref()

        self.consume("RPAREN")

        return Aggregate(func_name, arg)

    def parse(self) -> Select:
        self.consume("KEYWORD", "SELECT")

        # Select List
        # items_with_pos: list of (expr, key, start_pos)
        items_with_pos, columns, is_star, star_pos = self.parse_select_list()

        self.consume("KEYWORD", "FROM")

        table_token = self.consume("IDENT")
        table_name = table_token.value

        join = None
        if self.match("KEYWORD", "JOIN"):
            self.consume()
            join_table_token = self.consume("IDENT")
            join_table_name = join_table_token.value

            self.consume("KEYWORD", "ON")
            left_col = self.parse_ref()
            self.consume("OP", "=")
            right_col = self.parse_ref()

            join = Join(join_table_name, left_col, right_col)

        where = None
        if self.match("KEYWORD", "WHERE"):
            self.consume()
            where = self.parse_condition()

        group_by = []
        if self.match("KEYWORD", "GROUP"):
            self.consume()
            self.consume("KEYWORD", "BY")
            group_by = self.parse_group_by_refs()

        order_by_raw = [] # list of (text, desc, is_agg, start_pos)
        if self.match("KEYWORD", "ORDER"):
            self.consume()
            self.consume("KEYWORD", "BY")
            order_by_raw = self.parse_order_items()

        limit = None
        if self.match("KEYWORD", "LIMIT"):
            self.consume()
            num_token = self.consume("NUMBER")
            if not isinstance(num_token.value, int) or num_token.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", num_token.pos)
            limit = num_token.value

        if not self.match("EOF"):
            raise SQLSyntaxError("Unexpected token after statement end", self.peek().pos)

        # Post-parse validations

        has_aggregates = any(isinstance(e, Aggregate) for e, _, _ in items_with_pos)
        is_grouped = bool(group_by) or has_aggregates

        # 1. Check for * in grouped query
        if is_grouped and is_star:
            raise SQLSyntaxError("Cannot use * in grouped query", star_pos)

        # 2. Check for aggregates in ORDER BY of non-grouped query
        if not is_grouped:
            for text, desc, is_agg, pos in order_by_raw:
                if is_agg:
                    raise SQLSyntaxError("Aggregate in ORDER BY of non-grouped query", pos)

        # 3. Check column visibility in grouped query
        if is_grouped and not is_star:
            for expr, key, pos in items_with_pos:
                if isinstance(expr, Column):
                    if expr.name not in group_by:
                        raise SQLSyntaxError("Column not in GROUP BY and not aggregated", pos)

        # Constructing order_by final list (text, desc)
        order_by = [(text, desc) for text, desc, _, _ in order_by_raw]

        # Construct items for Select (expr, key)
        items = [(e, k) for e, k, _ in items_with_pos]

        return Select(
            columns=columns,
            table=table_name,
            where=where,
            order_by=order_by,
            limit=limit,
            items=items,
            join=join,
            group_by=group_by
        )

    def parse_select_list(self) -> tuple[list, Optional[list[str]], bool, int]:
        """
        Returns (items_with_pos, columns, is_star, star_pos).
        items_with_pos: list of (expr, key, start_pos)
        """
        if self.match("STAR"):
            token = self.consume()
            return ([], None, True, token.pos)

        items = []
        keys = set()

        # Parse first item
        start_pos = self.peek().pos
        expr, key = self.parse_select_item()
        if key in keys:
             raise SQLSyntaxError("Duplicate column key in select list", start_pos)
        keys.add(key)
        items.append((expr, key, start_pos))

        while self.match("COMMA"):
            self.consume()
            start_pos = self.peek().pos
            expr, key = self.parse_select_item()
            if key in keys:
                raise SQLSyntaxError("Duplicate column key in select list", start_pos)
            keys.add(key)
            items.append((expr, key, start_pos))

        return (items, [k for _, k, _ in items], False, -1)

    def parse_select_item(self) -> tuple[Any, str]:
        token = self.peek()
        expr = None
        key = None

        if token.kind == "KEYWORD" and token.value in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
            expr = self.parse_agg()
            key = expr.canonical_text
        else:
            expr = self.parse_ref()
            key = expr.name

        if self.match("KEYWORD", "AS"):
            self.consume()
            alias_token = self.consume("IDENT")
            key = alias_token.value

        return (expr, key)

    def parse_group_by_refs(self) -> list[str]:
        refs = []
        refs.append(self.parse_ref().name)
        while self.match("COMMA"):
            self.consume()
            refs.append(self.parse_ref().name)
        return refs

    def parse_order_items(self) -> list[tuple[str, bool, bool, int]]:
        items = []
        items.append(self.parse_order_item())
        while self.match("COMMA"):
            self.consume()
            items.append(self.parse_order_item())
        return items

    def parse_order_item(self) -> tuple[str, bool, bool, int]:
        # Returns (text, desc, is_agg, start_pos)
        token = self.peek()
        start_pos = token.pos
        is_agg = False

        if token.kind == "KEYWORD" and token.value in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
            is_agg = True
            expr = self.parse_agg()
            text = expr.canonical_text
        else:
            expr = self.parse_ref()
            text = expr.name

        desc = False
        if self.match("KEYWORD", "DESC"):
            self.consume()
            desc = True
        elif self.match("KEYWORD", "ASC"):
            self.consume()

        return (text, desc, is_agg, start_pos)

    def parse_condition(self) -> Any:
        return self.parse_or()

    def parse_or(self) -> Any:
        left = self.parse_and()
        while self.match("KEYWORD", "OR"):
            self.consume()
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self) -> Any:
        left = self.parse_not()
        while self.match("KEYWORD", "AND"):
            self.consume()
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self) -> Any:
        if self.match("KEYWORD", "NOT"):
            self.consume()
            operand = self.parse_not()
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self) -> Any:
        if self.match("LPAREN"):
            self.consume()
            cond = self.parse_condition()
            self.consume("RPAREN")
            return cond

        left = self.parse_operand()

        if self.match("KEYWORD", "IS"):
            self.consume()
            negated = False
            if self.match("KEYWORD", "NOT"):
                self.consume()
                negated = True
            self.consume("KEYWORD", "NULL")
            return IsNull(left, negated)

        if self.match("OP"):
            op_token = self.consume("OP")
            right = self.parse_operand()
            return Compare(op_token.value, left, right)

        raise SQLSyntaxError("Expected operator or IS after operand", self.peek().pos)

    def parse_operand(self) -> Any:
        token = self.peek()
        if token.kind == "IDENT":
            return self.parse_ref()

        if token.kind == "NUMBER":
            self.consume()
            return Literal(token.value)

        if token.kind == "STRING":
            self.consume()
            return Literal(token.value)

        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.consume()
                return Literal(None)
            if token.value == "TRUE":
                self.consume()
                return Literal(True)
            if token.value == "FALSE":
                self.consume()
                return Literal(False)

        raise SQLSyntaxError(f"Expected operand, got {token.kind}", token.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()
