    """
    Returns True, False, or None (Unknown).
    """
    if isinstance(cond, And):
        left_res = evaluate_condition(cond.left, row)
        right_res = evaluate_condition(cond.right, row)
        if left_res is False or right_res is False:
            return False
        if left_res is None or right_res is None:
            return None
        return True

    if isinstance(cond, Or):
        left_res = evaluate_condition(cond.left, row)
        right_res = evaluate_condition(cond.right, row)
        if left_res is True or right_res is True:
            return True
        if left_res is None or right_res is None:
