        # Canonical name is 't.c' or 'c' (if unqualified).
        # If unqualified 'c', error.
        if '.' not in col.name:
            raise SQLExecutionError(f"Unqualified reference '{col.name}' in JOIN query")
        table_part, col_part = col.name.split('.', 1)
        if table_part != from_table and table_part != join.table:
            raise SQLExecutionError(f"Unknown qualifier '{table_part}' in JOIN query")
        # The row keys in join result are 'table.col'
        return col.name
    else:
        # No join
        if '.' in col.name:
            table_part, col_part = col.name.split('.', 1)
            if table_part != from_table:
                raise SQLExecutionError(f"Unknown qualifier '{table_part}' in non-JOIN query")
