            # Create index-value pairs
            indexed_rows = list(enumerate(filtered_rows))

            def cmp_row_indices(i1, i2):
                idx1, _ = i1
                idx2, _ = i2

                for col_idx, (text, desc) in enumerate(stmt.order_by):
                    v1 = order_items_data[col_idx][idx1]
                    v2 = order_items_data[col_idx][idx2]

                    if v1 is None and v2 is None:
                        continue
                    if v1 is None:
                        if not desc: return -1
                        else: return 1
                    if v2 is None:
                        if not desc: return 1
                        else: return -1

                    # Same kind (validated)
                    if v1 == v2: continue
                    if not desc:
                        if v1 < v2: return -1
                        else: return 1
                    else:
                        if v1 > v2: return -1
                        else: return 1
                return 0

            import functools
            indexed_rows.sort(key=functools.cmp_to_key(cmp_row_indices))

            sorted_filtered_rows = [r for _, r in indexed_rows]

            output_rows = []
            for row in sorted_filtered_rows:
                output_row = {}
                for expr, key_name in stmt.items:
                    actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                    val = row.get(actual_key)
                    output_row[key_name] = val
                output_rows.append(output_row)

    # 5. Limit
    if stmt.limit is not None:
        output_rows = output_rows[:stmt.limit]

    return output_rows


def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from minisql.parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)
