from dataclasses import dataclass
from typing import Any


class SQLError(Exception):
    """Base class for all minisql errors."""
    pass


class SQLSyntaxError(SQLError):
    """Raised when tokenize or parse encounters invalid syntax."""

    def __init__(self, message: str, pos: int):
        self.pos = pos
        super().__init__(f"{message} at position {pos}")


@dataclass(frozen=True)
class Token:
    kind: str
    value: Any
    pos: int


KEYWORDS = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", 
    "ORDER", "BY", "ASC", "DESC", "LIMIT", 
    "IS", "NULL", "TRUE", "FALSE",
    "JOIN", "ON", "GROUP", "AS", "COUNT", "SUM", "AVG", "MIN", "MAX"
}


def tokenize(sql: str) -> list[Token]:
    """
    Tokenize a SQL string into a list of Tokens, ending with an EOF token.
    """
    tokens: list[Token] = []
    i = 0
    n = len(sql)

    while i < n:
        # Skip whitespace
        if sql[i].isspace():
            i += 1
            continue

        start = i
        char = sql[i]

        # Identifiers and Keywords
        if char.isalpha() or char == '_':
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                i += 1
            word = sql[start:i]
            upper_word = word.upper()
            if upper_word in KEYWORDS:
                tokens.append(Token("KEYWORD", upper_word, start))
            else:
                tokens.append(Token("IDENT", word, start))
            continue

        # Numbers
        # Must start with digit or -digit. 
        # If it starts with -, next MUST be digit.
        # If it starts with digit, it consumes digits.
        # If followed by ., it MUST have digit after dot to be a number.
        # Otherwise, if it's just digits, it's an int.
        if char.isdigit() or (char == '-' and i + 1 < n and sql[i+1].isdigit()):
            if char == '-':
                i += 1  # consume '-'

            while i < n and sql[i].isdigit():
                i += 1

            is_float = False
            if i < n and sql[i] == '.':
                # Check if digits follow. If not, it's not a number token here.
                # It might be an error if it looks like a number start but fails (e.g. 1.).
                # Spec: "A . must have digits on both sides; a . without them is an error at the ."
                # So if we are in number context and see dot, and no digit after, error at dot.
                if i + 1 >= n or not sql[i+1].isdigit():
                    raise SQLSyntaxError("Invalid number format", i)
                is_float = True
                i += 1  # consume '.'
                while i < n and sql[i].isdigit():
                    i += 1

            num_str = sql[start:i]
            if is_float:
                val = float(num_str)
            else:
                val = int(num_str)
            tokens.append(Token("NUMBER", val, start))
            continue

        # Strings
        if char == "'":
            j = i + 1
            val_chars = []
            terminated = False
            while j < n:
                if sql[j] == "'":
                    if j + 1 < n and sql[j+1] == "'":
                        val_chars.append("'")
                        j += 2
                    else:
                        terminated = True
                        break
                else:
                    val_chars.append(sql[j])
                    j += 1

            if not terminated:
                raise SQLSyntaxError("Unterminated string literal", start)

            val = "".join(val_chars)
            i = j + 1 # move past closing quote
            tokens.append(Token("STRING", val, start))
            continue

        # Operators
        if char == '!' and i + 1 < n and sql[i+1] == '=':
            tokens.append(Token("OP", '!=', start))
            i += 2
            continue
        if char == '<' and i + 1 < n and sql[i+1] == '>':
            tokens.append(Token("OP", '!=', start))
            i += 2
            continue
        if char == '<' and i + 1 < n and sql[i+1] == '=':
            tokens.append(Token("OP", '<=', start))
            i += 2
            continue
        if char == '>' and i + 1 < n and sql[i+1] == '=':
            tokens.append(Token("OP", '>=', start))
            i += 2
            continue
        if char == '<':
            tokens.append(Token("OP", '<', start))
            i += 1
            continue
        if char == '>':
            tokens.append(Token("OP", '>', start))
            i += 1
            continue
        if char == '=':
            tokens.append(Token("OP", '=', start))
            i += 1
            continue

        # Punctuation
        if char == '*':
            tokens.append(Token("STAR", "*", start))
            i += 1
            continue
        if char == ',':
            tokens.append(Token("COMMA", ",", start))
            i += 1
            continue
        if char == '(':
            tokens.append(Token("LPAREN", "(", start))
            i += 1
            continue
        if char == ')':
            tokens.append(Token("RPAREN", ")", start))
            i += 1
            continue
        if char == '.':
            tokens.append(Token("DOT", ".", start))
            i += 1
            continue

        # Unknown character
        raise SQLSyntaxError(f"Unexpected character '{char}'", start)

    tokens.append(Token("EOF", None, len(sql)))
    return tokens
