from dataclasses import dataclass, field
from typing import Any, Union, Optional
from minisql.tokens import Token, tokenize, SQLSyntaxError


# Syntax Tree Nodes
@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Aggregate:
    func: str
    arg: Union[Column, None]

    @property
    def canonical_text(self) -> str:
        if self.arg is None:
            return f"{self.func}(*)"
        return f"{self.func}({self.arg.name})"

@dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclass(frozen=True)
class Select:
    columns: Union[None, list[str]]
    table: str
    where: Any
    order_by: list[tuple[str, bool]]
    limit: Union[None, int]
    items: list = field(default_factory=list)
    join: Optional[Join] = None
    group_by: list[str] = field(default_factory=list)


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset: int = 0) -> Token:
        idx = self.pos + offset
        if idx >= len(self.tokens):
            return self.tokens[-1] 
        return self.tokens[idx]

    def consume(self, expected_kind: str = None, expected_value: Any = None) -> Token:
        token = self.tokens[self.pos]
        if expected_kind is not None and token.kind != expected_kind:
            raise SQLSyntaxError(f"Expected {expected_kind}, got {token.kind}", token.pos)
        if expected_value is not None and token.value != expected_value:
            raise SQLSyntaxError(f"Expected {expected_value}, got {token.value}", token.pos)
        self.pos += 1
        return token

    def match(self, kind: str, value: Any = None) -> bool:
        token = self.peek()
        if token.kind == kind:
            if value is None or token.value == value:
                return True
        return False

    def parse_ref(self) -> Column:
        start = self.pos
        token = self.peek()
        if token.kind != "IDENT":
            raise SQLSyntaxError(f"Expected identifier, got {token.kind}", token.pos)

        self.consume() 

        parts = [token.value]

        if self.match("DOT"):
            self.consume()
            second_token = self.peek()
            if second_token.kind != "IDENT":
                raise SQLSyntaxError(f"Expected identifier after '.', got {second_token.kind}", second_token.pos)
            self.consume()
            parts.append(".")
            parts.append(second_token.value)

        canonical = "".join(parts)
        return Column(canonical)

    def parse_agg(self) -> Aggregate:
        func_token = self.consume("KEYWORD")
        func_name = func_token.value 

        self.consume("LPAREN")

        arg = None
        if self.match("STAR"):
            self.consume()
            arg = None
        else:
            arg = self.parse_ref()

        self.consume("RPAREN")

        return Aggregate(func_name, arg)

    def parse(self) -> Select:
        self.consume("KEYWORD", "SELECT")

        # Select List
        # items_with_pos: list of (expr, key, start_pos)
        items_with_pos, columns, is_star, star_pos = self.parse_select_list()

        self.consume("KEYWORD", "FROM")

        table_token = self.consume("IDENT")
        table_name = table_token.value

        join = None
        if self.match("KEYWORD", "JOIN"):
            self.consume()
            join_table_token = self.consume("IDENT")
            join_table_name = join_table_token.value

            self.consume("KEYWORD", "ON")
            left_col = self.parse_ref()
            self.consume("OP", "=")
            right_col = self.parse_ref()

            join = Join(join_table_name, left_col, right_col)

        where = None
        if self.match("KEYWORD", "WHERE"):
            self.consume()
            where = self.parse_condition()

        group_by = []
        if self.match("KEYWORD", "GROUP"):
            self.consume()
            self.consume("KEYWORD", "BY")
            group_by = self.parse_group_by_refs()

        order_by_raw = [] # list of (text, desc, is_agg, start_pos)
        if self.match("KEYWORD", "ORDER"):
            self.consume()
            self.consume("KEYWORD", "BY")
            order_by_raw = self.parse_order_items()

        limit = None
        if self.match("KEYWORD", "LIMIT"):
            self.consume()
            num_token = self.consume("NUMBER")
            if not isinstance(num_token.value, int) or num_token.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", num_token.pos)
            limit = num_token.value

        if not self.match("EOF"):
            raise SQLSyntaxError("Unexpected token after statement end", self.peek().pos)

