            for expr, key, pos in items_with_pos:
                if isinstance(expr, Column):
                    if expr.name not in group_by:
                        raise SQLSyntaxError("Column not in GROUP BY and not aggregated", pos)

        # Constructing order_by final list (text, desc)
        order_by = [(text, desc) for text, desc, _, _ in order_by_raw]

