                                val = calculate_aggregate(expr.func, expr.arg, rows_in_group, stmt.table, stmt.join)
                            else:
                                # Column, must be in group by
                                # Resolve from first row
                                actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                                val = rows_in_group[0].get(actual_key)
                            break
                    if not found:
                         raise SQLExecutionError(f"ORDER BY text '{text}' not found in select list")
                    sort_vals.append((desc, val)) # desc bool determines sort order direction
                return sort_vals

            # Now sort group_order
            # We need a stable sort.
            # We calculate keys for all groups
            group_sort_data = []
            for i, k in enumerate(group_order):
                vals = calc_group_sort_values(k, groups[k])
                group_sort_data.append((i, vals))

            # Sort by vals, then by original index for stability (though dict order is insertion, Python 3.7+ dicts are ordered, but we used list group_order)
            # Python sort is stable. If we sort by keys, ties keep original order.

            def compare_keys(item1, item2):
                _, vals1 = item1
                _, vals2 = item2
                for (desc1, v1), (desc2, v2) in zip(vals1, vals2):
                    # Compare v1 and v2
                    if v1 is None and v2 is None:
                        continue
                    if v1 is None:
                        # ASC: NULL first (smaller). DESC: NULL last (larger).
                        if not desc1: return -1 # v1 < v2
                        else: return 1  # v1 > v2
                    if v2 is None:
                        if not desc1: return 1  # v1 > v2
                        else: return -1 # v1 < v2

                    # Both not None. Check kinds?
                    # Spec: "If the non-NULL values of an ordering column in the kept rows are of different kinds, execute raises SQLExecutionError"
                    # We assume valid data here or check?
                    # We should check kinds.
                    k1 = get_kind(v1)
                    k2 = get_kind(v2)
                    if k1 != k2:
                        raise SQLExecutionError("Mixed kinds in ordering column")

                    # Same kind
                    try:
                        if v1 == v2: continue
                        if not desc1:
                            if v1 < v2: return -1
                            else: return 1
                        else:
                            if v1 > v2: return -1
                            else: return 1
                    except TypeError:
                        raise SQLExecutionError("Comparison error")
                return 0

            import functools
            group_sort_data.sort(key=functools.cmp_to_key(compare_keys))

            # Reorder groups
            sorted_group_order = [d[0] for d in group_sort_data]
            # Wait, cmp_to_key sorts ascending.
            # My comparator returns -1 if v1 < v2 (ASC) or v1 > v2 (DESC).
            # So if desc is False, we want smaller first -> return -1.
            # If desc is True, we want larger first -> return -1 if v1 > v2.
            # This matches.

            ordered_keys = [group_order[i] for i in sorted_group_order]

            output_rows = []
            for k in ordered_keys:
                rows_in_group = groups[k]
                output_row = {}
                for expr, key_name in stmt.items:
                    if isinstance(expr, Aggregate):
                        val = calculate_aggregate(expr.func, expr.arg, rows_in_group, stmt.table, stmt.join)
                    else:
                        actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                        val = rows_in_group[0].get(actual_key)
                    output_row[key_name] = val
                output_rows.append(output_row)

        else:
            # Not Grouped. Sort `filtered_rows`.
            # We need to handle ORDER BY texts that are not in select list.
            # Rule 6: "any other ref sorts by that column of the row as before".

            def calc_row_sort_values(row):
                sort_vals = []
                for text, desc in stmt.order_by:
                    # Check if text is a select alias/key
                    found_in_select = False
                    val = None
                    for expr, key in stmt.items:
                        if text == key:
                            found_in_select = True
                            # Value in output is same as value in row?
                            # Yes, non-aggregate select items copy value from row.
                            actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                            val = row.get(actual_key)
                            break

                    if not found_in_select:
                        # Treat as ref
                        try:
                            col = Column(text)
                            actual_key = resolve_column_name(col, stmt.table, stmt.join)
                            val = row.get(actual_key)
                        except SQLExecutionError:
                            raise SQLExecutionError(f"ORDER BY column '{text}' not found")

                    sort_vals.append((desc, val))
                return sort_vals

            # Compute keys for all filtered rows
            # We need to validate mixed kinds during sort or pre-check.
            # Python sort is stable.

            # To handle the "Mixed kinds" error properly, we need to inspect values for each order item.
            # If any two non-NULL values in that column have different kinds, raise error.

            order_items_data = [] # list of lists of values for each order item across all rows
            for i, (text, desc) in enumerate(stmt.order_by):
                col_vals = []
                for row in filtered_rows:
                    # Re-calculate val for this row to check kinds
                    # We can optimize by calculating once, but for clarity:
                    found_in_select = False
                    val = None
                    for expr, key in stmt.items:
                        if text == key:
                            actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                            val = row.get(actual_key)
                            found_in_select = True
                            break
                    if not found_in_select:
                        col = Column(text)
                        actual_key = resolve_column_name(col, stmt.table, stmt.join)
                        val = row.get(actual_key)

                    col_vals.append(val)

                # Check kinds
                kinds = set()
                for v in col_vals:
                    if v is not None:
                        k = get_kind(v)
                        kinds.add(k)
                if len(kinds) > 1:
                    raise SQLExecutionError(f"Mixed types in ordering column '{text}'")

                order_items_data.append(col_vals)

            # Now sort filtered_rows using these pre-calculated values
            # Create index-value pairs
            indexed_rows = list(enumerate(filtered_rows))

            def cmp_row_indices(i1, i2):
                idx1, _ = i1
                idx2, _ = i2

                for col_idx, (text, desc) in enumerate(stmt.order_by):
                    v1 = order_items_data[col_idx][idx1]
                    v2 = order_items_data[col_idx][idx2]

                    if v1 is None and v2 is None:
                        continue
                    if v1 is None:
                        if not desc: return -1
                        else: return 1
                    if v2 is None:
                        if not desc: return 1
                        else: return -1

                    # Same kind (validated)
                    if v1 == v2: continue
                    if not desc:
                        if v1 < v2: return -1
                        else: return 1
                    else:
                        if v1 > v2: return -1
                        else: return 1
                return 0

            import functools
            indexed_rows.sort(key=functools.cmp_to_key(cmp_row_indices))

            sorted_filtered_rows = [r for _, r in indexed_rows]

            output_rows = []
            for row in sorted_filtered_rows:
                output_row = {}
                for expr, key_name in stmt.items:
                    actual_key = resolve_column_name(expr, stmt.table, stmt.join)
                    val = row.get(actual_key)
                    output_row[key_name] = val
                output_rows.append(output_row)

    # 5. Limit
    if stmt.limit is not None:
        output_rows = output_rows[:stmt.limit]

    return output_rows


def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from minisql.parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)
