import re

def parse_blocks(text: str) -> list[tuple]:
    """Parse Markdown text into a list of blocks."""
    # Normalize line endings
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    lines = text.split('\n')

    blocks = []
    i = 0
    n = len(lines)

    while i < n:
        # Skip blank lines
        if not lines[i].strip():
            i += 1
            continue

        # At a non-blank line, check each rule
        line = lines[i]

        # Rule 1: Fenced code
        if line.startswith('```'):
            block, i = _parse_fenced_code(lines, i)
            blocks.append(block)
            continue

        # Rule 2: Heading
        if _is_heading_start(line):
            level, heading_text, i = _parse_heading(lines, i)
            blocks.append(('heading', level, heading_text))
            continue

        # Rule 3: Horizontal rule
        if _is_hr(line):
            blocks.append(('hr',))
            i += 1
            continue

        # Rule 4: Blockquote
        if line.startswith('>'):
            block, i = _parse_blockquote(lines, i)
            blocks.append(block)
            continue

        # Rule 5: List
        if _is_list_start(line):
            block, i = _parse_list(lines, i)
            blocks.append(block)
            continue

        # Rule 6: Table
        if _is_table_start(lines, i):
            block, i = _parse_table(lines, i)
            blocks.append(block)
            continue

        # Rule 7: Paragraph
        text_lines, i = _parse_paragraph(lines, i)
        blocks.append(('paragraph', text_lines))

    return blocks


def _is_heading_start(line: str) -> bool:
    """Check if line starts a heading."""
    if line.startswith(' '):
        return False
    match = re.match(r'^(#{1,6})(\s|$)', line)
    return match is not None


def _parse_heading(lines: list[str], i: int) -> tuple[int, str, int]:
    """Parse a heading. Returns (level, text, next_line_index)."""
    line = lines[i]
    match = re.match(r'^(#{1,6})(\s|$)', line)
    level = len(match.group(1))
    text_start = match.end()
    raw_text = line[text_start:]

    raw_text = raw_text.strip()

    if raw_text == '#' * len(raw_text) and len(raw_text) > 0:
        raw_text = ""
    else:
        if re.search(r'\s#+$', raw_text):
            raw_text = raw_text.rstrip('#')
            raw_text = raw_text.strip()

    raw_text = raw_text.strip()

    return (level, raw_text, i + 1)


def _is_hr(line: str) -> bool:
    """Check if line is a horizontal rule."""
    if line.startswith(' '):
        return False
    stripped = line.strip()
    if len(stripped) < 3:
        return False

    chars = [c for c in stripped if c in '-*_']
    if len(chars) < 3:
        return False

    if all(c == chars[0] for c in chars):
        for c in stripped:
            if c != chars[0] and c != ' ':
                return False
        return True

    return False


def _parse_blockquote(lines: list[str], i: int) -> tuple[tuple, int]:
    """Parse a blockquote. Returns ((block_type, children), next_line_index)."""
    child_lines = []
    n = len(lines)

    while i < n:
        line = lines[i]
        if not line.startswith('>'):
            break

        content = line[1:]
        if content.startswith(' '):
            content = content[1:]
        child_lines.append(content)
        i += 1

    child_text = '\n'.join(child_lines)
    children = parse_blocks(child_text)

    return (('blockquote', children), i)


def _is_list_start(line: str) -> bool:
    """Check if line starts a list item (top-level)."""
    if line.startswith(' '):
        return False
    if re.match(r'^[-*+]\s', line):
        return True
    if re.match(r'^\d{1,9}\.\s', line):
        return True
    return False


def _is_any_list_marker(line: str) -> bool:
    """Check if the content after leading whitespace is a list marker."""
    stripped = line.lstrip(' ')
    if not stripped:
        return False
    if re.match(r'^[-*+]\s', stripped):
        return True
    if re.match(r'^\d{1,9}\.\s', stripped):
        return True
    return False

def _get_list_marker_info_with_indent(line: str) -> tuple[str, any, int] | None:
    """Get kind, identifier, and indent for any list marker line (including indented)."""
    # Count leading spaces
    indent = 0
    while indent < len(line) and line[indent] == ' ':
        indent += 1

    stripped = line[indent:]
    if not stripped:
        return None

    m = re.match(r'^([-*+])\s', stripped)
    if m:
        return ('bullet', m.group(1), indent)

    m = re.match(r'^(\d{1,9})\.\s', stripped)
    if m:
        return ('ordered', int(m.group(1)), indent)

    return None


def _starts_any_block(line: str) -> bool:
    """Check if line starts any block by rules 1-4 or 6."""
    if line.startswith(' '):
        return False

    return (line.startswith('```') or
            _is_heading_start(line) or
            _is_hr(line) or
            line.startswith('>') or
            _is_table_start_line(line))


def _is_table_start_line(line: str) -> bool:
    """Check if line could be the start of a table (contains | and doesn't start with space)."""
    if line.startswith(' '):
        return False
    if '|' not in line:
        return False
    return True


def _split_cells(line: str) -> list[str]:
    """Split a line into cells for table parsing."""
    stripped = line.strip()
    if not stripped:
        return []

    # Remove leading | if not escaped
    if stripped.startswith('|'):
        if not stripped.startswith('\\|'):
            stripped = stripped[1:]

    # Remove trailing | if not escaped
    if stripped.endswith('|'):
        if len(stripped) > 1 and stripped[-2] == '\\':
            pass
        else:
            stripped = stripped[:-1]

    # Split at | not preceded by \
    cells = []
    current = ""
    i = 0
    while i < len(stripped):
        if stripped[i] == '\\' and i + 1 < len(stripped) and stripped[i+1] == '|':
            current += '|'
            i += 2
        elif stripped[i] == '|':
            cells.append(current.strip())
            current = ""
            i += 1
        else:
            current += stripped[i]
            i += 1
    cells.append(current.strip())

    return cells


def _is_delimiter_row(cells: list[str]) -> bool:
    """Check if cells form a valid delimiter row."""
    if not cells:
        return False

    for cell in cells:
        if not cell:
            return False
        if not re.fullmatch(r':?-+:?', cell):
            return False

    return True


def _parse_alignments(cells: list[str]) -> list[str | None]:
    """Parse alignments from delimiter cells."""
    aligns = []
    for cell in cells:
        left = cell.startswith(':')
        right = cell.endswith(':')

        if left and right:
            aligns.append('center')
        elif right:
            aligns.append('right')
        elif left:
            aligns.append('left')
        else:
            aligns.append(None)
    return aligns


def _is_table_start(lines: list[str], i: int) -> bool:
    """Check if a table starts at line i."""
    if i + 1 >= len(lines):
        return False

    line = lines[i]
    if line.startswith(' '):
        return False

    if '|' not in line:
        return False

    header_cells = _split_cells(line)
    if not header_cells:
        return False

    next_line = lines[i+1]
    if next_line.startswith(' '):
        return False

    delim_cells = _split_cells(next_line)
    if not delim_cells:
        return False

    if len(header_cells) != len(delim_cells):
        return False

    if not _is_delimiter_row(delim_cells):
        return False

    return True


def _parse_table(lines: list[str], i: int) -> tuple[tuple, int]:
    """Parse a table block."""
    n = len(lines)

    header_line = lines[i]
    header_cells = _split_cells(header_line)

    delim_line = lines[i+1]
    delim_cells = _split_cells(delim_line)
    aligns = _parse_alignments(delim_cells)

    i += 2

    rows = []

    while i < n:
        line = lines[i]

        if not line.strip():
            break

        if '|' not in line:
            break

        if _starts_any_block(line):
             break

        row_cells = _split_cells(line)

        num_cols = len(header_cells)
        if len(row_cells) < num_cols:
            row_cells += [''] * (num_cols - len(row_cells))
        elif len(row_cells) > num_cols:
            row_cells = row_cells[:num_cols]

        rows.append(row_cells)
        i += 1

    return (('table', aligns, header_cells, rows), i)


def _parse_list(lines: list[str], i: int) -> tuple[tuple, int]:
    """Parse a list with nested lists. Returns (block, next_line_index)."""
    n = len(lines)

    class ListParser:
        def __init__(self):
            # Stack of dicts: {'indent': int, 'kind': str, 'identifier': any, 'items': list}
            self.open_lists = []

        def get_innermost_list(self):
            if not self.open_lists:
                return None
            return self.open_lists[-1]

        def close_lists(self, indent):
            # Close nested lists while innermost open list's indent > D
            # Top-level list (indent 0) is never closed by this rule
            while len(self.open_lists) > 1:
                current = self.open_lists[-1]
                if current['indent'] > indent:
                    closed_state = self.open_lists.pop()
                    # Finalize this list into a block and attach to parent
                    ordered = closed_state['kind'] == 'ordered'
                    start = closed_state['identifier'] if ordered else None
                    list_block = ('list', ordered, start, closed_state['items'])

                    # Find parent item to attach to
                    if self.open_lists:
                        parent = self.open_lists[-1]
                        if parent['items']:
                            parent_last_item = parent['items'][-1]
                            text, children = parent_last_item
                            children.append(list_block)
                            parent['items'][-1] = (text, children)
                else:
                    break

        def parse_line(self, line):
            indent = 0
            while indent < len(line) and line[indent] == ' ':
                indent += 1

            content = line[indent:]

            m_info = _get_list_marker_info_with_indent(line)

            if m_info:
                kind, identifier, line_indent = m_info

                # 1. Close deeper lists
                self.close_lists(line_indent)

                current_list = self.get_innermost_list()

                if current_list is None:
                    return False

                current_indent = current_list['indent']
                current_kind = current_list['kind']
                current_identifier = current_list['identifier']

                # Determine action
                if line_indent > current_indent:
                    # Starts a new list nested in the last item of the current list
                    if not current_list['items']:
                        return False

                    # Create new list state
                    new_list_state = {
                        'indent': line_indent,
                        'kind': kind,
                        'identifier': identifier,
                        'items': []
                    }

                    # Parse the first item of this new list
                    item_text = self._get_item_text(content, kind, identifier)
                    new_item_entry = (item_text, [])
                    new_list_state['items'].append(new_item_entry)

                    self.open_lists.append(new_list_state)

                elif line_indent == current_indent:
                    is_same = False
                    if current_kind == 'bullet':
                        if kind == 'bullet' and identifier == current_identifier:
                            is_same = True
                    elif current_kind == 'ordered':
                        if kind == 'ordered':
                            is_same = True

                    if is_same:
                        # Add item to current list
                        item_text = self._get_item_text(content, kind, identifier)
                        new_item_entry = (item_text, [])
                        current_list['items'].append(new_item_entry)
                    else:
                        # Kind differs
                        if current_indent > 0:
                            # Nested list: Close this list and start new one as another child of same item
                            closed_state = self.open_lists.pop()
                            # Attach closed state to parent
                            if self.open_lists:
                                parent = self.open_lists[-1]
                                if parent['items']:
                                    parent_last_item = parent['items'][-1]
                                    text, children = parent_last_item
                                    ordered = closed_state['kind'] == 'ordered'
                                    start = closed_state['identifier'] if ordered else None
                                    list_block = ('list', ordered, start, closed_state['items'])
                                    children.append(list_block)
                                    parent['items'][-1] = (text, children)

                            # Start new list
                            new_list_state = {
                                'indent': line_indent,
                                'kind': kind,
                                'identifier': identifier,
                                'items': []
                            }
                            item_text = self._get_item_text(content, kind, identifier)
                            new_item_entry = (item_text, [])
                            new_list_state['items'].append(new_item_entry)
                            self.open_lists.append(new_list_state)
                        else:
                            # Top level list, kind differs -> End the list
                            return False
                else:
                    # line_indent < current_indent should be handled by close_lists
                    # If we are here, it means we couldn't close enough?
                    # Or it means we are trying to add to a parent list while a child is open?
                    # close_lists ensures current_indent <= line_indent
                    # So this branch (line_indent < current_indent) is unreachable if close_lists works correctly
                    pass

            else:
                # Not a marker line. Continuation.
                current_list = self.get_innermost_list()
                if not current_list:
                    return False

                if not current_list['items']:
                    return False

                last_item_entry = current_list['items'][-1]
                text, children = last_item_entry
                stripped_content = content.strip()

                if text:
                    new_text = text + "\n" + stripped_content
                else:
                    new_text = stripped_content

                current_list['items'][-1] = (new_text, children)

        def _get_item_text(self, content, kind, identifier):
            if kind == 'bullet':
                # Marker is char + space
                return content[2:].strip()
            else: # ordered
                # Marker is digits + . + space
                for j, c in enumerate(content):
                    if c == ' ':
                        return content[j+1:].strip()
                return ""

    parser = ListParser()

    first_info = _get_list_marker_info_with_indent(lines[i])
    if not first_info:
        return (None, i)

    kind, identifier, indent = first_info

    text = parser._get_item_text(lines[i][indent:], kind, identifier)
    first_item_entry = (text, [])

    initial_list_state = {
        'indent': 0,
        'kind': kind,
        'identifier': identifier,
        'items': [first_item_entry]
    }
    parser.open_lists.append(initial_list_state)

    i += 1

    while i < n:
        line = lines[i]

        if not line.strip():
            break

        is_block_start = False
        if not line.startswith(' '):
             if _starts_any_block(line):
                 is_block_start = True

        if is_block_start:
            break

        consumed = parser.parse_line(line)

        if not consumed:
            break

        i += 1

    # After loop, close all remaining nested lists
    # This attaches them to their respective parents
    while len(parser.open_lists) > 1:
        closed_state = parser.open_lists.pop()
        ordered = closed_state['kind'] == 'ordered'
        start = closed_state['identifier'] if ordered else None
        list_block = ('list', ordered, start, closed_state['items'])

        parent = parser.open_lists[-1]
        if parent['items']:
            parent_last_item = parent['items'][-1]
            text, children = parent_last_item
            children.append(list_block)
            parent['items'][-1] = (text, children)

    if not parser.open_lists:
        return (None, i)

    top_list_state = parser.open_lists[0]

    final_items = []
    for text, children in top_list_state['items']:
        final_items.append((text, children))

    return (('list', top_list_state['kind'] == 'ordered', top_list_state['identifier'] if top_list_state['kind'] == 'ordered' else None, final_items), i)


def _parse_paragraph(lines: list[str], i: int) -> tuple[str, int]:
    """Parse a paragraph. Returns (text, next_line_index)."""
    n = len(lines)
    para_lines = []

    while i < n:
        line = lines[i]

        if not line.strip():
            break

        if line.startswith(' ```') or line.startswith('```'):
             break
        if _is_heading_start(line):
            break
        if _is_hr(line):
            break
        if line.startswith('>'):
            break
        if _is_list_start(line):
            break
        if _is_table_start_line(line):
            if _is_table_start(lines, i):
                break

        para_lines.append(line.strip())
        i += 1

    return ('\n'.join(para_lines), i)
