import string

def escape_html(text: str) -> str:
    """Escape HTML special characters."""
    return (text
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;"))


def _find_closing_backticks(text: str, start: int, count: int) -> int:
    """Find the next run of exactly `count` backticks starting from position `start`.

    Returns the index of the start of that run, or -1 if not found.
    """
    i = start
    n = len(text)
    while i < n:
        if text[i] == '`':
            # Count the run of backticks
            run_start = i
            while i < n and text[i] == '`':
                i += 1
            if i - run_start == count:
                return run_start
        else:
            i += 1
    return -1


def _find_close_paren(text: str, start: int) -> int:
    """Find the first ')' from start position."""
    for j in range(start, len(text)):
        if text[j] == ')':
            return j
    return -1


def _parse_url_title(url_title: str) -> tuple[str | None, str | None]:
    """Parse URL and optional title from the content between ( and ).

    Returns (url, title) where title may be None.
    If parsing fails, returns (None, None).
    """
    if not url_title:
        return "", None

    # Find first space
    space_pos = -1
    for j in range(len(url_title)):
        if url_title[j] == ' ':
            space_pos = j
            break

    if space_pos == -1:
        # No space, so the whole thing is the URL
        return url_title, None

    url = url_title[:space_pos]
    rest = url_title[space_pos:]

    # Title must start with at least one space
    # We already split at space, so `rest` starts with space.
    # Spec: "one or more spaces, then a double-quoted string ... then optional spaces"

    # Lstrip the spaces from rest
    stripped_rest = rest.lstrip(' ')

    if not stripped_rest:
        # Only spaces after URL
        return url, None

    if not stripped_rest.startswith('"'):
        # Not a quote, so it's part of the URL?
        # Spec: "URL ... up to the first space".
        # So URL is just `url`. The rest is unexpected.
        # Does this cause failure?
        # If the input is `(foo bar)`, URL is `foo`, rest is `bar`.
        # `bar` is not a title.
        # Usually this is treated as just URL `foo bar`? No, spec says URL ends at space.
        # If there's trailing garbage, it might be invalid.
        # Let's assume if it doesn't look like a title, it's a fail?
        # Or return url and ignore rest?
        # Spec: "If any of this fails..."
        # Let's try to be strict. If rest is not a valid title, return None.
        return None, None

    # It starts with a quote
    # Find closing quote
    close_quote = stripped_rest.find('"', 1)
    if close_quote == -1:
        return None, None

    # Check if there is a " between start and close_quote? 
    # find returns the FIRST ". So if there was another " before, we would have found it.
    # But if the string is `"foo" "bar"`, find(") returns 4.
    # Title is `foo`.
    # After title: ` "bar"`.
    # "then optional spaces".
    # So ` "bar"` must be only spaces.
    after_title = stripped_rest[close_quote + 1:]
    if after_title.strip():
        # There is non-whitespace content after the title
        return None, None

    title = stripped_rest[1:close_quote]
    return url, title


def render_inline(text: str) -> str:
    """Render inline Markdown markup to HTML."""
    result = []
    i = 0
    n = len(text)

    while i < n:
        char = text[i]

        # Rule 1: Backslash escape
        if char == '\\' and i + 1 < n and text[i + 1] in string.punctuation:
            result.append(escape_html(text[i + 1]))
            i += 2
            continue

        # Rule 2: Code span
        if char == '`':
            # Count the opening backtick run
            run_start = i
            while i < n and text[i] == '`':
                i += 1
            count = i - run_start

            # Find closing backticks of same length
            close_start = _find_closing_backticks(text, i, count)

            if close_start == -1:
                # No closing found: output literal backticks
                result.append('`' * count)
            else:
                # Extract content
                content = text[i:close_start]
                # Strip one leading/trailing space if both exist and not only spaces
                if len(content) >= 2 and content[0] == ' ' and content[-1] == ' ' and content.strip():
                    content = content[1:-1]
                result.append('<code>' + escape_html(content) + '</code>')
                i = close_start + count
            continue

        # Rule 3: Image
        if char == '!' and i + 1 < n and text[i + 1] == '[':
            # Try to parse image: ![alt](url) or ![alt](url "title")
            close_bracket = text.find(']', i + 2)
            if close_bracket != -1 and close_bracket + 1 < n and text[close_bracket + 1] == '(':
                # Find the closing parenthesis
                close_paren = _find_close_paren(text, close_bracket + 2)
                if close_paren != -1:
                    alt = text[i + 2:close_bracket]
                    url_title = text[close_bracket + 2:close_paren]
                    url, title = _parse_url_title(url_title)
                    if url is not None:
                        if title is not None:
                            result.append(f'<img src="{escape_html(url)}" alt="{escape_html(alt)}" title="{escape_html(title)}" />')
                        else:
                            result.append(f'<img src="{escape_html(url)}" alt="{escape_html(alt)}" />')
                        i = close_paren + 1
                        continue
            # If failed, fall through to treat ! as ordinary character?
            # Spec: "If any of this fails, the [ (or !) is an ordinary character"
            # So we just output '!' and move on.

        # Rule 4: Link
        if char == '[':
            close_bracket = text.find(']', i + 1)
            if close_bracket != -1 and close_bracket + 1 < n and text[close_bracket + 1] == '(':
                close_paren = _find_close_paren(text, close_bracket + 2)
                if close_paren != -1:
                    label = text[i + 1:close_bracket]
                    url_title = text[close_bracket + 2:close_paren]
                    url, title = _parse_url_title(url_title)
                    if url is not None:
                        rendered_label = render_inline(label)
                        if title is not None:
                            result.append(f'<a href="{escape_html(url)}" title="{escape_html(title)}">{rendered_label}</a>')
                        else:
                            result.append(f'<a href="{escape_html(url)}">{rendered_label}</a>')
                        i = close_paren + 1
                        continue
            # If failed, fall through to treat [ as ordinary character

        # Rule 5: Emphasis
        if char in ('*', '_'):
            emph_result, new_i = _try_emphasis(text, i)
            if emph_result is not None:
                result.append(emph_result)
                i = new_i
                continue

        # Rule 6: Plain character
        result.append(escape_html(char))
        i += 1

    return ''.join(result)


def _find_emphasis_closer(text: str, start: int, delim: str, delim_len: int) -> tuple[int, int]:
    """Find the first valid closer for emphasis.

    Returns (start_index, length) of the closer, or (-1, 0) if not found.
    """
    n = len(text)
    i = start
    # Skip escaped characters when searching
    while i < n:
        if text[i] == '\\':
            # Skip this backslash and the next character (if exists)
            i += 2
            continue

        if text[i] == delim:
            # Count the run of delimiters at this position
            run_start = i
            while i < n and text[i] == delim:
                i += 1
            run_len = i - run_start

            # For a closer, the run length must be >= delim_len
            if run_len >= delim_len:
                closer_len = delim_len
                closer_start = run_start

                # The closer must be preceded by a non-whitespace character
                if closer_start > 0 and text[closer_start - 1].isspace():
                    # Not a valid closer, continue searching
                    continue

                # For single delimiters, the closer must not have the same char before or after
                if delim_len == 1:
                    before_ok = closer_start == 0 or text[closer_start - 1] != delim
                    after_idx = closer_start + delim_len
                    after_ok = after_idx >= n or text[after_idx] != delim

                    # Additional check for underscore: must not be followed by alnum
                    if delim == '_':
                        if after_idx < n and text[after_idx].isalnum():
                            before_ok = False # Force failure

                    if not (before_ok and after_ok):
                        continue
                else:  # delim_len == 2
                    after_idx = closer_start + delim_len
                    # A _ or __ closer must not be followed by a letter or digit
                    if delim == '_' or delim == '__':
                        if after_idx < n and text[after_idx].isalnum():
                            continue

                return (closer_start, closer_len)
            # If run_len < delim_len, this isn't a valid closer, continue
        else:
            i += 1

    return (-1, 0)


def _try_emphasis(text: str, pos: int) -> tuple[str | None, int]:
    """Try to parse emphasis at position pos.

    Returns (html, new_position) on success, or (None, -1) on failure.
    """
    n = len(text)
    char = text[pos]

    if char == '_':
        # Check for double delimiter first
        if pos + 1 < n and text[pos + 1] == '_':
            opener_len = 2
            opener_end = pos + 2
            # Opener must not be preceded by letter/digit
            if pos > 0 and text[pos - 1].isalnum():
                return (None, -1)
        else:
            opener_len = 1
            opener_end = pos + 1
            # Opener must not be preceded by letter/digit
            if pos > 0 and text[pos - 1].isalnum():
                return (None, -1)
    else:  # char == '*'
        if pos + 1 < n and text[pos + 1] == '*':
            opener_len = 2
            opener_end = pos + 2
        else:
            opener_len = 1
            opener_end = pos + 1

    # Opener must be followed by a non-whitespace character
    if opener_end >= n or text[opener_end].isspace():
        return (None, -1)

    # Find the first valid closer
    closer_start, closer_len = _find_emphasis_closer(text, opener_end, char, opener_len)

    if closer_start == -1:
        return (None, -1)

    # Content is between opener_end and closer_start
    content = text[opener_end:closer_start]

    # Render content recursively
    rendered_content = render_inline(content)

    if opener_len == 2:
        tag = 'strong'
    else:
        tag = 'em'

    return (f'<{tag}>{rendered_content}</{tag}>', closer_start + closer_len)
