from .inline import render_inline, escape_html

def render_blocks(blocks: list[tuple]) -> str:
    """Render parsed blocks to HTML."""
    if not blocks:
        return ""

    html_parts = []

    for block in blocks:
        block_type = block[0]

        if block_type == 'heading':
            _, level, text = block
            html_parts.append(f'<h{level}>{render_inline(text)}</h{level}>')

        elif block_type == 'paragraph':
            _, text = block
            html_parts.append(f'<p>{render_inline(text)}</p>')

        elif block_type == 'code':
            _, lang, code = block
            if lang:
                html_parts.append(f'<pre><code class="language-{escape_html(lang)}">{escape_html(code)}</code></pre>')
            else:
                html_parts.append(f'<pre><code>{escape_html(code)}</code></pre>')

        elif block_type == 'blockquote':
            _, children = block
            child_html = render_blocks(children)
            if child_html:
                html_parts.append(f'<blockquote>\n{child_html}\n</blockquote>')
            else:
                html_parts.append(f'<blockquote>\n</blockquote>')

        elif block_type == 'list':
            _, ordered, start, items = block
            if ordered:
                if start != 1:
                    tag_open = f'<ol start="{start}">'
                else:
                    tag_open = '<ol>'
                tag_close = '</ol>'
            else:
                tag_open = '<ul>'
                tag_close = '</ul>'

            li_parts = []
            for item_text, children in items:
                inline_text = render_inline(item_text)

                if children:
                    children_html = render_blocks(children)
                    li_parts.append(f'<li>{inline_text}\n{children_html}\n</li>')
                else:
                    li_parts.append(f'<li>{inline_text}</li>')

            html_parts.append(f'{tag_open}\n' + '\n'.join(li_parts) + f'\n{tag_close}')

        elif block_type == 'hr':
            html_parts.append('<hr />')

        elif block_type == 'table':
            _, aligns, header, rows = block
            parts = []
            parts.append('<table>')
            parts.append('<thead>')
            parts.append('<tr>')

            for i, cell in enumerate(header):
                align = aligns[i] if i < len(aligns) else None
                inline_cell = render_inline(cell)
                if align:
                    parts.append(f'<th align="{align}">{inline_cell}</th>')
                else:
                    parts.append(f'<th>{inline_cell}</th>')

            parts.append('</tr>')
            parts.append('</thead>')

            if rows:
                parts.append('<tbody>')
                for row in rows:
                    parts.append('<tr>')
                    for i, cell in enumerate(row):
                        align = aligns[i] if i < len(aligns) else None
                        inline_cell = render_inline(cell)
                        if align:
                            parts.append(f'<td align="{align}">{inline_cell}</td>')
                        else:
                            parts.append(f'<td>{inline_cell}</td>')
                    parts.append('</tr>')
                parts.append('</tbody>')

            parts.append('</table>')

            html_parts.append('\n'.join(parts))

    return '\n'.join(html_parts)


def to_html(text: str) -> str:
    """Convert Markdown text to HTML."""
    from .blocks import parse_blocks

    blocks = parse_blocks(text)
    if not blocks:
        return ""

    return render_blocks(blocks) + "\n"
