def _to_decimal(value) -> Decimal:
    """Convert value to Decimal, raising TypeError for floats, ValueError for invalid decimals."""
    if isinstance(value, float):
        raise TypeError("Float is not supported; use Decimal, int, or string")
    if isinstance(value, Decimal):
        val = value
    elif isinstance(value, int):
        val = Decimal(value)
    elif isinstance(value, str):
        try:
            val = Decimal(value)
        except InvalidOperation:
            raise ValueError(f"Invalid numeric string: {value}")
    else:
        # Should not happen based on spec, but handle strictly
        raise TypeError(f"Invalid type: {type(value)}")

    if val < 0:
        raise ValueError("Amount must be non-negative")

    # Check decimal places: at most 2
    if val != val.quantize(Decimal('0.01')):
        raise ValueError("Amount must have at most two decimal places")

    return val


@dataclass(frozen=True)
class Line:
    account: str
    debit: Decimal = Decimal(0)
    credit: Decimal = Decimal(0)

    def __post_init__(self):
        # Ensure amounts are Decimals with correct precision
        object.__setattr__(self, 'debit', _to_decimal(self.debit))
        object.__setattr__(self, 'credit', _to_decimal(self.credit))


@dataclass(frozen=True)
class Entry:
    number: int
    day: datetime.date
    memo: str
    lines: tuple[Line, ...]


LedgerRow = namedtuple('LedgerRow', ['number', 'day', 'memo', 'debit', 'credit', 'balance'])


class Journal:
    def __init__(self, chart: Chart):
        self._chart = chart
        self._entries: list[Entry] = []

    def post(self, day: datetime.date, memo: str, lines: list[tuple]) -> Entry:
        if len(lines) < 2:
            raise ValueError("At least two lines required")

        parsed_lines = []
        for line_data in lines:
            if len(line_data) != 3:
                raise ValueError("Line must have account, debit, credit")

            acc_code, debit, credit = line_data

            # Check account exists and is leaf
            try:
                account = self._chart.get(acc_code)
            except KeyError:
                raise KeyError(f"Account {acc_code} not found")

            if not self._chart.is_leaf(acc_code):
                raise ValueError(f"Account {acc_code} is not a leaf")

            # Convert amounts
            try:
                d_amt = _to_decimal(debit)
                c_amt = _to_decimal(credit)
            except (TypeError, ValueError) as e:
                # Propagate original error type if possible, but generic ValueError is likely expected by spec "amounts are valid"
                raise e

            # Exactly one of debit/credit is non-zero
            if (d_amt > 0 and c_amt > 0) or (d_amt == 0 and c_amt == 0):
                 raise ValueError("Exactly one of debit and credit must be non-zero")

            parsed_lines.append(Line(account=acc_code, debit=d_amt, credit=c_amt))

        # Check balance
        total_debit = sum(l.debit for l in parsed_lines)
        total_credit = sum(l.credit for l in parsed_lines)
        if total_debit != total_credit:
            raise UnbalancedEntryError(f"Debits ({total_debit}) and Credits ({total_credit}) do not match")

        # Create Entry
        entry_number = len(self._entries) + 1
        entry = Entry(number=entry_number, day=day, memo=memo, lines=tuple(parsed_lines))
        self._entries.append(entry)
        return entry

    def entries(self) -> list[Entry]:
        return list(self._entries)

    def _get_descendant_codes(self, code: str) -> list[str]:
        """Get code and all its descendant codes."""
        codes = [code]

        def find_descendants(c):
            for child_acc in self._chart.children(c):
                codes.append(child_acc.code)
                find_descendants(child_acc.code)

        find_descendants(code)
        return codes

    def balance(self, code: str, start: Optional[datetime.date] = None, end: Optional[datetime.date] = None) -> Decimal:
        # Check account exists
        try:
            account = self._chart.get(code)
        except KeyError:
            raise KeyError(f"Account {code} not found")

        # Get all descendant codes including self
        all_codes = self._get_descendant_codes(code)
        all_codes_set = set(all_codes)

        total_debit = Decimal(0)
        total_credit = Decimal(0)

        for entry in self._entries:
            if start and entry.day < start:
                continue
            if end and entry.day > end:
                continue

            for line in entry.lines:
                if line.account in all_codes_set:
                    total_debit += line.debit
                    total_credit += line.credit

        if account.type.is_debit_normal:
            return total_debit - total_credit
        else:
            return total_credit - total_debit

    def ledger(self, code: str) -> list[LedgerRow]:
        try:
            account = self._chart.get(code)
        except KeyError:
            raise KeyError(f"Account {code} not found")

        all_codes = self._get_descendant_codes(code)
        all_codes_set = set(all_codes)

        rows = []
        running_balance = Decimal(0)
        is_debit_normal = account.type.is_debit_normal

        # Order: day, entry number, line position.
        sorted_entries = sorted(self._entries, key=lambda e: (e.day, e.number))

        for entry in sorted_entries:
            for idx, line in enumerate(entry.lines):
                if line.account in all_codes_set:
                    if is_debit_normal:
                        amount_change = line.debit - line.credit
                    else:
                        amount_change = line.credit - line.debit

                    running_balance += amount_change

                    rows.append(LedgerRow(
                        number=entry.number,
                        day=entry.day,
                        memo=entry.memo,
                        debit=line.debit,
                        credit=line.credit,
                        balance=running_balance
                    ))

        return rows
