from books.journal import Journal
from books.accounts import Chart, Account, AccountType


def _format_amount(amount: Decimal) -> str:
    """Format decimal with 2 places and leading minus if negative."""
    quantized = amount.quantize(Decimal('0.01'))
    return f"{quantized}"


def trial_balance(journal: Journal, as_of: Optional[datetime.date] = None) -> str:
    if as_of is None:
        header = "TRIAL BALANCE"
    else:
        header = f"TRIAL BALANCE as of {as_of.isoformat()}"

    lines = [header + "\n"]

    chart = journal._chart
    entries = journal.entries()

    # Filter entries based on as_of
    if as_of is not None:
        relevant_entries = [e for e in entries if e.day <= as_of]
    else:
        relevant_entries = entries

    # 1. Determine which accounts have activity
    active_accounts = set()

    # Pre-calculate balances and direct debit/credit sums for all accounts to avoid repeated iteration
    all_accounts_list = [acc for acc, _ in chart.walk()]
    direct_debits = {acc.code: Decimal(0) for acc in all_accounts_list}
    direct_credits = {acc.code: Decimal(0) for acc in all_accounts_list}

    # Also need to know if an account is active (has activity in subtree)
    accounts_to_show = set()

    # Function to add account and ancestors to accounts_to_show
    def mark_active(code: str):
        if code in accounts_to_show:
            return
        accounts_to_show.add(code)
        acc = chart.get(code)
        if acc.parent:
            mark_active(acc.parent)

    for entry in relevant_entries:
        for line in entry.lines:
            if line.debit != 0:
                direct_debits[line.account] += line.debit
                mark_active(line.account)
            if line.credit != 0:
                direct_credits[line.account] += line.credit
                mark_active(line.account)

    # Helper to calculate net raw balance (debits - credits) for an account and all its descendants
    net_raw_cache = {}
    def get_net_raw_cached(code: str) -> Decimal:
        if code in net_raw_cache:
            return net_raw_cache[code]
        val = direct_debits[code] - direct_credits[code]
        for child in chart.children(code):
            val += get_net_raw_cached(child.code)
        net_raw_cache[code] = val
        return val

    # Prepare output lines
    output_entries = []
    total_debits = Decimal(0)
    total_credits = Decimal(0)

    for account, depth in chart.walk():
        if account.code not in accounts_to_show:
            continue

        # Calculate balance on normal side
        raw_net = get_net_raw_cached(account.code)
        if account.type.is_debit_normal:
            balance = raw_net
        else:
            balance = -raw_net

        # Calculate Total Debits/Credits contribution from THIS account's OWN lines only
        own_net = direct_debits[account.code] - direct_credits[account.code]

        if own_net > 0:
            total_debits += own_net
        elif own_net < 0:
            total_credits += abs(own_net)

        indent = "  " * depth
        line_str = f"{indent}{account.code} {account.name}: {_format_amount(balance)}\n"
        output_entries.append(line_str)

    lines.extend(output_entries)

    lines.append(f"Total debits: {_format_amount(total_debits)}\n")
    lines.append(f"Total credits: {_format_amount(total_credits)}\n")

    return "".join(lines)


def income_statement(journal: Journal, start: datetime.date, end: datetime.date) -> str:
    if start > end:
        raise ValueError("start must be <= end")

    header = f"INCOME STATEMENT {start.isoformat()} to {end.isoformat()}\n"
    lines = [header]

    chart = journal._chart
    entries = journal.entries()
    relevant_entries = [e for e in entries if start <= e.day <= end]

    # Gather data
    direct_debits = {acc.code: Decimal(0) for acc, _ in chart.walk()}
    direct_credits = {acc.code: Decimal(0) for acc, _ in chart.walk()}

    accounts_to_show = set()

    def mark_active(code: str):
        if code in accounts_to_show:
            return
        accounts_to_show.add(code)
        acc = chart.get(code)
        if acc.parent:
            mark_active(acc.parent)

    for entry in relevant_entries:
        for line in entry.lines:
            if line.debit != 0:
                direct_debits[line.account] += line.debit
                mark_active(line.account)
            if line.credit != 0:
                direct_credits[line.account] += line.credit
                mark_active(line.account)

    memo_net = {}
    def get_net_raw_cached(code: str, memo: dict = None) -> Decimal:
        if memo is None:
            memo = {}
        if code in memo:
            return memo[code]
        val = direct_debits[code] - direct_credits[code]
        for child in chart.children(code):
            val += get_net_raw_cached(child.code, memo)
        memo[code] = val
        return val

    def get_balance(account: Account) -> Decimal:
        raw_net = get_net_raw_cached(account.code, memo_net)
        if account.type.is_debit_normal:
            return raw_net
        else:
            return -raw_net

    # Helper to generate section lines
    def generate_section(section_name: str, account_type: AccountType) -> list[str]:
        output = []
        output.append(f"{section_name}\n")

        total = Decimal(0)

        # Precompute depth map for efficiency in finding relative depth
        depth_map = {acc.code: d for acc, d in chart.walk()}

        for account, depth in chart.walk():
            if account.type != account_type:
                continue
            if account.code not in accounts_to_show:
                continue

            # Find root of this branch
            curr_code = account.code
            temp = account
            while temp.parent is not None:
                temp = chart.get(temp.parent)
            root_acc = temp

            # Calculate depth relative to root
            rel_depth = depth - depth_map[root_acc.code]

            indent = "  " * rel_depth
            balance = get_balance(account)

            # Sum totals only for ROOT accounts of this type
            if account.parent is None:
                total += balance

            line_str = f"{indent}{account.code} {account.name}: {_format_amount(balance)}\n"
            output.append(line_str)

        output.append(f"Total {section_name.lower()}: {_format_amount(total)}\n")
        return output

    income_lines = generate_section("Income", AccountType.INCOME)
    expense_lines = generate_section("Expenses", AccountType.EXPENSE)

    # Calculate Net Income from the totals calculated in sections
    total_income = Decimal(0)
    total_expenses = Decimal(0)

    # We can re-calculate or extract. Re-calculating is safer/cleaner logic separation.
    for account, _ in chart.walk():
        if account.type == AccountType.INCOME and account.parent is None:
            if account.code in accounts_to_show:
                total_income += get_balance(account)
        elif account.type == AccountType.EXPENSE and account.parent is None:
            if account.code in accounts_to_show:
                total_expenses += get_balance(account)

    net_income = total_income - total_expenses

    lines.extend(income_lines)
    lines.extend(expense_lines)
    lines.append(f"Net income: {_format_amount(net_income)}\n")

    return "".join(lines)
