        elif c == '+' and plus_to_space:
            out_bytes.append(ord(' '))
            i += 1
        else:
            out_bytes.extend(c.encode('utf-8'))
            i += 1

    try:
        return out_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raise BadRequest("Invalid UTF-8")

class Headers:
    def __init__(self, pairs=()):
        self._fields: list[tuple[str, str]] = []
        for name, value in pairs:
            self.add(name, value)

    def add(self, name: str, value: str):
        self._fields.append((name, value))

    def set(self, name: str, value: str):
        name_lower = name.lower()
        found = False
        new_fields = []
        for n, v in self._fields:
            if n.lower() == name_lower:
                if not found:
                    new_fields.append((name, value))
                    found = True
                # Otherwise skip (replaced)
            else:
                new_fields.append((n, v))
        if not found:
            new_fields.append((name, value))
        self._fields = new_fields

    def get(self, name: str, default=None):
        name_lower = name.lower()
        for n, v in self._fields:
            if n.lower() == name_lower:
                return v
        return default

    def __getitem__(self, name: str) -> str:
        name_lower = name.lower()
        for n, v in self._fields:
            if n.lower() == name_lower:
                return v
        raise KeyError(name)

    def get_all(self, name: str) -> list[str]:
        name_lower = name.lower()
        return [v for n, v in self._fields if n.lower() == name_lower]

    def __contains__(self, name: str) -> bool:
        name_lower = name.lower()
        for n, v in self._fields:
            if n.lower() == name_lower:
                return True
        return False

    def __len__(self) -> int:
        return len(self._fields)

    def items(self) -> list[tuple[str, str]]:
        return list(self._fields)

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: dict = field(default_factory=dict)
    state: dict = field(default_factory=dict)

    @property
    def query(self) -> dict[str, list[str]]:
        result: dict[str, list[str]] = {}
        if not self.query_string:
            return result

        pieces = self.query_string.split('&')
        for piece in pieces:
            if not piece:
                continue

            if '=' in piece:
                name_enc, _, val_enc = piece.partition('=')
                name = _percent_decode_str(name_enc)
                val = _percent_decode_str(val_enc)
            else:
                name = _percent_decode_str(piece)
                val = ''

            result.setdefault(name, []).append(val)
        return result

    @property
    def content_type(self) -> tuple[str, dict[str, str]]:
        ct_header = self.headers.get('Content-Type')
        if ct_header is None:
            return ('', {})

        pieces = ct_header.split(';')
        media_type = pieces[0].strip().lower()
        params: dict[str, str] = {}
        seen: set[str] = set()

        for piece in pieces[1:]:
            piece = piece.strip()
            if not piece:
                continue
            if '=' not in piece:
                continue

            name_part, _, val_part = piece.partition('=')
            name = name_part.strip().lower()
            val = val_part.strip()

            # Remove surrounding double quotes if present
            if len(val) >= 2 and val.startswith('"') and val.endswith('"'):
                val = val[1:-1]

            if name not in seen:
                params[name] = val
                seen.add(name)

        return (media_type, params)

    def text(self) -> str:
        _, params = self.content_type
        charset = params.get('charset', 'utf-8')
        try:
            return self.body.decode(charset)
        except UnicodeDecodeError as e:
            raise BadRequest(f"Invalid body encoding: {charset}") from e

    def json(self) -> Any:
        s = self.text()
        try:
            return json.loads(s)
        except json.JSONDecodeError as e:
            raise BadRequest("Invalid JSON body") from e

@dataclass
class Response:
    status: int = 200
    headers: Headers = field(default_factory=Headers)
    body: bytes = b''

    @classmethod
    def text(cls, s: str, status: int = 200) -> 'Response':
        return cls(
            status=status,
            headers=Headers([('Content-Type', 'text/plain; charset=utf-8')]),
            body=s.encode('utf-8')
        )

    @classmethod
    def json(cls, obj: Any, status: int = 200) -> 'Response':
        s = json.dumps(obj, separators=(',', ':'), sort_keys=True)
        return cls(
            status=status,
            headers=Headers([('Content-Type', 'application/json')]),
            body=s.encode('utf-8')
        )

    def to_bytes(self) -> bytes:
        reason = _reason_for(self.status)
        # Status line
        status_line = f"HTTP/1.1 {self.status} {reason}\r\n".encode('ascii')

        # Headers
        header_lines = []
        has_cl = False
        for name, value in self.headers.items():
            if name.lower() == 'content-length':
                has_cl = True
                continue
            header_lines.append(f"{name}: {value}\r\n".encode('latin-1'))

        # Add Content-Length
        cl_line = f"Content-Length: {len(self.body)}\r\n".encode('ascii')
        header_lines.append(cl_line)

        return status_line + b''.join(header_lines) + b"\r\n" + self.body

def _is_valid_method(method: str) -> bool:
    if not method:
        return False
    # ASCII uppercase letters only
    return all('A' <= c <= 'Z' for c in method)

def _parse_headers(lines: list[str]) -> Headers:
    headers = Headers()
    for line in lines:
        if not line:
            continue
        if line[0] in (' ', '\t'):
            raise BadRequest("Obsolete line folding not allowed")

        if ':' not in line:
            raise BadRequest("Invalid header line")

        name, _, value = line.partition(':')
        if not name:
            raise BadRequest("Empty header name")

        # Validate token chars
        if any(c not in _TOKEN_CHARS for c in name):
            raise BadRequest("Invalid character in header name")

        headers.add(name, value.strip(' \t'))

    return headers

def _parse_chunked_body(data: bytes) -> bytes:
    """
    Parse chunked transfer encoding.
    Returns the decoded body. Raises BadRequest on error.
    """
    body = bytearray()
    pos = 0
    n = len(data)

    while pos < n:
        # Find CRLF
        crlf_pos = data.find(b'\r\n', pos)
        if crlf_pos == -1:
            raise BadRequest("Invalid chunked encoding: missing CRLF in chunk size")

        size_line = data[pos:crlf_pos]
        pos = crlf_pos + 2

        # Extract hex size (ignore extensions after ';')
        size_str = size_line.split(b';', 1)[0].strip()
        try:
            chunk_size = int(size_str, 16)
        except ValueError:
            raise BadRequest("Invalid chunk size")

        if chunk_size == 0:
            # Last chunk. Read trailers and final CRLF.
            # Read lines until empty line
            while pos < n:
                crlf_idx = data.find(b'\r\n', pos)
                if crlf_idx == -1:
                    raise BadRequest("Invalid chunked encoding: missing CRLF in trailer")

                line = data[pos:crlf_idx]
                pos = crlf_idx + 2

                if line == b'':
                    # End of trailers
                    break
                # Else, trailer line (ignored)

            # Check if there is trailing data
            if pos != n:
                # We broke out of loop with pos pointing past the final empty line.
                # However, if pos != n, it means there are extra bytes.
                # Wait, if pos == n, we are good. If pos < n, error.
                # But my loop breaks when it sees an empty line.
                # If the stream ends exactly after the empty line, pos == n.
                if pos != n:
                     raise BadRequest("Invalid chunked encoding: trailing garbage")
            break

        # Read chunk data
        if pos + chunk_size > n:
            raise BadRequest("Invalid chunked encoding: truncated chunk data")

        body.extend(data[pos:pos+chunk_size])
        pos += chunk_size

        # Read trailing CRLF after chunk data
        if pos + 2 > n:
            raise BadRequest("Invalid chunked encoding: missing CRLF after chunk")

        if data[pos:pos+2] != b'\r\n':
            raise BadRequest("Invalid chunked encoding: invalid trailing CRLF after chunk")

        pos += 2

    return bytes(body)

def parse_request(data: bytes) -> Request:
    # 1. Split head and body
    sep = b'\r\n\r\n'
    idx = data.find(sep)
    if idx == -1:
        raise BadRequest("Missing head separator")

    head_data = data[:idx]
    body_data = data[idx+4:]

    # 2. Decode head (ISO-8859-1)
    try:
        head_str = head_data.decode('iso-8859-1')
    except UnicodeDecodeError:
        raise BadRequest("Invalid head encoding")

    # 3. Split lines
    lines = head_str.split('\r\n')
    if not lines or not lines[0]:
        raise BadRequest("Empty head")

    request_line = lines[0]
    header_lines = lines[1:]

    # 4. Parse request line
    # METHOD SP target SP version
    parts = request_line.split(' ')
    if len(parts) != 3:
        raise BadRequest("Invalid request line format")

    method, target, version = parts

    if not _is_valid_method(method):
        raise BadRequest("Invalid method")

    if not target.startswith('/'):
        raise BadRequest("Invalid target")

    if version not in ('HTTP/1.1', 'HTTP/1.0'):
        raise BadRequest("Invalid version")

    # 5. Parse path and query
    if '?' in target:
        path, query_string = target.split('?', 1)
    else:
        path, query_string = target, ''

    # 6. Parse headers
    headers = _parse_headers(header_lines)

    # Check Host
    if version == 'HTTP/1.1' and 'Host' not in headers:
        raise BadRequest("Missing Host header")

    # 7. Handle Body
    transfer_encoding = headers.get('Transfer-Encoding')
    content_lengths = headers.get_all('Content-Length')

    body = b''
    consumed_len = 0

    if transfer_encoding is not None:
        if content_lengths:
            raise BadRequest("Transfer-Encoding and Content-Length present")

        if transfer_encoding.lower() != 'chunked':
            raise BadRequest("Unsupported Transfer-Encoding")

        body = _parse_chunked_body(body_data)
        # Check for leftover bytes
        # _parse_chunked_body returns the body, but we need to ensure all bytes were consumed.
        # The implementation of _parse_chunked_body above tracks `pos` internally but doesn't return it.
        # We need to know if `pos` ended up at `len(body_data)`.
        # Let's rewrite _parse_chunked_body to return (body, consumed) to be safe, 
        # or we can check if the re-serialization of parsed chunks equals length? No, that's complex.
        # It's better to have the helper return the consumed length.

        # Refactoring _parse_chunked_body to return (bytes, int) is cleaner.
        # Let's assume I fix the helper.

        # For the logic here, I will rely on the helper checking it. 
        # Actually, the prompt says "Bytes left over after the body are an error."
        # So if _parse_chunked_body consumed only part of body_data, it's an error.
        # The helper needs to return how much it read.

        # Re-defining _parse_chunked_body in the scope to return (bytes, int) is the right move.
        # I will integrate this logic directly or call a corrected helper.

        # Let's do it inline to be safe and explicit about the "leftover" check.
        pos = 0
        n = len(body_data)
        parsed_body = bytearray()

        while pos < n:
            crlf_pos = body_data.find(b'\r\n', pos)
            if crlf_pos == -1:
                raise BadRequest("Invalid chunked encoding: missing CRLF in chunk size")

            size_line = body_data[pos:crlf_pos]
            pos = crlf_pos + 2

            size_str = size_line.split(b';', 1)[0].strip()
            try:
                chunk_size = int(size_str, 16)
            except ValueError:
                raise BadRequest("Invalid chunk size")

            if chunk_size == 0:
                while pos < n:
                    crlf_idx = body_data.find(b'\r\n', pos)
                    if crlf_idx == -1:
                        raise BadRequest("Invalid chunked encoding: missing CRLF in trailer")
                    line = body_data[pos:crlf_idx]
                    pos = crlf_idx + 2
                    if line == b'':
                        break

                if pos != n:
                    raise BadRequest("Invalid chunked encoding: trailing garbage")
                break

            if pos + chunk_size > n:
                raise BadRequest("Invalid chunked encoding: truncated chunk data")

            parsed_body.extend(body_data[pos:pos+chunk_size])
            pos += chunk_size

            if pos + 2 > n:
                raise BadRequest("Invalid chunked encoding: missing CRLF after chunk")

            if body_data[pos:pos+2] != b'\r\n':
                raise BadRequest("Invalid chunked encoding: invalid trailing CRLF after chunk")

            pos += 2

        body = bytes(parsed_body)

    elif content_lengths:
        # Validate Content-Lengths
        # Must be decimal digits
        # All same value
        cl_vals = []
        for cl in content_lengths:
            if not cl.isdigit():
                raise BadRequest("Invalid Content-Length")
            cl_vals.append(int(cl))

        if len(set(cl_vals)) > 1:
            raise BadRequest("Conflicting Content-Length values")

        cl = cl_vals[0]

        if len(body_data) < cl:
            raise BadRequest("Content-Length exceeds body length")

        body = body_data[:cl]
        # Check for leftover bytes
        if len(body_data) > cl:
            raise BadRequest("Trailing garbage after body")

    # If neither, body is empty. body_data must be empty? 
    # "Bytes left over after the body are an error."
    # If no TE and no CL, body is empty. If body_data is not empty, it's leftover.
    else:
        if body_data:
            raise BadRequest("Unexpected body data without Transfer-Encoding or Content-Length")
        body = b''

    return Request(
        method=method,
        target=target,
        path=path,
        query_string=query_string,
        version=version,
        headers=headers,
        body=body,
        params={},
        state={}
    )
