from .request import HTTPError, BadRequest, Request, Response

class NotFound(HTTPError):
    def __init__(self, message: str | None = None):
        super().__init__(404, message if message is not None else "Not Found")

class MethodNotAllowed(HTTPError):
    def __init__(self, allowed: list[str], message: str | None = None):
        super().__init__(405, message if message is not None else "Method Not Allowed")
        self.allowed = sorted(allowed)

class Router:
    def __init__(self):
        # Store routes: list of tuples (pattern_string, method, converter_list, handler)
        # But we need to match dynamically.
        # Better: list of tuples (pattern_string, method, regex_parts, handler)
        # Actually, simple segment matching is easier than regex for this spec.
        self.routes: list[tuple[str, str, list[dict], callable]] = []
        # route(pattern, methods) -> decorator
        # add(method, pattern, handler)

    def add(self, method: str, pattern: str, handler):
        """Register a handler."""
        # Validate pattern
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with /")

        segments = pattern.split('/')
        # First segment is empty string for root
        if segments[0] != '':
             raise ValueError("Pattern must start with /")

        param_names = set()
        parsed_parts = []

        for i, seg in enumerate(segments[1:]): # Skip first empty
            if seg == '':
                # Empty segment. 
                # If it's the last segment, it means trailing slash.
                # If it's in the middle, it's an error? 
                # Spec: "/users/" has empty last segment.
                # Spec: "/foo//bar" ? Not explicitly forbidden but likely matches empty segment?
                # Spec: "no parameter matches an empty segment".
                # Literal empty segment matches literal empty segment.
                parsed_parts.append({'type': 'literal', 'value': ''})
                continue

            if seg.startswith('{') and seg.endswith('}'):
                name_part = seg[1:-1]
                if ':' in name_part:
                    name, converter = name_part.split(':', 1)
                else:
                    name, converter = name_part, 'str'

                if name in param_names:
                    raise ValueError(f"Duplicate parameter name: {name}")
                param_names.add(name)

                if converter not in ('str', 'int', 'path'):
                    raise ValueError(f"Unknown converter: {converter}")

                if converter == 'path':
                    if i != len(segments) - 2: # Last segment check (segments[1:] length is len-1)
                         # Wait, segments is list from split.
                         # /a/{name:path} -> ['', 'a', '{name:path}']
                         # i is index in segments[1:]. 
                         # If pattern ends with /{path}, segments[1:] last element is it.
                         # If pattern is /{path}, segments[1:] has 1 element, i=0. len-1 is 0? No.
                         # Let's check: is this the last element of the pattern segments?
                         pass

                    # Check if path is last segment
                    if i < len(segments) - 2:
                         raise ValueError("'path' converter must be the last segment")

                    parsed_parts.append({'type': 'path', 'name': name, 'converter': 'int' if converter=='int' else 'str'}) # Wait, path is always str?
                    # Spec: {name:path} -> one or more segments, kept joined. Type? Usually str.
                    # Spec doesn't say int/path. Just {name:path}.
                    parsed_parts.append({'type': 'path', 'name': name})
                elif converter == 'int':
                    parsed_parts.append({'type': 'int', 'name': name})
                else: # str
                    parsed_parts.append({'type': 'str', 'name': name})
            else:
                parsed_parts.append({'type': 'literal', 'value': seg})

        # Check for duplicate registration of same method and pattern string?
        # "if the same method and pattern string are already registered"
        for p, m, _, _ in self.routes:
            if p == pattern and m == method:
                raise ValueError(f"Route already registered: {method} {pattern}")

        self.routes.append((pattern, method, parsed_parts, handler))

    def route(self, pattern: str, methods: tuple[str, ...] = ('GET',)):
        def decorator(handler):
            for method in methods:
                self.add(method, pattern, handler)
            return handler
        return decorator

    def resolve(self, method: str, path: str) -> tuple[callable, dict]:
        """
        Returns (handler, params).
        Raises NotFound or MethodNotAllowed.
        """
        # Split path, removing leading slash
        # path is like "/a/b". split('/') -> ['', 'a', 'b']
        # We want segments after root.
        raw_segments = path.split('/')
        if raw_segments[0] == '':
            segments_raw = raw_segments[1:]
        else:
            # Should have started with / in request, but safe fallback
            segments_raw = raw_segments

        # Decode segments
        decoded_segments = []
        for seg in segments_raw:
            # Percent decode, + stays +
            try:
                dec = _decode_path_segment(seg)
                decoded_segments.append(dec)
            except BadRequest:
                raise NotFound() # Or BadRequest? Spec says "Bad escapes raise BadRequest".
                # So raise BadRequest, which is an HTTPError.

        # Iterate routes in order
        found_path_match = False
        allowed_methods = set()

        for pattern_str, r_method, parts, handler in self.routes:
            params = {}
            is_match = True

            # Special handling for path segment matching
            # parts length vs decoded_segments length
            # Note: path segments can vary if 'path' converter is used.

            # Determine expected length constraints
            # If any part is type 'path', the number of segments consumed from 'path' part onwards
            # is flexible (>=1).

            # Simple simulation:
            seg_idx = 0
            part_idx = 0

            for part in parts:
                if part['type'] == 'literal':
                    if seg_idx >= len(decoded_segments):
                        is_match = False
                        break
                    if decoded_segments[seg_idx] != part['value']:
                        is_match = False
                        break
                    seg_idx += 1

                elif part['type'] == 'str':
                    if seg_idx >= len(decoded_segments):
                        is_match = False
                        break
                    val = decoded_segments[seg_idx]
                    if val == '': # No param matches empty segment
                        is_match = False
                        break
                    params[part['name']] = val
                    seg_idx += 1

                elif part['type'] == 'int':
                    if seg_idx >= len(decoded_segments):
                        is_match = False
                        break
                    val = decoded_segments[seg_idx]
                    if val == '':
                        is_match = False
                        break
                    # Must be ASCII digits
                    if not val.isdigit():
                        is_match = False
                        break
                    params[part['name']] = int(val)
                    seg_idx += 1

                elif part['type'] == 'path':
                    # Must have at least one segment remaining
                    if seg_idx >= len(decoded_segments):
                        is_match = False
                        break
                    # Consume all remaining segments
                    remaining = decoded_segments[seg_idx:]
                    if any(s == '' for s in remaining):
                        # "no parameter matches an empty segment"
                        # Does this apply to individual segments in the joined path?
                        # Spec: "no parameter matches an empty segment".
                        # If a segment in the middle is empty, does it match?
                        # "/a//b" -> ['a', '', 'b'].
                        # If pattern is /a/{name:path}, it matches 'a', then takes '', 'b'.
                        # Does '' invalidate it?
                        # "one or more segments... allowed only as last".
                        # If any segment is empty, does it match?
                        # "A literal matches a segment equal to it... no parameter matches an empty segment."
                        # This usually applies to single-segment parameters.
                        # For path, it's ambiguous. Let's assume empty segments in the path part make it invalid.
                        is_match = False
                        break

                    params[part['name']] = '/'.join(remaining)
                    seg_idx = len(decoded_segments) # Consumed all

            if is_match and seg_idx == len(decoded_segments):
                found_path_match = True
                if r_method == method:
                    return handler, params
                elif method == 'HEAD' and r_method == 'GET':
                    return handler, params
                else:
                    allowed_methods.add(r_method)
                    if r_method == 'GET':
                        allowed_methods.add('HEAD')

        if found_path_match:
            raise MethodNotAllowed(list(allowed_methods))
        else:
            raise NotFound()

    def dispatch(self, request: Request) -> Response:
        handler, params = self.resolve(request.method, request.path)
        request.params = params

        # Call handler
        resp = handler(request)

        # Handle HEAD served by GET
        # How to know if it was served by GET?
        # resolve returned handler. If method is HEAD and handler came from GET, strip body.
        # But dispatch calls resolve. resolve doesn't tell us if it was a HEAD fallback.
        # We can check: if request.method == 'HEAD', we need to know if the resolved route was for HEAD.
        # But we resolved to GET if HEAD wasn't available.
        # So if request.method == 'HEAD', we strip the body.
        if request.method == 'HEAD':
            return Response(status=resp.status, headers=resp.headers, body=b'')

        return resp

def _decode_path_segment(s: str) -> str:
    # Decodes percent encoded, but + is +
    return _percent_decode_str(s)

def _percent_decode_str(s: str) -> str:
    # Duplicate of request.py helper to avoid circular import or tight coupling?
    # But request.py imports nothing from router.
    # router imports from request.
    # So router can use request's helper?
    # request.py defines _percent_decode_str_internal.
    # It is private.
    # I will copy the logic here or expose it.
    # Copying is safer for modularity.

    out_bytes = bytearray()
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '%':
            if i + 2 < n:
                hex_val = s[i+1:i+3]
                try:
                    byte_val = int(hex_val, 16)
                    out_bytes.append(byte_val)
                    i += 3
                    continue
                except ValueError:
                    raise BadRequest(f"Invalid percent escape: %{hex_val}")
            else:
                raise BadRequest("Invalid percent escape: truncated")
        else:
            out_bytes.extend(c.encode('utf-8'))
            i += 1

    try:
        return out_bytes.decode('utf-8')
    except UnicodeDecodeError:
        raise BadRequest("Invalid UTF-8")
