from .request import Request, Response, parse_request, HTTPError, BadRequest
from .router import Router, MethodNotAllowed
import base64

class App:
    def __init__(self, router: Router, middleware=()):
        self.router = router
        self.middleware = list(middleware)

    def use(self, mw):
        self.middleware.append(mw)

    def _inner_call(self, request: Request) -> Response:
        """The innermost step: Router dispatch + Error handling."""
        try:
            return self.router.dispatch(request)
        except HTTPError as e:
            headers = Headers()
            if isinstance(e, MethodNotAllowed):
                headers.set('Allow', ', '.join(e.allowed))
            return Response(
                status=e.status,
                headers=headers,
                body=f"{e.status} {e.reason}".encode('utf-8')
            )
        except Exception as e:
            return Response(
                status=500,
                body=b"500 Internal Server Error"
            )

    def handle(self, request: Request) -> Response:
        """Run middleware chain."""
        # Build chain
        # middleware[0](request, lambda r: middleware[1](r, ...))

        call_next = self._inner_call

        # Wrap in reverse order so first middleware is outermost
        for mw in reversed(self.middleware):
            # Capture current call_next for the closure
            _call_next = call_next
            def mw_wrapper(req, _mw=mw, _next=_call_next):
                return _mw(req, _next)
            call_next = mw_wrapper

        try:
            return call_next(request)
        except HTTPError as e:
            headers = Headers()
