    Otherwise, '+' is kept as is.
    Raises BadRequest on invalid percent encoding or invalid UTF-8.
    """
    out_bytes = bytearray()
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '%':
            if i + 2 < n:
                hex_val = s[i+1:i+3]
                try:
                    byte_val = int(hex_val, 16)
                    out_bytes.append(byte_val)
                    i += 3
                    continue
                except ValueError:
                    raise BadRequest(f"Invalid percent escape: %{hex_val}")
            else:
