        in_stack = set()
        stack_path = []

        def dfs(node):
            visited.add(node)
            in_stack.add(node)
            stack_path.append(node)

            for neighbor in adj.get(node, set()):
                if neighbor not in visited:
                    dfs(neighbor)
                elif neighbor in in_stack:
                    # Found cycle
                    # All nodes in stack_path from neighbor's index to end are on cycle
                    idx = stack_path.index(neighbor)
                    for k in range(idx, len(stack_path)):
                        cycles.add(stack_path[k])

            in_stack.remove(node)
            stack_path.pop()

        for node in all_nodes:
            if node not in visited:
                dfs(node)

        return cycles
