import re
from typing import Any, Callable, Set, List, Tuple

class FormulaError(ValueError):
    """Raised when a formula cannot be parsed."""
    pass

class ErrorValue(str):
    """A string subclass representing an error state in the sheet."""
    def __new__(cls, value: str):
        return super().__new__(cls, value)

    def __eq__(self, other: object) -> bool:
        # Compare equal to their text
        return str.__eq__(self, other)

    def __hash__(self) -> int:
        return str.__hash__(self)

# Error constants
ERROR = ErrorValue("#ERROR!")
CYCLE = ErrorValue("#CYCLE!")

# --- Syntax Tree Classes ---

class Node:
    pass

class Number(Node):
    def __init__(self, value: int | float):
        self.value = value

class Ref(Node):
    def __init__(self, name: str):
        self.name = name  # Always upper case

class UnaryOp(Node):
    def __init__(self, op: str, operand: Node):
        self.op = op
        self.operand = operand

class BinaryOp(Node):
    def __init__(self, op: str, left: Node, right: Node):
        self.op = op
        self.left = left
        self.right = right

# --- Parsing ---

def _validate_ref(name: str) -> bool:
    """
    Validates a cell reference name.
    Must be 1 letter followed by digits.
    Row 1-999. No leading zeros in row.
    """
    if len(name) < 2:
        return False

    col = name[0]
    row_str = name[1:]

    if not col.isalpha():
        return False

    # Columns are A-Z. Case-insensitive check, but we normalized to upper earlier.
    if not ('A' <= col <= 'Z'):
        return False

    if not row_str.isdigit():
        return False

    if len(row_str) > 1 and row_str[0] == '0':
        return False

    try:
        row = int(row_str)
    except ValueError:
        return False

    if row < 1 or row > 999:
        return False

    return True

def _tokenize(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        if source[i].isspace():
            i += 1
            continue

        if source[i] in '+-*/()':
            tokens.append(('op', source[i]))
            i += 1
            continue

        # Number: digits [. digits]
        if source[i].isdigit():
            m = re.match(r'^\d+(\.\d+)?', source[i:])
            if m:
                tokens.append(('num', m.group()))
                i += len(m.group())
                continue
            else:
                # Shouldn't happen if starts with digit and regex is correct
                raise FormulaError("Invalid number format")

        # Reference: letters digits
        if source[i].isalpha():
            m = re.match(r'^([A-Za-z]+)(\d+)', source[i:])
            if m:
                raw_name = m.group(0)
                name = raw_name.upper()
                if not _validate_ref(name):
                    raise FormulaError(f"Reference outside sheet: {raw_name}")
                tokens.append(('ref', name))
                i += len(raw_name)
                continue
            else:
                # Letter not followed by digits
                raise FormulaError("Invalid reference: letters must be followed by digits")

        raise FormulaError(f"Unexpected character: {source[i]}")

    return tokens

class Parser:
    def __init__(self, tokens: list[tuple[str, str]]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> tuple[str, str]:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, val: str):
        tok = self.consume()
        if tok[1] != val:
            raise FormulaError(f"Expected {val}")

    def parse_expr(self) -> Node:
        node = self.parse_term()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('+', '-'):
            op = self.consume()[1]
            right = self.parse_term()
            node = BinaryOp(op, node, right)
        return node

    def parse_term(self) -> Node:
        node = self.parse_unary()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('*', '/'):
            op = self.consume()[1]
            right = self.parse_unary()
            node = BinaryOp(op, node, right)
        return node

    def parse_unary(self) -> Node:
        tok = self.peek()
        if tok and tok[0] == 'op' and tok[1] in ('+', '-'):
            op = self.consume()[1]
            operand = self.parse_unary()
            return UnaryOp(op, operand)
        return self.parse_atom()

    def parse_atom(self) -> Node:
        tok = self.peek()
        if not tok:
            raise FormulaError("Unexpected end of expression")

        if tok[0] == 'num':
            self.consume()
            # int if no dot, float if dot
            if '.' in tok[1]:
                return Number(float(tok[1]))
            else:
                return Number(int(tok[1]))

        if tok[0] == 'ref':
            self.consume()
            return Ref(tok[1])

        if tok[0] == 'op' and tok[1] == '(':
            self.consume()
            node = self.parse_expr()
            self.expect(')')
            return node

        raise FormulaError(f"Unexpected token: {tok}")

def parse_formula(source: str) -> Node:
    """
    Parses the formula string (after '=') and returns an AST.
    """
    if not source or not source.strip():
        raise FormulaError("Empty formula")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    parser = Parser(tokens)
    tree = parser.parse_expr()

    if parser.pos != len(parser.tokens):
        raise FormulaError("Unexpected trailing characters")

    return tree

# --- Evaluation ---

def references(tree: Node) -> set[str]:
    """Returns the set of cell names referenced by the formula tree."""
    refs = set()

    def traverse(node: Node):
        if isinstance(node, Ref):
            refs.add(node.name)
        elif isinstance(node, UnaryOp):
            traverse(node.operand)
        elif isinstance(node, BinaryOp):
            traverse(node.left)
            traverse(node.right)

    traverse(tree)
    return refs

def evaluate(tree: Node, lookup: Callable[[str], Any]) -> Any:
    """
    Computes the value of the formula tree using lookup for cell values.
    """
    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, Ref):
        val = lookup(tree.name)
        if val is None:
            return 0
        return val

    if isinstance(tree, UnaryOp):
        operand = evaluate(tree.operand, lookup)
        if isinstance(operand, ErrorValue):
            return operand
        if isinstance(operand, str):
            return ERROR
        # operand is int or float
        if tree.op == '-':
            return -operand
        else: # '+'
            return operand

    if isinstance(tree, BinaryOp):
        left = evaluate(tree.left, lookup)
        right = evaluate(tree.right, lookup)

        # Rule 3: Error handling
        if isinstance(left, ErrorValue):
            return left
        if isinstance(right, ErrorValue):
            return right

        # Rule 3: Text handling
        if isinstance(left, str) or isinstance(right, str):
            return ERROR

        # Rule 4: Arithmetic
        # left and right are int or float

        if tree.op == '+':
            if isinstance(left, int) and isinstance(right, int):
                return left + right
            return float(left) + float(right)

        elif tree.op == '-':
            if isinstance(left, int) and isinstance(right, int):
                return left - right
            return float(left) - float(right)

        elif tree.op == '*':
            if isinstance(left, int) and isinstance(right, int):
                return left * right
            return float(left) * float(right)

        elif tree.op == '/':
            if right == 0:
                return ERROR
            return float(left) / float(right)

    raise FormulaError("Invalid AST node")
