from typing import Set, Iterable, Dict

class DependencyGraph:
    def __init__(self):
        # cell -> set of precedent cells
        self._precedents: Dict[str, Set[str]] = {}
        # cell -> set of dependent cells
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Replaces the precedents for a cell.
        Updates reverse links.
        """
        new_precedents = set(precedents)
        old_precedents = self._precedents.get(cell, set())

        # Remove old reverse links
        for p in old_precedents:
            if cell in self._dependents.get(p, set()):
                self._dependents[p].remove(cell)
                if not self._dependents[p]:
                    del self._dependents[p]

        # Add new reverse links
        for p in new_precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Update precedents map
        if not new_precedents:
            if cell in self._precedents:
                del self._precedents[cell]
        else:
            self._precedents[cell] = new_precedents

    def precedents(self, cell: str) -> Set[str]:
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns all cells that depend on cell, directly or indirectly.
        It contains cell itself only when cell is on a cycle.
        """
        visited = set()
        stack = [cell]

        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)

            # Get direct dependents of current
            direct_deps = self._dependents.get(current, set())
            for d in direct_deps:
                if d not in visited:
                    stack.append(d)

        # If cell is in visited, it means there is a path from cell back to cell (cycle)
        # OR cell depends on itself directly.
        # However, 'all_dependents' usually excludes the node itself unless cyclic.
        # The spec says: "It contains cell itself only when cell is on a cycle."
        # Our DFS starts with cell, so cell is always in visited.
        # We need to check if there is a path from cell -> ... -> cell.
        # If cell is on a cycle, it is its own dependent (transitively).
        # If cell is NOT on a cycle, cell is not in _dependents of any node that reaches back to it?
        # Actually, if A->B, all_dependents(A) = {B}. A is not dependent on A.
        # But our DFS visited A.
        # So we must filter out cell if it is not actually a dependent of itself (via cycle).

        if cell in self._dependents.get(cell, set()):
            return visited

        # Check if cell is reachable from any of its dependents? 
        # No, all_dependents(cell) is the set of nodes D such that cell ->* D.
        # If cell is on a cycle, cell ->* cell, so cell is in the set.
        # If cell is not on a cycle, cell is NOT in the set of nodes that depend on it (excluding itself by definition of dependency).
        # But our traversal started at cell.

        # Let's re-read spec carefully:
        # "all_dependents(cell) -> set[str] gives every cell that refers to cell directly or through other cells."
        # "It contains cell itself only when cell is on a cycle."

        # So if cell is on a cycle, keep cell.
        # If cell is NOT on a cycle, remove cell.

        is_on_cycle = False
        # Check if cell can reach itself via precedents?
        # No, dependencies are "who depends on me".
        # Cell depends on Precedents.
        # Dependents depend on Cell.
        # Cycle: Cell -> Precedent -> ... -> Cell.
        # This implies Precedent is in all_dependents(Cell)? No.
        # If A -> B (A precedes B, B depends on A), then B is dependent of A.
        # Cycle: A depends on B, B depends on A.
        # all_dependents(A) includes B. Does it include A?
        # A depends on B. B depends on A.
        # So A is a dependent of B. And B is a dependent of A.
        # Is A a dependent of A? Yes, via B.

        # So if cell is on a cycle, it IS in the set of cells that refer to it (transitively).
        # If not, it is not.

        # We can check: is cell in the dependents of any of its direct dependents that are reachable?
        # Or simpler: run BFS/DFS from cell. If we encounter cell again, it's a cycle.
        # But we visited cell first.

        # Better approach for correctness:
        # Find nodes reachable from cell via _dependents edges.
        # If cell is reachable from any node in that set (excluding the start state logic), it's on a cycle.
        # Actually, if cell is on a cycle, cell will be reachable from some dependent d, where cell -> ... -> d -> ... -> cell.
        # So cell is in the transitive closure of dependents of cell.

        # My previous DFS added 'cell' to visited immediately.
        # If I look at neighbors of cell, do I eventually come back to cell?

        if cell in visited:
            # We need to determine if cell is reachable from any OTHER node that is a dependent of cell.
            # If cell has a dependent d, and d leads back to cell, then cell is on a cycle.

            # Check if cell is in the dependents of any node in 'visited' excluding the trivial start?
            # No, just check: is cell in the transitive closure of its own dependents?

            # Let's do a quick check:
            # If cell is on a cycle, there exists a path cell -> d1 -> ... -> cell.
            # So cell is a dependent of d1, which is a dependent of cell...

            # Simple check: Does cell appear as a dependent of any node in 'visited' where that node is NOT the trivial start?
            # No, 'visited' contains cell.

            # Let's check: is cell in _dependents[x] for some x that is in all_dependents(cell) AND x != cell?
            # Or is cell in _dependents[cell]?

            # If I set dependencies of A to empty, all_dependents(A) should be {}.
            # My code returns {A}.
            # Spec: "It contains cell itself only when cell is on a cycle."
            # If no dependencies, not on cycle. So should return {}.

            # If A -> B, all_dependents(A) should be {B}.
            # My code returns {A, B}.

            # So I must exclude 'cell' unless it is on a cycle.

            pass

        if not self._is_on_cycle(cell):
            visited.discard(cell)

        return visited

    def _is_on_cycle(self, cell: str) -> bool:
        """Checks if a specific cell is on a cycle."""
        # A cell is on a cycle if it can reach itself via precedents.
        # Edge direction: Cell -> Precedents.
        stack = list(self._precedents.get(cell, set()))
        visited = set()

        while stack:
            current = stack.pop()
            if current == cell:
                return True
            if current in visited:
                continue
            visited.add(current)

            for p in self._precedents.get(current, set()):
                if p == cell:
                    return True
                if p not in visited:
                    stack.append(p)

        return False

    def cycle_cells(self) -> Set[str]:
        """
        Returns all cells that lie on a cycle.
        A cell is on a cycle if following precedents leads back to itself.
        """
        cycles = set()

        # Collect all nodes involved in the dependency graph
        all_nodes = set(self._precedents.keys())
        for p_list in self._precedents.values():
            all_nodes.update(p_list)

        # We only care about nodes that have precedents (formula cells) or are precedents of formula cells.
        # But essentially, if a node has no precedents, it can't be on a cycle (unless self-loop, but self-loop requires precedents).
        # If a node is a precedent but has no precedents of its own, it can't be on a cycle.

        # Tarjan's Algorithm for Strongly Connected Components
        index_counter = [0]
        stack = []
        lowlink = {}
        index = {}
        on_stack = set()

        def strongconnect(node):
            index[node] = index_counter[0]
            lowlink[node] = index_counter[0]
            index_counter[0] += 1
            stack.append(node)
            on_stack.add(node)

            # Consider successors
            for neighbor in self._precedents.get(node, set()):
                if neighbor not in all_nodes: 
                    # Should not happen if all_nodes is comprehensive, but safe guard
                    continue

                if neighbor not in index:
                    # Successor has not yet been visited; recurse on it
                    strongconnect(neighbor)
                    lowlink[node] = min(lowlink[node], lowlink[neighbor])
                elif neighbor in on_stack:
                    # Successor is on stack and hence in the current SCC
                    lowlink[node] = min(lowlink[node], index[neighbor])

            # If node is a root node, pop the stack and generate an SCC
            if lowlink[node] == index[node]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == node:
                        break

                # If SCC size > 1, all nodes are in a cycle.
                # If SCC size == 1, it is in a cycle ONLY IF it has a self-loop (edge to itself).
                if len(scc) > 1:
                    cycles.update(scc)
                elif len(scc) == 1:
                    node = scc[0]
                    if node in self._precedents.get(node, set()):
                        cycles.add(node)

        for node in all_nodes:
            if node not in index:
                strongconnect(node)

        return cycles
