import heapq
import re
from typing import List, Any, Dict

from .formula import parse_formula, references, evaluate, FormulaError, ErrorValue, CYCLE, ERROR, Node
from .graph import DependencyGraph

class Sheet:
    def __init__(self):
        self._raw: dict[str, str] = {}
        self._values: dict[str, Any] = {}
        self._trees: dict[str, Node] = {}
        self._graph = DependencyGraph()
        self.evaluations = 0

    def _validate_name(self, name: str):
        if not isinstance(name, str):
            raise ValueError("Name must be a string")
        name = name.upper()
        if len(name) < 2:
            raise ValueError("Invalid cell name")

        # Check column
        col = name[0]
        if not ('A' <= col <= 'Z'):
            raise ValueError("Column out of range")

        row_str = name[1:]
        if not row_str.isdigit():
            raise ValueError("Invalid row")

        row = int(row_str)
        if row < 1 or row > 999:
            raise ValueError("Row out of range")

        # Check for leading zeros in row (e.g. A01)
        if len(row_str) > 1 and row_str[0] == '0':
            raise ValueError("Invalid row format")

    def _is_number(self, s: str) -> bool:
        stripped = s.strip()
        # Optional - followed by digits [. digits]
        return bool(re.match(r'^-?\d+(\.\d+)?$', stripped))

    def _parse_number(self, s: str) -> int | float:
        stripped = s.strip()
        if '.' in stripped:
            return float(stripped)
        else:
            return int(stripped)

    def _row_major_key(self, name: str):
        # Row then Column
        # B1 -> (1, 'B')
        # A2 -> (2, 'A')
        r = int(name[1:])
        c = name[0]
        return (r, c)

    def set(self, name: str, raw: str) -> List[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        name = name.upper()
        self._validate_name(name)

        # Determine new dependencies and tree
        new_deps = set()
        new_tree = None

        if raw.startswith("="):
            try:
                new_tree = parse_formula(raw[1:])
                new_deps = references(new_tree)
            except FormulaError:
                raise FormulaError(f"Invalid formula: {raw}")

        # Update state
        self._raw[name] = raw

        if new_tree is not None:
            self._trees[name] = new_tree
            self._graph.set_dependencies(name, new_deps)
            # Value will be determined in recalculation loop
        else:
            if name in self._trees:
                del self._trees[name]
            self._graph.set_dependencies(name, set())

            # Set immediate value for non-formula
            if raw == "":
                self._values[name] = None
            elif self._is_number(raw):
                self._values[name] = self._parse_number(raw)
            else:
                self._values[name] = raw

        # Identify affected cells
        # all_dependents returns cells that depend on 'name' (and name if on cycle)
        # We need 'name' plus its dependents.
        # If 'name' is not on a cycle, all_dependents('name') will NOT include 'name'.
        # So we explicitly add 'name'.

        affected = self._graph.all_dependents(name)
        affected.add(name)

        affected_list = sorted(affected, key=self._row_major_key)

        # Identify cells on cycles
        cycle_cells = self._graph.cycle_cells()

        # Separate into cycle and non-cycle for processing
        # Cells on cycles are set to CYCLE and not evaluated.
        # Cells NOT on cycles are evaluated in topological order.

        # 1. Mark cycle cells in affected list as CYCLE
        for cell in affected_list:
            if cell in cycle_cells:
                self._values[cell] = CYCLE

        # 2. Prepare non-cycle cells for evaluation
        # Only formula cells need evaluation. Value cells are already set.
        formula_cells_to_eval = []
        for cell in affected_list:
            if cell in cycle_cells:
                continue
            if cell in self._trees: # It is a formula cell
                formula_cells_to_eval.append(cell)

        # 3. Topological sort of formula_cells_to_eval
        # We need to evaluate cells such that precedents are evaluated first.
        # Precedents might be outside this set (if they are values or unaffected formulas).
        # We only need to resolve order for dependencies WITHIN the set.

        # Build local dependency graph
        # Edge: P -> D if D depends on P.
        # We want to process D after P.

        indegree = {cell: 0 for cell in formula_cells_to_eval}
        local_dependents = {cell: set() for cell in formula_cells_to_eval}

        for cell in formula_cells_to_eval:
            # Get precedents of this cell
            precedents = self._graph.precedents(cell)
            for p in precedents:
                if p in indegree:
                    # p is a precedent of cell, and is in the set
                    # So cell depends on p
                    # In topo sort (Kahn's), we usually count incoming edges (dependencies).
                    # If cell depends on p, there is an edge p -> cell in the "dependency" graph.
                    # indegree of cell increases.
                    indegree[cell] += 1
                    local_dependents[p].add(cell)

        # Initialize heap with nodes having indegree 0
        # Use heap for deterministic row-major order among available nodes
        heap = []
        for cell in formula_cells_to_eval:
            if indegree[cell] == 0:
                heapq.heappush(heap, self._row_major_key(cell))
                # Store key to cell mapping? 
                # Since key is derived from name, we can recover name or store tuple.
                # Let's store (key, cell) in heap? No, heapq compares tuples.
                # If I push key, I need to map back. 
                # Better: push key, and keep a map key->cell? 
                # Or just push key and derive cell? 
                # key = (row, col). cell = f"{col}{row}".
                pass

        # Re-implement heap with keys
        heap = []
        for cell in formula_cells_to_eval:
            if indegree[cell] == 0:
                # We need to pop cells. 
                # If we push key, we can reconstruct cell.
                heapq.heappush(heap, (self._row_major_key(cell), cell))

        topo_order = []
        while heap:
            _, cell = heapq.heappop(heap)
            topo_order.append(cell)

            for dep in local_dependents.get(cell, set()):
                indegree[dep] -= 1
                if indegree[dep] == 0:
                    heapq.heappush(heap, (self._row_major_key(dep), dep))

        # If heap empties but topo_order < len(formula_cells_to_eval), there is a cycle among them?
        # But we already excluded cycle_cells. 
        # Note: cycle_cells detects cycles in the WHOLE graph.
        # It is possible to have a cycle involving cells NOT in affected_list?
        # No, if they are in cycle_cells, they are marked CYCLE.
        # The remaining cells are guaranteed to be acyclic relative to each other?
        # If A->B->C and all are in affected, and no cycle, topo sort works.
        # If there was a cycle, they would be in cycle_cells.
        # So topo_order should contain all formula_cells_to_eval.

        # 4. Evaluate
        for cell in topo_order:
            tree = self._trees[cell]
            # Define lookup closure
            def lookup(n: str) -> Any:
                return self._values.get(n)

            try:
                val = evaluate(tree, lookup)
                self._values[cell] = val
            except Exception:
                # Catch any unexpected errors during evaluation
                self._values[cell] = ERROR

            self.evaluations += 1

        return affected_list

    def get(self, name: str) -> Any:
        name = name.upper()
        self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        name = name.upper()
        self._validate_name(name)
        return self._raw.get(name, "")

    def cells(self) -> List[str]:
        # Non-empty cells: raw != ""
        non_empty = [name for name, raw in self._raw.items() if raw != ""]
        return sorted(non_empty, key=self._row_major_key)
