import re
from typing import Any, Callable, List, Set, Tuple

class FormulaError(ValueError):
    """Raised when a formula cannot be parsed."""
    pass

class ErrorValue(str):
    """A string subclass representing an error state in the sheet."""
    def __new__(cls, value: str):
        return super().__new__(cls, value)

    def __eq__(self, other: object) -> bool:
        return str.__eq__(self, other)

    def __hash__(self) -> int:
        return str.__hash__(self)

# Error constants
DIV_ZERO = ErrorValue("#DIV/0!")
VALUE_ERR = ErrorValue("#VALUE!")
REF_ERR = ErrorValue("#REF!")
CYCLE = ErrorValue("#CYCLE!")

# --- Syntax Tree Classes ---

class Node:
    pass

class Number(Node):
    def __init__(self, value: int | float):
        self.value = value

class Ref(Node):
    def __init__(self, name: str):
        self.name = name  # Always upper case

class UnaryOp(Node):
    def __init__(self, op: str, operand: Node):
        self.op = op
        self.operand = operand

class BinaryOp(Node):
    def __init__(self, op: str, left: Node, right: Node):
        self.op = op
        self.left = left
        self.right = right

class RangeNode(Node):
    def __init__(self, start: Ref, end: Ref):
        self.start = start
        self.end = end

class FunctionCall(Node):
    def __init__(self, fname: str, args: List[Node]):
        self.fname = fname
        self.args = args

# --- Parsing ---

def _is_valid_ref_name(name: str) -> bool:
    if not name:
        return False

    # Must end with digits and start with letters
    col_part = ''
    row_part = ''
    for i, char in enumerate(name):
        if char.isdigit():
            col_part = name[:i]
            row_part = name[i:]
            break
    else:
        return False # No digits found

    if not col_part or not row_part:
        return False

    # Column validation
    if len(col_part) != 1 or not ('A' <= col_part[0] <= 'Z'):
        return False

    # Row validation
    if not row_part.isdigit():
        return False
    if len(row_part) > 1 and row_part[0] == '0':
        return False

    try:
        row = int(row_part)
    except ValueError:
        return False

    if row < 1 or row > 999:
        return False

    return True

def _tokenize(source: str) -> List[Tuple[str, str]]:
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        if source[i].isspace():
            i += 1
            continue

        if source[i] in '+-*/(),:':
            tokens.append(('op', source[i]))
            i += 1
            continue

        if source[i].isalpha():
            m = re.match(r'^[A-Za-z]+', source[i:])
            letters = m.group()
            i += len(letters)

            if i < n and source[i].isdigit():
                # It's a reference
                m2 = re.match(r'^\d+', source[i:])
                digits = m2.group()
                name = (letters + digits).upper()
                tokens.append(('ref', name))
                i += len(digits)
            else:
                fname = letters.upper()
                tokens.append(('fname', fname))
            continue

        if source[i].isdigit():
            m = re.match(r'^\d+(\.\d+)?', source[i:])
            if m:
                tokens.append(('num', m.group()))
                i += len(m.group())
                continue
            else:
                raise FormulaError("Invalid number format")

        raise FormulaError(f"Unexpected character: {source[i]}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Tuple[str, str]]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Tuple[str, str] | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Tuple[str, str]:
        if self.pos >= len(self.tokens):
            raise FormulaError("Unexpected end of input")
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, val: str):
        tok = self.consume()
        if tok[1] != val:
            raise FormulaError(f"Expected {val}")

    def parse_expr(self) -> Node:
        node = self.parse_term()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('+', '-'):
            op = self.consume()[1]
            right = self.parse_term()
            node = BinaryOp(op, node, right)
        return node

    def parse_term(self) -> Node:
        node = self.parse_unary()
        while self.peek() and self.peek()[0] == 'op' and self.peek()[1] in ('*', '/'):
            op = self.consume()[1]
            right = self.parse_unary()
            node = BinaryOp(op, node, right)
        return node

    def parse_unary(self) -> Node:
        tok = self.peek()
        if tok and tok[0] == 'op' and tok[1] in ('+', '-'):
            op = self.consume()[1]
            operand = self.parse_unary()
            return UnaryOp(op, operand)
        return self.parse_atom()

    def parse_atom(self) -> Node:
        tok = self.peek()
        if not tok:
            raise FormulaError("Unexpected end of expression")

        if tok[0] == 'num':
            self.consume()
            if '.' in tok[1]:
                return Number(float(tok[1]))
            else:
                return Number(int(tok[1]))

        if tok[0] == 'ref':
            self.consume()
            return Ref(tok[1])

        if tok[0] == 'fname':
            fname = self.consume()[1]
            if fname not in ['SUM', 'AVG', 'MIN', 'MAX']:
                raise FormulaError(f"Unknown function {fname}")

            self.expect('(')

            args = []
            if self.peek() and self.peek()[1] == ')':
                raise FormulaError("Function call with no arguments")

            while True:
                arg = self.parse_arg()
                args.append(arg)

                if self.peek() and self.peek()[1] == ',':
                    self.consume()
                    continue
                elif self.peek() and self.peek()[1] == ')':
                    self.consume()
                    break
                else:
                    raise FormulaError("Expected ',' or ')' in function arguments")

            return FunctionCall(fname, args)

        if tok[0] == 'op' and tok[1] == '(':
            self.consume()
            node = self.parse_expr()
            self.expect(')')
            return node

        raise FormulaError(f"Unexpected token: {tok}")

    def parse_arg(self) -> Node:
        start_pos = self.pos

        tok = self.peek()
        if tok and tok[0] == 'ref':
            ref1 = self.consume()[1]

            if self.peek() and self.peek()[1] == ':':
                self.consume() # consume ':'

                tok2 = self.peek()
                if tok2 and tok2[0] == 'ref':
                    ref2 = self.consume()[1]
                    r1 = Ref(ref1)
                    r2 = Ref(ref2)
                    return RangeNode(r1, r2)
                else:
                    raise FormulaError("Invalid range syntax")
            else:
                self.pos = start_pos
                return self.parse_expr()
        else:
            return self.parse_expr()

def parse_formula(source: str) -> Node:
    if not source or not source.strip():
        raise FormulaError("Empty formula")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    parser = Parser(tokens)
    tree = parser.parse_expr()

    if parser.pos != len(parser.tokens):
        raise FormulaError("Unexpected trailing characters")

    return tree

# --- References ---

def _get_cells_in_range(start: str, end: str) -> List[str]:
    cells = []

    def parse_cell(name):
        if not name: return None, None
        col_str = ""
        row_str = ""
        for i, char in enumerate(name):
            if char.isdigit():
                col_str = name[:i]
                row_str = name[i:]
                break
        if not col_str or not row_str: return None, None
        if len(col_str) != 1: return None, None
        c_char = col_str[0]
        if not ('A' <= c_char <= 'Z'): return None, None
        if not row_str.isdigit(): return None, None
        if len(row_str) > 1 and row_str[0] == '0': return None, None
        try:
            r = int(row_str)
        except:
            return None, None
        if r < 1 or r > 999: return None, None
        return c_char, r

    c1, r1 = parse_cell(start)
    c2, r2 = parse_cell(end)

    if c1 is None or r1 is None or c2 is None or r2 is None:
        return []

    min_c, max_c = sorted([c1, c2])
    min_r, max_r = sorted([r1, r2])

    for r in range(min_r, max_r + 1):
        for c_ord in range(ord(min_c), ord(max_c) + 1):
            c = chr(c_ord)
            cell_name = f"{c}{r}"
            cells.append(cell_name)

    return cells

def references(tree: Node) -> Set[str]:
    refs = set()

    def traverse(node: Node):
        if isinstance(node, Ref):
            if _is_valid_ref_name(node.name):
                refs.add(node.name)
        elif isinstance(node, UnaryOp):
            traverse(node.operand)
        elif isinstance(node, BinaryOp):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, FunctionCall):
            for arg in node.args:
                traverse(arg)
        elif isinstance(node, RangeNode):
            r1 = node.start.name
            r2 = node.end.name
            if _is_valid_ref_name(r1) and _is_valid_ref_name(r2):
                valid_cells = _get_cells_in_range(r1, r2)
                refs.update(valid_cells)

    traverse(tree)
    return refs

# --- Evaluation ---

def _evaluate_range(node: RangeNode, lookup: Callable[[str], Any]) -> Tuple[Any, List[int | float]]:
    r1 = node.start.name
    r2 = node.end.name

    if not _is_valid_ref_name(r1) or not _is_valid_ref_name(r2):
        return REF_ERR, []

    cells = _get_cells_in_range(r1, r2)
    numbers = []

    for cell in cells:
        val = lookup(cell)
        if isinstance(val, ErrorValue):
            return val, []
        if val is None:
            continue
        if isinstance(val, str):
            continue # Skip text
        numbers.append(val)

    return None, numbers

def _evaluate_call(node: FunctionCall, lookup: Callable[[str], Any]) -> Any:
    all_numbers = []

    for arg in node.args:
        if isinstance(arg, RangeNode):
            err, nums = _evaluate_range(arg, lookup)
            if err is not None:
                return err
            all_numbers.extend(nums)
        else:
            if isinstance(arg, Ref):
                cell_name = arg.name
                if not _is_valid_ref_name(cell_name):
                    return REF_ERR

                val = lookup(cell_name)
                if isinstance(val, ErrorValue):
                    return val
                if val is None:
                    continue
                if isinstance(val, str):
                    continue # Skip text
                all_numbers.append(val)
            else:
                val = evaluate(arg, lookup)
                if isinstance(val, ErrorValue):
                    return val
                if isinstance(val, str):
                    return VALUE_ERR
                all_numbers.append(val)

    fname = node.fname

    if not all_numbers:
        if fname == 'SUM':
            return 0
        elif fname == 'AVG':
            return DIV_ZERO
        elif fname == 'MIN' or fname == 'MAX':
            return 0

    if fname == 'SUM':
        if all(isinstance(n, int) for n in all_numbers):
            return sum(all_numbers)
        else:
            return float(sum(all_numbers))

    if fname == 'AVG':
        return float(sum(all_numbers)) / float(len(all_numbers))

    if fname == 'MIN':
        return min(all_numbers)

    if fname == 'MAX':
        return max(all_numbers)

    return VALUE_ERR 

def evaluate(tree: Node, lookup: Callable[[str], Any]) -> Any:
    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, Ref):
        if not _is_valid_ref_name(tree.name):
            return REF_ERR
        val = lookup(tree.name)
        if val is None:
            return 0
        return val

    if isinstance(tree, UnaryOp):
        operand = evaluate(tree.operand, lookup)
        if isinstance(operand, ErrorValue):
            return operand
        if isinstance(operand, str):
            return VALUE_ERR
        if tree.op == '-':
            return -operand
        else:
            return operand

    if isinstance(tree, BinaryOp):
        left = evaluate(tree.left, lookup)
        right = evaluate(tree.right, lookup)

        if isinstance(left, ErrorValue):
            return left
        if isinstance(right, ErrorValue):
            return right

        if isinstance(left, str) or isinstance(right, str):
            return VALUE_ERR

        if tree.op == '+':
            if isinstance(left, int) and isinstance(right, int):
                return left + right
            return float(left) + float(right)

        elif tree.op == '-':
            if isinstance(left, int) and isinstance(right, int):
                return left - right
            return float(left) - float(right)

        elif tree.op == '*':
            if isinstance(left, int) and isinstance(right, int):
                return left * right
            return float(left) * float(right)

        elif tree.op == '/':
            if right == 0:
                return DIV_ZERO
            return float(left) / float(right)

    if isinstance(tree, FunctionCall):
        return _evaluate_call(tree, lookup)

    if isinstance(tree, RangeNode):
        raise FormulaError("Range evaluated outside of function")

    raise FormulaError("Invalid AST node")
