from dataclasses import dataclass
from typing import Union, Tuple, List
import re

class RegexError(ValueError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.message = message
        self.position = position

# AST Classes
@dataclass(frozen=True)
class Empty:
    pass

@dataclass(frozen=True)
class Literal:
    char: str

@dataclass(frozen=True)
class AnyChar:
    pass

@dataclass(frozen=True)
class CharClass:
    items: Tuple[Tuple[str, str], ...]
    negated: bool

@dataclass(frozen=True)
class Concat:
    items: Tuple['Node', ...]

@dataclass(frozen=True)
class Alt:
    options: Tuple['Node', ...]

@dataclass(frozen=True)
class Star:
    node: 'Node'

@dataclass(frozen=True)
class Plus:
    node: 'Node'

@dataclass(frozen=True)
class Optional:
    node: 'Node'

@dataclass(frozen=True)
class Group:
    node: 'Node'

Node = Union[Empty, Literal, AnyChar, CharClass, Concat, Alt, Star, Plus, Optional, Group]

def parse(pattern: str) -> Node:
    parser = _Parser(pattern)
    ast = parser.parse_pattern()
    if parser.i < len(pattern):
        # Should not happen if logic is correct, but defensive
        raise RegexError("Unexpected character", parser.i)
    return ast

class _Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.i = 0
        self.len = len(pattern)
        # Stack to track open parenthesis positions for error reporting
        self.open_parens = []

    def peek(self):
        if self.i >= self.len:
            return None
        return self.pattern[self.i]

    def consume(self):
        c = self.pattern[self.i]
        self.i += 1
        return c

    def parse_pattern(self) -> Node:
        options = [self.parse_alt_sequence()]
        while self.peek() == '|':
            self.consume() # consume '|'
            options.append(self.parse_alt_sequence())

        if len(options) == 1:
            return options[0]
        return Alt(tuple(options))

    def parse_alt_sequence(self) -> Node:
        items = []
        while True:
            c = self.peek()
            if c is None or c == '|' or c == ')':
                break

            atom = self.parse_atom_with_quantifiers()
            items.append(atom)

        if len(items) == 0:
            return Empty()
        elif len(items) == 1:
            return items[0]
        else:
            return Concat(tuple(items))

    def parse_atom_with_quantifiers(self) -> Node:
        atom = self.parse_atom()
        while self.peek() in ('*', '+', '?'):
            q = self.consume()
            if q == '*':
                atom = Star(atom)
            elif q == '+':
                atom = Plus(atom)
            elif q == '?':
                atom = Optional(atom)
        return atom

    def parse_atom(self) -> Node:
        c = self.peek()
        if c is None:
            return Empty()

        if c == '(':
            self.consume() # consume '('
            # Save position for error reporting
            start_pos = self.i - 1
            self.open_parens.append(start_pos)

            node = self.parse_pattern()

            if self.peek() != ')':
                # End of pattern reached with unclosed parens
                # The last opened paren is the one to blame
                pos = self.open_parens[-1]
                raise RegexError("Unclosed parenthesis", pos)

            self.consume() # consume ')'
            self.open_parens.pop() # remove from stack

            return Group(node)

        elif c == '[':
            return self.parse_char_class()

        elif c == '.':
            self.consume()
            return AnyChar()

        elif c == '\\':
            self.consume() # consume '\'
            if self.i >= self.len:
                raise RegexError("Trailing backslash", self.i - 1)
            return Literal(self.consume())

        elif c in ('*', '+', '?'):
            # Quantifier with nothing to repeat
            pos = self.i
            self.consume()
            raise RegexError("Nothing to repeat", pos)

        elif c == ')':
            # This should be handled by higher level, but if we see it here directly
            # it means it's unmatched at the start or after another quantifier error was passed?
            # Actually, unmatched ')' is detected in parse_alt_sequence loop termination check?
            # No, if we start with ')', parse_alt_sequence breaks immediately.
            # Then parse_pattern returns Empty. Then caller checks if next is ')'.
            # If caller is parse_pattern (top level), and next is ')', then parse_pattern returns.
            # Then _Parser.parse_pattern checks if i < len.
            # If i < len, it raises "Unexpected character".
            # But spec says: "a ) with no matching ( " -> position is that )
            # We need to detect this specifically.
            pos = self.i
            self.consume()
            raise RegexError("Unmatched parenthesis", pos)

        else:
            # Literal
            self.consume()
            return Literal(c)

    def parse_char_class(self) -> Node:
        # Consume '['
        open_pos = self.i
        self.consume()

        negated = False
        if self.peek() == '^':
            negated = True
            self.consume()

        items: List[Tuple[str, str]] = []
        first_item = True

        while True:
            if self.i >= self.len:
                raise RegexError("Unclosed character class", open_pos)

            c = self.pattern[self.i]

            if c == ']' and not first_item:
                self.consume()
                break

            # Parse character or range
            # First, get the start character
            if self.i >= self.len:
                 raise RegexError("Unclosed character class", open_pos)

            low = self.parse_class_char()

            # Check for range '-'
            # It's a range if next is '-' AND next-next is not ']' (and not end)
            # Also, if we are at the start of the class (after negation), '-' is literal
            # If '-' is the last character in class (followed by ']'), it's literal

            is_range = False
            high = None

            if self.i < self.len and self.pattern[self.i] == '-':
                # Lookahead for ']' or end
                if self.i + 1 >= self.len or self.pattern[self.i+1] != ']':
                    # Consume '-'
                    self.consume()
                    if self.i >= self.len:
                        raise RegexError("Unclosed character class", open_pos)
                    high = self.parse_class_char()
                    is_range = True

            if is_range:
                if low > high:
                    # Find position of low char
                    # We need to track positions. 
                    # Simplified: we know the last consumed char was high.
                    # The low char was consumed earlier.
                    # We need to know where 'low' was.
                    # Let's refactor to track positions.
                    pass 
                items.append((low, high))
            else:
                items.append((low, low))

            first_item = False

        if len(items) == 0:
            raise RegexError("Empty character class", open_pos)

        return CharClass(tuple(items), negated)

    def parse_class_char(self) -> str:
        c = self.pattern[self.i]
        if c == '\\':
            self.consume()
            if self.i >= self.len:
                raise RegexError("Trailing backslash in class", self.i - 1) # Or similar
            return self.consume()
        else:
            self.consume()
            return c

# Refined Parser with Position Tracking for Range Errors

class _Parser2:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.i = 0
        self.len = len(pattern)
        self.open_parens = []

    def peek(self, offset=0):
        if self.i + offset >= self.len:
            return None
        return self.pattern[self.i + offset]

    def consume(self):
        c = self.pattern[self.i]
        self.i += 1
        return c

