        while self.peek() == '|':
            self.consume()
            options.append(self._parse_concat_seq())

        if len(options) == 1:
            return options[0]
        return Alt(tuple(options))

    def _parse_concat_seq(self) -> Node:
        items = []
        while True:
            c = self.peek()
            if c is None or c == '|' or c == ')':
                break

