            # This is handled in parse_atom_with_quantifiers if the atom fails to return
            # But if we have nothing before *, it will error.

            atom = self._parse_atom_with_quantifiers()
            items.append(atom)

        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Concat(tuple(items))

    def _parse_atom_with_quantifiers(self) -> Node:
        atom = self._parse_atom()

        while self.peek() in ('*', '+', '?'):
            q_pos = self.i
            q = self.consume()
            if q == '*':
                atom = Star(atom)
            elif q == '+':
                atom = Plus(atom)
            elif q == '?':
                atom = Optional(atom)

        return atom

    def _parse_atom(self) -> Node:
        c = self.peek()
        if c is None:
            # Empty atom
            return Empty()

        if c == '(':
            self.consume()
            start_pos = self.i - 1
            self.open_parens.append(start_pos)

            node = self.parse_pattern()

            if self.peek() != ')':
                pos = self.open_parens[-1]
                raise RegexError("Unclosed parenthesis", pos)

            self.consume()
            self.open_parens.pop()

            return Group(node)

        if c == '[':
            return self._parse_char_class()

        if c == '.':
            self.consume()
            return AnyChar()

        if c == '\\':
            self.consume()
            if self.i >= self.len:
                raise RegexError("Trailing backslash", self.i - 1)
            return Literal(self.consume())

        if c in ('*', '+', '?'):
            raise RegexError("Nothing to repeat", self.i)

        if c == ')':
            raise RegexError("Unmatched parenthesis", self.i)

        # Literal
        self.consume()
        return Literal(c)

    def _parse_char_class(self) -> Node:
        open_pos = self.i
        self.consume() # [

        negated = False
        if self.peek() == '^':
            negated = True
            self.consume()

        items = []
        is_first = True

        while True:
            if self.i >= self.len:
                raise RegexError("Unclosed character class", open_pos)

            c = self.pattern[self.i]

            if c == ']' and not is_first:
                self.consume()
                break

            # Determine if we are parsing a range or a single char
            # A range is X-Y
            # But if it's the first item, '-' is literal? 
            # Spec: "A - is a literal when it is the first item (after any ^) or the last item."

            # Try to parse the first char of potential range
            low_pos = self.i
            low = self._parse_class_char()

            # Check for '-'
            if self.peek() == '-' and not (self.peek(1) == ']' or self.peek(1) is None):
                 # It's a range!
                 # Wait, if is_first, is it a range? 
                 # "A - is a literal when it is the first item"
                 # So if is_first, we treat '-' as the next char? No, we already consumed low.
                 # If low was a char, and next is '-', and it's the first item...
                 # Example: [-a] -> items: '-', 'a'. 
                 # Example: [a-z] -> items: (a,z).
                 # If is_first, we cannot have a range starting with the first char? 
                 # Actually, if the first char is 'a', and next is '-', it CAN be a range.
                 # The rule is about the '-' character itself being literal.
                 # If we parse 'a', then see '-', then see 'z', it's a range.
                 # The "first item" rule means if the CLASS STARTS with '-', it's literal.
                 # i.e. [-a] -> '-' and 'a'.
                 # Here, low is 'a'. It is not '-'. So we are in the middle of parsing.
                 # If the sequence was `[-a]`, low would be '-', is_first=True.
                 # Then we see '-'? No, we consumed '-'. Next is 'a'. Not a range syntax X-Y-X.

                 # So, is_first only matters if the CHARACTER ITSELF is '-'.
                 # Since we already extracted `low`, if `low` is '-', it was treated as a literal single char.
                 # If `low` is not '-', we can form a range.

                 self.consume() # consume '-'
                 high_pos = self.i
                 high = self._parse_class_char()

                 if low > high:
                     raise RegexError("Range out of order", low_pos)

                 items.append((low, high))
            else:
