                items.append((low, low))

            is_first = False

        if not items:
            raise RegexError("Empty character class", open_pos)

        return CharClass(tuple(items), negated)

    def _parse_class_char(self) -> str:
        c = self.pattern[self.i]
        if c == '\\':
            self.consume()
            if self.i >= self.len:
                 raise RegexError("Trailing backslash in class", self.i - 1)
            return self.consume()
        self.consume()
        return c

