from typing import List, Set, Optional, Tuple, Union
from .parse import (
    Node, Empty, Literal, AnyChar, CharClass, Concat, Alt, Star, Plus, Optional, Group,
    parse, RegexError
)

# NFA States are represented as integers.
# Transitions:
# epsilon -> set of states
# char -> set of states (for literal)
# any -> set of states (for .)
# class -> set of states (for [])
# neg_class -> set of states (for [^])

class NFA:
    def __init__(self, start: int, states: List[dict], accept_states: Set[int]):
        self.start = start
        self.states = states # list of dicts: {'eps': [states], 'lit': {char: [states]}, ...}
        self.accept_states = accept_states

    def match(self, text: str) -> bool:
        return self.search(text, 0, whole=True) is not None

    def search(self, text: str, start=0, whole=False) -> Optional[Tuple[int, int]]:
        # Simulate NFA with epsilon closure
        # We want the leftmost match, and among those, the longest.
        # Thompson NFA simulation tracks a set of active states.
        # To find the longest match, we continue simulating even after reaching an accept state.

        n_states = len(self.states)

        # Helper to compute epsilon closure
        def epsilon_closure(states: Set[int]) -> Set[int]:
            stack = list(states)
            closed = set(states)
            while stack:
                s = stack.pop()
                for next_s in self.states[s].get('eps', []):
                    if next_s not in closed:
                        closed.add(next_s)
                        stack.append(next_s)
            return closed

        # Initial states
        current_states = epsilon_closure({self.start})

        # Find matches
        best_match = None

        # We scan from start.
        # We need to reset if we are doing search from a specific start point?
        # The method signature is search(text, start=0).
        # It finds leftmost match >= start.

        i = start
        n = len(text)

        # We need to simulate NFA steps.
        # State: set of NFA states.
        # We track matches. A match ends when we are at an accept state after consuming i chars.
        # But since we want longest match, we keep going.

        # However, standard NFA simulation for regex usually finds *a* match.
        # For longest match, we can just simulate to the end of the text (or until no states remain)
        # and record the last time we were in an accept state.

        # But search needs the *leftmost* match.
        # So we start scanning from `start`.
        # If we find any match, we record the end position.
        # We continue simulation to see if it extends.
