                 # Here, low is 'a'. It is not '-'. So we are in the middle of parsing.
                 # If the sequence was `[-a]`, low would be '-', is_first=True.
                 # Then we see '-'? No, we consumed '-'. Next is 'a'. Not a range syntax X-Y-X.

                 # So, is_first only matters if the CHARACTER ITSELF is '-'.
                 # Since we already extracted `low`, if `low` is '-', it was treated as a literal single char.
                 # If `low` is not '-', we can form a range.

                 self.consume() # consume '-'
                 high_pos = self.i
                 high = self._parse_class_char()

                 if low > high:
                     raise RegexError("Range out of order", low_pos)

                 items.append((low, high))
            else:
                # Single char
                items.append((low, low))

            is_first = False

        if not items:
            raise RegexError("Empty character class", open_pos)

        return CharClass(tuple(items), negated)

    def _parse_class_char(self) -> str:
        c = self.pattern[self.i]
        if c == '\\':
            self.consume()
            if self.i >= self.len:
                 raise RegexError("Trailing backslash in class", self.i - 1)
            return self.consume()
        self.consume()
        return c

# Alias back
Parser = _Parser2

def parse(pattern: str) -> Node:
    parser = _Parser2(pattern)
    ast = parser.parse_pattern()

    # Check for unmatched ')'
    if parser.i < parser.len:
        # The current char must be ')' since other stops break the loop
        # Or just unexpected
        raise RegexError("Unmatched parenthesis", parser.i)

    # Check for unclosed '('
    if parser.open_parens:
        pos = parser.open_parens[0] # First unclosed? Spec: "if several are unclosed, the last one opened"
        # Wait, "last one opened". That is the top of the stack.
        # The stack contains all unclosed parens found so far in order of opening.
        # The last one opened is the last element.
        pos = parser.open_parens[-1]
        raise RegexError("Unclosed parenthesis", pos)

    return ast
