from typing import List, Set, Optional, Tuple, Union, Dict
from .parse import (
    Node, Empty, Literal, AnyChar, CharClass, Concat, Alt, Star, Plus, Optional, Group,
    parse, RegexError
)

# State structure:
# epsilon: List[int]
# transitions: Dict[str, List[int]] (for literal chars)
# any_next: List[int] (for .)
# class_next: Optional[Tuple[Tuple[Tuple[str,str],...], bool, List[int]]] 
#   Actually, simpler: just check class membership during transition step.
# Let's store class info in the transition definition.
# state[s] = {
#   'eps': [int],
#   'lit': {'a': [int]},
#   'any': [int],
#   'class': { 'items': (...), 'negated': bool, 'next': [int] }
# }

class NFA:
    def __init__(self):
        self.start = 0
        self.accept = {0} # Simple NFA: 1 state, start=accept, eps? 
        # Need to build properly.
        # Let's build from AST recursively.

    def build_from_ast(self, ast: Node):
        # Reset
        self.states = []
        self.start = 0
        self.accept = set()

        # Helper to add state
        def new_state():
            s_id = len(self.states)
            self.states.append({'eps': [], 'lit': {}, 'any': [], 'class': None})
            return s_id

        # Recursive function to build NFA for node, returning (start_state, accept_state)
        def build(node: Node) -> Tuple[int, int]:
            if isinstance(node, Empty):
                s = new_state()
                a = new_state()
                self.states[s]['eps'].append(a)
                return (s, a)

            elif isinstance(node, Literal):
                s = new_state()
                a = new_state()
                self.states[s]['lit'][node.char] = [a]
                return (s, a)

            elif isinstance(node, AnyChar):
                s = new_state()
                a = new_state()
                self.states[s]['any'].append(a)
                return (s, a)

            elif isinstance(node, CharClass):
                s = new_state()
                a = new_state()
                self.states[s]['class'] = {
                    'items': node.items,
                    'negated': node.negated,
                    'next': [a]
                }
                return (s, a)

            elif isinstance(node, Concat):
                prev_a = None
                start_s = None
                for item in node.items:
                    s_a_pair = build(item)
                    s_i, a_i = s_a_pair
                    if start_s is None:
                        start_s = s_i
                    else:
                        self.states[prev_a]['eps'].append(s_i)
                    prev_a = a_i
                return (start_s, prev_a)

            elif isinstance(node, Alt):
                start_s = new_state()
                end_s = new_state()
                for option in node.options:
                    s_i, a_i = build(option)
                    self.states[start_s]['eps'].append(s_i)
                    self.states[a_i]['eps'].append(end_s)
                return (start_s, end_s)

            elif isinstance(node, Star):
                start_s = new_state()
                end_s = new_state()
                s_i, a_i = build(node.node)
                # Loop
                self.states[start_s]['eps'].append(s_i)
                self.states[start_s]['eps'].append(end_s)
                self.states[a_i]['eps'].append(s_i)
                self.states[a_i]['eps'].append(end_s)
                return (start_s, end_s)

            elif isinstance(node, Plus):
                start_s = new_state()
                end_s = new_state()
                s_i, a_i = build(node.node)
                # At least one
                self.states[start_s]['eps'].append(s_i)
                self.states[a_i]['eps'].append(s_i)
                self.states[a_i]['eps'].append(end_s)
                return (start_s, end_s)

            elif isinstance(node, Optional):
                start_s = new_state()
                end_s = new_state()
                s_i, a_i = build(node.node)
                self.states[start_s]['eps'].append(s_i)
                self.states[start_s]['eps'].append(end_s)
                self.states[a_i]['eps'].append(end_s)
                return (start_s, end_s)

            elif isinstance(node, Group):
                return build(node.node)

            else:
                raise NotImplementedError(f"Unknown node type {type(node)}")

        s, a = build(ast)
        self.start = s
        self.accept = {a}

    def _epsilon_closure(self, states: Set[int]) -> Set[int]:
        stack = list(states)
        closed = set(states)
        while stack:
            s = stack.pop()
            for next_s in self.states[s]['eps']:
                if next_s not in closed:
                    closed.add(next_s)
                    stack.append(next_s)
        return closed

    def _step(self, current_states: Set[int], char: str) -> Set[int]:
        next_states = set()
        for s in current_states:
            state_data = self.states[s]

            # Literal
            if char in state_data['lit']:
                for ns in state_data['lit'][char]:
                    next_states.add(ns)

            # AnyChar
            if state_data['any']:
                if char != '\n':
                    for ns in state_data['any']:
                        next_states.add(ns)

            # CharClass
            if state_data['class'] is not None:
                cinfo = state_data['class']
                in_class = False
                for low, high in cinfo['items']:
                    if low <= char <= high:
                        in_class = True
                        break

                if cinfo['negated']:
                    if not in_class:
                        for ns in cinfo['next']:
                            next_states.add(ns)
                else:
                    if in_class:
                        for ns in cinfo['next']:
                            next_states.add(ns)

        return self._epsilon_closure(next_states)

    def search(self, text: str, start: int = 0, whole: bool = False) -> Optional[Tuple[int, int]]:
        # Find leftmost match starting at or after start
        # And longest

        # To be efficient and correct for "linear", 
        # we should ideally track start positions. 
        # But for now, restart from each start point.

        n = len(text)

        for s_pos in range(start, n + 1):
            match_end = self._match_at(text, s_pos, whole)
            if match_end is not None:
                return (s_pos, match_end)

        return None

    def _match_at(self, text: str, start: int, whole: bool) -> Optional[int]:
        # Returns end index (exclusive) of longest match starting at start, or None
        n = len(text)

        current_states = self._epsilon_closure({self.start})

        last_match_end = -1

        # Check empty match
        if any(s in self.accept for s in current_states):
            last_match_end = start

        if whole and last_match_end == start:
            # Empty match is valid for whole only if start == n? 
            # "match(text)" is true when whole text matches.
            # So if text is "", and pattern is "a*", it matches.
            # If text is "b", and pattern is "a*", it does not match whole.

        for i in range(start, n):
            char = text[i]
            current_states = self._step(current_states, char)

            if not current_states:
                break

            if any(s in self.accept for s in current_states):
                last_match_end = i + 1

        # If whole=True, we require the match to end exactly at n
        if whole:
            if last_match_end == n:
                return last_match_end
            else:
                return None
        else:
            if last_match_end != -1:
                return last_match_end
            return None

    def match(self, text: str) -> bool:
        return self.search(text, 0, whole=True) is not None

def compile(pattern: Union[str, Node]) -> NFA:
    if isinstance(pattern, str):
        ast = parse(pattern)
    else:
        ast = pattern

    nfa = NFA()
    nfa.build_from_ast(ast)
    return nfa

def match(pattern: Union[str, Node], text: str) -> bool:
    return compile(pattern).match(text)

def search(pattern: Union[str, Node], text: str, start: int = 0) -> Optional[Tuple[int, int]]:
    return compile(pattern).search(text, start)

def findall(pattern: Union[str, Node], text: str) -> List[str]:
    nfa = compile(pattern)
    matches = []
    pos = 0
    n = len(text)

    while pos <= n:
        match_res = nfa.search(text, pos)
        if match_res is None:
            break

        i, j = match_res
        matches.append(text[i:j])

        if i == j: # Empty match
            pos = j + 1
        else:
            pos = j

    return matches
