    parser.expect_eof()
    return value


class _Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return self.tokens[-1]  # EOF

    def _advance(self):
        if self.pos < len(self.tokens):
            self.pos += 1

    def parse_value(self):
        token = self._current()
        if token.kind == 'STRING':
            self._advance()
            return token.value
        elif token.kind == 'NUMBER':
            self._advance()
            return token.value
        elif token.kind == 'TRUE':
            self._advance()
            return True
        elif token.kind == 'FALSE':
            self._advance()
            return False
        elif token.kind == 'NULL':
            self._advance()
            return None
        elif token.kind == '{':
            return self.parse_object()
        elif token.kind == '[':
            return self.parse_array()
        elif token.kind == 'EOF':
            raise JSONError("unexpected end of input", token.line, token.column)
        else:
            raise JSONError("unexpected token", token.line, token.column)

    def parse_object(self) -> dict:
        token = self._current()
        assert token.kind == '{'
        self._advance()

        result = {}
        first = True

        while True:
            token = self._current()
            if token.kind == '}':
                if not first:
                    # Trailing comma before }
                    raise JSONError("unexpected token", token.line, token.column)
                self._advance()
                return result

            # Parse key
            if token.kind != 'STRING':
                raise JSONError("expected string key", token.line, token.column)
            key = token.value
            self._advance()

            # Expect colon
            token = self._current()
            if token.kind != ':':
                raise JSONError("expected colon", token.line, token.column)
            self._advance()

            # Parse value
            value = self.parse_value()

            # Handle duplicate keys: keep last value, preserve first position
            result[key] = value

            # Expect comma or closing brace
            token = self._current()
            if token.kind == ',':
                first = False
                self._advance()
            elif token.kind == '}':
                self._advance()
                return result
            elif token.kind == 'EOF':
                raise JSONError("unexpected end of input", token.line, token.column)
            else:
                raise JSONError("unexpected token", token.line, token.column)

    def parse_array(self) -> list:
        token = self._current()
        assert token.kind == '['
        self._advance()

        result = []
        first = True

        while True:
            token = self._current()
            if token.kind == ']':
                if not first:
                    # Trailing comma before ]
                    raise JSONError("unexpected token", token.line, token.column)
                self._advance()
                return result

            # Parse value
            value = self.parse_value()
            result.append(value)

            # Expect comma or closing bracket
            token = self._current()
            if token.kind == ',':
                first = False
                self._advance()
            elif token.kind == ']':
                self._advance()
                return result
            elif token.kind == 'EOF':
                raise JSONError("unexpected end of input", token.line, token.column)
            else:
                raise JSONError("unexpected token", token.line, token.column)

    def expect_eof(self):
        token = self._current()
        if token.kind != 'EOF':
            raise JSONError("unexpected token", token.line, token.column)
