def parse_date(text: str) -> datetime.date:
    # Format check: exactly YYYY-MM-DD
    if len(text) != 10 or text[4] != '-' or text[7] != '-':
        raise ValueError("date must be in YYYY-MM-DD format")

    year_part = text[:4]
    month_part = text[5:7]
    day_part = text[8:10]

    if not (year_part.isdigit() and month_part.isdigit() and day_part.isdigit()):
        raise ValueError("date must be in YYYY-MM-DD format")

    try:
        year = int(year_part)
        month = int(month_part)
        day = int(day_part)
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError("date is not a valid calendar date")


def parse_int(text: str) -> int:
    if not text.isdigit():
        raise ValueError("must be a whole number of at least 1")
    val = int(text)
    if val < 1:
        raise ValueError("must be a whole number of at least 1")
    return val


def parse_decimal(text: str) -> Decimal:
    # Valid: digits, optionally followed by . and one or two digits
    if not text:
        raise ValueError("invalid number format")

    parts = text.split('.')
    if len(parts) == 1:
        if not parts[0].isdigit():
            raise ValueError("invalid number format")
    elif len(parts) == 2:
        if not parts[0].isdigit():
            raise ValueError("invalid number format")
        if not parts[1].isdigit():
            raise ValueError("invalid number format")
        if len(parts[1]) > 2:
            raise ValueError("invalid number format")
    else:
        raise ValueError("invalid number format")

    try:
        return Decimal(text)
    except Exception:
        raise ValueError("invalid number format")


def parse_sales(text: str) -> Tuple[List[Sale], List[RowError]]:
    if not text:
        raise IngestError("input has no header row")

    lines = text.splitlines()
    # csv reader on lines might not be ideal if lines contain unescaped newlines inside quotes
    # But spec says "The input is CSV ... first row is a header".
    # Usually CSV parsing handles multi-line records. 
    # However, "line: int" in RowError implies line number.
    # csv module reader works on file-like objects.

    import io
    reader = csv.reader(io.StringIO(text))

    try:
        header_row = next(reader)
    except StopIteration:
        raise IngestError("input has no header row")

    # Normalize header
    header_map = {} # normalized_name -> original_index
    required_fields = ['date', 'region', 'product', 'units', 'unit_price']

    for idx, name in enumerate(header_row):
        norm_name = name.strip().lower()
        header_map[norm_name] = idx

    for req in required_fields:
        if req not in header_map:
            raise IngestError(f"header lacks required column: {req}")

    col_indices = {req: header_map[req] for req in required_fields}
    num_header_cols = len(header_row)

    sales = []
    errors = []

    line_num = 2 # Header is line 1
    for row in reader:
        # Empty lines are skipped by csv.reader? 
        # csv.reader skips empty lines at the end of file sometimes?
        # Or returns []?
        # If the line is completely empty, csv.reader yields []?
        # Actually, csv.reader on '\n' yields []. On '   ' yields ['   ']?
        # "Lines that are completely empty are skipped silently."
        # If row is empty list, it's an empty line.
        if not row:
            line_num += 1
            continue

        # If row has different number of fields from header
        if len(row) != num_header_cols:
            errors.append(RowError(line_num, f"row: number of fields does not match header"))
            line_num += 1
            continue

        try:
            # Get raw values stripped
            vals = {req: row[idx].strip() for req, idx in col_indices.items()}

            # Validate and parse in order: date, region, product, units, unit_price

            # Date
            date_str = vals['date']
            try:
                sale_date = parse_date(date_str)
            except ValueError as e:
                raise ValueError(f"date: {e}")

            # Region
            region_str = vals['region']
            if not region_str:
                raise ValueError("region: must not be empty")

            # Product
            product_str = vals['product']
            if not product_str:
                raise ValueError("product: must not be empty")

            # Units
            units_str = vals['units']
            try:
                units_val = parse_int(units_str)
            except ValueError as e:
                raise ValueError(f"units: {e}")

            # Unit Price
            price_str = vals['unit_price']
            try:
                price_val = parse_decimal(price_str)
            except ValueError as e:
                raise ValueError(f"unit_price: {e}")

            sales.append(Sale(sale_date, region_str, product_str, units_val, price_val))

        except ValueError as e:
            # The first invalid field causes the error
            # We raised ValueError with "field: message" format
            errors.append(RowError(line_num, str(e)))

        line_num += 1

    return sales, errors


def read_sales(path: str) -> Tuple[List[Sale], List[RowError]]:
    with open(path, 'r', encoding='utf-8-sig') as f:
        content = f.read()
    return parse_sales(content)
