import datetime
from decimal import Decimal
from typing import List, Tuple, Dict, Any

FIELDS = ('month', 'region', 'product')


def parse_month(text: str) -> str:
    # YYYY-MM
    if len(text) != 7 or text[4] != '-':
        raise ValueError("invalid month format")
    year_part = text[:4]
    month_part = text[5:7]
    if not year_part.isdigit() or not month_part.isdigit():
        raise ValueError("invalid month format")
    month = int(month_part)
    if month < 1 or month > 12:
        raise ValueError("month out of range")
    return text


def filter_months(sales: List[Any], start: str = None, end: str = None) -> List[Any]:
    if start is not None:
        start = parse_month(start)
    if end is not None:
        end = parse_month(end)

    if start and end and start > end:
        raise ValueError("start month is later than end month")

    result = []
    for sale in sales:
        sale_month = sale.date.strftime("%Y-%m")
        if start is not None and sale_month < start:
            continue
        if end is not None and sale_month > end:
            continue
        result.append(sale)
    return result


class Group:
    def __init__(self, key: Tuple[str, ...], units: int, orders: int, revenue: Decimal):
        object.__setattr__(self, 'key', key)
        object.__setattr__(self, 'units', units)
        object.__setattr__(self, 'orders', orders)
        object.__setattr__(self, 'revenue', revenue)

    def __setattr__(self, key, value):
        raise AttributeError(f"{type(self).__name__} is immutable")

    def __delattr__(self, item):
        raise AttributeError(f"{type(self).__name__} is immutable")

    def __repr__(self):
        return f"Group(key={self.key!r}, units={self.units!r}, orders={self.orders!r}, revenue={self.revenue!r})"

    def __eq__(self, other):
        if not isinstance(other, Group):
            return NotImplemented
        return (self.key == other.key and
                self.units == other.units and
                self.orders == other.orders and
                self.revenue == other.revenue)

    def __hash__(self):
        return hash((self.key, self.units, self.orders, self.revenue))


def aggregate(sales: List[Any], by: Tuple[str, ...]) -> List[Group]:
    if not by:
        raise ValueError("by must contain at least one field")
    if len(set(by)) != len(by):
        raise ValueError("by fields must be unique")
    for f in by:
        if f not in FIELDS:
            raise ValueError(f"unknown field: {f}")

    groups = {}

    for sale in sales:
        key_parts = []
        for f in by:
            if f == 'month':
                key_parts.append(sale.date.strftime("%Y-%m"))
            elif f == 'region':
                key_parts.append(sale.region)
            elif f == 'product':
                key_parts.append(sale.product)
        key = tuple(key_parts)

        if key not in groups:
            groups[key] = {
                'units': 0,
                'orders': 0,
                'revenue': Decimal('0')
            }

        g = groups[key]
        g['units'] += sale.units
        g['orders'] += 1
        g['revenue'] += sale.revenue

    result = []
    for key in sorted(groups.keys()):
        g = groups[key]
        result.append(Group(key, g['units'], g['orders'], g['revenue']))

    return result


class Report:
    def __init__(self, by: Tuple[str, ...], groups: List[Group], total: Group):
        object.__setattr__(self, 'by', by)
        object.__setattr__(self, 'groups', groups)
        object.__setattr__(self, 'total', total)

    def __setattr__(self, key, value):
        raise AttributeError(f"{type(self).__name__} is immutable")

    def __delattr__(self, item):
        raise AttributeError(f"{type(self).__name__} is immutable")

    def __repr__(self):
        return f"Report(by={self.by!r}, groups={self.groups!r}, total={self.total!r})"

    def __eq__(self, other):
        if not isinstance(other, Report):
            return NotImplemented
        return (self.by == other.by and
                self.groups == other.groups and
                self.total == other.total)

    def __hash__(self):
        return hash((self.by, tuple(self.groups), self.total))


def build_report(sales: List[Any], by: Tuple[str, ...]) -> Report:
    groups = aggregate(sales, by)

    total_units = sum(g.units for g in groups)
    total_orders = sum(g.orders for g in groups)
    total_revenue = sum((g.revenue for g in groups), Decimal('0'))

    total_group = Group((), total_units, total_orders, total_revenue)

    return Report(by, groups, total_group)
