import csv
import io
from decimal import Decimal, ROUND_HALF_UP
from typing import List
from .aggregate import Report, Group


def _format_revenue(revenue: Decimal) -> str:
    return str(revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def _format_share(revenue: Decimal, total_revenue: Decimal) -> str:
    if total_revenue == 0:
        return "0.0%"

    # Calculate share as percentage
    share = (revenue / total_revenue) * 100

    # Round half up to 1 decimal place
    share_rounded = share.quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

    return f"{share_rounded}%"


def to_csv(report: Report) -> str:
    output = io.StringIO()
    writer = csv.writer(output, lineterminator='\n')

    # Header
    header = list(report.by) + ['units', 'orders', 'revenue', 'share']
    writer.writerow(header)

    total_revenue = report.total.revenue

    # Data Rows
    for group in report.groups:
        row = list(group.key)
        row.append(str(group.units))
        row.append(str(group.orders))
        row.append(_format_revenue(group.revenue))
        row.append(_format_share(group.revenue, total_revenue))
        writer.writerow(row)

    # Total Row
    total_key = ['TOTAL'] + [''] * (len(report.by) - 1)
    total_row = total_key
    total_row.append(str(report.total.units))
    total_row.append(str(report.total.orders))
    total_row.append(_format_revenue(report.total.revenue))
    total_row.append(_format_share(report.total.revenue, total_revenue))
    writer.writerow(total_row)

    return output.getvalue()


def to_markdown(report: Report) -> str:
    lines = []

    # Header
    header_cells = list(report.by) + ['units', 'orders', 'revenue', 'share']
    # Escape | in cells? Usually not in header unless field name has it. 
    # Spec: "A | inside a cell is written as \|"
    header_cells_escaped = [cell.replace('|', '\\|') for cell in header_cells]
    header_line = "| " + " | ".join(header_cells_escaped) + " |"
    lines.append(header_line)

    # Alignment line
    align_cells = []
    for _ in report.by:
        align_cells.append('---')
    for _ in range(4): # units, orders, revenue, share
        align_cells.append('---:')
    align_line = "| " + " | ".join(align_cells) + " |"
    lines.append(align_line)

    total_revenue = report.total.revenue

    # Data Rows
    for group in report.groups:
        row_cells = list(group.key)
        row_cells.append(str(group.units))
        row_cells.append(str(group.orders))
        row_cells.append(_format_revenue(group.revenue))
        row_cells.append(_format_share(group.revenue, total_revenue))

        row_cells_escaped = [cell.replace('|', '\\|') for cell in row_cells]
        line = "| " + " | ".join(row_cells_escaped) + " |"
        lines.append(line)

    # Total Row
    total_cells = ['TOTAL'] + [''] * (len(report.by) - 1)
    total_cells.append(str(report.total.units))
    total_cells.append(str(report.total.orders))
    total_cells.append(_format_revenue(report.total.revenue))
    total_cells.append(_format_share(report.total.revenue, total_revenue))

    total_cells_escaped = [cell.replace('|', '\\|') for cell in total_cells]
    total_line = "| " + " | ".join(total_cells_escaped) + " |"
    lines.append(total_line)

    return "\n".join(lines) + "\n"
