import re

_VERSION_RE = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$")


class Version:
    def __init__(self, text):
        if not isinstance(text, str):
            raise ValueError("version must be a string")
        m = _VERSION_RE.match(text)
        if not m:
            raise ValueError(f"invalid version: {text!r}")
        self.major = int(m.group(1))
        self.minor = int(m.group(2))
        self.patch = int(m.group(3))

    def _key(self):
        return (self.major, self.minor, self.patch)

    def __hash__(self):
        return hash(self._key())

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._key() == other._key()
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._key() < other._key()
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, Version):
            return self._key() <= other._key()
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, Version):
            return self._key() > other._key()
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, Version):
            return self._key() >= other._key()
        return NotImplemented

    def __repr__(self):
        return f"Version({str(self)!r})"

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"


class Range:
    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError("range spec must be a string")
        self._parts = []
        self._texts = []
        for part in spec.split(","):
            text = part.strip()
            if text == "":
                raise ValueError("empty constraint")
            preds = self._parse_constraint(text)
            self._parts.append(preds)
            self._texts.append(text)

    @staticmethod
    def _split_operator(part):
        for op in ("^", "~", "==", "!=", ">=", "<=", ">", "<"):
            if part.startswith(op):
                return op, part[len(op):].strip()
        return "", part.strip()

    @staticmethod
    def _caret_upper(v):
        if v.major != 0:
            return Version(f"{v.major + 1}.0.0")
        if v.minor != 0:
            return Version(f"0.{v.minor + 1}.0")
        return Version(f"0.0.{v.patch + 1}")

    def _parse_constraint(self, text):
        # "*" alone is any.
        if text == "*":
            return [("any", None)]
        op, ver_text = self._split_operator(text)
        if op == "*" and ver_text == "":
            # This shouldn't happen since we checked text == "*" above,
            # but just in case of weird input like " * " which is already stripped.
            return [("any", None)]
        if ver_text == "":
            raise ValueError(f"missing version in constraint: {text!r}")
        v = Version(ver_text)
        if op in ("", "=="):
            return [("eq", v)]
        if op == "!=":
            return [("ne", v)]
        if op == ">":
            return [("gt", v)]
        if op == ">=":
            return [("ge", v)]
        if op == "<":
            return [("lt", v)]
        if op == "<=":
            return [("le", v)]
        if op == "^":
            return [("ge", v), ("lt", self._caret_upper(v))]
        if op == "~":
            return [("ge", v), ("lt", Version(f"{v.major}.{v.minor + 1}.0"))]
        raise ValueError(f"unknown operator: {text!r}")

    def contains(self, v):
        for preds in self._parts:
            for op, ver in preds:
                if op == "any":
                    continue
                if op == "eq" and v != ver:
                    return False
                if op == "ne" and v == ver:
                    return False
                if op == "gt" and not (v > ver):
                    return False
                if op == "ge" and not (v >= ver):
                    return False
                if op == "lt" and not (v < ver):
                    return False
                if op == "le" and not (v <= ver):
                    return False
        return True

    def __contains__(self, v):
        return self.contains(v)

    def __str__(self):
        return ",".join(self._texts)

    def __repr__(self):
        return f"Range({str(self)!r})"
