    root_ranges = {}
    for name, spec in requirements.items():
        root_ranges[name] = Range(spec)

    # Order of packages to resolve. Initially root requirements sorted alphabetically.
    order = sorted(requirements.keys())

    # List of (name, Version) selected in order
    selected = []

    # Store the first failure encountered
    first_failure = None

    def build_explanation(pkg, constraints, selected_map):
        lines = [f"cannot resolve {pkg}"]
        for requirer, rng in constraints:
            lines.append(f"  {requirer} requires {pkg} {rng}")

        versions = index.versions(pkg)
        if not versions:
            lines.append(f"  no versions of {pkg} are known")
            return lines

        for v in versions:
            # Check if excluded by any constraint
            if not all(rng.contains(v) for _, rng in constraints):
                lines.append(f"  {pkg} {v} is excluded by the constraints")
            else:
                # Find first conflicting dependency in alphabetical order
                reqs = index.requirements(pkg, v)
                conflict_found = False
                for dep_name in sorted(reqs.keys()):
                    dep_rng = reqs[dep_name]
                    if dep_name in selected_map:
                        selected_ver = selected_map[dep_name]
                        if not dep_rng.contains(selected_ver):
                            lines.append(
                                f"  {pkg} {v} requires {dep_name} {dep_rng}, "
                                f"but {dep_name} {selected_ver} is selected"
                            )
                            conflict_found = True
                            break

                # If no conflict with selected packages, this version was technically
                # "acceptable" locally but led to failure deeper in the search.
                # According to the spec, we only explain the FIRST step that found
                # NO acceptable candidate. Thus, if we are building explanation here,
                # it implies this step had no acceptable candidates.
                # If a version was acceptable locally, it would have been tried.
                # If it failed deeper, the "first failure" would be the deeper step.
                # So at the "first failure" step, every version must be rejected
                # by constraints or immediate conflicts with selected deps.
                # However, to be robust against edge cases or spec interpretation nuances:
                if not conflict_found:
                    # This case implies the version was acceptable but the failure
                    # is attributed to this step because deeper failures were not
                    # recorded as "first" (perhaps because deeper steps found
                    # acceptable candidates).
                    # But the spec says: "first step that found no acceptable candidate".
                    # If this version was acceptable, this step DID find an acceptable candidate.
                    # So this line should ideally not be reached for the *first* failure.
                    # If reached, it suggests the definition of "first failure" might
                    # include steps where candidates exist but all lead to failure.
                    # The spec format provided doesn't cover this case explicitly.
                    # We'll assume it doesn't happen for the *first* failure step
                    # in the DFS order, so we don't add a line or add a generic one.
                    # Given the example and strict DFS definition, we expect every
                    # version listed here to be rejected.
                    pass

        return lines

    def step():
        nonlocal first_failure

        # Find next package to resolve
        selected_names = {n for n, _ in selected}
        pkg = None
        for name in order:
            if name not in selected_names:
                pkg = name
                break

        if pkg is None:
            return True

        # Gather constraints on pkg
        constraints = []
        if pkg in root_ranges:
            constraints.append(("<root>", root_ranges[pkg]))

        for sname, sver in selected:
            reqs = index.requirements(sname, sver)
            if pkg in reqs:
                constraints.append((f"{sname} {sver}", reqs[pkg]))

        selected_map = {n: v for n, v in selected}
        candidates = index.versions(pkg)

        step_found_acceptable = False

        for cand in candidates:
            # Check acceptability
            ok = all(rng.contains(cand) for _, rng in constraints)

            if ok:
                # Check dependencies against already selected packages
                cand_reqs = index.requirements(pkg, cand)
                for dep_name, dep_rng in cand_reqs.items():
                    if dep_name in selected_map:
                        if not dep_rng.contains(selected_map[dep_name]):
                            ok = False
                            break

            if not ok:
                continue

            step_found_acceptable = True

            # Select it
            selected.append((pkg, cand))
            cand_reqs = index.requirements(pkg, cand)

            # Append new dependency names to order
            existing_names = set(order)
            added_names = sorted(set(cand_reqs.keys()) - existing_names)
            order.extend(added_names)

            if step():
                return True

            # Undo
            for n in added_names:
                order.remove(n)
            selected.pop()

        # No candidate led to success
        if not step_found_acceptable:
            explanation_lines = build_explanation(pkg, constraints, selected_map)
            if first_failure is None:
                first_failure = (pkg, explanation_lines)

        return False

    if step():
        return {n: v for n, v in selected}

    if first_failure is None:
        # Should not happen if step() returned False and found nothing?
        # If step() returns False, it either found no acceptable candidates (recorded)
        # or found acceptable candidates that failed deeper (deeper failure recorded).
        # If no failure recorded, it's an unexpected state.
        raise ResolutionError("unknown", "failed to resolve")

    pkg, lines = first_failure
    raise ResolutionError(pkg, "\n".join(lines))
