from typing import Optional, NamedTuple


class ParseError(ValueError):
    pass


class Command(NamedTuple):
    verb: str
    arg: Optional[str]


_ARTICLES = {'the', 'a', 'an'}

_DIRECTION_MAP = {}
for d in ('north', 'south', 'east', 'west', 'up', 'down'):
    _DIRECTION_MAP[d] = d
    _DIRECTION_MAP[d[0]] = d


def parse(line: str) -> Command:
    if not line.strip():
        raise ParseError("Say something.")

    words = line.lower().split()
    if not words:
        raise ParseError("Say something.")

    first_word = words[0]

    # Handle directions directly as commands
    if first_word in _DIRECTION_MAP:
        if len(words) > 1:
            raise ParseError("I don't understand that.")
        direction = _DIRECTION_MAP[first_word]
        return Command('go', direction)

    # Handle specific verbs
    if first_word in ('go',):
        if len(words) == 1:
            raise ParseError("Go where?")
        # Remove articles from the rest
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Go where?")

        # Check if the rest forms a single direction
        if len(rest) == 1 and rest[0] in _DIRECTION_MAP:
            return Command('go', _DIRECTION_MAP[rest[0]])
        else:
            # "WORDS" is not a direction.
            # The spec says: go followed by something that is not a direction
            # Error message: "WORDS" is not a direction. (the rest of the line, as lower-cased and joined)
            # Wait, the spec says: `go` followed by something that is not a direction
            # And the error message uses "WORDS" which implies the joined rest.
            # But does it remove articles before checking? 
            # Example: `go to north` -> if "to" is not a direction?
            # Let's look at the input `go DIR`.
            # If I type `go north`, rest is `['north']`. It maps to direction.
            # If I type `go foo`, rest is `['foo']`. "foo" is not a direction.
            # If I type `go the north`, rest is `['north']`. It maps to direction.
            # If I type `go to north`, rest is `['to', 'north']`. 
            # Joined is "to north". "to north" is not a direction.
            # The error message says `"WORDS" is not a direction.` where WORDS is the rest joined.
            # Does "WORDS" include articles? The spec says "the rest of the line, as lower-cased and joined".
            # But earlier it said "removes every the, a and an after the first word".
            # The parse function description: "removes every `the`, `a` and `an` after the first word, and returns a `Command`; `arg` is the remaining words joined".
            # So for `go`, we strip articles. If the remaining words don't form a valid direction, we error.
            # The error message shows the *rest of the line* joined. Does this mean the original words or the filtered words?
            # "the rest of the line, as lower-cased and joined". This usually implies the original words after the verb.
            # However, since articles are removed to form the arg, let's assume the check is on the filtered words.
            # If filtered words exist but don't match a direction, we use the joined filtered words for the error?
            # Or the joined original words?
            # Let's look at the error message format: `"WORDS" is not a direction.`
            # If input is `go to north`, articles removed: `to` is not an article. So rest is `to north`.
            # "to north" is not a direction.
            # If input is `go the north`, articles removed: rest is `north`. `north` is a direction. Success.
            # If input is `go foo bar`, rest is `foo bar`. "foo bar" is not a direction.
            # It seems safe to use the filtered words joined for the error message, as they represent the semantic argument.
            joined = ' '.join(rest)
            raise ParseError(f'"{joined}" is not a direction.')

    elif first_word in ('take', 'get'):
        if len(words) == 1:
            raise ParseError("Take what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Take what?")
        arg = ' '.join(rest)
        return Command('take', arg)

    elif first_word == 'drop':
        if len(words) == 1:
            raise ParseError("Drop what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Drop what?")
        arg = ' '.join(rest)
        return Command('drop', arg)

    elif first_word in ('look', 'l'):
        if len(words) == 1:
            return Command('look', None)
        # Check for "look at X"
        if words[1] == 'at':
            if len(words) == 2:
                raise ParseError("Examine what?")
            rest = [w for w in words[2:] if w not in _ARTICLES]
        else:
            rest = [w for w in words[1:] if w not in _ARTICLES]

        if not rest:
            raise ParseError("Examine what?")
        arg = ' '.join(rest)
        return Command('look', arg)

    elif first_word in ('examine', 'x'):
        if len(words) == 1:
            raise ParseError("Examine what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Examine what?")
        arg = ' '.join(rest)
        return Command('look', arg)

    elif first_word in ('inventory', 'inv', 'i'):
        if len(words) > 1:
            raise ParseError("I don't understand that.")
        return Command('inventory', None)

    else:
        raise ParseError(f'I don\'t know the word "{first_word}".')
