import json
import copy
from typing import Dict, List, Optional

from .world import World, Room, Item
from .parser import parse, ParseError, Command


class SaveError(ValueError):
    pass


class Game:
    def __init__(self, world: World):
        self._world = world
        self._current_room_id: str = world.start
        # items_in_room: dict room_id -> list of item_ids
        self._items_in_room: Dict[str, List[str]] = {}
        # Initialize items from world definition
        for room_id, room in world.rooms.items():
            self._items_in_room[room_id] = list(room.items)

        self._inventory: List[str] = []
        self._moves: int = 0

    @property
    def room(self) -> str:
        return self._current_room_id

    @property
    def inventory(self) -> List[str]:
        return list(self._inventory)

    @property
    def moves(self) -> int:
        return self._moves

    def items_in(self, room_id: str) -> List[str]:
        if room_id not in self._items_in_room:
            return []
        return list(self._items_in_room[room_id])

    def _get_room(self, room_id: str) -> Room:
        return self._world.rooms[room_id]

    def _get_item(self, item_id: str) -> Item:
        return self._world.items[item_id]

    def _match_item(self, item_id: str, query: str) -> bool:
        item = self._get_item(item_id)
        # Matches if query equals item id or item name lower-cased
        return query == item.id or query == item.name.lower()

    def _find_item_in_room(self, room_id: str, query: str) -> Optional[str]:
        items = self._items_in_room.get(room_id, [])
        for item_id in items:
            if self._match_item(item_id, query):
                return item_id
        return None

    def _find_item_in_inventory(self, query: str) -> Optional[str]:
        for item_id in self._inventory:
            if self._match_item(item_id, query):
                return item_id
        return None

    def _look_room_text(self, room_id: str) -> str:
        room = self._get_room(room_id)
        lines = []
        lines.append(room.name)
        lines.append(room.description)

        # Exits
        valid_exits = [d for d in ['north', 'south', 'east', 'west', 'up', 'down'] if d in room.exits]
        if valid_exits:
            exits_str = ', '.join(valid_exits) + '.'
            lines.append(f"Exits: {exits_str}")
        else:
            lines.append("Exits: none.")

        # Items
        items_in_room = self._items_in_room.get(room_id, [])
        if items_in_room:
            item_names = [self._get_item(i).name for i in items_in_room]
            items_str = ', '.join(item_names) + '.'
            lines.append(f"You see: {items_str}")

        return '\n'.join(lines)

    def do(self, line: str) -> str:
        try:
            cmd = parse(line)
        except ParseError as e:
            return str(e)

        if cmd.verb == 'look':
            if cmd.arg is None:
                return self._look_room_text(self._current_room_id)
            else:
                # Look at item
                # Check room first
                item_id = self._find_item_in_room(self._current_room_id, cmd.arg)
                if item_id is None:
                    # Check inventory
                    item_id = self._find_item_in_inventory(cmd.arg)

                if item_id is None:
                    return f"You see no {cmd.arg} here."

                item = self._get_item(item_id)
                return item.description

        elif cmd.verb == 'go':
            target_dir = cmd.arg
            room = self._get_room(self._current_room_id)
            if target_dir in room.exits:
                new_room_id = room.exits[target_dir]
                self._current_room_id = new_room_id
                self._moves += 1
                return self._look_room_text(new_room_id)
            else:
                return "You can't go that way."

        elif cmd.verb == 'take':
            # arg is guaranteed to be a string by parser logic for take
            if cmd.arg is None:
                return "Take what?" # Should be caught by parser, but safety

            # Check if in room
            item_id = self._find_item_in_room(self._current_room_id, cmd.arg)
            if item_id is not None:
                item = self._get_item(item_id)
                if not item.portable:
                    return f"You can't take the {item.name}."

                # Move to inventory
                self._items_in_room[self._current_room_id].remove(item_id)
                self._inventory.append(item_id)
                return f"Taken: {item.name}."

            # Check if already in inventory
            item_id_inv = self._find_item_in_inventory(cmd.arg)
            if item_id_inv is not None:
                item = self._get_item(item_id_inv)
                return f"You already have the {item.name}."

            return f"You see no {cmd.arg} here."

        elif cmd.verb == 'drop':
            if cmd.arg is None:
                return "Drop what?" # Safety

            # Check inventory
            item_id = self._find_item_in_inventory(cmd.arg)
            if item_id is not None:
                item = self._get_item(item_id)
                # Remove from inventory
                self._inventory.remove(item_id)
                # Add to current room
                self._items_in_room[self._current_room_id].append(item_id)
                return f"Dropped: {item.name}."
            else:
                return "You aren't carrying that."

        elif cmd.verb == 'inventory':
            if not self._inventory:
                return "You are carrying nothing."

            item_names = [self._get_item(i).name for i in self._inventory]
            inv_str = ', '.join(item_names) + '.'
            return f"You are carrying: {inv_str}"

        else:
            # Parser should prevent unknown verbs reaching here, but if a new verb is added without handling
            return "I don't understand that."

    def save(self) -> str:
        # Keys: "version", "room", "inventory", "items", "moves"
        # items: object with one key per room of the world
        # Even if room has no items, it maps to [].

        data = {
            "version": 1,
            "room": self._current_room_id,
            "inventory": list(self._inventory),
            "items": {room_id: list(items) for room_id, items in self._items_in_room.items()},
            "moves": self._moves
        }
        return json.dumps(data)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("JSON root is not an object")

        # Check keys
        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            missing = required_keys - set(data.keys())
            raise SaveError(f"Missing keys: {missing}")

        if data["version"] != 1:
            raise SaveError("Unsupported version")

        moves = data["moves"]
        if not isinstance(moves, int) or moves < 0:
            raise SaveError("Moves must be a non-negative integer")

        room_id = data["room"]
        if room_id not in world.rooms:
            raise SaveError(f"Room {room_id} not in world")

        # Validate items structure
        items_data = data["items"]
        if not isinstance(items_data, dict):
            raise SaveError("Items field is not an object")

        # All keys in items_data must be rooms in world
        for key in items_data.keys():
            if key not in world.rooms:
                raise SaveError(f"Item map key {key} is not a room in world")

        # Validate all item IDs exist in world and no duplicates across inventory and rooms
        seen_items = set()

        # Check inventory items
        inv_items = data["inventory"]
        if not isinstance(inv_items, list):
            raise SaveError("Inventory is not a list")
        for item_id in inv_items:
            if item_id not in world.items:
                raise SaveError(f"Item {item_id} not in world")
            if item_id in seen_items:
                raise SaveError(f"Duplicate item {item_id}")
            seen_items.add(item_id)

        # Check room items
        room_items_map = {}
        for room_id, item_ids in items_data.items():
            if not isinstance(item_ids, list):
                raise SaveError(f"Items for room {room_id} is not a list")
            for item_id in item_ids:
                if item_id not in world.items:
                    raise SaveError(f"Item {item_id} not in world")
                if item_id in seen_items:
                    raise SaveError(f"Duplicate item {item_id}")
                seen_items.add(item_id)
            room_items_map[room_id] = list(item_ids)

        # Construct game
        game = cls(world)
        game._current_room_id = room_id
        game._inventory = list(inv_items)
        game._moves = moves

        # Reset internal items state to match save
        # We need to ensure self._items_in_room matches exactly what was saved
        # The constructor initialized it from world.rooms. We must overwrite it completely.
        game._items_in_room = {}
        for room_id in world.rooms:
            game._items_in_room[room_id] = room_items_map.get(room_id, [])

        return game
