    exits: Dict[str, str] = field(default_factory=dict)
    locks: Dict[str, str] = field(default_factory=dict)
    items: Tuple[str, ...] = ()


@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True
    treasure: int = 0


class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self._start = start
        self._rooms = rooms
        self._items = items

    @property
    def start(self) -> str:
        return self._start

    @property
    def rooms(self) -> Dict[str, Room]:
        return dict(self._rooms)

    @property
    def items(self) -> Dict[str, Item]:
        return dict(self._items)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'World':
        # Validate start
        if 'start' not in data:
            raise WorldError("start is missing")
        start = data['start']

        # Validate rooms exist
        rooms_data = data.get('rooms', {})
        if start not in rooms_data:
            raise WorldError(f"start room '{start}' is not a room")

        # Build items
        items_data = data.get('items', {})
        items: Dict[str, Item] = {}
        for item_id, item_info in items_data.items():
            if not isinstance(item_info, dict):
                raise WorldError(f"item '{item_id}' definition is invalid")
            name = item_info.get('name')
            description = item_info.get('description')
            if name is None:
                raise WorldError(f"item '{item_id}' lacks a name")
            if description is None:
                raise WorldError(f"item '{item_id}' lacks a description")
            portable = item_info.get('portable', True)
            treasure = item_info.get('treasure', 0)
            if not isinstance(treasure, int) or isinstance(treasure, bool) or treasure < 0:
                raise WorldError(f"item '{item_id}' has invalid treasure value")
            items[item_id] = Item(
                id=item_id,
                name=name,
                description=description,
                portable=portable,
                treasure=treasure
            )

        # Build rooms
        rooms: Dict[str, Room] = {}
        item_occurrences: Dict[str, int] = {} # Track to detect duplicates

        for room_id, room_info in rooms_data.items():
            if not isinstance(room_info, dict):
                raise WorldError(f"room '{room_id}' definition is invalid")

            name = room_info.get('name')
            description = room_info.get('description')
            if name is None:
                raise WorldError(f"room '{room_id}' lacks a name")
            if description is None:
                raise WorldError(f"room '{room_id}' lacks a description")

            exits_data = room_info.get('exits', {})
            if not isinstance(exits_data, dict):
                raise WorldError(f"room '{room_id}' exits is invalid")

            exits: Dict[str, str] = {}
            locks: Dict[str, str] = {}
            for direction, exit_info in exits_data.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"exit direction '{direction}' is not valid")

                if isinstance(exit_info, dict):
                    # Locked exit
                    if 'to' not in exit_info or 'key' not in exit_info:
                        raise WorldError(f"exit '{direction}' in room '{room_id}' missing 'to' or 'key'")
                    target_room = exit_info['to']
                    key_item = exit_info['key']

                    if target_room not in rooms_data:
                        raise WorldError(f"exit leads to unknown room '{target_room}'")
                    if key_item not in items_data:
                        raise WorldError(f"exit key '{key_item}' is not an item")

                    exits[direction] = target_room
                    locks[direction] = key_item
                else:
                    # Unlocked exit
                    target_room = exit_info
                    if target_room not in rooms_data:
                        raise WorldError(f"exit leads to unknown room '{target_room}'")
                    exits[direction] = target_room

            items_list = room_info.get('items', [])
            if not isinstance(items_list, list):
                raise WorldError(f"room '{room_id}' items is invalid")

            room_items: Tuple[str, ...] = ()
            temp_items: list[str] = []
            for item_id in items_list:
                if item_id not in items_data:
                    raise WorldError(f"room '{room_id}' lists unknown item '{item_id}'")
                if item_id in item_occurrences:
                    raise WorldError(f"item '{item_id}' is listed more than once")
                item_occurrences[item_id] = 1
                temp_items.append(item_id)
            room_items = tuple(temp_items)

            rooms[room_id] = Room(
                id=room_id,
                name=name,
                description=description,
                exits=exits,
                locks=locks,
                items=room_items
            )

        return cls(start, rooms, items)
