from typing import Optional, NamedTuple


class ParseError(ValueError):
    pass


class Command(NamedTuple):
    verb: str
    arg: Optional[str]


_ARTICLES = {'the', 'a', 'an'}

_DIRECTION_MAP = {}
for d in ('north', 'south', 'east', 'west', 'up', 'down'):
    _DIRECTION_MAP[d] = d
    _DIRECTION_MAP[d[0]] = d


def parse(line: str) -> Command:
    if not line.strip():
        raise ParseError("Say something.")

    words = line.lower().split()
    if not words:
        raise ParseError("Say something.")

    first_word = words[0]

    # Handle directions directly as commands
    if first_word in _DIRECTION_MAP:
        if len(words) > 1:
            raise ParseError("I don't understand that.")
        direction = _DIRECTION_MAP[first_word]
        return Command('go', direction)

    # Handle specific verbs
    if first_word in ('go',):
        if len(words) == 1:
            raise ParseError("Go where?")

        # Check if the remaining words form a single valid direction (after removing articles)
        filtered_rest = [w for w in words[1:] if w not in _ARTICLES]

        if len(filtered_rest) == 1 and filtered_rest[0] in _DIRECTION_MAP:
            return Command('go', _DIRECTION_MAP[filtered_rest[0]])
        else:
            # Error message uses "the rest of the line", which implies the original words (lowercased)
            raw_rest = ' '.join(words[1:])
            raise ParseError(f'"{raw_rest}" is not a direction.')

    elif first_word in ('take', 'get'):
        if len(words) == 1:
            raise ParseError("Take what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Take what?")
        arg = ' '.join(rest)
        return Command('take', arg)

    elif first_word == 'drop':
        if len(words) == 1:
            raise ParseError("Drop what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Drop what?")
        arg = ' '.join(rest)
        return Command('drop', arg)

    elif first_word in ('look', 'l'):
        if len(words) == 1:
            return Command('look', None)

        # Check for "look at X"
        if words[1] == 'at':
            if len(words) == 2:
                raise ParseError("Examine what?")
            rest = [w for w in words[2:] if w not in _ARTICLES]
            if not rest:
                raise ParseError("Examine what?")
            arg = ' '.join(rest)
            return Command('look', arg)
        else:
            # "look X"
            rest = [w for w in words[1:] if w not in _ARTICLES]
            if not rest:
                # Input was like "look the", which effectively becomes just "look"
                return Command('look', None)
            arg = ' '.join(rest)
            return Command('look', arg)

    elif first_word in ('examine', 'x'):
        if len(words) == 1:
            raise ParseError("Examine what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Examine what?")
        arg = ' '.join(rest)
        return Command('look', arg)

    elif first_word in ('inventory', 'inv', 'i'):
        if len(words) > 1:
            raise ParseError("I don't understand that.")
        return Command('inventory', None)

    elif first_word == 'use':
        if len(words) == 1:
            raise ParseError("Use what?")
        rest = [w for w in words[1:] if w not in _ARTICLES]
        if not rest:
            raise ParseError("Use what?")
        arg = ' '.join(rest)
        return Command('use', arg)

    elif first_word == 'score':
        if len(words) > 1:
            raise ParseError("I don't understand that.")
        return Command('score', None)

    else:
        raise ParseError(f'I don\'t know the word "{first_word}".')
