import json
from typing import Dict, List, Optional, Set, Tuple

from .world import World, Room, Item, DIRECTIONS
from .parser import parse, ParseError, Command


class SaveError(ValueError):
    pass


class Game:
    def __init__(self, world: World):
        self._world = world
        self._current_room_id: str = world.start
        # items_in_room: dict room_id -> list of item_ids
        self._items_in_room: Dict[str, List[str]] = {}
        # Initialize items from world definition
        for room_id, room in world.rooms.items():
            self._items_in_room[room_id] = list(room.items)

        self._inventory: List[str] = []
        self._moves: int = 0

        # New state
        self._visited: Set[str] = {world.start}
        self._scored: Set[str] = set()
        self._score: int = 0
        # unlocked: set of (room_id, direction)
        self._unlocked: Set[Tuple[str, str]] = set()

    @property
    def room(self) -> str:
        return self._current_room_id

    @property
    def inventory(self) -> List[str]:
        return list(self._inventory)

    @property
    def moves(self) -> int:
        return self._moves

    @property
    def score(self) -> int:
        return self._score

    def items_in(self, room_id: str) -> List[str]:
        if room_id not in self._items_in_room:
            return []
        return list(self._items_in_room[room_id])

    def _get_room(self, room_id: str) -> Room:
        return self._world.rooms[room_id]

    def _get_item(self, item_id: str) -> Item:
        return self._world.items[item_id]

    def _match_item(self, item_id: str, query: str) -> bool:
        item = self._get_item(item_id)
        # Matches if query equals item id or item name lower-cased
        return query == item.id or query == item.name.lower()

    def _find_item_in_room(self, room_id: str, query: str) -> Optional[str]:
        items = self._items_in_room.get(room_id, [])
        for item_id in items:
            if self._match_item(item_id, query):
                return item_id
        return None

    def _find_item_in_inventory(self, query: str) -> Optional[str]:
        for item_id in self._inventory:
            if self._match_item(item_id, query):
                return item_id
        return None

    def _look_room_text(self, room_id: str) -> str:
        room = self._get_room(room_id)
        lines = []
        lines.append(room.name)
        lines.append(room.description)

        # Exits
        valid_exits = []
        for d in DIRECTIONS:
            if d in room.exits:
                if d in room.locks and (room_id, d) not in self._unlocked:
                    valid_exits.append(f"{d} (locked)")
                else:
                    valid_exits.append(d)

        if valid_exits:
            exits_str = ', '.join(valid_exits) + '.'
            lines.append(f"Exits: {exits_str}")
        else:
            lines.append("Exits: none.")

        # Items
        items_in_room = self._items_in_room.get(room_id, [])
        if items_in_room:
            item_names = [self._get_item(i).name for i in items_in_room]
            items_str = ', '.join(item_names) + '.'
            lines.append(f"You see: {items_str}")

        return '\n'.join(lines)

    def _is_exit_locked(self, room_id: str, direction: str) -> bool:
        room = self._get_room(room_id)
        return direction in room.locks and (room_id, direction) not in self._unlocked

    def do(self, line: str) -> str:
        try:
            cmd = parse(line)
        except ParseError as e:
            return str(e)

        if cmd.verb == 'look':
            if cmd.arg is None:
                return self._look_room_text(self._current_room_id)
            else:
                # Look at item
                # Check room first
                item_id = self._find_item_in_room(self._current_room_id, cmd.arg)
                if item_id is None:
                    # Check inventory
                    item_id = self._find_item_in_inventory(cmd.arg)

                if item_id is None:
                    return f"You see no {cmd.arg} here."

                item = self._get_item(item_id)
                return item.description

        elif cmd.verb == 'go':
            target_dir = cmd.arg
            room = self._get_room(self._current_room_id)

            if target_dir not in room.exits:
                return "You can't go that way."

            if self._is_exit_locked(self._current_room_id, target_dir):
                return f"The way {target_dir} is locked."

            new_room_id = room.exits[target_dir]
            self._current_room_id = new_room_id
            self._moves += 1

            if new_room_id not in self._visited:
                self._visited.add(new_room_id)
                self._score += 10

            return self._look_room_text(new_room_id)

        elif cmd.verb == 'take':
            # arg is guaranteed to be a string by parser logic for take
            if cmd.arg is None:
                return "Take what?" # Should be caught by parser, but safety

            # Check if in room
            item_id = self._find_item_in_room(self._current_room_id, cmd.arg)
            if item_id is not None:
                item = self._get_item(item_id)
                if not item.portable:
                    return f"You can't take the {item.name}."

                # Move to inventory
                self._items_in_room[self._current_room_id].remove(item_id)
                self._inventory.append(item_id)

                # Score treasure
                if item.treasure > 0 and item_id not in self._scored:
                    self._score += item.treasure
                    self._scored.add(item_id)

                return f"Taken: {item.name}."

            # Check if already in inventory
            item_id_inv = self._find_item_in_inventory(cmd.arg)
            if item_id_inv is not None:
                item = self._get_item(item_id_inv)
                return f"You already have the {item.name}."

            return f"You see no {cmd.arg} here."

        elif cmd.verb == 'drop':
            if cmd.arg is None:
                return "Drop what?" # Safety

            # Check inventory
            item_id = self._find_item_in_inventory(cmd.arg)
            if item_id is not None:
                item = self._get_item(item_id)
                # Remove from inventory
                self._inventory.remove(item_id)
                # Add to current room
                self._items_in_room[self._current_room_id].append(item_id)
                return f"Dropped: {item.name}."
            else:
                return "You aren't carrying that."

        elif cmd.verb == 'inventory':
            if not self._inventory:
                return "You are carrying nothing."

            item_names = [self._get_item(i).name for i in self._inventory]
            inv_str = ', '.join(item_names) + '.'
            return f"You are carrying: {inv_str}"

        elif cmd.verb == 'use':
            if cmd.arg is None:
                return "Use what?" # Safety

            # Check if in inventory
            item_id = self._find_item_in_inventory(cmd.arg)
            if item_id is None:
                return "You aren't carrying that."

            item = self._get_item(item_id)
            room = self._get_room(self._current_room_id)

            unlocked_dirs = []
            for direction in DIRECTIONS:
                if direction in room.locks:
                    if room.locks[direction] == item_id:
                        if (self._current_room_id, direction) not in self._unlocked:
                            self._unlocked.add((self._current_room_id, direction))
                            unlocked_dirs.append(direction)

            if unlocked_dirs:
                dirs_str = ', '.join(unlocked_dirs) + '.'
                return f"Unlocked: {dirs_str}"
            else:
                return f"Nothing here to use the {item.name} on."

        elif cmd.verb == 'score':
            return f"Your score is {self._score}."

        else:
            # Parser should prevent unknown verbs reaching here, but if a new verb is added without handling
            return "I don't understand that."

    def save(self) -> str:
        # Keys: "version", "room", "inventory", "items", "moves", "unlocked", "visited", "scored", "score"

        unlocked_list = sorted(list(self._unlocked))
        visited_list = sorted(list(self._visited))
        scored_list = sorted(list(self._scored))

        data = {
            "version": 2,
            "room": self._current_room_id,
            "inventory": list(self._inventory),
            "items": {room_id: list(items) for room_id, items in self._items_in_room.items()},
            "moves": self._moves,
            "unlocked": [[r, d] for r, d in unlocked_list],
            "visited": visited_list,
            "scored": scored_list,
            "score": self._score
        }
        return json.dumps(data)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("JSON root is not an object")

        if 'version' not in data:
            raise SaveError("Missing version")

        version = data['version']

        # Common validation
        if version not in (1, 2):
            raise SaveError(f"Unsupported version: {version}")

        required_keys = {"room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            missing = required_keys - set(data.keys())
            raise SaveError(f"Missing keys: {missing}")

        moves = data["moves"]
        if not isinstance(moves, int) or isinstance(moves, bool) or moves < 0:
            raise SaveError("Moves must be a non-negative integer")

        room_id = data["room"]
        if room_id not in world.rooms:
            raise SaveError(f"Room {room_id} not in world")

        # Validate items structure
        items_data = data["items"]
        if not isinstance(items_data, dict):
            raise SaveError("Items field is not an object")

        # All keys in items_data must be rooms in world
        for key in items_data.keys():
            if key not in world.rooms:
                raise SaveError(f"Item map key {key} is not a room in world")

        # Validate all item IDs exist in world and no duplicates across inventory and rooms
        seen_items = set()

        # Check inventory items
        inv_items = data["inventory"]
        if not isinstance(inv_items, list):
            raise SaveError("Inventory is not a list")
        for item_id in inv_items:
            if item_id not in world.items:
                raise SaveError(f"Item {item_id} not in world")
            if item_id in seen_items:
                raise SaveError(f"Duplicate item {item_id}")
            seen_items.add(item_id)

        # Check room items
        room_items_map = {}
        for r_id, item_ids in items_data.items():
            if not isinstance(item_ids, list):
                raise SaveError(f"Items for room {r_id} is not a list")
            for item_id in item_ids:
                if item_id not in world.items:
                    raise SaveError(f"Item {item_id} not in world")
                if item_id in seen_items:
                    raise SaveError(f"Duplicate item {item_id}")
                seen_items.add(item_id)
            room_items_map[r_id] = list(item_ids)

        # Construct game
        game = cls(world)
        game._current_room_id = room_id
        game._inventory = list(inv_items)
        game._moves = moves

        # Reset internal items state to match save
        game._items_in_room = {}
        for r_id in world.rooms:
            game._items_in_room[r_id] = room_items_map.get(r_id, [])

        if version == 2:
            required_v2_keys = {"unlocked", "visited", "scored", "score"}
            if not required_v2_keys.issubset(data.keys()):
                missing = required_v2_keys - set(data.keys())
                raise SaveError(f"Missing keys: {missing}")

            # Validate unlocked
            unlocked_data = data["unlocked"]
            if not isinstance(unlocked_data, list):
                raise SaveError("Unlocked is not a list")

            game._unlocked = set()
            for pair in unlocked_data:
                if not isinstance(pair, list) or len(pair) != 2:
                    raise SaveError("Invalid unlocked pair format")
                r_id, dir_name = pair

                if r_id not in world.rooms:
                    raise SaveError(f"Unlocked room {r_id} not in world")

                room = world.rooms[r_id]
                if dir_name not in room.locks:
                    raise SaveError(f"Unlocking non-locked exit {dir_name} in room {r_id}")

                # Check if already added (duplicate in list? spec says sorted, but duplicates might break logic if we just use set)
                # Spec says "sorted list", implying no duplicates usually, but set handles uniqueness.
                # If a duplicate exists in the JSON, it's technically valid data representing same state.
                if (r_id, dir_name) in game._unlocked:
                     # If it's already there, fine.
                     pass
                else:
                    game._unlocked.add((r_id, dir_name))

            # Validate visited
            visited_data = data["visited"]
            if not isinstance(visited_data, list):
                raise SaveError("Visited is not a list")

            game._visited = set()
            for v_id in visited_data:
                if v_id not in world.rooms:
                    raise SaveError(f"Visited room {v_id} not in world")
                game._visited.add(v_id)

            # Ensure current room is in visited? 
            # The state of the game implies current room is visited.
            # If save is consistent, it should be there. If not, maybe add it? 
            # Spec doesn't explicitly say load fixes inconsistencies, but logical.
            # Let's assume saved state is consistent.

            # Validate scored
            scored_data = data["scored"]
            if not isinstance(scored_data, list):
                raise SaveError("Scored is not a list")

            game._scored = set()
            for s_id in scored_data:
                if s_id not in world.items:
                    raise SaveError(f"Scored item {s_id} not in world")
                game._scored.add(s_id)

            # Validate score
            score_val = data["score"]
            if not isinstance(score_val, int) or isinstance(score_val, bool) or score_val < 0:
                raise SaveError("Score must be a non-negative integer")

            game._score = score_val

        elif version == 1:
            # Version 1 logic:
            # every lock still locked -> game._unlocked remains empty set (init)
            # the start room and the saved current room as its visited rooms
            game._visited = {world.start, room_id}
            # nothing scored
            game._scored = set()
            # score of 0
            game._score = 0

        return game
