def main(argv=None) -> int:
    class ArgParser(argparse.ArgumentParser):
        def error(self, message):
            sys.stderr.write(f'error: {message}\n')
            sys.exit(2)

    parser = ArgParser(prog='logagg')
    parser.add_argument('files', nargs='+', help='Files to read')
    parser.add_argument('--format', default='auto', choices=['auto', 'clf', 'jsonl'])
    parser.add_argument('--since')
    parser.add_argument('--until')
    parser.add_argument('--status')
    parser.add_argument('--top', type=int, default=3)
    parser.add_argument('--json', action='store_true')

    try:
        args = parser.parse_args(argv)
    except SystemExit:
        # Help was requested or error in args (already handled by parser.error)
        raise

    # Validate top
    if args.top < 0:
        sys.stderr.write("error: --top must be non-negative\n")
        return 2

    # Parse times
    since = None
    until = None
    try:
        if args.since:
            since = parse_time_arg(args.since, '--since')
        if args.until:
