    except ValueError as e:
        sys.stderr.write(f"error: {e}\n")
        return 2

    # Validate status
    if args.status:
        try:
            # We rely on filter_records to validate status strictly, 
            # but we need to catch it here to return code 2.
            # However, filter_records is called later on empty/full list.
            # Better to validate here using same logic or call filter_records with empty list to test validation?
            # No, just duplicate simple check or rely on later catch.
            # The spec says "a bad --status ... prints ... exits with code 2".
            # filter_records raises ValueError.
            # We can catch ValueError from filter_records.
            pass
        except ValueError as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    all_records = []
    total_bad = 0

    for filename in args.files:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                lines = f.readlines()
                records, bad = read_records(lines, args.format)
                all_records.extend(records)
                total_bad += len(bad)
        except FileNotFoundError:
            sys.stderr.write(f"error: file not found: {filename}\n")
            return 2
        except IOError:
            sys.stderr.write(f"error: unreadable file: {filename}\n")
            return 2
        except Exception as e:
            sys.stderr.write(f"error: {e}\n")
            return 2

    # Filter
    try:
        filtered = filter_records(all_records, since, until, args.status)
    except ValueError as e:
        sys.stderr.write(f"error: {e}\n")
        return 2

    # Summarize
    try:
        summary = summarize(filtered, args.top)
    except ValueError as e:
        sys.stderr.write(f"error: {e}\n")
        return 2

    if args.json:
        output = dict(summary)
        output['bad_lines'] = total_bad
        print(json.dumps(output, indent=2))
    else:
        print(f"requests: {summary['requests']}")
        print(f"bad lines: {total_bad}")
        print(f"bytes: {summary['bytes']}")

        classes = summary['classes']
        # classes dict keys order is preserved in Python 3.7+ if inserted in order
        # In summarize, we inserted 1xx..5xx in order.
        class_str = " ".join([f"{k}={v}" for k, v in classes.items()])
        print(f"status: {class_str}")

        lat = summary['latency_ms']
        if lat['count'] > 0:
            print(f"latency: p50={lat['p50']:.1f} ms p95={lat['p95']:.1f} ms max={lat['max']:.1f} ms")
        else:
            print("latency: n/a")

        print("top paths:")
        if not summary['top_paths']:
            print("  none")
        else:
            for path, count in summary['top_paths']:
                print(f"  {count} {path}")

    return 0

if __name__ == '__main__':
    sys.exit(main())
