import fnmatch
from .paths import normalize, join, split, is_within

class FSError(Exception):
    """Base error for VFS operations. str(error) is the path."""
    def __init__(self, path):
        self.path = path
        super().__init__(str(path))

class NotFound(FSError):
    pass

class AlreadyExists(FSError):
    pass

class NotADirectory(FSError):
    pass

class IsADirectory(FSError):
    pass

class InvalidOperation(FSError):
    pass

class FileSystem:
    def __init__(self):
        self._root = '/'
        self._cwd = '/'
        # Tree structure: dictionary mapping path -> type
        # Directories are implicit or explicit? 
        # We store files explicitly. Directories exist if they have contents or were explicitly created.
        # To support 'mkdir', we need to track directories.
        # Let's store a set of directory paths and a dictionary of file contents.
        # Directories: set of normalized absolute paths. Root '/' is always present.
        # Files: dict of normalized absolute path -> text

        self._dirs = set()
        self._files = {} # path -> text

    def _ensure_parents(self, path):
        """Ensures all parent directories of 'path' exist."""
        p = path
        while p != '/':
            parent = normalize(p + '/../')
            if parent not in self._dirs:
                self._dirs.add(parent)
            p = parent
        # Root is always assumed to exist in _dirs initialization?
        if '/' not in self._dirs:
             self._dirs.add('/')

    def _check_path_through_file(self, path):
        """
        Checks if any ancestor of `path` (excluding path itself) is a file.
        If so, raises NotADirectory(path).
        """
        p = path
        while p != '/':
            parent = normalize(p + '/../')
            if parent in self._files:
                raise NotADirectory(path)
            p = parent
        # Root is never a file, so loop terminates safely

    def _ensure_dirs_exist(self):
        """Ensures root is always present"""
        if '/' not in self._dirs:
             self._dirs.add('/')

    def pwd(self):
        return self._cwd

    def _normalize(self, path):
        if not path:
            raise ValueError("empty path")
        return normalize(path, self._cwd)

    def cd(self, path):
        norm_path = self._normalize(path)

        # Check existence
        if not self._exists(norm_path):
            raise NotFound(norm_path)

        if not self._is_dir(norm_path):
            raise NotADirectory(norm_path)

        self._cwd = norm_path

    def _exists(self, path):
        return path in self._dirs or path in self._files

    def _is_dir(self, path):
        return path in self._dirs

    def _is_file(self, path):
        return path in self._files

    def mkdir(self, path, parents=False):
        norm_path = self._normalize(path)

        # Check if it already exists
        if self._exists(norm_path):
            if self._is_file(norm_path):
                raise AlreadyExists(norm_path)
            # It's a directory
            if not parents:
                raise AlreadyExists(norm_path)
            else:
                return # No error if parents=True and it is a dir

        # Check if any ancestor is a file
        self._check_path_through_file(norm_path)

        # Check parent existence if not parents
        parent_path = normalize(norm_path + '/../')
        if not parents:
            if not self._exists(parent_path):
                raise NotFound(norm_path)

        # Create parents if needed
        if parents:
            self._ensure_parents(norm_path)

        # Create the directory
        self._dirs.add(norm_path)

    def write(self, path, text, append=False):
        norm_path = self._normalize(path)

        # Check if target is a directory
        if self._is_dir(norm_path):
            raise IsADirectory(norm_path)

        # Check if any ancestor is a file (general rule: NotADirectory)
        # This must be checked before checking parent existence to ensure
        # "passes through file" takes precedence over "parent missing"
        self._check_path_through_file(norm_path)

        # Check parent
        parent_path = normalize(norm_path + '/../')
        if not self._exists(parent_path):
            raise NotFound(norm_path)

        if append and norm_path in self._files:
            self._files[norm_path] += text
        else:
            self._files[norm_path] = text

    def read(self, path):
        norm_path = self._normalize(path)

        if not self._exists(norm_path):
            raise NotFound(norm_path)

        if self._is_dir(norm_path):
            raise IsADirectory(norm_path)

        return self._files[norm_path]

    def ls(self, path='.'):
        norm_path = self._normalize(path)

        if not self._exists(norm_path):
            raise NotFound(norm_path)

        if self._is_file(norm_path):
            _, name = split(norm_path)
            return [name]

        # It's a directory
        # Find all children
        children = set()
        prefix = norm_path + '/' if norm_path != '/' else '/'

        # Check files
        for f_path in self._files:
            if f_path.startswith(prefix):
                rest = f_path[len(prefix):]
                if '/' not in rest and rest:
                    children.add(rest)

        # Check dirs (direct children only)
        for d_path in self._dirs:
            if d_path.startswith(prefix):
                rest = d_path[len(prefix):]
                if '/' not in rest and rest:
                    children.add(rest + '/')

        return sorted(list(children))

    def rm(self, path, recursive=False):
        norm_path = self._normalize(path)

        if not self._exists(norm_path):
            raise NotFound(norm_path)

        # Check if it's root, cwd, or ancestor of cwd
        if norm_path == '/' or norm_path == self._cwd or is_within(self._cwd, norm_path):
            raise InvalidOperation(norm_path)

        if self._is_dir(norm_path):
            if not recursive:
                raise IsADirectory(norm_path)

            # Remove directory recursively
            # Find all contents
            prefix = norm_path + '/' if norm_path != '/' else '/'

            # Collect paths to delete
            to_delete_files = [p for p in self._files if p.startswith(prefix) or p == norm_path]
            to_delete_dirs = [p for p in self._dirs if p.startswith(prefix) or p == norm_path]

            # Delete files
            for p in to_delete_files:
                if p in self._files:
                    del self._files[p]

            # Delete dirs (deepest first to avoid issues if we cared, but set removal is fine)
            for p in to_delete_dirs:
                if p in self._dirs:
                    self._dirs.remove(p)
        else:
            # It's a file
            del self._files[norm_path]

    def mv(self, src, dst):
        norm_src = self._normalize(src)
        norm_dst = self._normalize(dst)

        # 1. NotFound(src)
        if not self._exists(norm_src):
            raise NotFound(norm_src)

        # 2. InvalidOperation(src) if src is /, cwd, or ancestor of cwd
        if norm_src == '/' or norm_src == self._cwd or is_within(self._cwd, norm_src):
            raise InvalidOperation(norm_src)

        # Determine target
        # if dst is an existing directory, target is dst/NAME
        # else target is dst

        target = norm_dst
        if self._is_dir(norm_dst):
            _, name = split(norm_src)
            target = join(norm_dst, name)

        # Check passes through file for target? 
        # The spec doesn't explicitly say mv checks target ancestry for NotADirectory in the table,
        # but the general rule applies to "operation's path". Here, the operation involves the target.
        # Usually mv fails if target parent is a file.
        # We must check this before checking if target parent exists, to match the spec's priority
        # if the general rule is interpreted strictly.
        self._check_path_through_file(target)

        # 3. InvalidOperation(src) if target is src itself or inside it
        if target == norm_src or is_within(target, norm_src):
            raise InvalidOperation(norm_src) # Error with src's path

        # 4. AlreadyExists(target) if target exists
        if self._exists(target):
            raise AlreadyExists(target)

        # 5. NotFound(dst) if the target's parent is missing
        target_parent = normalize(target + '/../')
        if not self._exists(target_parent):
             raise NotFound(target) 

        # Move logic
        if self._is_dir(norm_src):
            # Move directory
            # Collect all paths under src
            prefix = norm_src + '/' if norm_src != '/' else '/'

            files_to_move = [(p, self._files[p]) for p in list(self._files.keys()) if p.startswith(prefix)]
            dirs_to_move = [p for p in list(self._dirs) if p.startswith(prefix) or p == norm_src]

            # Update CWD if it is inside src
            if is_within(self._cwd, norm_src):
                # Replace prefix of cwd with target
                # CWD is norm_src + suffix. New CWD is target + suffix.
                suffix = self._cwd[len(norm_src):]
                self._cwd = target + suffix

            # Move files
            for old_path, content in files_to_move:
                new_path = target + old_path[len(norm_src):]
                self._files[new_path] = content
                del self._files[old_path]

            # Move dirs
            for old_path in dirs_to_move:
                new_path = target + old_path[len(norm_src):]
                self._dirs.add(new_path)
                if old_path in self._dirs:
                    self._dirs.remove(old_path)

        else:
            # Move file
            content = self._files[norm_src]
            # Ensure target parent exists (checked above)
            self._files[target] = content
            del self._files[norm_src]

    def find(self, path='.', pattern='*'):
        norm_path = self._normalize(path)

        if not self._exists(norm_path):
            raise NotFound(norm_path)

        results = []

        if self._is_file(norm_path):
            _, name = split(norm_path)
            if fnmatch.fnmatchcase(name, pattern):
                results.append(norm_path)
            return results

        # Directory search
        # Everything below path (not path itself)
        prefix = norm_path + '/' if norm_path != '/' else '/'

        # Search files
        for p in self._files:
            if p.startswith(prefix):
                _, name = split(p)
                if fnmatch.fnmatchcase(name, pattern):
                    results.append(p)

        # Search dirs
        for p in self._dirs:
            if p.startswith(prefix) and p != norm_path:
                _, name = split(p)
                if fnmatch.fnmatchcase(name, pattern):
                    results.append(p)

        return sorted(results)

    def exists(self, path):
        norm_path = self._normalize(path)
        return self._exists(norm_path)

    def is_dir(self, path):
        norm_path = self._normalize(path)
        return self._is_dir(norm_path)
