import sys
import shlex
from .fs import FileSystem, FSError
from .paths import normalize, join, split, is_within

def _run_script(script, shell):
    """
    Runs the script in the shell.
    Returns (output, status).
    """
    output = ""
    lines = script.splitlines()

    for i, line in enumerate(lines, start=1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        try:
            words = shlex.split(line)
        except ValueError:
            # Quoting error
            # "wrong arguments... quoting error... usage"
            # Command is first word? shlex failed, so we can't get words easily?
            # Spec: "quoting error ... add line N: COMMAND: usage"
            # We need COMMAND. If shlex fails, we can try to get the first word naively?
            # shlex.split raises ValueError. 
            # Let's assume the command is the first token up to space?
            parts = line.split()
            cmd = parts[0] if parts else ""
            output += f"line {i}: {cmd}: usage\n"
            return output, 2

        if not words:
            continue

        cmd = words[0]
        args = words[1:]

        # Recognize flags for mkdir and rm
        if cmd in ('mkdir', 'rm'):
            if args and args[0].startswith('-'):
                flag = args[0]
                args = args[1:]

                if flag == '-p' and cmd == 'mkdir':
                    try:
                        if not args:
                            raise ValueError("usage")
                        for p in args:
                            shell.fs.mkdir(p, parents=True)
                    except FSError as e:
                        output += f"line {i}: {cmd}: {type(e).__name__}: {e.path}\n"
                        return output, 1
                    except Exception:
                        output += f"line {i}: {cmd}: usage\n"
                        return output, 2
                    continue
                elif flag == '-r' and cmd == 'rm':
                    try:
                        if not args:
                            raise ValueError("usage")
                        for p in args:
                            shell.fs.rm(p, recursive=True)
                    except FSError as e:
                        output += f"line {i}: {cmd}: {type(e).__name__}: {e.path}\n"
                        return output, 1
                    except Exception:
                        output += f"line {i}: {cmd}: usage\n"
                        return output, 2
                    continue
                else:
                    # Unknown flag or flag for wrong command
                    # "an argument starting with - other than the recognised flags... usage"
                    output += f"line {i}: {cmd}: usage\n"
                    return output, 2

        try:
            if cmd == 'pwd':
                if args:
                    raise ValueError("usage")
                output += shell.fs.pwd() + '\n'

            elif cmd == 'cd':
                if len(args) != 1:
                    raise ValueError("usage")
                shell.fs.cd(args[0])

            elif cmd == 'mkdir':
                if len(args) == 0:
                    raise ValueError("usage")
                for p in args:
                    shell.fs.mkdir(p, parents=False)

            elif cmd == 'ls':
                if len(args) > 1:
                    raise ValueError("usage")
                path = args[0] if args else '.'
                entries = shell.fs.ls(path)
                for e in entries:
                    output += e + '\n'

            elif cmd == 'rm':
                if len(args) == 0:
                    raise ValueError("usage")
                for p in args:
                    shell.fs.rm(p, recursive=False)

            elif cmd == 'mv':
                if len(args) != 2:
                    raise ValueError("usage")
                shell.fs.mv(args[0], args[1])

            elif cmd == 'write':
                if len(args) < 1:
                    raise ValueError("usage")
                path = args[0]
                words_to_write = args[1:]
                text = ' '.join(words_to_write) + '\n'
                shell.fs.write(path, text)

            elif cmd == 'append':
                if len(args) < 1:
                    raise ValueError("usage")
                path = args[0]
                words_to_write = args[1:]
                text = ' '.join(words_to_write) + '\n'
                shell.fs.write(path, text, append=True)

            elif cmd == 'cat':
                if len(args) == 0:
                    raise ValueError("usage")
                for p in args:
                    output += shell.fs.read(p)

            elif cmd == 'find':
                # find [PATH] [-name PATTERN]
                path = '.'
                pattern = '*'

                # Parse args: find [PATH] [-name PATTERN]
                # Order isn't strictly specified as positional vs flag, 
                # but usually flags can be anywhere? 
                # "find [PATH] [-name PATTERN]" suggests PATH then flag.
                # But robust parsing is better.
                # Let's assume standard: flags must be handled.
                # If an arg starts with '-', it must be -name.
                # If we see -name, next is pattern.
                # Any non-flag arg is the path.

                i = 0
                path_found = False
                name_found = False

                while i < len(args):
                    arg = args[i]
                    if arg == '-name':
                        if i + 1 >= len(args):
                            raise ValueError("usage")
                        if name_found:
                            raise ValueError("usage")
                        pattern = args[i+1]
                        name_found = True
                        i += 2
                    elif arg.startswith('-'):
                        raise ValueError("usage")
                    else:
                        if path_found:
                            raise ValueError("usage")
                        path = arg
                        path_found = True
                        i += 1

                results = shell.fs.find(path, pattern)
                for p in results:
                    output += p + '\n'

            else:
                output += f"line {i}: {cmd}: unknown command\n"
                return output, 2

        except FSError as e:
            output += f"line {i}: {cmd}: {type(e).__name__}: {e.path}\n"
            return output, 1
        except ValueError:
            output += f"line {i}: {cmd}: usage\n"
            return output, 2

    return output, 0

class Shell:
    def __init__(self, fs=None):
        self.fs = fs or FileSystem()

    def run(self, script):
        return _run_script(script, self)

def main():
    if len(sys.argv) != 2:
        print(f"usage: python -m vfs.shell SCRIPT", file=sys.stderr)
        sys.exit(2)

    script_path = sys.argv[1]

    try:
        with open(script_path, 'r') as f:
            script = f.read()
    except (OSError, IOError) as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(2)

    shell = Shell()
    output, status = shell.run(script)

    print(output, end='')
    sys.exit(status)

if __name__ == '__main__':
    main()
