```python
import dataclasses
from typing import Any, Callable, Optional


@dataclasses.dataclass
class Job:
    id: Any
    payload: Any
    status: str = 'pending'
    attempts: int = 0
    available_at: float = 0.0
    last_error: Optional[str] = None


class JobQueue:
    def __init__(self, clock: Callable[[], float]) -> None:
        self._clock = clock
        self._by_id: dict[Any, Job] = {}
        self._pending: list[Job] = []
        self._dead: list[Job] = []
        self._order = 0

    def submit(self, job_id: Any, payload: Any, delay: float = 0.0) -> Job:
        if job_id in self._by_id:
            raise ValueError(f'duplicate job id: {job_id!r}')
        if delay < 0:
            raise ValueError('delay must not be negative')
        available_at = self._clock() + delay
        job = Job(id=job_id, payload=payload, status='pending', attempts=0,
                  available_at=available_at, last_error=None)
        self._by_id[job_id] = job
        self._pending.append(job)
        return job

    def claim(self) -> Optional[Job]:
        now = self._clock()
        ready: Optional[Job] = None
        for job in self._pending:
            if job.available_at <= now:
                if ready is None or job.available_at < ready.available_at:
                    ready = job
        if ready is None:
            return None
        self._pending.remove(ready)
        ready.status = 'running'
        ready.attempts += 1
        return ready

    def _require_running(self, job_id: Any) -> Job:
        job = self._by_id.get(job_id)
        if job is None:
            raise KeyError(job_id)
        if job.status != 'running':
            raise ValueError(f'job {job_id!r} is not running')
        return job

    def complete(self, job_id: Any) -> None:
        job = self._require_running(job_id)
        job.status = 'done'

    def retry(self, job_id: Any, error: str, at: float) -> None:
        job = self._require_running(job_id)
        job.status = 'pending'
        job.available_at = at
        job.last_error = error
        self._pending.append(job)

    def bury(self, job_id: Any, error: str) -> None:
        job = self._require_running(job_id)
        job.status = 'dead'
        job.last_error = error
        self._dead.append(job)

    def get(self, job_id: Any) -> Job:
        job = self._by_id.get(job_id)
        if job is None:
            raise KeyError(job_id)
        return job

    def dead_letters(self) -> list[Job]:
        return list(self._dead)

    def counts(self) -> dict[str, int]:
        result = {'pending': 0, 'running': 0, 'done': 0, 'dead': 0}
        for job in self._by_id.values():
            result[job.status] += 1
        return result

    def next_available(self) -> Optional[float]:
        if not self._pending:
            return None
        return min(job.available_at for job in self._pending)
