from typing import Any, Callable, NamedTuple, Optional

from .queue import Job, JobQueue
from .retry import PermanentError, RetryPolicy


class ManualClock:
    def __init__(self, start: float = 0.0) -> None:
        self._now = float(start)

    def __call__(self) -> float:
        return self._now

    def advance(self, dt: float) -> None:
        if dt < 0:
            raise ValueError('dt must be >= 0')
        self._now += dt

    def set(self, t: float) -> None:
        if t < self._now:
            raise ValueError('t must not be earlier than now')
        self._now = float(t)


class Event(NamedTuple):
    time: float
    worker: str
    job_id: Any
    attempt: int
    outcome: str
    delay: Optional[float]


class Worker:
    def __init__(self, name: str, queue: JobQueue, handler: Callable[[Any], Any],
                 policy: RetryPolicy, rng: Any, clock: Callable[[], float]) -> None:
        self.name = name
        self.queue = queue
        self.handler = handler
        self.policy = policy
        self.rng = rng
        self.clock = clock

    def step(self) -> Optional[Event]:
        job = self.queue.claim()
        if job is None:
            return None
        event_time = self.clock()
        attempt = job.attempts
        try:
            self.handler(job.payload)
        except PermanentError as exc:
            self.queue.bury(job.id, f'{type(exc).__name__}: {exc}')
            return Event(time=event_time, worker=self.name, job_id=job.id,
                         attempt=attempt, outcome='dead', delay=None)
        except Exception as exc:
            error = f'{type(exc).__name__}: {exc}'
            if self.policy.should_retry(job.attempts):
                delay = self.policy.delay(job.attempts, self.rng)
                self.queue.retry(job.id, error, event_time + delay)
                return Event(time=event_time, worker=self.name, job_id=job.id,
                             attempt=attempt, outcome='retry', delay=delay)
            else:
                self.queue.bury(job.id, error)
                return Event(time=event_time, worker=self.name, job_id=job.id,
                             attempt=attempt, outcome='dead', delay=None)
        self.queue.complete(job.id)
        return Event(time=event_time, worker=self.name, job_id=job.id,
                     attempt=attempt, outcome='done', delay=None)


def run_until_idle(queue: JobQueue, workers: list[Worker],
                   clock: ManualClock, max_steps: int = 10000) -> list[Event]:
    events: list[Event] = []
    while True:
        progressed = False
        for worker in workers:
            event = worker.step()
            if event is not None:
                progressed = True
                events.append(event)
                if len(events) > max_steps:
                    raise RuntimeError(f'exceeded max_steps={max_steps} events')
        if not progressed:
            next_time = queue.next_available()
            if next_time is None:
                break
            clock.set(next_time)
    return events
