import dataclasses
from typing import Any, Callable, Optional


@dataclasses.dataclass
class Job:
    id: Any
    payload: Any
    status: str = 'pending'
    attempts: int = 0
    available_at: float = 0.0
    last_error: Optional[str] = None


class JobQueue:
    def __init__(self, clock: Callable[[], float]) -> None:
        self._clock = clock
        self._by_id: dict[Any, Job] = {}
        # _pending stores tuples (available_at, submission_order, job) to ensure stable sorting by submission order for ties
        self._pending: list[tuple[float, int, Job]] = []
        self._dead: list[Job] = []
        self._order = 0

    def submit(self, job_id: Any, payload: Any, delay: float = 0.0) -> Job:
        if job_id in self._by_id:
            raise ValueError(f'duplicate job id: {job_id!r}')
        if delay < 0:
            raise ValueError('delay must not be negative')
        available_at = self._clock() + delay
        job = Job(id=job_id, payload=payload, status='pending', attempts=0,
                  available_at=available_at, last_error=None)
        self._by_id[job_id] = job
        self._pending.append((available_at, self._order, job))
        self._order += 1
        return job

    def claim(self) -> Optional[Job]:
        if not self._pending:
            return None

        now = self._clock()

        # Find the index of the job to claim:
        # 1. Must be ready (available_at <= now)
        # 2. Earliest available_at
        # 3. Ties broken by earliest submission order

        best_idx = -1
        best_available = float('inf')
        best_order = float('inf')

        for i, (avail, order, job) in enumerate(self._pending):
            if avail > now:
                continue

            if best_idx == -1 or avail < best_available or (avail == best_available and order < best_order):
                best_idx = i
                best_available = avail
                best_order = order

        if best_idx == -1:
            return None

        _, _, job = self._pending.pop(best_idx)
        job.status = 'running'
        job.attempts += 1
        return job

    def _require_running(self, job_id: Any) -> Job:
        job = self._by_id.get(job_id)
        if job is None:
            raise KeyError(job_id)
        if job.status != 'running':
            raise ValueError(f'job {job_id!r} is not running')
        return job

    def complete(self, job_id: Any) -> None:
        job = self._require_running(job_id)
        job.status = 'done'

    def retry(self, job_id: Any, error: str, at: float) -> None:
        job = self._require_running(job_id)
        job.status = 'pending'
        job.available_at = at
        job.last_error = error
        # Append with current self._order to maintain original submission sequence for tie-breaking
        self._pending.append((at, self._order, job))
        self._order += 1

    def bury(self, job_id: Any, error: str) -> None:
        job = self._require_running(job_id)
        job.status = 'dead'
        job.last_error = error
        self._dead.append(job)

    def get(self, job_id: Any) -> Job:
        job = self._by_id.get(job_id)
        if job is None:
            raise KeyError(job_id)
        return job

    def dead_letters(self) -> list[Job]:
        return list(self._dead)

    def counts(self) -> dict[str, int]:
        result = {'pending': 0, 'running': 0, 'done': 0, 'dead': 0}
        for job in self._by_id.values():
            result[job.status] += 1
        return result

    def next_available(self) -> Optional[float]:
        if not self._pending:
            return None
        return min(avail for avail, _, _ in self._pending)
