from .lexer import tokenize, Token

class StackError(Exception):
    def __init__(self, message, word=None, line=None, col=None):
        super().__init__(message)
        self.word = word
        self.line = line
        self.col = col

class StackUnderflow(StackError):
    pass

class UnknownWord(StackError):
    pass

class DivisionByZero(StackError):
    pass

class ControlError(StackError):
    pass

class StepLimitExceeded(StackError):
    pass

class Interpreter:
    def __init__(self, max_steps=100000):
        self.stack = []
        self.output = []
        self.max_steps = max_steps

    def _push(self, val):
        self.stack.append(val)

    def _pop(self, token):
        if not self.stack:
            raise StackUnderflow("Stack underflow", token.value, token.line, token.col)
        return self.stack.pop()

    def _peek(self):
        if not self.stack:
            raise StackUnderflow("Stack underflow")
        return self.stack[-1]

    def run(self, source):
        tokens = tokenize(source)

        # 1. Validation Phase (Control Structure Check)
        # We check for control structure errors before executing anything.
        # Structure: List of expected closers for open blocks.
        # if -> expects then
        # begin -> expects until
        # We also handle else.

        struct_stack = []
        has_else = set() # Track index of 'if' token that has an 'else'

        for i, tok in enumerate(tokens):
            if tok.kind == 'word':
                word = tok.value
                if word == 'if':
                    struct_stack.append(('if', i))
                elif word == 'begin':
                    struct_stack.append(('begin', i))
                elif word == 'else':
                    if not struct_stack:
                        raise ControlError("else without matching if", tok.value, tok.line, tok.col)

                    kind, start_idx = struct_stack[-1]
                    if kind != 'if':
                        raise ControlError("else without matching if", tok.value, tok.line, tok.col)

                    # Check if this if already had an else
                    if start_idx in has_else:
                        raise ControlError("multiple else for same if", tok.value, tok.line, tok.col)

                    has_else.add(start_idx)

                elif word == 'then':
                    if not struct_stack:
                        raise ControlError("then without matching if", tok.value, tok.line, tok.col)

                    kind, start_idx = struct_stack.pop()
                    if kind != 'if':
                        # Found begin but expecting if closer
                        raise ControlError("then without matching if", tok.value, tok.line, tok.col)

                elif word == 'until':
                    if not struct_stack:
                        raise ControlError("until without matching begin", tok.value, tok.line, tok.col)

                    kind, start_idx = struct_stack.pop()
                    if kind != 'begin':
                         # Found if but expecting begin closer
                        raise ControlError("until without matching begin", tok.value, tok.line, tok.col)

        if struct_stack:
            kind, start_idx = struct_stack[-1]
            tok = tokens[start_idx]
            raise ControlError("unclosed control structure", tok.value, tok.line, tok.col)

        # 2. Execution Phase
        steps_taken = 0

        # We need to handle control flow jumps. 
        # Standard approach: recursive execution or program counter with block boundaries.
        # Given the constraints (nesting freely), a recursive approach is cleaner.
        # However, we need to respect the "step count" across the whole run() call.

        def execute_segment(start_idx, end_idx):
            nonlocal steps_taken
            i = start_idx

            while i < end_idx:
                tok = tokens[i]

                if tok.kind == 'number':
                    if steps_taken >= self.max_steps:
                        raise StepLimitExceeded("Step limit exceeded", tok.value, tok.line, tok.col)
                    steps_taken += 1
                    self._push(tok.value)
                    i += 1
                    continue

                word = tok.value

                # Control Words
                if word == 'if':
                    # Find matching 'then'
                    # Note: We know structure is valid from validation phase.
                    # We need to find the 'then' that matches this 'if'.
                    # We can scan forward maintaining a depth counter.
                    depth = 0
                    j = i + 1
                    else_idx = None
                    then_idx = None

                    while j < len(tokens):
                        tw = tokens[j]
                        if tw.kind == 'word':
                            if tw.value == 'if' or tw.value == 'begin':
                                depth += 1
                            elif tw.value == 'then':
                                if depth == 0:
                                    then_idx = j
                                    break
                                depth -= 1
                            elif tw.value == 'until':
                                if depth == 0:
                                    # Should have been caught in validation? 
                                    # Actually inside if, we don't care about inner begins/untils matching unless they close the if's block scope?
                                    # No, until closes begin. If we see until at depth 0 while looking for if's then, it means we are in a begin block?
                                    # Wait, if we are inside an if, and we see begin, depth increases.
                                    # If we see until, depth decreases.
                                    # The matching 'then' for this 'if' is at depth 0 relative to this if.
                                    # 'until' decreases depth if we are inside a begin.
                                    # So if depth is 0, we are not inside a nested begin/if.
                                    # 'until' should not appear at depth 0 for an 'if' search, it would be a mismatch, but validation ensures structure is correct.
                                    # However, 'until' is closer for 'begin'. 
                                    # If depth is 0, and we see 'then', we are done.
                                    # If we see 'else' at depth 0, we record it.
                                    pass
                            elif tw.value == 'else':
                                if depth == 0:
                                    if else_idx is not None:
                                        # Validation ensured only one else per if, so this shouldn't happen if logic holds
                                        # But let's capture first else.
                                        if else_idx is None:
                                            else_idx = j
                                    else:
                                        else_idx = j

                        j += 1

                    if then_idx is None:
                         raise ControlError("Internal error: unclosed if during execution", tok.value, tok.line, tok.col)

                    # Consume 'if' as a step
                    if steps_taken >= self.max_steps:
                        raise StepLimitExceeded("Step limit exceeded", tok.value, tok.line, tok.col)
                    steps_taken += 1

                    # Pop condition
                    cond = self._pop(tok)

                    # Determine branch
                    if cond != 0:
                        # Run 'then' branch (from i+1 to else_idx or then_idx)
                        next_i = else_idx if else_idx is not None else then_idx
                        execute_segment(i + 1, next_i)
                    else:
                        # Run 'else' branch if exists, else skip
                        if else_idx is not None:
                            execute_segment(else_idx + 1, then_idx)

                    # Jump over the rest of the if block
                    i = then_idx + 1
                    continue

                elif word == 'begin':
                    # Find matching 'until'
                    depth = 0
                    j = i + 1
                    until_idx = None

                    while j < len(tokens):
                        tw = tokens[j]
                        if tw.kind == 'word':
                            if tw.value == 'if' or tw.value == 'begin':
                                depth += 1
                            elif tw.value == 'until':
                                if depth == 0:
                                    until_idx = j
                                    break
                                depth -= 1
                            elif tw.value == 'then':
                                # Should not close begin
                                pass

                        j += 1

                    if until_idx is None:
                        raise ControlError("Internal error: unclosed begin during execution", tok.value, tok.line, tok.col)

                    # Execute loop
                    while True:
                        # Execute body
                        execute_segment(i + 1, until_idx)

                        # Evaluate until
                        if steps_taken >= self.max_steps:
                            raise StepLimitExceeded("Step limit exceeded", tokens[until_idx].value, tokens[until_idx].line, tokens[until_idx].col)
                        steps_taken += 1

                        cond = self._pop(tokens[until_idx])
                        if cond != 0:
                            break

                    i = until_idx + 1
                    continue

                elif word == 'else':
                    # Should not be reached directly if control flow is correct
                    # 'else' is skipped by the logic of 'if' or 'if' executes one branch.
                    # If we encounter 'else' here, it means it wasn't skipped, which implies we are in the 'else' branch execution?
                    # No, execute_segment for else starts at else_idx + 1.
                    # So 'else' token itself is never executed as a word.
                    i += 1
                    continue

                elif word == 'then':
                    # Skipped by control flow
                    i += 1
                    continue

                elif word == 'until':
                    # Skipped by control flow (handled in begin loop)
                    i += 1
                    continue

                # Simple Words
                # Arithmetic
                if word == '+':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a + b)
                elif word == '-':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a - b)
                elif word == '*':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a * b)
                elif word == '/':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    if b == 0: raise DivisionByZero("Division by zero", word, tok.line, tok.col)
                    self._push(a // b)
                elif word == 'mod':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    if b == 0: raise DivisionByZero("Division by zero", word, tok.line, tok.col)
                    self._push(a % b)

                elif word == 'negate':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    a = self._pop(tok)
                    self._push(-a)
                elif word == 'abs':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    a = self._pop(tok)
                    self._push(abs(a))

                # Stack Manipulation
                elif word == 'dup':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    a = self._pop(tok)
                    self._push(a); self._push(a)
                elif word == 'drop':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    self._pop(tok)
                elif word == 'swap':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(b); self._push(a)
                elif word == 'over':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a); self._push(b); self._push(a)
                elif word == 'rot':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    c = self._pop(tok); b = self._pop(tok); a = self._pop(tok)
                    self._push(b); self._push(c); self._push(a)
                elif word == 'depth':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    # Depth is number of items BEFORE this word.
                    # Current stack length is the depth.
                    # Wait, if we just checked steps, did we pop? No.
                    # The spec says "number of items on the stack before this word".
                    # If stack is [1, 2], depth is 2.
                    self._push(len(self.stack))

                # Comparison
                elif word == '=':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(-1 if a == b else 0)
                elif word == '<>':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(-1 if a != b else 0)
                elif word == '<':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(-1 if a < b else 0)
                elif word == '>':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(-1 if a > b else 0)
                elif word == '0=':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    a = self._pop(tok)
                    self._push(-1 if a == 0 else 0)

                # Logic
                elif word == 'and':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a & b)
                elif word == 'or':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    b = self._pop(tok); a = self._pop(tok)
                    self._push(a | b)

                # Output
                elif word == '.':
                    if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                    steps_taken += 1
                    a = self._pop(tok)
                    self.output.append(a)

                else:
                    raise UnknownWord(f"Unknown word: {word}", word, tok.line, tok.col)

        execute_segment(0, len(tokens))

def evaluate(source: str) -> list[int]:
    interp = Interpreter()
    interp.run(source)
    return interp.stack
