import sys
from .lexer import tokenize, Token

class StackError(Exception):
    def __init__(self, message, word=None, line=None, col=None):
        super().__init__(message)
        self.word = word
        self.line = line
        self.col = col

class StackUnderflow(StackError):
    pass

class UnknownWord(StackError):
    pass

class DivisionByZero(StackError):
    pass

class ControlError(StackError):
    pass

class StepLimitExceeded(StackError):
    pass

class CallDepthExceeded(StackError):
    pass

# Reserved words that cannot be redefined
BUILTIN_WORDS = {
    '+', '-', '*', '/', 'mod', 'negate', 'abs',
    'dup', 'drop', 'swap', 'over', 'rot',
    '=', '<>', '<', '>', '0=',
    'and', 'or', 'depth',
    '.', 
    # Control words
    'if', 'else', 'then', 'begin', 'until',
    # Definition words
    ':', ';'
}

def validate_structure(tokens: list[Token]) -> None:
    """
    Validates control structures and definitions before execution.
    Raises ControlError if invalid.
    """
    # Stack elements: dict with 'type', 'index'
    # type: 'if', 'begin', 'def'
    stack = []

    for i, tok in enumerate(tokens):
        if tok.kind != 'word':
            continue
        w = tok.value

        if w == 'if':
            stack.append({'type': 'if', 'index': i})
        elif w == 'begin':
            stack.append({'type': 'begin', 'index': i})
        elif w == ':':
            # Cannot define inside if/begin/def
            if stack:
                top_type = stack[-1]['type']
                if top_type in ['if', 'begin', 'def']:
                    raise ControlError("definition inside definition or control structure", tok.value, tok.line, tok.col)

            # Check if there is a name token following ':'
            if i + 1 >= len(tokens):
                raise ControlError("definition without name", tok.value, tok.line, tok.col)

            name_tok = tokens[i+1]
            # Name must be a word and not a reserved word
            if name_tok.kind != 'word':
                raise ControlError("definition name must be a word", name_tok.value, name_tok.line, name_tok.col)

            if name_tok.value in BUILTIN_WORDS:
                raise ControlError("cannot redefine builtin word", name_tok.value, name_tok.line, name_tok.col)

            stack.append({'type': 'def', 'index': i})

        elif w == 'else':
            if not stack:
                raise ControlError("else without matching if", tok.value, tok.line, tok.col)
            if stack[-1]['type'] != 'if':
                raise ControlError("else without matching if", tok.value, tok.line, tok.col)
            # Mark that else was seen for this if
            if 'has_else' in stack[-1] and stack[-1]['has_else']:
                raise ControlError("duplicate else", tok.value, tok.line, tok.col)
            stack[-1]['has_else'] = True

        elif w == 'then':
            if not stack:
                raise ControlError("then without matching if", tok.value, tok.line, tok.col)
            top = stack.pop()
            if top['type'] != 'if':
                raise ControlError("then without matching if", top['index'] if top['type']=='def' else tok.value, 
                                   tokens[top['index']].line if top['type']=='def' else tok.line,
                                   tokens[top['index']].col if top['type']=='def' else tok.col)

        elif w == 'until':
            if not stack:
                raise ControlError("until without matching begin", tok.value, tok.line, tok.col)
            top = stack.pop()
            if top['type'] != 'begin':
                raise ControlError("until without matching begin", top['index'] if top['type']=='def' else tok.value,
                                   tokens[top['index']].line if top['type']=='def' else tok.line,
                                   tokens[top['index']].col if top['type']=='def' else tok.col)

        elif w == ';':
            if not stack:
                raise ControlError("semicolon without matching definition", tok.value, tok.line, tok.col)

            # Check if inner control structures are closed
            # We must pop everything until we hit the 'def'
            # If we encounter an 'if' or 'begin' on the way up, it means the definition was incomplete

            found_def_idx = -1
            for k in range(len(stack) - 1, -1, -1):
                if stack[k]['type'] == 'def':
                    found_def_idx = k
                    break

            if found_def_idx == -1:
                raise ControlError("semicolon without matching definition", tok.value, tok.line, tok.col)

            # Pop everything above the def
            while len(stack) - 1 > found_def_idx:
                top = stack.pop()
                if top['type'] in ['if', 'begin']:
                    # Unclosed control structure inside definition
                    raise ControlError("unclosed control structure in definition", tok.value, tok.line, tok.col)

            # Now pop the def itself
            # The stack top should now be the def we found
            if stack and stack[-1]['type'] == 'def':
                stack.pop()
            else:
                # This case shouldn't happen if logic above is correct
                raise ControlError("internal error: semicolon matching failed", tok.value, tok.line, tok.col)

    # Check for unclosed structures at the end
    if stack:
        # Report the last opener that is still open
        top = stack[-1]
        tok = tokens[top['index']]
        raise ControlError("unclosed structure", tok.value, tok.line, tok.col)

class Interpreter:
    def __init__(self, max_steps=100000, max_depth=100):
        self.stack = []
        self.output = []
        self.max_steps = max_steps
        self.max_depth = max_depth
        self.definitions = {} # name -> list of tokens (body)

    def defined(self):
        return sorted(self.definitions.keys())

    def _push(self, val):
        self.stack.append(val)

    def _pop(self, token):
        if not self.stack:
            raise StackUnderflow("Stack underflow", token.value, token.line, token.col)
        return self.stack.pop()

    def _find_matching_control(self, tokens, start_idx, open_word):
        """
        Given an open_word ('if' or 'begin') at start_idx, find the matching close word ('then' or 'until').
        Also finds 'else' if applicable.
        Returns (else_idx, close_idx) or raises ControlError.
        """
        depth = 0
        j = start_idx + 1
        else_idx = None
        close_word = 'then' if open_word == 'if' else 'until'

        while j < len(tokens):
            tw = tokens[j]
            if tw.kind == 'word':
                if tw.value == 'if' or tw.value == 'begin':
                    depth += 1
                elif tw.value == close_word:
                    if depth == 0:
                        return else_idx, j
                    depth -= 1
                elif tw.value == 'then' or tw.value == 'until':
                    # Closing a different structure type at depth 0?
                    # e.g., if ... until. This is invalid, but validate_structure should have caught it.
                    # If depth > 0, it closes a nested structure of possibly different type?
                    # No, stack-based validation ensures types match.
                    if depth > 0:
                        depth -= 1
                elif tw.value == 'else':
                    if depth == 0 and open_word == 'if':
                        if else_idx is None:
                            else_idx = j
            j += 1

        # Should not reach here if validation passed
        raise ControlError("Internal error: unclosed control structure", tokens[start_idx].value, tokens[start_idx].line, tokens[start_idx].col)

    def _execute_range(self, tokens, start_idx, end_idx, steps_taken, current_depth):
        """
        Executes tokens from start_idx to end_idx (exclusive).
        Returns updated steps_taken.
        """
        i = start_idx
        while i < end_idx:
            tok = tokens[i]

            if tok.kind == 'number':
                if steps_taken >= self.max_steps:
                    raise StepLimitExceeded("Step limit exceeded", tok.value, tok.line, tok.col)
                steps_taken += 1
                self._push(tok.value)
                i += 1
                continue

            word = tok.value

            # Control structures
            if word == 'if':
                if steps_taken >= self.max_steps:
                    raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1

                # Find matching else/then
                else_idx, then_idx = self._find_matching_control(tokens, i, 'if')

                cond = self._pop(tok)

                if cond != 0:
                    # Execute then-branch (from i+1 to else_idx or then_idx)
                    next_i = else_idx if else_idx is not None else then_idx
                    steps_taken = self._execute_range(tokens, i + 1, next_i, steps_taken, current_depth)
                else:
                    if else_idx is not None:
                        # Execute else-branch
                        steps_taken = self._execute_range(tokens, else_idx + 1, then_idx, steps_taken, current_depth)

                # Jump over the rest of the if block
                i = then_idx + 1
                continue

            if word == 'begin':
                # Find matching until
                _, until_idx = self._find_matching_control(tokens, i, 'begin')

                while True:
                    # Execute body
                    steps_taken = self._execute_range(tokens, i + 1, until_idx, steps_taken, current_depth)

                    # Evaluate until
                    until_tok = tokens[until_idx]
                    if steps_taken >= self.max_steps:
                        raise StepLimitExceeded("Step limit exceeded", until_tok.value, until_tok.line, until_tok.col)
                    steps_taken += 1

                    cond = self._pop(until_tok)
                    if cond != 0:
                        break

                i = until_idx + 1
                continue

            # Built-in words

            # Arithmetic
            if word == '+':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a + b)
            elif word == '-':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a - b)
            elif word == '*':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a * b)
            elif word == '/':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                if b == 0:
                    raise DivisionByZero("Division by zero", word, tok.line, tok.col)
                self._push(a // b)
            elif word == 'mod':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                if b == 0:
                    raise DivisionByZero("Division by zero", word, tok.line, tok.col)
                self._push(a % b)
            elif word == 'negate':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                a = self._pop(tok)
                self._push(-a)
            elif word == 'abs':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                a = self._pop(tok)
                self._push(abs(a))

            # Stack Manipulation
            elif word == 'dup':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                a = self._pop(tok)
                self._push(a)
                self._push(a)
            elif word == 'drop':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                self._pop(tok)
            elif word == 'swap':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(b)
                self._push(a)
            elif word == 'over':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a)
                self._push(b)
                self._push(a)
            elif word == 'rot':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 3:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                c = self.stack.pop()
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(b)
                self._push(c)
                self._push(a)
            elif word == 'depth':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                self._push(len(self.stack))

            # Comparison
            elif word == '=':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(-1 if a == b else 0)
            elif word == '<>':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(-1 if a != b else 0)
            elif word == '<':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(-1 if a < b else 0)
            elif word == '>':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(-1 if a > b else 0)
            elif word == '0=':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                a = self._pop(tok)
                self._push(-1 if a == 0 else 0)

            # Logic
            elif word == 'and':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a & b)
            elif word == 'or':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                if len(self.stack) < 2:
                    raise StackUnderflow("Stack underflow", tok.value, tok.line, tok.col)
                b = self.stack.pop()
                a = self.stack.pop()
                self._push(a | b)

            # Output
            elif word == '.':
                if steps_taken >= self.max_steps: raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1
                a = self._pop(tok)
                self.output.append(a)

            # User Defined Words
            elif word in self.definitions:
                if current_depth >= self.max_depth:
                    raise CallDepthExceeded("Call depth exceeded", word, tok.line, tok.col)

                if steps_taken >= self.max_steps:
                    raise StepLimitExceeded("Step limit exceeded", word, tok.line, tok.col)
                steps_taken += 1

                body = self.definitions[word]
