                tree_oid = val
            elif line.startswith(b'parent '):
                val = line[7:].decode("utf-8")
                if len(val) != 40: raise CorruptObject("Bad parent oid length")
                try: int(val, 16)
                except ValueError: raise CorruptObject("Bad parent oid hex")
