                    # But we are going deepest first.
                    # If c_path is in all_dir_paths, it must have been created.
                    # Unless it's an empty directory?
                    # If a directory is empty, it doesn't appear in files.
                    # If it appears in all_dir_paths, it must be an ancestor of a file.
                    # So it must have children.
                    # So it should be in tree_oids.
                    raise RuntimeError(f"Internal error: child {c_path} not built yet")

                name = c_path[-1]
                entries.append(TreeEntry(name=name, kind='tree', oid=child_oid))

