    def read_tree(self, oid: str) -> dict:
        if oid not in self:
            raise ObjectNotFound(oid)

        obj = self.get(oid)
        if not isinstance(obj, Tree):
            raise ValueError("Not a tree")

        result = {}

        # Walk recursively
        def walk(path, tree_oid):
            tree = self.get(tree_oid)
            for entry in tree.entries:
                full_path = f"{path}/{entry.name}" if path else entry.name
                if entry.kind == 'blob':
                    blob = self.get(entry.oid)
                    result[full_path] = blob.data
                elif entry.kind == 'tree':
                    walk(full_path, entry.oid)

        walk("", oid)
        return dict(sorted(result.items()))

    def commit(self, tree: str, parents=(), *, author, timestamp, message) -> str:
        # Validate tree
        if tree not in self:
            raise ObjectNotFound(tree)
        tree_obj = self.get(tree)
        if not isinstance(tree_obj, Tree):
            raise ValueError("Tree is not a tree")

        # Validate parents
        for p in parents:
            if p not in self:
                raise ObjectNotFound(p)
            p_obj = self.get(p)
            if not isinstance(p_obj, Commit):
                raise ValueError("Parent is not a commit")

        commit_obj = Commit(tree=tree, parents=parents, author=author, timestamp=timestamp, message=message)
        return self.put(commit_obj)

    def log(self, oid: str, first_parent: bool = False) -> list:
        # Returns list of commit oids

        if oid not in self:
            raise ObjectNotFound(oid)

        visited = set()

        def collect(c_oid):
            if c_oid in visited:
                return
            visited.add(c_oid)

            c_obj = self.get(c_oid)
            if not isinstance(c_obj, Commit):
                return

            if first_parent:
                if c_obj.parents:
                    collect(c_obj.parents[0])
            else:
                for p in c_obj.parents:
                    collect(p)

        collect(oid)

        # Sort
        # Order by timestamp (desc), then oid (asc)
        def sort_key(oid_val):
            c = self.get(oid_val)
            return (-c.timestamp, oid_val)

        return sorted(visited, key=sort_key)
