from collections import namedtuple
from .objects import Tree, Blob, TreeEntry
from .store import ObjectNotFound

Change = namedtuple('Change', ['status', 'path', 'old', 'new'])

def _read_files(store, tree_oid, prefix=""):
    """
    Generator yielding (path, oid) for all files in tree_oid.
    """
    if tree_oid is None:
        return

    try:
        tree = store.get(tree_oid)
    except ObjectNotFound:
        return

    for entry in tree.entries:
        path = f"{prefix}/{entry.name}" if prefix else entry.name
        if entry.kind == 'blob':
            yield (path, entry.oid)
        elif entry.kind == 'tree':
            yield from _read_files(store, entry.oid, path)

def diff_trees(store, old: str, new: str) -> list:
    # Read files from old and new trees into dicts mapping path -> oid
    # None stands for empty tree

    old_files = {}
    if old is not None:
        for path, oid in _read_files(store, old):
            old_files[path] = oid

    new_files = {}
    if new is not None:
        for path, oid in _read_files(store, new):
            new_files[path] = oid

    # Identify changes
    # A: Added (in new, not in old)
    # D: Deleted (in old, not in new)
    # M: Modified (in both, oid differs)

    # Where a name is a file on one side and a directory on the other,
    # the file is deleted or added and every file under the directory is added or deleted.

    # This implies we compare paths.

    changes = []

    # Handle old files
    for path, old_oid in old_files.items():
        if path in new_files:
            new_oid = new_files[path]
            if old_oid != new_oid:
                changes.append(Change('M', path, old_oid, new_oid))
        else:
            # Deleted
            # But check if this path is a prefix of a directory in new?
            # Actually, if it was a file in old, it appears as a path in old_files.
            # If it is gone in new, it is D.
            changes.append(Change('D', path, old_oid, None))

    # Handle new files
    for path, new_oid in new_files.items():
        if path not in old_files:
            changes.append(Change('A', path, None, new_oid))

    # Sort by path
    changes.sort(key=lambda c: c.path)

    return changes

def diff_commits(store, old, new) -> list:
    # Get trees from commits
    if old is None:
        old_tree = None
    else:
        old_commit = store.get(old)
        old_tree = old_commit.tree

    if new is None:
        new_tree = None
    else:
        new_commit = store.get(new)
        new_tree = new_commit.tree

    return diff_trees(store, old_tree, new_tree)

def format_changes(changes) -> str:
    return "".join(f"{c.status}\t{c.path}\n" for c in changes)
