from .model import Group

def balances(group: Group) -> dict[str, int]:
    """
    Returns a dict from every member, in alphabetical order, to their balance in cents.
    Positive means the group owes them money.
    """
    members = sorted(group.members)
    bal = {m: 0 for m in members}

    for expense, shares in group.expenses:
        # Payer paid the full amount
        bal[expense.paid_by] += expense.amount
        # Participants owe their share
        for member, share in shares.items():
            bal[member] -= share

    for payer, payee, amount in group.payments:
        # Payer gave money away (decrease balance relative to group? No, balance is "what they paid - shares + payments made - payments received")
        # Wait, definition: "what they paid for expenses, minus their shares, plus payments they made, minus payments they received"
        # Actually, usually "balance" in splitting apps is Net Debt/Credit.
        # Let's re-read carefully:
        # "Positive means the group owes them money."
        # Formula: Paid Expenses - Shares - Payments Made + Payments Received = Balance?
        # If I pay $10 for dinner shared equally with you, I paid 10, my share is 5. Balance = +5.
        # If I pay you $5 directly. I paid 0 extra expenses, my share 0, payment made 5. Balance = -5.
        # So: Bal = (Paid Expenses - Shares) - (Payments Made) + (Payments Received).

        bal[payer] -= amount
        bal[payee] += amount

    return bal

def format_balances(bals: dict[str, int]) -> str:
    """
    Returns one line per member in alphabetical order.
    """
    lines = []
    for name in sorted(bals.keys()):
        val = bals[name]
        if val > 0:
            formatted = f"+{val//100}.{val%100:02d}"
        else:
            # format_amount handles negative sign correctly
            from .model import format_amount
            formatted = format_amount(val)
        lines.append(f"{name}: {formatted}")
    return "".join(line + "\n" for line in lines)
