from typing import NamedTuple

class Transfer(NamedTuple):
    payer: str
    payee: str
    amount: int

def settle(bals: dict[str, int]) -> list[Transfer]:
    """
    Takes a balances dict and returns transfers to settle it.
    Raises ValueError if balances do not sum to 0.
    """
    if sum(bals.values()) != 0:
        raise ValueError("Balances do not sum to zero")

    # Work on a copy
    working_bals = dict(bals)
    transfers = []

    # Helper to get creditors and debtors
    # Creditors: > 0, Debtors: < 0
    # Greedy: 
    # 1. Find creditor with largest positive balance (tie: alphabetical)
    # 2. Find debtor with most negative balance (tie: alphabetical)

    while True:
        creditors = [(name, amt) for name, amt in working_bals.items() if amt > 0]
        debtors = [(name, amt) for name, amt in working_bals.items() if amt < 0]

        if not creditors or not debtors:
            break

        # Sort creditors: descending amount, then name ascending
        creditors.sort(key=lambda x: (-x[1], x[0]))
        # Sort debtors: ascending amount (most negative first), then name ascending
        debtors.sort(key=lambda x: (x[1], x[0]))

        creditor_name, creditor_amt = creditors[0]
        debtor_name, debtor_amt = debtors[0] # amt is negative

        transfer_amt = min(creditor_amt, -debtor_amt)

        transfers.append(Transfer(payer=debtor_name, payee=creditor_name, amount=transfer_amt))

        working_bals[creditor_name] -= transfer_amt
        working_bals[debtor_name] += transfer_amt

    return transfers

def format_plan(transfers: list[Transfer]) -> str:
    if not transfers:
        return "All settled.\n"

    from .model import format_amount

    lines = []
    for t in transfers:
        lines.append(f"{t.payer} pays {t.payee} {format_amount(t.amount)}")

    return "".join(line + "\n" for line in lines)
