from .model import Group, format_amount

def balances(group: Group) -> dict[str, int]:
    """
    Returns a dict from every member, in alphabetical order, to their balance in cents.
    Positive means the group owes them money.
    """
    members = sorted(group.members)
    bal = {m: 0 for m in members}

    for expense, shares in group.expenses:
        # Payer paid the full amount
        bal[expense.paid_by] += expense.amount
        # Participants owe their share
        for member, share in shares.items():
            bal[member] -= share

    for payer, payee, amount in group.payments:
        # Spec: "plus payments they made, minus payments they received"
        # Payer made a payment: add to balance (reduces debt/increases credit)
        # Payee received a payment: subtract from balance (reduces credit/increases debt relative to claim)
        bal[payer] += amount
        bal[payee] -= amount

    return bal

def format_balances(bals: dict[str, int]) -> str:
    """
    Returns one line per member in alphabetical order.
    """
    lines = []
    for name in sorted(bals.keys()):
        val = bals[name]
        if val > 0:
            formatted = f"+{val//100}.{val%100:02d}"
        elif val < 0:
            formatted = format_amount(val)
        else:
