import re
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from typing import Optional, Union, Dict, List

def parse_amount(text: str) -> int:
    """
    Accepts digits optionally followed by `.` and one or two digits.
    Returns cents as int.
    """
    if not isinstance(text, str):
        raise ValueError("Amount must be a string")
    if not re.fullmatch(r"\d+(\.\d{1,2})?", text):
        raise ValueError(f"Invalid amount format: {text}")

    parts = text.split('.')
    integer_part = parts[0]
    fractional_part = ""
    if len(parts) > 1:
        fractional_part = parts[1]

    cents = int(integer_part) * 100
    if len(fractional_part) == 1:
        cents += int(fractional_part) * 10
    elif len(fractional_part) == 2:
        cents += int(fractional_part)
    return cents

def format_amount(cents: int) -> str:
    """
    Returns the amount with exactly two decimals, with `-` for negative.
    """
    if cents < 0:
        return f"-{format_amount(-cents)}"
    return f"{cents // 100}.{cents % 100:02d}"

@dataclass(frozen=True)
class Equal:
    members: Optional[tuple] = None

@dataclass(frozen=True)
class Exact:
    shares: Dict[str, int]

@dataclass(frozen=True)
class Percent:
    shares: Dict[str, Union[int, Decimal, str]]

@dataclass(frozen=True)
class Expense:
    description: str
    paid_by: str
    amount: int
    split: Union[Equal, Exact, Percent]

class Group:
    def __init__(self, members: list[str]):
        if not isinstance(members, list) or not all(isinstance(m, str) and m for m in members):
            raise ValueError("Members must be non-empty strings")
        if len(members) != len(set(members)):
            raise ValueError("Duplicate members")

        self._members: list[str] = []
        for m in members:
            self.add_member(m)

        self._expenses: list[tuple[Expense, Dict[str, int]]] = []
        self._payments: list[tuple[str, str, int]] = []

    @property
    def members(self) -> list[str]:
        return list(self._members)

    @property
    def expenses(self) -> list[tuple[Expense, Dict[str, int]]]:
        return list(self._expenses)

    @property
    def payments(self) -> list[tuple[str, str, int]]:
        return list(self._payments)

    def add_member(self, name: str):
        if not isinstance(name, str) or not name:
            raise ValueError("Member name must be a non-empty string")
        if name in self._members:
            raise ValueError("Duplicate member")
        self._members.append(name)

    def add_expense(self, expense: Expense) -> Dict[str, int]:
        if not isinstance(expense, Expense):
            raise ValueError("Invalid expense object")
        if expense.amount <= 0:
            raise ValueError("Expense amount must be positive")
        if expense.paid_by not in self._members:
            raise ValueError(f"Payer {expense.paid_by} is not a member")

        shares_dict = self._compute_shares(expense)

        # Validate shares add up to amount
        if sum(shares_dict.values()) != expense.amount:
            raise ValueError("Internal error: shares do not sum to amount")

        # Ensure all participants are members
        for member in shares_dict:
            if member not in self._members:
                raise ValueError(f"Member {member} in shares is not in group")

        # Reorder shares to match group member order
        ordered_shares = {}
        for m in self._members:
            if m in shares_dict:
                ordered_shares[m] = shares_dict[m]

        self._expenses.append((expense, ordered_shares))
        return ordered_shares

    def _compute_shares(self, expense: Expense) -> Dict[str, int]:
        split = expense.split
        amount = expense.amount

        if isinstance(split, Equal):
            if split.members is not None:
                participants = list(split.members)
                if not participants:
                    raise ValueError("Equal split members list cannot be empty")
                if len(participants) != len(set(participants)):
                    raise ValueError("Duplicate members in Equal split")
                for m in participants:
                    if m not in self._members:
                        raise ValueError(f"Participant {m} is not a member")
            else:
                participants = list(self._members)

            if not participants:
                raise ValueError("No participants for Equal split")

            n = len(participants)
            base = amount // n
            remainder = amount % n

            # Sort alphabetically to distribute remainder
            sorted_participants = sorted(participants)

            shares = {p: base for p in participants}
            for i in range(remainder):
                shares[sorted_participants[i]] += 1

            return shares

        elif isinstance(split, Exact):
            shares = split.shares
            if not isinstance(shares, dict):
                raise ValueError("Exact split shares must be a dict")

            for member, cents in shares.items():
                if member not in self._members:
                    raise ValueError(f"Member {member} in Exact split is not in group")
                if not isinstance(cents, int):
                    raise ValueError("Exact share amounts must be integers (cents)")
                if cents < 0:
                    raise ValueError("Exact share amounts must be non-negative")

            if sum(shares.values()) != amount:
                raise ValueError("Exact shares do not sum to expense amount")

            return dict(shares)

        elif isinstance(split, Percent):
            shares_input = split.shares
            if not isinstance(shares_input, dict):
                raise ValueError("Percent split shares must be a dict")

            participants = list(shares_input.keys())
            for m in participants:
                if m not in self._members:
                    raise ValueError(f"Participant {m} in Percent split is not in member list")

            if not participants:
                raise ValueError("No participants in Percent split")

            # Validate and convert percentages
            percentages = {}
            total_pct = Decimal(0)
            for m, pct_val in shares_input.items():
                try:
                    if isinstance(pct_val, Decimal):
                        pct = pct_val
                    elif isinstance(pct_val, str):
                        pct = Decimal(pct_val)
                    elif isinstance(pct_val, int):
                        pct = Decimal(pct_val)
                    else:
                        raise ValueError("Invalid percentage type")
                except Exception:
                    raise ValueError(f"Invalid percentage value: {pct_val}")

                if pct < 0:
                    raise ValueError("Percentages must be non-negative")
                percentages[m] = pct
                total_pct += pct

            if total_pct != 100:
                raise ValueError(f"Percentages must sum to 100, got {total_pct}")

            # Compute exact floors and fractional parts
            amount_dec = Decimal(amount)
            base_shares = {}
            fractions = {}
            total_base = 0

            for m in participants:
                pct = percentages[m]
                exact_val = amount_dec * pct / Decimal(100)
                floor_val = int(exact_val) # Decimal int() truncates towards zero, but values are positive
                base_shares[m] = floor_val
                frac = exact_val - Decimal(floor_val)
                fractions[m] = (frac, m) # Store fraction for sorting
                total_base += floor_val

            remainder = amount - total_base

            # Sort by fractional part descending, then name ascending for ties
            # fractions is a list of tuples (frac, name)
            sorted_fractions = sorted(fractions.values(), key=lambda x: (-x[0], x[1]))

            shares = dict(base_shares)
            for i in range(remainder):
                _, m = sorted_fractions[i]
                shares[m] += 1

            return shares

        else:
            raise ValueError("Unknown split type")

    def add_payment(self, payer: str, payee: str, amount: int):
        if not isinstance(amount, int):
            raise ValueError("Payment amount must be an integer")
        if amount <= 0:
            raise ValueError("Payment amount must be positive")
        if payer not in self._members:
            raise ValueError(f"Payer {payer} is not a member")
        if payee not in self._members:
            raise ValueError(f"Payee {payee} is not a member")
        if payer == payee:
            raise ValueError("Payer and payee must be different")

        self._payments.append((payer, payee, amount))

def load_group(data: dict) -> Group:
    if not isinstance(data, dict):
        raise ValueError("Data must be a dictionary")

    try:
        members = data["members"]
    except KeyError:
        raise ValueError("Missing 'members' key")

    if not isinstance(members, list):
        raise ValueError("Members must be a list")

    group = Group(members)

    expenses = data.get("expenses", [])
    if not isinstance(expenses, list):
        raise ValueError("Expenses must be a list")

    for exp_data in expenses:
        if not isinstance(exp_data, dict):
            raise ValueError("Expense data must be a dict")

        try:
            description = exp_data["description"]
            paid_by = exp_data["paid_by"]
            amount_str = exp_data["amount"]
            split_data = exp_data["split"]
        except KeyError as e:
            raise ValueError(f"Missing key in expense data: {e}")

        if not isinstance(split_data, dict):
            raise ValueError("Split data must be a dict")

        amount = parse_amount(amount_str)

        split_type = split_data.get("type")
        if split_type == "equal":
            members_list = split_data.get("members")
            if members_list is not None:
                if not isinstance(members_list, list):
                    raise ValueError("Equal split members must be a list")
                split_obj = Equal(members=tuple(members_list))
            else:
                split_obj = Equal()
        elif split_type == "exact":
            try:
                shares_str = split_data["shares"]
            except KeyError:
                raise ValueError("Missing 'shares' key in exact split")
            if not isinstance(shares_str, dict):
                raise ValueError("Exact split shares must be a dict")
            # Convert string amounts to int cents
            try:
                shares_int = {k: parse_amount(v) for k, v in shares_str.items()}
            except Exception:
                raise ValueError("Invalid amount in exact split shares")
            split_obj = Exact(shares=shares_int)
        elif split_type == "percent":
            try:
                shares_str = split_data["shares"]
            except KeyError:
                raise ValueError("Missing 'shares' key in percent split")
            if not isinstance(shares_str, dict):
                raise ValueError("Percent split shares must be a dict")
            # Keep as is, model handles validation
            split_obj = Percent(shares=shares_str)
        else:
            raise ValueError(f"Unknown split type: {split_type}")

        expense = Expense(description=description, paid_by=paid_by, amount=amount, split=split_obj)
        group.add_expense(expense)

    payments = data.get("payments", [])
    if not isinstance(payments, list):
        raise ValueError("Payments must be a list")

    for pay_data in payments:
        if not isinstance(pay_data, dict):
            raise ValueError("Payment data must be a dict")

        try:
            payer = pay_data["from"]
            payee = pay_data["to"]
            amount_str = pay_data["amount"]
        except KeyError as e:
            raise ValueError(f"Missing key in payment data: {e}")

        amount = parse_amount(amount_str)

        group.add_payment(payer, payee, amount)

    return group
